import {
  clampNumber,
  getBearerToken,
  getOpenAIEnv,
  sendJson,
  sendText,
  truncateString,
  readJson,
  verifySupabaseJwt,
} from '../../src/server/ai-proxy.js';

export const config = {
  runtime: 'nodejs',
};

const ALLOWED_MODELS = new Set(['gpt-4o-mini', 'gpt-4o']);
const MAX_BODY_BYTES = 256 * 1024; // 256KB
const MAX_MESSAGES = 32;
const MAX_CONTENT_CHARS = 8000;
const MAX_TOTAL_CHARS = 24000;

export default async function handler(req: any, res: any) {
  if (req.method === 'OPTIONS') {
    // Same-origin requests shouldn't preflight, but handle just in case.
    res.statusCode = 204;
    res.setHeader('Allow', 'POST, OPTIONS');
    return res.end();
  }

  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST, OPTIONS');
    return sendText(res, 405, 'Method Not Allowed');
  }

  const { apiKey } = getOpenAIEnv();
  if (!apiKey) {
    return sendJson(res, 503, { error: 'OPENAI_API_KEY not configured' });
  }

  const token = getBearerToken(req);
  if (!token) {
    return sendJson(res, 401, { error: 'Missing Authorization bearer token' });
  }

  const user = await verifySupabaseJwt(token);
  if (!user) {
    return sendJson(res, 401, { error: 'Invalid Supabase session' });
  }

  let payload: any;
  try {
    payload = await readJson(req, MAX_BODY_BYTES);
  } catch (e: any) {
    return sendJson(res, 400, { error: e?.message || 'Invalid request body' });
  }

  const rawMessages = Array.isArray(payload?.messages) ? payload.messages : [];
  const messages = rawMessages
    .slice(0, MAX_MESSAGES)
    .map((m: any) => ({
      role: m?.role === 'system' || m?.role === 'assistant' || m?.role === 'user' ? m.role : 'user',
      content: truncateString(m?.content, MAX_CONTENT_CHARS),
    }))
    .filter((m: any) => typeof m.content === 'string' && m.content.trim().length > 0);

  const totalChars = messages.reduce((sum: number, m: any) => sum + (m.content?.length || 0), 0);
  if (messages.length === 0) {
    return sendJson(res, 400, { error: 'messages[] is required' });
  }
  if (totalChars > MAX_TOTAL_CHARS) {
    return sendJson(res, 400, { error: `messages too large (>${MAX_TOTAL_CHARS} chars)` });
  }

  const model = typeof payload?.model === 'string' && ALLOWED_MODELS.has(payload.model)
    ? payload.model
    : 'gpt-4o-mini';

  const max_tokens = clampNumber(payload?.max_tokens ?? payload?.maxTokens, 1, 1024, 512);
  const temperature = clampNumber(payload?.temperature, 0, 1, 0.7);

  // Minimal logging (no prompts)
  console.log('[api/ai/chat] request', {
    userId: user.id,
    model,
    messageCount: messages.length,
    totalChars,
    max_tokens,
  });

  const upstream = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model,
      messages,
      max_tokens,
      temperature,
      // OpenAI supports an optional "user" field for abuse monitoring.
      user: user.id,
    }),
  });

  const text = await upstream.text();

  if (!upstream.ok) {
    // Avoid leaking full payloads. Return a truncated upstream error message.
    return sendJson(res, upstream.status, {
      error: 'OpenAI request failed',
      status: upstream.status,
      message: truncateString(text, 500),
    });
  }

  let data: any;
  try {
    data = JSON.parse(text);
  } catch {
    return sendJson(res, 502, { error: 'Invalid OpenAI response' });
  }

  const content = data?.choices?.[0]?.message?.content;
  if (typeof content !== 'string') {
    return sendJson(res, 502, { error: 'OpenAI response missing content' });
  }

  return sendJson(res, 200, {
    content,
    model: data?.model || model,
    usage: data?.usage,
  });
}

import { getOpenAIEnv, getSupabaseEnv, sendJson, sendText } from '../../src/server/ai-proxy.js';

export const config = {
  runtime: 'nodejs',
};

export default async function handler(req: any, res: any) {
  if (req.method !== 'GET') {
    res.setHeader('Allow', 'GET');
    return sendText(res, 405, 'Method Not Allowed');
  }

  const { apiKey } = getOpenAIEnv();
  const { env: supabaseEnv, missing } = getSupabaseEnv();

  const openaiConfigured = !!apiKey;
  const supabaseConfigured = !!supabaseEnv;

  // "configured" means Demo Mode can actually function end-to-end (auth + OpenAI calls).
  const configured = openaiConfigured && supabaseConfigured;

  return sendJson(res, 200, {
    configured,
    openaiConfigured,
    supabaseConfigured,
    missing,
  });
}

import {
  getBearerToken,
  getOpenAIEnv,
  sendJson,
  sendText,
  truncateString,
  verifySupabaseJwt,
} from '../../src/server/ai-proxy.js';

export const config = {
  runtime: 'nodejs',
};

const MAX_FILE_BYTES = 10 * 1024 * 1024; // 10MB
const ALLOWED_MODELS = new Set(['whisper-1']);

export default async function handler(req: any, res: any) {
  if (req.method === 'OPTIONS') {
    res.statusCode = 204;
    res.setHeader('Allow', 'POST, OPTIONS');
    return res.end();
  }

  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST, OPTIONS');
    return sendText(res, 405, 'Method Not Allowed');
  }

  const { apiKey } = getOpenAIEnv();
  if (!apiKey) {
    return sendJson(res, 503, { error: 'OPENAI_API_KEY not configured' });
  }

  const token = getBearerToken(req);
  if (!token) {
    return sendJson(res, 401, { error: 'Missing Authorization bearer token' });
  }

  const user = await verifySupabaseJwt(token);
  if (!user) {
    return sendJson(res, 401, { error: 'Invalid Supabase session' });
  }

  // Parse multipart form
  let fields: any;
  let files: any;
  try {
    const mod: any = await import('formidable');
    const formidable = mod?.default || mod;
    const form = formidable({
      multiples: false,
      maxFileSize: MAX_FILE_BYTES,
      allowEmptyFiles: false,
      minFileSize: 1,
    });

    const parsed = await new Promise<any>((resolve, reject) => {
      form.parse(req, (err: any, flds: any, fls: any) => {
        if (err) return reject(err);
        resolve({ fields: flds, files: fls });
      });
    });

    fields = parsed.fields;
    files = parsed.files;
  } catch (e: any) {
    return sendJson(res, 400, { error: 'Invalid multipart form', message: e?.message });
  }

  const modelCandidate = typeof fields?.model === 'string' ? fields.model : 'whisper-1';
  const model = ALLOWED_MODELS.has(modelCandidate) ? modelCandidate : 'whisper-1';

  const file = files?.file || files?.audio || files?.blob;
  const picked = Array.isArray(file) ? file[0] : file;

  if (!picked?.filepath) {
    return sendJson(res, 400, { error: 'Missing audio file field (expected: file)' });
  }

  const fs = await import('node:fs/promises');
  const buf = await fs.readFile(picked.filepath);

  if (buf.length > MAX_FILE_BYTES) {
    return sendJson(res, 413, { error: `File too large (>${MAX_FILE_BYTES} bytes)` });
  }

  const filename = truncateString(picked.originalFilename || 'audio.webm', 200);
  const mimeType = truncateString(picked.mimetype || 'application/octet-stream', 200);

  console.log('[api/ai/stt] request', {
    userId: user.id,
    fileBytes: buf.length,
    mimeType,
    model,
  });

  const formData = new FormData();
  formData.append('file', new Blob([buf], { type: mimeType }), filename);
  formData.append('model', model);

  const upstream = await fetch('https://api.openai.com/v1/audio/transcriptions', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${apiKey}`,
    },
    body: formData,
  });

  const text = await upstream.text();

  if (!upstream.ok) {
    return sendJson(res, upstream.status, {
      error: 'OpenAI request failed',
      status: upstream.status,
      message: truncateString(text, 500),
    });
  }

  let data: any;
  try {
    data = JSON.parse(text);
  } catch {
    return sendJson(res, 502, { error: 'Invalid OpenAI response' });
  }

  const transcript = data?.text;
  if (typeof transcript !== 'string') {
    return sendJson(res, 502, { error: 'OpenAI response missing text' });
  }

  return sendJson(res, 200, { text: transcript });
}

import {
  clampNumber,
  getBearerToken,
  getOpenAIEnv,
  readJson,
  sendJson,
  sendText,
  truncateString,
  verifySupabaseJwt,
} from '../../src/server/ai-proxy.js';

export const config = {
  runtime: 'nodejs',
};

const ALLOWED_MODELS = new Set(['tts-1', 'tts-1-hd']);
const ALLOWED_VOICES = new Set(['alloy', 'ash', 'coral', 'echo', 'fable', 'nova', 'onyx', 'sage', 'shimmer']);

const MAX_BODY_BYTES = 64 * 1024; // 64KB
const MAX_INPUT_CHARS = 4096;

export default async function handler(req: any, res: any) {
  if (req.method === 'OPTIONS') {
    res.statusCode = 204;
    res.setHeader('Allow', 'POST, OPTIONS');
    return res.end();
  }

  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST, OPTIONS');
    return sendText(res, 405, 'Method Not Allowed');
  }

  const { apiKey } = getOpenAIEnv();
  if (!apiKey) {
    return sendJson(res, 503, { error: 'OPENAI_API_KEY not configured' });
  }

  const token = getBearerToken(req);
  if (!token) {
    return sendJson(res, 401, { error: 'Missing Authorization bearer token' });
  }

  const user = await verifySupabaseJwt(token);
  if (!user) {
    return sendJson(res, 401, { error: 'Invalid Supabase session' });
  }

  let payload: any;
  try {
    payload = await readJson(req, MAX_BODY_BYTES);
  } catch (e: any) {
    return sendJson(res, 400, { error: e?.message || 'Invalid request body' });
  }

  const inputRaw = payload?.input ?? payload?.text;
  const input = truncateString(inputRaw, MAX_INPUT_CHARS).trim();
  if (!input) {
    return sendJson(res, 400, { error: 'input/text is required' });
  }

  const model = typeof payload?.model === 'string' && ALLOWED_MODELS.has(payload.model)
    ? payload.model
    : 'tts-1';

  const voice = typeof payload?.voice === 'string' && ALLOWED_VOICES.has(payload.voice)
    ? payload.voice
    : 'nova';

  const speed = clampNumber(payload?.speed, 0.5, 2.0, 1.0);

  console.log('[api/ai/tts] request', {
    userId: user.id,
    model,
    voice,
    inputChars: input.length,
  });

  const upstream = await fetch('https://api.openai.com/v1/audio/speech', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      model,
      input,
      voice,
      response_format: 'mp3',
      speed,
    }),
  });

  if (!upstream.ok) {
    const text = await upstream.text();
    return sendJson(res, upstream.status, {
      error: 'OpenAI request failed',
      status: upstream.status,
      message: truncateString(text, 500),
    });
  }

  const arrayBuffer = await upstream.arrayBuffer();
  const buf = Buffer.from(arrayBuffer);

  res.statusCode = 200;
  res.setHeader('Content-Type', 'audio/mpeg');
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('Content-Length', String(buf.length));
  res.end(buf);
}

import { Toaster } from "@/components/ui/toaster";
import { Toaster as Sonner } from "@/components/ui/sonner";
import { TooltipProvider } from "@/components/ui/tooltip";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { BrowserRouter, Routes, Route, useLocation } from "react-router-dom";
import { AuthProvider } from "@/contexts/AuthContext";
import { VoiceProvider } from "@/contexts/VoiceContext";
import { ErrorBoundary } from "@/components/ErrorBoundary";
import { trackError } from "@/services/analytics";
import { usePageTracking } from "@/hooks/usePageTracking";
import ModelDownloadProgress from "@/components/ModelDownloadProgress";
import ProgressiveOnboarding from "@/components/ProgressiveOnboarding";
import { useGlobalShortcuts } from "@/hooks/useKeyboardShortcuts";
import { useVoicePreferences } from "@/hooks/useVoicePreferences";
import { useProfileSync } from "@/hooks/useProfileSync";
import { useAPIKeySync } from "@/hooks/useAPIKeySync";
import KeyboardShortcutsHelp from "@/components/KeyboardShortcutsHelp";
import OnboardingTour from "@/components/OnboardingTour";
import QuickAddModal, { useQuickAdd } from "@/components/QuickAddModal";
import { lazy, Suspense } from "react";
import NavBar from "@/components/NavBar";
import { Loader2 } from "lucide-react";

// Eager load critical pages
import Index from "./pages/Index";
import Login from "./pages/Login";
import NotFound from "./pages/NotFound";
import Marketing from "./pages/Marketing";

// Lazy load all other pages
const Chat = lazy(() => import("./pages/Chat"));
const VoiceChat = lazy(() => import("./pages/VoiceChat"));
const Settings = lazy(() => import("./pages/Settings"));
const Tools = lazy(() => import("./pages/Tools"));
const History = lazy(() => import("./pages/History"));
const Debug = lazy(() => import("./pages/Debug"));
const Knowledge = lazy(() => import("./pages/Knowledge"));
const KnowledgeBase = lazy(() => import("./pages/KnowledgeBase"));
const Profile = lazy(() => import("./pages/Profile"));
const Integrations = lazy(() => import("./pages/Integrations"));
const Tasks = lazy(() => import("./pages/Tasks"));
const Reminders = lazy(() => import("./pages/Reminders"));
const Notes = lazy(() => import("./pages/Notes"));
const Calendar = lazy(() => import("./pages/Calendar"));
const Notifications = lazy(() => import("./pages/Notifications"));
const Contacts = lazy(() => import("./pages/Contacts"));
const Messages = lazy(() => import("./pages/Messages"));
const Appointments = lazy(() => import("./pages/Appointments"));
const AILogs = lazy(() => import("./pages/AILogs"));
const Drafts = lazy(() => import("./pages/Drafts"));
const BookingTasks = lazy(() => import("./pages/BookingTasks"));
const Documents = lazy(() => import("./pages/Documents"));
const ListeningSessions = lazy(() => import("./pages/ListeningSessions"));
const DataManagement = lazy(() => import("./pages/DataManagement"));
const Analytics = lazy(() => import("./pages/Analytics"));
const Privacy = lazy(() => import("./pages/Privacy"));
const Terms = lazy(() => import("./pages/Terms"));
const SecondBrainPage = lazy(() => import("./pages/SecondBrain"));

// Loading fallback component
const PageLoader = () => (
  <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 flex items-center justify-center">
    <div className="text-center">
      <Loader2 className="h-8 w-8 text-fuchsia-400 animate-spin mx-auto mb-3" />
      <p className="text-sm text-slate-400">Loading...</p>
    </div>
  </div>
);
import MicButton from "@/components/MicButton";
import FloatingVoiceWidget from "@/components/FloatingVoiceWidget";
import VoiceStatusIndicator from "@/components/VoiceStatusIndicator";
import ListeningModeIndicator from "@/components/ListeningModeIndicator";
import SecondBrainIndicator from "@/components/SecondBrainIndicator";
import VoiceCommandPalette, { useCommandPalette } from "@/components/VoiceCommandPalette";
import ProtectedRoute from "@/components/ProtectedRoute";
import QuickAccessPanel from "@/components/QuickAccessPanel";
import ThumbsPanel from "@/components/ThumbsPanel";

const queryClient = new QueryClient();

// Wrapper component for command palette
function CommandPaletteWrapper() {
  const { isOpen, close } = useCommandPalette();
  return <VoiceCommandPalette open={isOpen} onClose={close} />;
}

// Wrapper component for global keyboard shortcuts
function GlobalShortcutsWrapper() {
  useGlobalShortcuts();
  return null;
}

// Wrapper component for voice preferences
function VoicePreferencesWrapper() {
  useVoicePreferences();
  return null;
}

// Wrapper component for profile sync (loads profile name on startup)
function ProfileSyncWrapper() {
  useProfileSync();
  return null;
}

// Wrapper component for API key sync (syncs OpenAI key to providers)
function APIKeySyncWrapper() {
  useAPIKeySync();
  return null;
}

// Wrapper component for page tracking
function PageTrackingWrapper() {
  usePageTracking();
  return null;
}

// Wrapper component for quick add modal
function QuickAddWrapper() {
  const { isOpen, close, defaultTab } = useQuickAdd();
  return <QuickAddModal open={isOpen} onClose={close} defaultTab={defaultTab} />;
}

// Conditional NavBar - hide on marketing page
function ConditionalNavBar() {
  const location = useLocation();
  const isMarketingPage = location.pathname === "/";
  
  if (isMarketingPage) return null;
  return <NavBar />;
}

// Conditional App Chrome - hide voice widgets on marketing page
function ConditionalAppChrome() {
  const location = useLocation();
  const isMarketingPage = location.pathname === "/";
  
  if (isMarketingPage) return null;
  
  return (
    <>
      <VoiceStatusIndicator />
      <CommandPaletteWrapper />
      <GlobalShortcutsWrapper />
      <VoicePreferencesWrapper />
      <KeyboardShortcutsHelp />
      <OnboardingTour />
      <QuickAddWrapper />
      <MicButton />
      <FloatingVoiceWidget />
      <ListeningModeIndicator />
      <SecondBrainIndicator position="top-right" />
      <QuickAccessPanel />
      <ThumbsPanel />
      <ModelDownloadProgress />
      <ProgressiveOnboarding />
    </>
  );
}

// Safe error tracking that won't throw
const safeTrackError = (message: string, details: any) => {
  try {
    trackError(message, details);
  } catch (e) {
    console.error('[App] Error tracking failed:', e);
  }
};

const App = () => (
  <ErrorBoundary onError={(error, errorInfo) => {
    safeTrackError(error.message, {
      stack: error.stack,
      componentStack: errorInfo.componentStack,
    });
  }}>
    <QueryClientProvider client={queryClient}>
      <AuthProvider>
      <TooltipProvider>
        <Toaster />
        <Sonner />
        <BrowserRouter future={{ v7_startTransition: true, v7_relativeSplatPath: true }}>
          <VoiceProvider>
            <ConditionalNavBar />
            <PageTrackingWrapper />
            <ProfileSyncWrapper />
            <APIKeySyncWrapper />
            <Suspense fallback={<PageLoader />}>
              <Routes>
                {/* Public routes */}
                <Route path="/" element={<Marketing />} />
                <Route path="/login" element={<Login />} />
                <Route path="/privacy" element={<Privacy />} />
                <Route path="/terms" element={<Terms />} />
                
                {/* Protected app routes */}
                <Route
                  path="/app"
                  element={
                    <ProtectedRoute>
                      <Index />
                    </ProtectedRoute>
                  }
                />
                <Route
                  path="/voice"
                  element={
                    <ProtectedRoute>
                      <VoiceChat />
                    </ProtectedRoute>
                  }
                />
              <Route
                path="/chat"
                element={
                  <ProtectedRoute>
                    <Chat />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/settings"
                element={
                  <ProtectedRoute>
                    <Settings />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/tools"
                element={
                  <ProtectedRoute>
                    <Tools />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/knowledge"
                element={
                  <ProtectedRoute>
                    <Knowledge />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/knowledge-base"
                element={
                  <ProtectedRoute>
                    <KnowledgeBase />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/history"
                element={
                  <ProtectedRoute>
                    <History />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/debug"
                element={
                  <ProtectedRoute>
                    <Debug />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/profile"
                element={
                  <ProtectedRoute>
                    <Profile />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/integrations"
                element={
                  <ProtectedRoute>
                    <Integrations />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/tasks"
                element={
                  <ProtectedRoute>
                    <Tasks />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/reminders"
                element={
                  <ProtectedRoute>
                    <Reminders />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/notes"
                element={
                  <ProtectedRoute>
                    <Notes />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/calendar"
                element={
                  <ProtectedRoute>
                    <Calendar />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/notifications"
                element={
                  <ProtectedRoute>
                    <Notifications />
                  </ProtectedRoute>
                  }
              />
              <Route
                path="/contacts"
                element={
                  <ProtectedRoute>
                    <Contacts />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/messages"
                element={
                  <ProtectedRoute>
                    <Messages />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/appointments"
                element={
                  <ProtectedRoute>
                    <Appointments />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/ai-logs"
                element={
                  <ProtectedRoute>
                    <AILogs />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/drafts"
                element={
                  <ProtectedRoute>
                    <Drafts />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/booking-tasks"
                element={
                  <ProtectedRoute>
                    <BookingTasks />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/documents"
                element={
                  <ProtectedRoute>
                    <Documents />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/listening-sessions"
                element={
                  <ProtectedRoute>
                    <ListeningSessions />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/data-management"
                element={
                  <ProtectedRoute>
                    <DataManagement />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/analytics"
                element={
                  <ProtectedRoute>
                    <Analytics />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/second-brain"
                element={
                  <ProtectedRoute>
                    <SecondBrainPage />
                  </ProtectedRoute>
                }
              />
              <Route path="*" element={<NotFound />} />
            </Routes>
            </Suspense>
            <ConditionalAppChrome />
          </VoiceProvider>
        </BrowserRouter>
      </TooltipProvider>
      </AuthProvider>
    </QueryClientProvider>
  </ErrorBoundary>
);

export default App;

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Loader2, Sparkles, CheckCircle, XCircle } from "lucide-react";
import { showSuccess, showError } from "@/utils/toast";

interface AITestButtonProps {
  apiKey: string;
  provider?: "openai" | "anthropic";
}

export default function AITestButton({ apiKey, provider = "openai" }: AITestButtonProps) {
  const [testing, setTesting] = useState(false);
  const [result, setResult] = useState<"success" | "error" | null>(null);

  const testConnection = async () => {
    if (!apiKey) {
      showError("Please enter an API key first");
      return;
    }

    setTesting(true);
    setResult(null);

    try {
      if (provider === "openai") {
        const response = await fetch("https://api.openai.com/v1/chat/completions", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${apiKey}`,
          },
          body: JSON.stringify({
            model: "gpt-4o-mini",
            messages: [{ role: "user", content: "Say 'Hello! Connection successful.' in exactly those words." }],
            max_tokens: 20,
          }),
        });

        if (!response.ok) {
          const error = await response.text();
          throw new Error(error);
        }

        const data = await response.json();
        const content = data.choices[0].message.content;
        
        setResult("success");
        showSuccess(`AI responded: "${content.substring(0, 50)}..."`);
      } else if (provider === "anthropic") {
        const response = await fetch("https://api.anthropic.com/v1/messages", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "x-api-key": apiKey,
            "anthropic-version": "2023-06-01",
          },
          body: JSON.stringify({
            model: "claude-3-haiku-20240307",
            max_tokens: 20,
            messages: [{ role: "user", content: "Say 'Hello! Connection successful.' in exactly those words." }],
          }),
        });

        if (!response.ok) {
          const error = await response.text();
          throw new Error(error);
        }

        const data = await response.json();
        const content = data.content[0].text;
        
        setResult("success");
        showSuccess(`AI responded: "${content.substring(0, 50)}..."`);
      }
    } catch (error: any) {
      setResult("error");
      showError(`Connection failed: ${error.message?.substring(0, 100) || "Unknown error"}`);
    }

    setTesting(false);
  };

  return (
    <Button
      onClick={testConnection}
      disabled={testing || !apiKey}
      variant="outline"
      className="border-fuchsia-500/50 text-fuchsia-300 hover:bg-fuchsia-500/20"
    >
      {testing ? (
        <>
          <Loader2 className="h-4 w-4 mr-2 animate-spin" />
          Testing...
        </>
      ) : result === "success" ? (
        <>
          <CheckCircle className="h-4 w-4 mr-2 text-green-400" />
          Connected
        </>
      ) : result === "error" ? (
        <>
          <XCircle className="h-4 w-4 mr-2 text-red-400" />
          Failed
        </>
      ) : (
        <>
          <Sparkles className="h-4 w-4 mr-2" />
          Test AI
        </>
      )}
    </Button>
  );
}

