const STORAGE_KEY = "echo:onboarding-completed";

interface TourStep {
  title: string;
  description: string;
  icon: React.ReactNode;
  tips: string[];
  color: string;
}

const TOUR_STEPS: TourStep[] = [
  {
    title: "Welcome to Echo!",
