                    : index < currentStep
                    ? "w-1.5 bg-fuchsia-500/50"
                    : "w-1.5 bg-slate-700"
                )}
              />
            ))}
          </div>
        </DialogHeader>

        <div className="py-6 text-center overflow-y-auto scrollbar-hide flex-1">
          <div className={cn("mx-auto mb-4", step.color)}>
            {step.icon}
          </div>
          <DialogTitle className="text-xl text-white mb-2">
            {step.title}
          </DialogTitle>
          <p id="onboarding-description" className="text-slate-400 mb-6">{step.description}</p>

          <div className="space-y-2 text-left">
            {step.tips.map((tip, index) => (
              <div
                key={index}
                className="flex items-start gap-2 p-2 rounded-lg bg-slate-800/50"
              >
                <Badge
                  variant="outline"
                  className="border-slate-600 text-slate-400 text-xs shrink-0"
                >
                  {index + 1}
                </Badge>
                <span className="text-sm text-slate-300">{tip}</span>
              </div>
            ))}
          </div>
        </div>

        <DialogFooter className="flex justify-between items-center">
          <div className="flex gap-2">
            <Button
              variant="ghost"
              onClick={handlePrev}
              disabled={currentStep === 0}
              className="text-slate-400 hover:text-white"
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back
            </Button>
            <Button
              variant="ghost"
              onClick={handleSkip}
              className="text-slate-500 hover:text-slate-300"
            >
              Skip Tour
            </Button>
          </div>
          <Button
            onClick={handleNext}
            className="bg-fuchsia-600 hover:bg-fuchsia-500 text-white"
          >
            {currentStep === TOUR_STEPS.length - 1 ? (
              "Get Started"
            ) : (
              <>
                Next
                <ArrowRight className="h-4 w-4 ml-2" />
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

