export default function VoiceCommandPalette({ open, onClose }: VoiceCommandPaletteProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const { startListening, isListening, isProcessing } = useVoice();

  // Filter commands based on search
  const filteredCategories = COMMAND_CATEGORIES.map(category => ({
    ...category,
    commands: category.commands.filter(
      cmd =>
        cmd.phrase.toLowerCase().includes(searchQuery.toLowerCase()) ||
        cmd.description.toLowerCase().includes(searchQuery.toLowerCase())
    ),
  })).filter(category => 
    selectedCategory ? category.name === selectedCategory : category.commands.length > 0
  );

  const handleVoiceActivate = async () => {
    onClose();
    await startListening();
  };

  // Keyboard shortcut to open
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        if (open) {
          onClose();
        }
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [open, onClose]);

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="bg-slate-900 border-slate-700 max-w-2xl p-0 gap-0">
        {/* Search Header */}
        <div className="flex items-center gap-3 p-4 border-b border-slate-700">
          <Search className="h-5 w-5 text-slate-400" />
          <Input
            placeholder="Search voice commands..."
            className="border-0 bg-transparent text-white placeholder:text-slate-500 focus-visible:ring-0 p-0 h-auto text-lg"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            autoFocus
          />
          <button
            onClick={handleVoiceActivate}
            disabled={isListening || isProcessing}
            className={`p-2 rounded-lg transition-colors ${
              isListening 
                ? "bg-red-500/20 text-red-400" 
                : "bg-fuchsia-500/20 text-fuchsia-400 hover:bg-fuchsia-500/30"
            }`}
          >
            <Mic className={`h-5 w-5 ${isListening ? "animate-pulse" : ""}`} />
          </button>
        </div>

        {/* Category Tabs */}
        <div className="flex gap-1 p-2 border-b border-slate-800 overflow-x-auto">
          <button
            onClick={() => setSelectedCategory(null)}
            className={`px-3 py-1.5 rounded-md text-xs font-medium transition-colors whitespace-nowrap ${
              !selectedCategory 
                ? "bg-fuchsia-500/20 text-fuchsia-300" 
                : "text-slate-400 hover:text-white hover:bg-slate-800"
            }`}
          >
            All
          </button>
          {COMMAND_CATEGORIES.map(category => (
            <button
              key={category.name}
              onClick={() => setSelectedCategory(category.name)}
              className={`px-3 py-1.5 rounded-md text-xs font-medium transition-colors whitespace-nowrap flex items-center gap-1.5 ${
                selectedCategory === category.name 
                  ? "bg-fuchsia-500/20 text-fuchsia-300" 
                  : "text-slate-400 hover:text-white hover:bg-slate-800"
              }`}
            >
              <category.icon className={`h-3 w-3 ${category.color}`} />
              {category.name}
            </button>
          ))}
        </div>

        {/* Commands List */}
        <ScrollArea className="h-[400px]">
          <div className="p-2">
            {filteredCategories.length === 0 ? (
              <div className="text-center py-8 text-slate-400">
                <Search className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No commands found</p>
              </div>
            ) : (
              filteredCategories.map(category => (
                <div key={category.name} className="mb-4">
                  <div className="flex items-center gap-2 px-2 py-1 text-xs font-medium text-slate-500 uppercase">
                    <category.icon className={`h-3 w-3 ${category.color}`} />
                    {category.name}
                  </div>
                  <div className="space-y-1">
                    {category.commands.map((cmd, idx) => (
                      <button
                        key={idx}
                        onClick={handleVoiceActivate}
                        className="w-full flex items-center justify-between p-2 rounded-lg hover:bg-slate-800 transition-colors group"
                      >
                        <div className="flex items-center gap-3">
                          <div className={`p-1.5 rounded-md bg-slate-800 group-hover:bg-slate-700 ${category.color}`}>
                            <Volume2 className="h-3 w-3" />
                          </div>
                          <div className="text-left">
                            <p className="text-sm text-white">"{cmd.phrase}"</p>
                            <p className="text-xs text-slate-500">{cmd.description}</p>
                          </div>
                        </div>
                        <Mic className="h-4 w-4 text-slate-600 group-hover:text-fuchsia-400 transition-colors" />
                      </button>
                    ))}
                  </div>
                </div>
              ))
            )}
          </div>
        </ScrollArea>

        {/* Footer */}
        <div className="flex items-center justify-between p-3 border-t border-slate-800 text-xs text-slate-500">
          <div className="flex items-center gap-4">
            <span className="flex items-center gap-1">
              <Keyboard className="h-3 w-3" />
              <kbd className="px-1.5 py-0.5 rounded bg-slate-800 text-slate-400">ΓîÿK</kbd>
              to open
            </span>
            <span className="flex items-center gap-1">
              <Mic className="h-3 w-3" />
              Click mic to speak
            </span>
          </div>
          <span>Tap any command to activate voice</span>
        </div>
      </DialogContent>
    </Dialog>
  );
}

// Hook to manage command palette state
export function useCommandPalette() {
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Don't open on login page
      if (window.location.pathname === "/login") {
        return;
      }
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        setIsOpen(prev => !prev);
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  return {
    isOpen,
    open: () => {
      // Don't open on login page
      if (window.location.pathname === "/login") {
        return;
      }
      setIsOpen(true);
    },
    close: () => setIsOpen(false),
    toggle: () => {
      // Don't toggle on login page
      if (window.location.pathname === "/login") {
        return;
      }
      setIsOpen(prev => !prev);
    },
  };
}

import { useEffect, useRef } from "react";
import { usePreferences } from "@/state/preferences";

interface VoiceFeedbackProps {
  type: "start" | "stop" | "success" | "error";
  enabled?: boolean;
}

// Simple audio feedback using Web Audio API
export default function VoiceFeedback({ type, enabled = true }: VoiceFeedbackProps) {
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    if (!enabled) return;

    // Create audio context on first interaction
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }

    const ctx = audioContextRef.current;
    if (ctx.state === "suspended") {
      ctx.resume();
    }

    const oscillator = ctx.createOscillator();
    const gainNode = ctx.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(ctx.destination);

    // Different sounds for different feedback types
    switch (type) {
      case "start":
        // Rising tone
        oscillator.frequency.setValueAtTime(400, ctx.currentTime);
        oscillator.frequency.linearRampToValueAtTime(600, ctx.currentTime + 0.1);
        gainNode.gain.setValueAtTime(0.1, ctx.currentTime);
        gainNode.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.15);
        break;
      case "stop":
        // Falling tone
        oscillator.frequency.setValueAtTime(600, ctx.currentTime);
        oscillator.frequency.linearRampToValueAtTime(400, ctx.currentTime + 0.1);
        gainNode.gain.setValueAtTime(0.1, ctx.currentTime);
        gainNode.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.15);
        break;
      case "success":
        // Happy double beep
        oscillator.frequency.setValueAtTime(523, ctx.currentTime); // C5
        oscillator.frequency.setValueAtTime(659, ctx.currentTime + 0.1); // E5
        gainNode.gain.setValueAtTime(0.1, ctx.currentTime);
        gainNode.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.2);
        break;
      case "error":
        // Low buzz
        oscillator.frequency.setValueAtTime(200, ctx.currentTime);
        oscillator.type = "sawtooth";
        gainNode.gain.setValueAtTime(0.1, ctx.currentTime);
        gainNode.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.3);
        break;
    }

    oscillator.start(ctx.currentTime);
    oscillator.stop(ctx.currentTime + 0.3);

    return () => {
      oscillator.disconnect();
      gainNode.disconnect();
    };
  }, [type, enabled]);

  return null;
}

// Hook for playing feedback sounds
export function useVoiceFeedback() {
  const audioContextRef = useRef<AudioContext | null>(null);
  const { preferences } = usePreferences();

  const playFeedback = (type: "start" | "stop" | "success" | "error") => {
    // Check if feedback is enabled
    if (!preferences.voiceFeedbackEnabled) return;

    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }

    const ctx = audioContextRef.current;
    if (ctx.state === "suspended") {
      ctx.resume();
    }

    const oscillator = ctx.createOscillator();
    const gainNode = ctx.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(ctx.destination);

    const volume = (preferences.voiceFeedbackVolume || 0.5) * 0.15; // Scale to reasonable level

    switch (type) {
      case "start":
        oscillator.frequency.setValueAtTime(400, ctx.currentTime);
        oscillator.frequency.linearRampToValueAtTime(600, ctx.currentTime + 0.1);
        gainNode.gain.setValueAtTime(volume, ctx.currentTime);
        gainNode.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.15);
        break;
      case "stop":
        oscillator.frequency.setValueAtTime(600, ctx.currentTime);
        oscillator.frequency.linearRampToValueAtTime(400, ctx.currentTime + 0.1);
        gainNode.gain.setValueAtTime(volume, ctx.currentTime);
        gainNode.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.15);
        break;
      case "success":
        oscillator.frequency.setValueAtTime(523, ctx.currentTime);
        oscillator.frequency.setValueAtTime(659, ctx.currentTime + 0.1);
        gainNode.gain.setValueAtTime(volume, ctx.currentTime);
        gainNode.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.2);
        break;
      case "error":
        oscillator.frequency.setValueAtTime(200, ctx.currentTime);
        oscillator.type = "sawtooth";
        gainNode.gain.setValueAtTime(volume, ctx.currentTime);
        gainNode.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.3);
        break;
    }

    oscillator.start(ctx.currentTime);
    oscillator.stop(ctx.currentTime + 0.3);
  };

  return { playFeedback };
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Badge } from "@/components/ui/badge";
import { Mic, Volume2, Clock, Trash2, ChevronDown, ChevronUp } from "lucide-react";
import { format } from "date-fns";

interface VoiceInteraction {
  id: string;
  userText: string;
  assistantText: string;
  timestamp: number;
  toolsUsed?: string[];
}

const STORAGE_KEY = "echo:voice-history";
const MAX_HISTORY = 20;

export function saveVoiceInteraction(interaction: Omit<VoiceInteraction, "id">) {
  try {
    const existing = getVoiceHistory();
    const newInteraction: VoiceInteraction = {
      ...interaction,
      id: crypto.randomUUID(),
    };
    const updated = [newInteraction, ...existing].slice(0, MAX_HISTORY);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  } catch (error) {
    console.error("Failed to save voice interaction:", error);
  }
}

export function getVoiceHistory(): VoiceInteraction[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

export function clearVoiceHistory() {
  localStorage.removeItem(STORAGE_KEY);
}

interface VoiceHistoryProps {
  className?: string;
  maxItems?: number;
  showClear?: boolean;
}

export default function VoiceHistory({ className = "", maxItems = 5, showClear = true }: VoiceHistoryProps) {
  const [history, setHistory] = useState<VoiceInteraction[]>([]);
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    setHistory(getVoiceHistory());
    
    // Listen for storage changes
    const handleStorage = () => setHistory(getVoiceHistory());
    window.addEventListener("storage", handleStorage);
    return () => window.removeEventListener("storage", handleStorage);
  }, []);

  const handleClear = () => {
    clearVoiceHistory();
    setHistory([]);
  };

  const displayedHistory = expanded ? history : history.slice(0, maxItems);

  if (history.length === 0) {
    return null;
  }

  return (
    <Card className={`border-fuchsia-500/20 bg-black/30 backdrop-blur ${className}`}>
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm font-medium text-white flex items-center gap-2">
            <Clock className="h-4 w-4 text-fuchsia-400" />
            Recent Voice Commands
          </CardTitle>
          {showClear && (
            <Button
              variant="ghost"
              size="sm"
              onClick={handleClear}
              className="text-slate-400 hover:text-red-400 h-7 px-2"
            >
              <Trash2 className="h-3 w-3" />
            </Button>
          )}
        </div>
      </CardHeader>
      <CardContent className="pt-0">
        <ScrollArea className={expanded ? "h-[300px]" : ""}>
          <div className="space-y-2">
            {displayedHistory.map((interaction) => (
              <div
                key={interaction.id}
                className="p-2 rounded-lg bg-slate-800/50 border border-slate-700/50"
              >
                <div className="flex items-start gap-2">
                  <Mic className="h-3 w-3 text-fuchsia-400 mt-1 shrink-0" />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-white truncate">"{interaction.userText}"</p>
                    <p className="text-xs text-slate-400 truncate mt-0.5">
                      {interaction.assistantText.slice(0, 60)}...
                    </p>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-[10px] text-slate-500">
                        {format(interaction.timestamp, "h:mm a")}
                      </span>
                      {interaction.toolsUsed && interaction.toolsUsed.length > 0 && (
                        <Badge variant="outline" className="text-[10px] py-0 px-1 border-slate-600 text-slate-400">
                          {interaction.toolsUsed[0]}
                        </Badge>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </ScrollArea>
        
        {history.length > maxItems && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setExpanded(!expanded)}
            className="w-full mt-2 text-slate-400 hover:text-white h-7"
          >
            {expanded ? (
              <>
                <ChevronUp className="h-3 w-3 mr-1" />
                Show less
              </>
            ) : (
              <>
                <ChevronDown className="h-3 w-3 mr-1" />
                Show {history.length - maxItems} more
              </>
            )}
          </Button>
        )}
      </CardContent>
    </Card>
  );
}

