"use client";

import React, { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { showSuccess, showError } from "@/utils/toast";
import {
  Activity,
  CheckSquare,
  Bell,
  FileText,
  Calendar,
  MessageSquare,
  Search,
  Brain,
  RefreshCw,
  Filter,
  Undo2,
  ExternalLink
} from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { Link } from "react-router-dom";

interface ActivityItem {
  id: string;
  type: "task" | "reminder" | "note" | "event" | "message" | "search" | "knowledge" | "action";
  title: string;
  timestamp: string;
  action?: string;
  canUndo?: boolean;
}

const TYPE_ICONS: Record<string, React.ComponentType<{ className?: string }>> = {
  task: CheckSquare,
  reminder: Bell,
  note: FileText,
  event: Calendar,
  message: MessageSquare,
  search: Search,
  knowledge: Brain,
  action: Activity,
};

const TYPE_COLORS: Record<string, string> = {
  task: "text-green-400",
  reminder: "text-yellow-400",
  note: "text-orange-400",
  event: "text-blue-400",
  message: "text-emerald-400",
  search: "text-fuchsia-400",
  knowledge: "text-purple-400",
  action: "text-cyan-400",
};

const TYPE_BG_COLORS: Record<string, string> = {
  task: "bg-green-500/10",
  reminder: "bg-yellow-500/10",
  note: "bg-orange-500/10",
  event: "bg-blue-500/10",
  message: "bg-emerald-500/10",
  search: "bg-fuchsia-500/10",
  knowledge: "bg-purple-500/10",
  action: "bg-cyan-500/10",
};

export default function RecentActivityWidget() {
  const { user } = useAuth();
  const [activities, setActivities] = useState<ActivityItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterType, setFilterType] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<"all" | "today">("all");

  useEffect(() => {
    if (user) loadRecentActivity();
  }, [user, viewMode]);

  const loadRecentActivity = async () => {
    if (!user) return;
    setLoading(true);

    try {
      const timeFilter = viewMode === "today" 
        ? new Date(new Date().setHours(0, 0, 0, 0)).toISOString()
        : new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();

      const [tasks, reminders, notes, events, actionHistory] = await Promise.all([
        supabase
          .from("tasks")
          .select("id, title, created_at")
          .eq("user_id", user.id)
          .gte("created_at", timeFilter)
          .order("created_at", { ascending: false })
          .limit(5),
        supabase
          .from("reminders")
          .select("id, text, created_at")
          .eq("user_id", user.id)
          .gte("created_at", timeFilter)
          .order("created_at", { ascending: false })
          .limit(5),
        supabase
          .from("notes")
          .select("id, title, created_at")
          .eq("user_id", user.id)
          .gte("created_at", timeFilter)
          .order("created_at", { ascending: false })
          .limit(5),
        supabase
          .from("calendar_events")
          .select("id, title, created_at")
          .eq("user_id", user.id)
          .gte("created_at", timeFilter)
          .order("created_at", { ascending: false })
          .limit(5),
        supabase
          .from("action_history")
          .select("id, action_type, entity_type, can_undo, created_at")
          .eq("user_id", user.id)
          .gte("created_at", timeFilter)
          .order("created_at", { ascending: false })
          .limit(5),
      ]);

      const items: ActivityItem[] = [];

      if (tasks.data) {
        items.push(...tasks.data.map(t => ({
          id: t.id,
          type: "task" as const,
          title: t.title,
          timestamp: t.created_at,
        })));
      }

      if (reminders.data) {
        items.push(...reminders.data.map(r => ({
          id: r.id,
          type: "reminder" as const,
          title: r.text,
          timestamp: r.created_at,
        })));
      }

      if (notes.data) {
        items.push(...notes.data.map(n => ({
          id: n.id,
          type: "note" as const,
          title: n.title,
          timestamp: n.created_at,
        })));
      }

      if (events.data) {
        items.push(...events.data.map(e => ({
          id: e.id,
          type: "event" as const,
          title: e.title,
          timestamp: e.created_at,
        })));
      }

      if (actionHistory.data) {
        items.push(...actionHistory.data.map(a => ({
          id: a.id,
          type: "action" as const,
          title: `${a.action_type} ${a.entity_type}`,
          timestamp: a.created_at,
          action: a.action_type,
          canUndo: a.can_undo,
        })));
      }

      items.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
      setActivities(items.slice(0, 20));
    } catch (error) {
      console.error("Failed to load recent activity:", error);
    }

    setLoading(false);
  };

  const undoAction = async (actionId: string) => {
    try {
      const { data: action } = await supabase
        .from("action_history")
        .select("*")
        .eq("id", actionId)
        .single();

      if (!action || !action.can_undo || action.undone) {
        showError("Cannot undo this action");
        return;
      }

      // Mark as undone
      await supabase
        .from("action_history")
        .update({ undone: true })
        .eq("id", actionId);

      showSuccess("Action undone!");
      loadRecentActivity();
    } catch (error) {
      showError("Failed to undo action");
    }
  };

  const filteredActivities = filterType 
    ? activities.filter(a => a.type === filterType)
    : activities;

  const activityTypes = Array.from(new Set(activities.map(a => a.type)));

  if (loading) {
    return (
      <Card className="border-slate-700 bg-slate-800/50 backdrop-blur h-full w-full overflow-hidden flex flex-col">
        <CardHeader className="p-3 pb-2 shrink-0">
          <CardTitle className="text-sm text-white flex items-center gap-2">
            <Activity className="h-4 w-4 text-fuchsia-400" />
            Recent Activity
          </CardTitle>
        </CardHeader>
        <CardContent className="p-3 pt-0 flex-1 min-h-0 flex items-center justify-center">
          <div className="animate-pulse text-slate-400 text-xs">Loading...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-slate-700 bg-slate-800/50 backdrop-blur h-full w-full overflow-hidden flex flex-col">
      <CardHeader className="p-3 pb-2 shrink-0">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm text-white flex items-center gap-2">
            <Activity className="h-4 w-4 text-fuchsia-400" />
            Recent Activity
          </CardTitle>
          <div className="flex items-center gap-1">
            <Button
              size="sm"
              variant="ghost"
              onClick={() => setViewMode(viewMode === "all" ? "today" : "all")}
              className="h-6 px-2 text-[10px] text-slate-400 hover:text-white"
            >
              {viewMode === "all" ? "7d" : "Today"}
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={loadRecentActivity}
              disabled={loading}
              className="h-6 w-6 p-0 text-slate-400 hover:text-white"
            >
              <RefreshCw className={`h-3.5 w-3.5 ${loading ? "animate-spin" : ""}`} />
            </Button>
          </div>
        </div>
      </CardHeader>

      <CardContent className="p-3 pt-0 flex-1 min-h-0 flex flex-col gap-2">
        {/* Filter Chips */}
        {activityTypes.length > 1 && (
          <div className="flex items-center gap-1 flex-wrap">
            <Button
              size="sm"
              variant={filterType === null ? "default" : "outline"}
              onClick={() => setFilterType(null)}
              className={filterType === null 
                ? "h-5 px-2 text-[9px] bg-fuchsia-600 text-white" 
                : "h-5 px-2 text-[9px] border-slate-600 text-slate-400"
              }
            >
              All
            </Button>
            {activityTypes.map(type => (
              <Button
                key={type}
                size="sm"
                variant={filterType === type ? "default" : "outline"}
                onClick={() => setFilterType(type)}
                className={filterType === type 
                  ? "h-5 px-2 text-[9px] bg-fuchsia-600 text-white" 
                  : "h-5 px-2 text-[9px] border-slate-600 text-slate-400"
                }
              >
                {type}
              </Button>
            ))}
          </div>
        )}

        {/* Activity List */}
        <div className="flex-1 min-h-0 overflow-y-auto scrollbar-hide space-y-2">
          {filteredActivities.length === 0 ? (
            <p className="text-[10px] text-slate-500 text-center py-4">
              No {filterType || ""} activity
            </p>
          ) : (
            filteredActivities.map((activity) => {
              const IconComp = TYPE_ICONS[activity.type] || Activity;
              const colorClass = TYPE_COLORS[activity.type] || "text-slate-400";
              const bgColorClass = TYPE_BG_COLORS[activity.type] || "bg-slate-500/10";
              
              return (
                <div
                  key={`${activity.type}-${activity.id}`}
                  className="flex items-center gap-2 p-2 rounded-lg bg-slate-900/50 border border-slate-700/50"
                >
                  <div className={`p-1 rounded ${bgColorClass} shrink-0`}>
                    <IconComp className={`h-3 w-3 ${colorClass}`} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-white truncate">{activity.title}</p>
                    <p className="text-[10px] text-slate-500">
                      {formatDistanceToNow(new Date(activity.timestamp), { addSuffix: true })}
                    </p>
                  </div>
                  <div className="flex items-center gap-1 shrink-0">
                    <Badge variant="outline" className="border-slate-700 text-slate-500 text-[9px] capitalize">
                      {activity.type}
                    </Badge>
                    {activity.canUndo && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => undoAction(activity.id)}
                        className="h-5 w-5 p-0 text-slate-400 hover:text-fuchsia-400"
                        title="Undo"
                      >
                        <Undo2 className="h-3 w-3" />
                      </Button>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* View Full History Link */}
        <Link to="/history">
          <Button
            variant="outline"
            size="sm"
            className="w-full border-slate-600 text-slate-300 hover:bg-slate-700"
          >
            <ExternalLink className="h-3 w-3 mr-2" />
            View Full History
          </Button>
        </Link>
      </CardContent>
    </Card>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { showSuccess, showError } from "@/utils/toast";
import { 
  Bell, 
  Plus, 
  Trash2, 
  Edit,
  Clock,
  CheckCircle2,
  Circle,
  Repeat
} from "lucide-react";
import { format, isToday, isTomorrow, isPast, parseISO, isFuture } from "date-fns";

interface Reminder {
  id: string;
  text: string;
  due_time: string;
  channel: string;
  status: string;
  recurrence_rule?: string;
  recurrence_end_date?: string;
  created_at: string;
}

export default function RemindersWidget() {
  const { user } = useAuth();
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [loading, setLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingReminder, setEditingReminder] = useState<Reminder | null>(null);
  const [showCompleted, setShowCompleted] = useState(false);
  
  // Form fields
  const [newText, setNewText] = useState("");
  const [newDueTime, setNewDueTime] = useState("");
  const [newChannel, setNewChannel] = useState("sms");
  const [newRecurrence, setNewRecurrence] = useState("none");

  useEffect(() => {
    let isMounted = true;
    
    const load = async () => {
      if (!user || !isMounted) return;
      setLoading(true);
      
      const status = showCompleted ? "completed" : "pending";
      const { data, error } = await supabase
        .from("reminders")
        .select("*")
        .eq("user_id", user.id)
        .eq("status", status)
        .order("due_time", { ascending: true })
        .limit(10);

      if (!isMounted) return;

      if (error) {
        console.error("Failed to load reminders:", error);
      } else {
        setReminders(data || []);
      }
      setLoading(false);
    };
    
    load();
    
    return () => {
      isMounted = false;
    };
  }, [user?.id, showCompleted]);

  const loadReminders = async () => {
    if (!user) return;
    
    const status = showCompleted ? "completed" : "pending";
    const { data, error } = await supabase
      .from("reminders")
      .select("*")
      .eq("user_id", user.id)
      .eq("status", status)
      .order("due_time", { ascending: true })
      .limit(10);

    if (error) {
      console.error("Failed to load reminders:", error);
    } else {
      setReminders(data || []);
    }
    setLoading(false);
  };

  const openNewReminder = () => {
    setEditingReminder(null);
    setNewText("");
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    tomorrow.setHours(9, 0, 0, 0);
    setNewDueTime(tomorrow.toISOString().slice(0, 16));
    setNewChannel("sms");
    setNewRecurrence("none");
    setIsDialogOpen(true);
  };

  const startEditReminder = (reminder: Reminder) => {
    setEditingReminder(reminder);
    setNewText(reminder.text);
    setNewDueTime(reminder.due_time.slice(0, 16));
    setNewChannel(reminder.channel);
    setNewRecurrence(reminder.recurrence_rule || "none");
    setIsDialogOpen(true);
  };

  const createReminder = async () => {
    if (!user || !newText.trim() || !newDueTime) {
      showError("Please fill in all required fields");
      return;
    }

    const reminderData: any = {
      user_id: user.id,
      text: newText.trim(),
      due_time: new Date(newDueTime).toISOString(),
      channel: newChannel,
      status: "pending",
    };

    if (newRecurrence !== "none") {
      reminderData.recurrence_rule = newRecurrence;
    }

    const { error } = await supabase.from("reminders").insert(reminderData);

    if (error) {
      showError("Failed to create reminder");
    } else {
      await loadReminders();
      resetForm();
      showSuccess("Reminder created!");
    }
  };

  const updateReminder = async () => {
    if (!editingReminder || !newText.trim() || !newDueTime) {
      showError("Please fill in all required fields");
      return;
    }

    const updates: any = {
      text: newText.trim(),
      due_time: new Date(newDueTime).toISOString(),
      channel: newChannel,
    };

    if (newRecurrence !== "none") {
      updates.recurrence_rule = newRecurrence;
    } else {
      updates.recurrence_rule = null;
    }

    const { error } = await supabase
      .from("reminders")
      .update(updates)
      .eq("id", editingReminder.id);

    if (error) {
      showError("Failed to update reminder");
    } else {
      await loadReminders();
      resetForm();
      showSuccess("Reminder updated!");
    }
  };

  const toggleReminderStatus = async (reminder: Reminder) => {
    const newStatus = reminder.status === "pending" ? "completed" : "pending";

    const { error } = await supabase
      .from("reminders")
      .update({ status: newStatus })
      .eq("id", reminder.id);

    if (error) {
      showError("Failed to update reminder");
    } else {
      await loadReminders();
      showSuccess(newStatus === "completed" ? "Reminder completed!" : "Reminder reopened");
    }
  };

  const deleteReminder = async (id: string) => {
    const { error } = await supabase
      .from("reminders")
      .delete()
      .eq("id", id);

    if (error) {
      showError("Failed to delete reminder");
    } else {
      await loadReminders();
      showSuccess("Reminder deleted");
    }
  };

  const resetForm = () => {
    setNewText("");
    setNewDueTime("");
    setNewChannel("sms");
    setNewRecurrence("none");
    setEditingReminder(null);
    setIsDialogOpen(false);
  };

  const formatDueTime = (timeString: string) => {
    const date = parseISO(timeString);
    if (isToday(date)) return `Today ${format(date, "h:mm a")}`;
    if (isTomorrow(date)) return `Tomorrow ${format(date, "h:mm a")}`;
    if (isPast(date)) return `Overdue - ${format(date, "MMM d, h:mm a")}`;
    return format(date, "MMM d, h:mm a");
  };

  const getChannelColor = (channel: string) => {
    switch (channel) {
      case "sms": return "text-blue-400 bg-blue-500/10";
      case "email": return "text-purple-400 bg-purple-500/10";
      case "push": return "text-green-400 bg-green-500/10";
      default: return "text-slate-400 bg-slate-500/10";
    }
  };

  const getChannelIcon = (channel: string) => {
    return channel.toUpperCase();
  };

  if (loading) {
    return (
      <Card className="border-slate-700 bg-slate-800/50 backdrop-blur h-full w-full overflow-hidden flex flex-col">
        <CardHeader className="p-3 pb-2 shrink-0">
          <CardTitle className="text-sm text-white flex items-center gap-2">
            <Bell className="h-4 w-4 text-yellow-400" />
            Reminders
          </CardTitle>
        </CardHeader>
        <CardContent className="p-3 pt-0 flex-1 min-h-0 flex items-center justify-center">
          <div className="animate-pulse text-slate-400 text-xs">Loading...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <>
      <Card className="border-slate-700 bg-slate-800/50 backdrop-blur h-full w-full overflow-hidden flex flex-col">
        <CardHeader className="p-3 pb-2 shrink-0">
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm text-white flex items-center gap-2">
              <Bell className="h-4 w-4 text-yellow-400" />
              Reminders
            </CardTitle>
            <div className="flex items-center gap-1">
              <Button
                size="sm"
                variant="ghost"
                onClick={() => setShowCompleted(!showCompleted)}
                className="h-6 px-2 text-[10px] text-slate-400 hover:text-white"
              >
                {showCompleted ? "Pending" : "Done"}
              </Button>
              <Button
                size="sm"
                variant="ghost"
                onClick={openNewReminder}
                className="h-6 w-6 p-0 text-yellow-400 hover:text-yellow-300"
              >
                <Plus className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-3 pt-0 flex-1 min-h-0 overflow-y-auto scrollbar-hide space-y-2">
          {reminders.length === 0 ? (
            <p className="text-[10px] text-slate-500 text-center py-4">
              {showCompleted ? "No completed reminders" : "No pending reminders"}
            </p>
          ) : (
            reminders.map((reminder) => {
              const dueTime = formatDueTime(reminder.due_time);
              const isOverdue = isPast(parseISO(reminder.due_time)) && reminder.status === "pending";
              const isRecurring = !!reminder.recurrence_rule;
              
              return (
                <div
                  key={reminder.id}
                  className={`p-2 rounded-lg border transition-all ${
                    reminder.status === "completed"
                      ? "bg-slate-900/30 border-slate-700/30 opacity-60"
                      : "bg-slate-900/50 border-slate-700/50"
                  }`}
                >
                  <div className="flex items-start gap-2">
                    <button
                      onClick={() => toggleReminderStatus(reminder)}
                      className="mt-0.5 shrink-0 text-slate-400 hover:text-yellow-400 transition-colors"
                    >
                      {reminder.status === "completed" ? (
                        <CheckCircle2 className="h-4 w-4 text-yellow-400" />
                      ) : (
                        <Circle className="h-4 w-4" />
                      )}
                    </button>
                    
                    <div className="flex-1 min-w-0">
                      <p className={`text-xs text-white font-medium line-clamp-2 ${
                        reminder.status === "completed" ? "line-through opacity-60" : ""
                      }`}>
                        {reminder.text}
                      </p>
                      
                      <div className="flex items-center gap-2 mt-1 flex-wrap">
                        <span className={`text-[10px] px-1.5 py-0.5 rounded ${getChannelColor(reminder.channel)}`}>
                          {getChannelIcon(reminder.channel)}
                        </span>
                        
                        <span className={`text-[10px] flex items-center gap-1 ${
                          isOverdue ? "text-red-400" : "text-slate-500"
                        }`}>
                          <Clock className="h-3 w-3" />
                          {dueTime}
                        </span>

                        {isRecurring && (
                          <span className="text-[10px] text-purple-400 flex items-center gap-1">
                            <Repeat className="h-3 w-3" />
                            {reminder.recurrence_rule}
                          </span>
                        )}
                      </div>
                    </div>

                    {reminder.status === "pending" && (
                      <div className="flex items-center gap-1 shrink-0">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => startEditReminder(reminder)}
                          className="h-5 w-5 p-0 text-slate-400 hover:text-blue-400"
                        >
                          <Edit className="h-3 w-3" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => deleteReminder(reminder.id)}
                          className="h-5 w-5 p-0 text-slate-400 hover:text-red-400"
                        >
                          <Trash2 className="h-3 w-3" />
                        </Button>
                      </div>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </CardContent>
      </Card>

      {/* Reminder Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="bg-slate-900 border-slate-700 max-w-md" aria-describedby="reminder-dialog-description">
          <DialogHeader>
            <DialogTitle className="text-white">
              {editingReminder ? "Edit Reminder" : "New Reminder"}
            </DialogTitle>
            <p id="reminder-dialog-description" className="sr-only">
              {editingReminder ? "Edit reminder details including text, time, channel, and recurrence" : "Create a new reminder with text, time, channel, and recurrence options"}
            </p>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm text-slate-400 mb-1 block">Reminder Text *</label>
              <Input
                placeholder="What do you want to be reminded about?"
                className="bg-slate-800 border-slate-700 text-white"
                value={newText}
                onChange={(e) => setNewText(e.target.value)}
              />
            </div>
            <div>
              <label className="text-sm text-slate-400 mb-1 block">When *</label>
              <Input
                type="datetime-local"
                className="bg-slate-800 border-slate-700 text-white"
                value={newDueTime}
                onChange={(e) => setNewDueTime(e.target.value)}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm text-slate-400 mb-1 block">Channel</label>
                <Select value={newChannel} onValueChange={setNewChannel}>
                  <SelectTrigger className="bg-slate-800 border-slate-700 text-white">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-slate-800 border-slate-700">
                    <SelectItem value="sms" className="text-white">SMS</SelectItem>
                    <SelectItem value="email" className="text-white">Email</SelectItem>
                    <SelectItem value="push" className="text-white">Push</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <label className="text-sm text-slate-400 mb-1 block">Repeat</label>
                <Select value={newRecurrence} onValueChange={setNewRecurrence}>
                  <SelectTrigger className="bg-slate-800 border-slate-700 text-white">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-slate-800 border-slate-700">
                    <SelectItem value="none" className="text-white">None</SelectItem>
                    <SelectItem value="daily" className="text-white">Daily</SelectItem>
                    <SelectItem value="weekly" className="text-white">Weekly</SelectItem>
                    <SelectItem value="monthly" className="text-white">Monthly</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="flex justify-end gap-2">
              <Button 
                variant="outline" 
                onClick={resetForm}
                className="border-slate-600 text-slate-300"
              >
                Cancel
              </Button>
              <Button 
                onClick={editingReminder ? updateReminder : createReminder}
                className="bg-yellow-600 text-white hover:bg-yellow-500"
              >
                {editingReminder ? "Update" : "Create"}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { TrendingUp, TrendingDown, RefreshCw, DollarSign } from "lucide-react";
import WidgetSkeleton from "../WidgetSkeleton";

interface Stock {
  symbol: string;
  name: string;
  price: number;
  change: number;
  changePercent: number;
}

export default function StocksWidget() {
  const [stocks, setStocks] = useState<Stock[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const defaultSymbols = ['AAPL', 'GOOGL', 'MSFT', 'AMZN', 'TSLA'];

  const fetchStocks = async () => {
    setLoading(true);
    setError(null);

    try {
      // Using mock data for demo
      // To use real data, get a free API key from https://www.alphavantage.co/support/#api-key
      // and replace 'demo' with your key
      
      const stockData = defaultSymbols.map((symbol) => {
        const basePrice = {
          'AAPL': 180,
          'GOOGL': 140,
          'MSFT': 380,
          'AMZN': 150,
          'TSLA': 240,
        }[symbol] || 100;

        const change = (Math.random() - 0.5) * 10;
        const changePercent = (change / basePrice) * 100;

        return {
          symbol,
          name: symbol,
          price: basePrice + change,
          change,
          changePercent,
        };
      });

      setStocks(stockData);
    } catch (err) {
      setError('Failed to fetch stock data');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStocks();
    const interval = setInterval(fetchStocks, 60000); // Update every minute
    return () => clearInterval(interval);
  }, []);

  if (loading && stocks.length === 0) {
    return <WidgetSkeleton />;
  }

  return (
    <Card className="border-slate-700 bg-slate-800/50 backdrop-blur h-full w-full overflow-hidden flex flex-col">
      <CardHeader className="p-3 pb-2 shrink-0">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm text-white flex items-center gap-2">
            <DollarSign className="h-4 w-4 text-green-400" />
            Stocks
          </CardTitle>
          <Button
            size="sm"
            variant="ghost"
            onClick={fetchStocks}
            disabled={loading}
            className="h-6 w-6 p-0 text-slate-400 hover:text-white"
          >
            <RefreshCw className={`h-3.5 w-3.5 ${loading ? 'animate-spin' : ''}`} />
          </Button>
        </div>
      </CardHeader>

      <CardContent className="p-3 pt-0 flex-1 min-h-0 overflow-y-auto scrollbar-hide space-y-2">
        <div className="p-2 rounded-lg bg-blue-900/20 border border-blue-500/30 mb-2">
          <p className="text-[9px] text-blue-300">
            ≡ƒôè Demo data - Get free API key at alphavantage.co for real-time prices
          </p>
        </div>
        
        {error ? (
          <div className="text-center py-4">
            <p className="text-xs text-red-400 mb-2">{error}</p>
            <Button
              size="sm"
              onClick={fetchStocks}
              className="bg-fuchsia-600 text-white hover:bg-fuchsia-500"
            >
              Retry
            </Button>
          </div>
        ) : (
          stocks.map((stock) => (
            <div
              key={stock.symbol}
              className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50"
            >
              <div className="flex items-center justify-between mb-1">
                <span className="text-xs font-semibold text-white">{stock.symbol}</span>
                <span className="text-sm font-bold text-white">
                  ${stock.price.toFixed(2)}
                </span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-[10px] text-slate-500">{stock.name}</span>
                <div
                  className={`flex items-center gap-1 text-xs ${
                    stock.change >= 0 ? 'text-green-400' : 'text-red-400'
                  }`}
                >
                  {stock.change >= 0 ? (
                    <TrendingUp className="w-3 h-3" />
                  ) : (
                    <TrendingDown className="w-3 h-3" />
                  )}
                  <span>
                    {stock.change >= 0 ? '+' : ''}
                    {stock.change.toFixed(2)} ({stock.changePercent.toFixed(2)}%)
                  </span>
                </div>
              </div>
            </div>
          ))
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { showSuccess, showError } from "@/utils/toast";
import { 
  CheckSquare, 
  Plus, 
  Trash2, 
  Edit,
  Circle,
  CheckCircle2,
  AlertCircle,
  Clock
} from "lucide-react";
import { format, isToday, isTomorrow, isPast, parseISO } from "date-fns";

interface Task {
  id: string;
  title: string;
  description?: string;
  due_date?: string;
  priority: string;
  status: string;
  created_at: string;
}

export default function TasksWidget() {
  const { user } = useAuth();
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [showCompleted, setShowCompleted] = useState(false);
  
  // Form fields
  const [newTitle, setNewTitle] = useState("");
  const [newDescription, setNewDescription] = useState("");
  const [newDueDate, setNewDueDate] = useState("");
  const [newPriority, setNewPriority] = useState("medium");

  useEffect(() => {
    let isMounted = true;
    
    const load = async () => {
      if (!user || !isMounted) return;
      setLoading(true);
      
      const status = showCompleted ? "completed" : "pending";
      const { data, error } = await supabase
        .from("tasks")
        .select("*")
        .eq("user_id", user.id)
        .eq("status", status)
        .order("due_date", { ascending: true, nullsFirst: false })
        .order("priority", { ascending: false })
        .limit(10);

      if (!isMounted) return;

      if (error) {
        console.error("Failed to load tasks:", error);
      } else {
        setTasks(data || []);
      }
      setLoading(false);
    };
    
    load();
    
    return () => {
      isMounted = false;
    };
  }, [user?.id, showCompleted]);

  const loadTasks = async () => {
    if (!user) return;
    
    const status = showCompleted ? "completed" : "pending";
    const { data, error } = await supabase
      .from("tasks")
      .select("*")
      .eq("user_id", user.id)
      .eq("status", status)
      .order("due_date", { ascending: true, nullsFirst: false })
      .order("priority", { ascending: false })
      .limit(10);

    if (error) {
      console.error("Failed to load tasks:", error);
    } else {
      setTasks(data || []);
    }
    setLoading(false);
  };

  const openNewTask = () => {
    setEditingTask(null);
    setNewTitle("");
    setNewDescription("");
    setNewDueDate("");
    setNewPriority("medium");
    setIsDialogOpen(true);
  };

  const startEditTask = (task: Task) => {
    setEditingTask(task);
    setNewTitle(task.title);
    setNewDescription(task.description || "");
    setNewDueDate(task.due_date ? task.due_date.slice(0, 16) : "");
    setNewPriority(task.priority);
    setIsDialogOpen(true);
  };

  const createTask = async () => {
    if (!user || !newTitle.trim()) {
      showError("Please enter a task title");
      return;
    }

    const { error } = await supabase.from("tasks").insert({
      user_id: user.id,
      title: newTitle.trim(),
      description: newDescription.trim() || null,
      due_date: newDueDate ? new Date(newDueDate).toISOString() : null,
      priority: newPriority,
      status: "pending",
    });

    if (error) {
      showError("Failed to create task");
    } else {
      await loadTasks();
      resetForm();
      showSuccess("Task created!");
    }
  };

  const updateTask = async () => {
    if (!editingTask || !newTitle.trim()) {
      showError("Please enter a task title");
      return;
    }

    const updates = {
      title: newTitle.trim(),
      description: newDescription.trim() || null,
      due_date: newDueDate ? new Date(newDueDate).toISOString() : null,
      priority: newPriority,
    };

    const { error } = await supabase
      .from("tasks")
      .update(updates)
      .eq("id", editingTask.id);

    if (error) {
      showError("Failed to update task");
    } else {
      await loadTasks();
      resetForm();
      showSuccess("Task updated!");
    }
  };

  const toggleTaskStatus = async (task: Task) => {
    const newStatus = task.status === "pending" ? "completed" : "pending";
    const updates: any = { status: newStatus };
    
    if (newStatus === "completed") {
      updates.completed_at = new Date().toISOString();
    }

    const { error } = await supabase
      .from("tasks")
      .update(updates)
      .eq("id", task.id);

    if (error) {
      showError("Failed to update task");
    } else {
      await loadTasks();
      showSuccess(newStatus === "completed" ? "Task completed!" : "Task reopened");
    }
  };

  const deleteTask = async (id: string) => {
    const { error } = await supabase
      .from("tasks")
      .delete()
      .eq("id", id);

    if (error) {
      showError("Failed to delete task");
    } else {
      await loadTasks();
      showSuccess("Task deleted");
    }
  };

  const resetForm = () => {
    setNewTitle("");
    setNewDescription("");
    setNewDueDate("");
    setNewPriority("medium");
    setEditingTask(null);
    setIsDialogOpen(false);
  };

  const formatDueDate = (dateString?: string) => {
    if (!dateString) return null;
    const date = parseISO(dateString);
    if (isToday(date)) return "Today";
    if (isTomorrow(date)) return "Tomorrow";
    if (isPast(date)) return `Overdue - ${format(date, "MMM d")}`;
    return format(date, "MMM d");
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case "urgent": return "text-red-400 border-red-400/30 bg-red-500/10";
      case "high": return "text-orange-400 border-orange-400/30 bg-orange-500/10";
      case "medium": return "text-yellow-400 border-yellow-400/30 bg-yellow-500/10";
      case "low": return "text-green-400 border-green-400/30 bg-green-500/10";
      default: return "text-slate-400 border-slate-400/30 bg-slate-500/10";
    }
  };

  const getPriorityIcon = (priority: string) => {
    switch (priority) {
      case "urgent": return <AlertCircle className="h-3 w-3" />;
      case "high": return <AlertCircle className="h-3 w-3" />;
      default: return <Circle className="h-3 w-3" />;
    }
  };

  if (loading) {
    return (
      <Card className="border-slate-700 bg-slate-800/50 backdrop-blur h-full w-full overflow-hidden flex flex-col">
        <CardHeader className="p-3 pb-2 shrink-0">
          <CardTitle className="text-sm text-white flex items-center gap-2">
            <CheckSquare className="h-4 w-4 text-green-400" />
            Tasks
          </CardTitle>
        </CardHeader>
        <CardContent className="p-3 pt-0 flex-1 min-h-0 flex items-center justify-center">
          <div className="animate-pulse text-slate-400 text-xs">Loading...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <>
      <Card className="border-slate-700 bg-slate-800/50 backdrop-blur h-full w-full overflow-hidden flex flex-col">
        <CardHeader className="p-3 pb-2 shrink-0">
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm text-white flex items-center gap-2">
              <CheckSquare className="h-4 w-4 text-green-400" />
              Tasks
            </CardTitle>
            <div className="flex items-center gap-1">
              <Button
                size="sm"
                variant="ghost"
                onClick={() => setShowCompleted(!showCompleted)}
                className="h-6 px-2 text-[10px] text-slate-400 hover:text-white"
              >
                {showCompleted ? "Pending" : "Done"}
              </Button>
              <Button
                size="sm"
                variant="ghost"
                onClick={openNewTask}
                className="h-6 w-6 p-0 text-green-400 hover:text-green-300"
              >
                <Plus className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-3 pt-0 flex-1 min-h-0 overflow-y-auto scrollbar-hide space-y-2">
          {tasks.length === 0 ? (
            <p className="text-[10px] text-slate-500 text-center py-4">
              {showCompleted ? "No completed tasks" : "No pending tasks"}
            </p>
          ) : (
            tasks.map((task) => {
              const dueDate = formatDueDate(task.due_date);
              const isOverdue = task.due_date && isPast(parseISO(task.due_date)) && task.status === "pending";
              
              return (
                <div
                  key={task.id}
                  className={`p-2 rounded-lg border transition-all ${
                    task.status === "completed"
                      ? "bg-slate-900/30 border-slate-700/30 opacity-60"
                      : "bg-slate-900/50 border-slate-700/50"
                  }`}
                >
                  <div className="flex items-start gap-2">
                    <button
                      onClick={() => toggleTaskStatus(task)}
                      className="mt-0.5 shrink-0 text-slate-400 hover:text-green-400 transition-colors"
                    >
                      {task.status === "completed" ? (
                        <CheckCircle2 className="h-4 w-4 text-green-400" />
                      ) : (
                        <Circle className="h-4 w-4" />
                      )}
                    </button>
                    
                    <div className="flex-1 min-w-0">
                      <p className={`text-xs text-white font-medium line-clamp-2 ${
                        task.status === "completed" ? "line-through opacity-60" : ""
                      }`}>
                        {task.title}
                      </p>
                      
                      <div className="flex items-center gap-2 mt-1 flex-wrap">
                        {task.priority !== "medium" && (
                          <span className={`text-[10px] px-1.5 py-0.5 rounded border flex items-center gap-1 ${getPriorityColor(task.priority)}`}>
                            {getPriorityIcon(task.priority)}
                            {task.priority}
                          </span>
                        )}
                        
                        {dueDate && (
                          <span className={`text-[10px] flex items-center gap-1 ${
                            isOverdue ? "text-red-400" : "text-slate-500"
                          }`}>
                            <Clock className="h-3 w-3" />
                            {dueDate}
                          </span>
                        )}
                      </div>
                    </div>

                    {task.status === "pending" && (
                      <div className="flex items-center gap-1 shrink-0">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => startEditTask(task)}
                          className="h-5 w-5 p-0 text-slate-400 hover:text-blue-400"
                        >
                          <Edit className="h-3 w-3" />
                        </Button>
                        <Button
                          variant="ghost"
