"use client";

import React, { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { getWeather, WeatherData } from "@/services/search";
import { getLocationContext } from "@/services/context";
import { showSuccess, showError } from "@/utils/toast";
import { 
  CloudSun, 
  Thermometer, 
  Droplets, 
  Wind, 
  RefreshCw, 
  MapPin, 
  Sun, 
  Cloud, 
  CloudRain, 
  Snowflake,
  Plus,
  Trash2,
  Eye,
  Gauge,
  Sunrise as SunriseIcon,
  Sunset as SunsetIcon
} from "lucide-react";

interface SavedLocation {
  id: string;
  name: string;
  lat: number;
  lng: number;
}

interface ExtendedWeatherData extends WeatherData {
  visibility?: number;
  pressure?: number;
  sunrise?: number;
  sunset?: number;
}

export default function WeatherWidget() {
  const [weather, setWeather] = useState<ExtendedWeatherData | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [locationName, setLocationName] = useState<string>("Your Location");
  // Default to Fahrenheit for US users (detect via timezone or locale)
  const [useCelsius, setUseCelsius] = useState(() => {
    // Check if user is in US timezone or has US locale
    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const locale = navigator.language || 'en-US';
    const isUS = timezone.startsWith('America/') || locale.includes('US') || locale === 'en-US';
    // Return false (Fahrenheit) for US users, true (Celsius) for others
    return !isUS;
  });
  const [savedLocations, setSavedLocations] = useState<SavedLocation[]>([]);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [newLocationName, setNewLocationName] = useState("");
  const [currentLocation, setCurrentLocation] = useState<{ lat: number; lng: number } | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem("weatherLocations");
    if (saved) {
      try {
        setSavedLocations(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load saved locations");
      }
    }
    fetchWeather();
  }, []);

  useEffect(() => {
    if (savedLocations.length > 0) {
      localStorage.setItem("weatherLocations", JSON.stringify(savedLocations));
    }
  }, [savedLocations]);

  const fetchWeather = async (lat?: number, lng?: number, name?: string) => {
    setLoading(true);
    setError(null);
    
    try {
      let targetLat = lat;
      let targetLng = lng;
      let targetName = name;

      if (!targetLat || !targetLng) {
        const location = await getLocationContext();
        if (!location) {
          setError("Location not available");
          setLoading(false);
          return;
        }
        targetLat = location.lat;
        targetLng = location.lng;
        targetName = location.city || "Your Location";
        setCurrentLocation({ lat: targetLat, lng: targetLng });
      }
      
      const weatherData = await getWeather(targetLat, targetLng);
      setWeather(weatherData as ExtendedWeatherData);
      setLocationName(targetName || "Location");
    } catch (e: unknown) {
      const errorMessage = e instanceof Error ? e.message : "Failed to get weather";
      setError(errorMessage);
      showError(errorMessage);
    }
    
    setLoading(false);
  };

  const addLocation = async () => {
    if (!newLocationName.trim()) {
      showError("Please enter a location name");
      return;
    }

    if (!currentLocation) {
      showError("Current location not available");
      return;
    }

    const newLocation: SavedLocation = {
      id: Date.now().toString(),
      name: newLocationName.trim(),
      lat: currentLocation.lat,
      lng: currentLocation.lng
    };

    setSavedLocations([...savedLocations, newLocation]);
    setIsDialogOpen(false);
    setNewLocationName("");
    showSuccess("Location saved!");
  };

  const removeLocation = (id: string) => {
    setSavedLocations(savedLocations.filter(loc => loc.id !== id));
    showSuccess("Location removed");
  };

  const convertTemp = (celsius: number) => {
    if (useCelsius) return Math.round(celsius);
    return Math.round((celsius * 9/5) + 32);
  };

  const tempUnit = useCelsius ? "┬░C" : "┬░F";

  const getWeatherIcon = (description?: string) => {
    if (!description) return <CloudSun className="h-8 w-8 text-yellow-400" />;
    const desc = description.toLowerCase();
    if (desc.includes("rain")) return <CloudRain className="h-8 w-8 text-blue-400" />;
    if (desc.includes("snow")) return <Snowflake className="h-8 w-8 text-cyan-300" />;
    if (desc.includes("cloud")) return <Cloud className="h-8 w-8 text-slate-300" />;
    if (desc.includes("clear") || desc.includes("sun")) return <Sun className="h-8 w-8 text-yellow-400" />;
    return <CloudSun className="h-8 w-8 text-yellow-400" />;
  };

  const formatTime = (timestamp?: number) => {
    if (!timestamp) return "--:--";
    const date = new Date(timestamp * 1000);
    return date.toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" });
  };

  if (error && !weather) {
    return (
      <Card className="border-slate-700 bg-slate-800/50 backdrop-blur h-full w-full overflow-hidden flex flex-col">
        <CardHeader className="p-3 pb-2 shrink-0">
          <CardTitle className="text-sm text-white flex items-center gap-2">
            <CloudSun className="h-4 w-4 text-blue-400" />
            Weather
          </CardTitle>
        </CardHeader>
        <CardContent className="p-3 pt-0 flex-1 min-h-0 flex flex-col items-center justify-center">
          <p className="text-xs text-slate-500 mb-2">{error}</p>
          <Button
            variant="outline"
            size="sm"
            onClick={() => fetchWeather()}
            className="border-slate-600 text-slate-300"
          >
            Try Again
          </Button>
        </CardContent>
      </Card>
    );
  }

  return (
    <>
      <Card className="border-slate-700 bg-slate-800/50 backdrop-blur h-full w-full overflow-hidden flex flex-col">
        <CardHeader className="p-3 pb-2 shrink-0">
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm text-white flex items-center gap-2">
              <CloudSun className="h-4 w-4 text-blue-400" />
              Weather
            </CardTitle>
            <div className="flex items-center gap-1">
              <Button
                size="sm"
                variant="ghost"
                onClick={() => setUseCelsius(!useCelsius)}
                className="h-6 px-2 text-[10px] text-slate-400 hover:text-white"
              >
                {useCelsius ? "┬░C" : "┬░F"}
              </Button>
              <Button
                size="sm"
                variant="ghost"
                onClick={() => fetchWeather()}
                disabled={loading}
                className="h-6 w-6 p-0 text-slate-400 hover:text-white"
              >
                <RefreshCw className={`h-3.5 w-3.5 ${loading ? "animate-spin" : ""}`} />
              </Button>
              <Button
                size="sm"
                variant="ghost"
                onClick={() => setIsDialogOpen(true)}
                className="h-6 w-6 p-0 text-blue-400 hover:text-blue-300"
              >
                <Plus className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-3 pt-0 flex-1 min-h-0 overflow-y-auto scrollbar-hide space-y-3">
          {!weather ? (
            <div className="flex items-center justify-center py-8">
              <p className="text-xs text-slate-500">
                {loading ? "Loading weather..." : "Click refresh to get weather"}
              </p>
            </div>
          ) : (
            <>
              {/* Current Weather */}
              <div className="p-3 rounded-lg bg-slate-900/50 border border-slate-700/50">
                <div className="flex items-center gap-2 mb-2">
                  <MapPin className="h-3 w-3 text-blue-400" />
                  <span className="text-xs font-medium text-white">{locationName}</span>
                </div>
                
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-3xl font-bold text-white">
                      {convertTemp(weather.temperature)}{tempUnit}
                    </p>
                    <p className="text-xs text-slate-300 capitalize">{weather.description}</p>
                    <p className="text-[10px] text-slate-500 mt-1">
                      Feels like {convertTemp(weather.feelsLike)}{tempUnit}
                    </p>
                  </div>
                  {getWeatherIcon(weather.description)}
                </div>
              </div>

              {/* Weather Details Grid */}
              <div className="grid grid-cols-2 gap-2">
                <div className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                  <div className="flex items-center gap-1.5">
                    <Droplets className="h-3 w-3 text-blue-400" />
                    <span className="text-[10px] text-slate-500">Humidity</span>
                  </div>
                  <p className="text-sm font-medium text-white mt-1">{weather.humidity}%</p>
                </div>

                <div className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                  <div className="flex items-center gap-1.5">
                    <Wind className="h-3 w-3 text-cyan-400" />
                    <span className="text-[10px] text-slate-500">Wind</span>
                  </div>
                  <p className="text-sm font-medium text-white mt-1">{weather.windSpeed} km/h</p>
                </div>

                {weather.visibility && (
                  <div className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                    <div className="flex items-center gap-1.5">
                      <Eye className="h-3 w-3 text-purple-400" />
                      <span className="text-[10px] text-slate-500">Visibility</span>
                    </div>
                    <p className="text-sm font-medium text-white mt-1">{Math.round(weather.visibility / 1000)} km</p>
                  </div>
                )}

                {weather.pressure && (
                  <div className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                    <div className="flex items-center gap-1.5">
                      <Gauge className="h-3 w-3 text-orange-400" />
                      <span className="text-[10px] text-slate-500">Pressure</span>
                    </div>
                    <p className="text-sm font-medium text-white mt-1">{weather.pressure} hPa</p>
                  </div>
                )}
              </div>

              {/* Sunrise/Sunset */}
              {(weather.sunrise || weather.sunset) && (
                <div className="grid grid-cols-2 gap-2">
                  {weather.sunrise && (
                    <div className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                      <div className="flex items-center gap-1.5">
                        <SunriseIcon className="h-3 w-3 text-orange-400" />
                        <span className="text-[10px] text-slate-500">Sunrise</span>
                      </div>
                      <p className="text-sm font-medium text-white mt-1">{formatTime(weather.sunrise)}</p>
                    </div>
                  )}

                  {weather.sunset && (
                    <div className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                      <div className="flex items-center gap-1.5">
                        <SunsetIcon className="h-3 w-3 text-purple-400" />
                        <span className="text-[10px] text-slate-500">Sunset</span>
                      </div>
                      <p className="text-sm font-medium text-white mt-1">{formatTime(weather.sunset)}</p>
                    </div>
                  )}
                </div>
              )}

              {/* Saved Locations */}
              {savedLocations.length > 0 && (
                <div className="space-y-2">
                  <div className="flex items-center gap-1 text-xs text-slate-400">
                    <MapPin className="h-3 w-3" />
                    <span>Saved Locations</span>
                  </div>
                  {savedLocations.map(location => (
                    <div
                      key={location.id}
                      className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50 flex items-center justify-between"
                    >
                      <button
                        onClick={() => fetchWeather(location.lat, location.lng, location.name)}
                        className="flex-1 text-left"
                      >
                        <p className="text-xs text-white font-medium">{location.name}</p>
                        <p className="text-[10px] text-slate-500">Click to view weather</p>
                      </button>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => removeLocation(location.id)}
                        className="h-5 w-5 p-0 text-slate-400 hover:text-red-400"
                      >
                        <Trash2 className="h-3 w-3" />
                      </Button>
                    </div>
                  ))}
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      {/* Add Location Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="bg-slate-900 border-slate-700 max-w-md">
          <DialogHeader>
            <DialogTitle className="text-white">Save Current Location</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm text-slate-400 mb-1 block">Location Name</label>
              <Input
                placeholder="e.g., Home, Office, Vacation Spot"
                className="bg-slate-800 border-slate-700 text-white"
                value={newLocationName}
                onChange={(e) => setNewLocationName(e.target.value)}
              />
            </div>
            <p className="text-xs text-slate-500">
              This will save the current location's weather for quick access.
            </p>
            <div className="flex justify-end gap-2">
              <Button
                variant="outline"
                onClick={() => {
                  setIsDialogOpen(false);
                  setNewLocationName("");
                }}
                className="border-slate-600 text-slate-300"
              >
                Cancel
              </Button>
              <Button
                onClick={addLocation}
                className="bg-blue-600 text-white hover:bg-blue-500"
              >
                Save Location
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";
import React, { useEffect, useState } from "react";
import CurrentTimeDisplay from "@/components/CurrentTimeDisplay";
import LocationDisplay from "@/components/LocationDisplay";
import QuickActions from "@/components/QuickActions";
import RecentActivity from "@/components/RecentActivity";
import ProductivityInsights from "@/components/ProductivityInsights";
import CalendarWidget from "./CalendarWidget";
import TasksWidget from "./TasksWidget";
import RemindersWidget from "./RemindersWidget";
import NotesWidget from "./NotesWidget";
import ContactsWidget from "./ContactsWidget";
import ClockWidget from "./ClockWidget";
import WeatherWidget from "./WeatherWidget";
import MapWidget from "./MapWidget";
import QuickActionsWidget from "./QuickActionsWidget";
import AIUsageWidget from "./AIUsageWidget";
import RecentActivityWidget from "./RecentActivityWidget";
import ProductivityWidget from "./ProductivityWidget";
import UpcomingWidget from "./UpcomingWidget";
import MessagesWidget from "./MessagesWidget";
import EnhancedStocksWidget from "./EnhancedStocksWidget";
import EnhancedNewsWidget from "./EnhancedNewsWidget";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { CheckSquare, Bell, FileText, Calendar, Users, Send, TrendingUp } from "lucide-react";
import { format, isToday, isTomorrow, parseISO } from "date-fns";

interface WidgetContentProps {
  type: string;
}

const SPECIAL = new Set([
  "time",
  "weather",
  "location",
  "quick-actions",
  "ai-usage",
  "recent-activity",
  "productivity",
  "calendar",
  "tasks",
  "reminders",
  "notes",
  "contacts",
  "upcoming",
  "messages",
  "stocks",
  "news",
]);

export default function WidgetContent({ type }: WidgetContentProps) {
  const { user } = useAuth();
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (user && !SPECIAL.has(type)) {
      void loadData();
    } else {
      setLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user, type]);

  const loadData = async () => {
    if (!user) return;

    switch (type) {
      case "tasks": {
        const { data: tasks } = await supabase
          .from("tasks")
          .select("*")
          .eq("user_id", user.id)
          .eq("status", "pending")
          .order("due_date", { ascending: true })
          .limit(5);
        setData(tasks || []);
        break;
      }
      case "reminders": {
        const { data: reminders } = await supabase
          .from("reminders")
          .select("*")
          .eq("user_id", user.id)
          .eq("status", "pending")
          .order("due_time", { ascending: true })
          .limit(5);
        setData(reminders || []);
        break;
      }
      case "notes": {
        const { data: notes } = await supabase
          .from("notes")
          .select("*")
          .eq("user_id", user.id)
          .order("updated_at", { ascending: false })
          .limit(5);
        setData(notes || []);
        break;
      }
      case "calendar": {
        const now = new Date();
        const weekEnd = new Date(now);
        weekEnd.setDate(weekEnd.getDate() + 7);
        const { data: events } = await supabase
          .from("calendar_events")
          .select("*")
          .eq("user_id", user.id)
          .gte("start_time", now.toISOString())
          .lte("start_time", weekEnd.toISOString())
          .order("start_time", { ascending: true })
          .limit(5);
        setData(events || []);
        break;
      }
      case "contacts": {
        const { data: contacts } = await supabase
          .from("contacts")
          .select("*")
          .eq("user_id", user.id)
          .order("created_at", { ascending: false })
          .limit(5);
        setData(contacts || []);
        break;
      }
      case "messages": {
        const { data: messages } = await supabase
          .from("messages")
          .select("*")
          .eq("user_id", user.id)
          .order("created_at", { ascending: false })
          .limit(5);
        setData(messages || []);
        break;
      }
      case "upcoming": {
        const weekEndUpcoming = new Date();
        weekEndUpcoming.setDate(weekEndUpcoming.getDate() + 7);

        const [upcomingReminders, upcomingEvents, urgentTasks] = await Promise.all([
          supabase
            .from("reminders")
            .select("id, text, due_time")
            .eq("user_id", user.id)
            .eq("status", "pending")
            .gte("due_time", new Date().toISOString())
            .lte("due_time", weekEndUpcoming.toISOString())
            .order("due_time", { ascending: true })
            .limit(3),
          supabase
            .from("calendar_events")
            .select("id, title, start_time")
            .eq("user_id", user.id)
            .gte("start_time", new Date().toISOString())
            .lte("start_time", weekEndUpcoming.toISOString())
            .order("start_time", { ascending: true })
            .limit(3),
          supabase
            .from("tasks")
            .select("id, title, due_date, priority")
            .eq("user_id", user.id)
            .eq("status", "pending")
            .in("priority", ["high", "urgent"])
            .order("due_date", { ascending: true })
            .limit(3),
        ]);

        const items: any[] = [];
        if (upcomingReminders.data) items.push(...upcomingReminders.data.map((r) => ({ id: r.id, type: "reminder", title: r.text, time: r.due_time })));
        if (upcomingEvents.data) items.push(...upcomingEvents.data.map((e) => ({ id: e.id, type: "event", title: e.title, time: e.start_time })));
        if (urgentTasks.data) items.push(...urgentTasks.data.map((t) => ({ id: t.id, type: "task", title: t.title, time: t.due_date, priority: t.priority })));

        items.sort((a, b) => new Date(a.time || 0).getTime() - new Date(b.time || 0).getTime());
        setData(items.slice(0, 5));
        break;
      }
      default:
        setData([]);
        break;
    }

    setLoading(false);
  };

  // Special widgets (they render their own cards)
  if (type === "time") return <div className="h-full w-full overflow-hidden"><ClockWidget /></div>;
  if (type === "weather") return <div className="h-full w-full overflow-hidden"><WeatherWidget /></div>;
  if (type === "location") return <div className="h-full w-full overflow-hidden"><MapWidget /></div>;
  if (type === "quick-actions") return <div className="h-full w-full overflow-hidden"><QuickActionsWidget /></div>;
  if (type === "ai-usage") return <div className="h-full w-full overflow-hidden"><AIUsageWidget /></div>;
  if (type === "recent-activity") return <div className="h-full w-full overflow-hidden"><RecentActivityWidget /></div>;
  if (type === "productivity") return <div className="h-full w-full overflow-hidden"><ProductivityWidget /></div>;
  if (type === "upcoming") return <div className="h-full w-full overflow-hidden"><UpcomingWidget /></div>;
  if (type === "messages") return <div className="h-full w-full overflow-hidden"><MessagesWidget /></div>;
  if (type === "calendar") return <div className="h-full w-full overflow-hidden"><CalendarWidget /></div>;
  if (type === "tasks") return <div className="h-full w-full overflow-hidden"><TasksWidget /></div>;
  if (type === "reminders") return <div className="h-full w-full overflow-hidden"><RemindersWidget /></div>;
  if (type === "notes") return <div className="h-full w-full overflow-hidden"><NotesWidget /></div>;
  if (type === "contacts") return <div className="h-full w-full overflow-hidden"><ContactsWidget /></div>;
  if (type === "stocks") return <div className="h-full w-full overflow-hidden"><EnhancedStocksWidget /></div>;
  if (type === "news") return <div className="h-full w-full overflow-hidden"><EnhancedNewsWidget /></div>;

  const formatTime = (time: string) => {
    if (!time) return "No due date";
    const date = parseISO(time);
    if (isToday(date)) return `Today ${format(date, "h:mm a")}`;
    if (isTomorrow(date)) return `Tomorrow ${format(date, "h:mm a")}`;
    return format(date, "MMM d, h:mm a");
  };

  const header = (
    <CardTitle className="text-sm text-white flex items-center gap-2">
      {type === "tasks" && (<><CheckSquare className="h-4 w-4 text-green-400" />Tasks</>)}
      {type === "reminders" && (<><Bell className="h-4 w-4 text-yellow-400" />Reminders</>)}
      {type === "notes" && (<><FileText className="h-4 w-4 text-orange-400" />Notes</>)}
      {type === "calendar" && (<><Calendar className="h-4 w-4 text-blue-400" />Calendar</>)}
      {type === "contacts" && (<><Users className="h-4 w-4 text-cyan-400" />Contacts</>)}
      {type === "messages" && (<><Send className="h-4 w-4 text-emerald-400" />Messages</>)}
      {type === "upcoming" && (<><TrendingUp className="h-4 w-4 text-fuchsia-400" />Coming Up</>)}
    </CardTitle>
  );

  if (loading) {
    return (
      <Card className="border-slate-700 bg-slate-800/50 backdrop-blur h-full w-full overflow-hidden flex flex-col">
        <CardHeader className="p-3 pb-2 shrink-0">{header}</CardHeader>
        <CardContent className="p-3 pt-0 flex-1 min-h-0 flex items-center justify-center">
          <div className="animate-pulse text-slate-400 text-xs">Loading...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-slate-700 bg-slate-800/50 backdrop-blur h-full w-full overflow-hidden flex flex-col">
      <CardHeader className="p-3 pb-2 shrink-0">{header}</CardHeader>

      <CardContent className="p-3 pt-0 flex-1 min-h-0 overflow-y-auto">
        {!data || data.length === 0 ? (
          <p className="text-xs text-slate-500 text-center py-4">No items</p>
        ) : (
          <div className="space-y-2">
            {type === "upcoming" ? (
              data.map((item: any) => (
                <div key={`${item.type}-${item.id}`} className="flex items-center gap-2 p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-white truncate">{item.title}</p>
                    <p className="text-[10px] text-slate-500">{formatTime(item.time)}</p>
                  </div>
                </div>
              ))
            ) : type === "tasks" ? (
              data.map((task: any) => (
                <div key={task.id} className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                  <p className="text-xs text-white truncate">{task.title}</p>
                  {task.due_date && <p className="text-[10px] text-slate-500">{formatTime(task.due_date)}</p>}
                </div>
              ))
            ) : type === "reminders" ? (
              data.map((reminder: any) => (
                <div key={reminder.id} className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                  <p className="text-xs text-white truncate">{reminder.text}</p>
                  <p className="text-[10px] text-slate-500">{formatTime(reminder.due_time)}</p>
                </div>
              ))
            ) : type === "notes" ? (
              data.map((note: any) => (
                <div key={note.id} className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                  <p className="text-xs text-white font-medium truncate">{note.title}</p>
                  <p className="text-[10px] text-slate-500 line-clamp-2">{note.content}</p>
                </div>
              ))
            ) : type === "calendar" ? (
              data.map((event: any) => (
                <div key={event.id} className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                  <p className="text-xs text-white truncate">{event.title}</p>
                  <p className="text-[10px] text-slate-500">{formatTime(event.start_time)}</p>
                </div>
              ))
            ) : type === "contacts" ? (
              data.map((contact: any) => (
                <div key={contact.id} className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                  <p className="text-xs text-white truncate">{contact.name}</p>
                  <p className="text-[10px] text-slate-500 truncate">{contact.phone}</p>
                </div>
              ))
            ) : type === "messages" ? (
              data.map((message: any) => (
                <div key={message.id} className="p-2 rounded-lg bg-slate-900/50 border border-slate-700/50">
                  <p className="text-xs text-white font-medium truncate">{message.from_name || "Unknown"}</p>
                  <p className="text-[10px] text-slate-500 line-clamp-2">{message.message_text}</p>
                </div>
              ))
            ) : null}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import React from "react";
import { Card, CardContent } from "@/components/ui/card";
import { WIDGET_CONFIGS } from "@/types/widgets";
import {
  Clock,
  CloudSun,
  CheckSquare,
  Bell,
  FileText,
  Calendar,
  TrendingUp,
  Users,
  Send,
  MapPin,
  Target,
  Brain,
  Zap,
  Activity,
  Newspaper,
} from "lucide-react";

const ICON_MAP: Record<string, any> = {
  Clock,
  CloudSun,
  CheckSquare,
  Bell,
  FileText,
  Calendar,
  TrendingUp, // Used for both "upcoming" and "stocks"
  Users,
  Send,
  MapPin,
  Target,
  Brain,
  Zap,
  Activity,
  Newspaper,
};

export default function WidgetPicker() {
  const handleWidgetClick = (type: string) => {
    const config = WIDGET_CONFIGS[type];
    if (config && (window as any).addWidgetToDashboard) {
      (window as any).addWidgetToDashboard(type, config.defaultSize);
    }
  };

  return (
    <div className="space-y-3">
      <div>
        <h3 className="text-sm font-semibold text-slate-700 mb-1">Available Widgets</h3>
        <p className="text-xs text-slate-500">Click to add to dashboard</p>
      </div>
      <div className="grid grid-cols-2 gap-2">
        {Object.values(WIDGET_CONFIGS).map((config) => {
          const Icon = ICON_MAP[config.icon];
          return (
            <Card
              key={config.type}
              onClick={() => handleWidgetClick(config.type)}
              className="cursor-pointer border-slate-200/60 bg-white/90 hover:bg-gradient-to-br hover:from-purple-50/90 hover:to-fuchsia-50/90 transition-all hover:shadow-md backdrop-blur-sm active:scale-95"
            >
              <CardContent className="p-3 flex flex-col items-center text-center gap-2">
                <div className="p-2 rounded-lg bg-slate-100">
                  {Icon && <Icon className="h-5 w-5 text-purple-500" />}
                </div>
                <span className="text-xs text-slate-700 font-medium">{config.name}</span>
                <span className="text-[10px] text-slate-500">
                  {config.defaultSize.w}├ù{config.defaultSize.h}
                </span>
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Plus, GripVertical, RotateCcw, AlertTriangle } from "lucide-react";
import type { Widget } from "@/types/widgets";
import { WIDGET_CONFIGS } from "@/types/widgets";
import { usePreferences } from "@/state/preferences";
import { showSuccess, showError } from "@/utils/toast";
import { findNextPosition, packWidgets } from "../system/layout.ts";
import WidgetCell from "./WidgetCell.tsx";
import { trackWidgetInteraction } from "@/services/analytics";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";

const GRID_COLS = 4;
const CELL_HEIGHT = 100;
const GAP = 8;
const PADDING = 12;
const DEBOUNCE_MS = 100;

type ResizeDir = "n" | "s" | "e" | "w" | "ne" | "nw" | "se" | "sw";

const DEFAULT_WIDGETS: Widget[] = [
  { id: "default-1", type: "time", x: 0, y: 0, w: 1, h: 1 },
  { id: "default-2", type: "weather", x: 1, y: 0, w: 2, h: 2 },
  { id: "default-3", type: "tasks", x: 3, y: 0, w: 1, h: 2 },
  { id: "default-4", type: "upcoming", x: 0, y: 2, w: 2, h: 2 },
];

function validateWidget(widget: Partial<Widget>): widget is Widget {
  return (
    typeof widget.id === 'string' &&
    typeof widget.type === 'string' &&
    typeof widget.x === 'number' &&
    typeof widget.y === 'number' &&
    typeof widget.w === 'number' &&
    typeof widget.h === 'number' &&
    widget.w > 0 && widget.h > 0
  );
}

function sanitizeWidgets(widgets: any[]): Widget[] {
  return widgets.filter(validateWidget).map(w => ({
    ...w,
    x: Math.max(0, Math.min(GRID_COLS - w.w, w.x)),
    y: Math.max(0, w.y),
    w: Math.max(1, Math.min(GRID_COLS, w.w)),
    h: Math.max(1, w.h)
  }));
}

function buildOccupied(widgets: Widget[], excludeId?: string) {
  const occ = new Set<string>();
  for (const w of widgets) {
    if (excludeId && w.id === excludeId) continue;
    for (let dy = 0; dy < w.h; dy++) {
      for (let dx = 0; dx < w.w; dx++) {
        occ.add(`${w.x + dx},${w.y + dy}`);
      }
    }
  }
  return occ;
}

function canPlaceAt(widgets: Widget[], x: number, y: number, w: number, h: number, excludeId?: string) {
  if (x < 0 || y < 0 || x + w > GRID_COLS) return false;
  const occ = buildOccupied(widgets, excludeId);
  for (let dy = 0; dy < h; dy++) {
    for (let dx = 0; dx < w; dx++) {
      if (occ.has(`${x + dx},${y + dy}`)) return false;
    }
  }
  return true;
}

function debounce<T extends (...args: any[]) => any>(func: T, wait: number): T {
  let timeout: NodeJS.Timeout;
  return ((...args: Parameters<T>) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), wait);
  }) as T;
}

export default function WidgetGrid() {
  const { user } = useAuth();
  const { preferences, setPreferences } = usePreferences();
  const [isEditMode, setIsEditMode] = useState(false);
  const [widgets, setWidgets] = useState<Widget[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [activeResize, setActiveResize] = useState<{
    widgetId: string;
    dir: ResizeDir;
    startX: number;
    startY: number;
    original: Widget;
  } | null>(null);

  const [activeDrag, setActiveDrag] = useState<{
    widgetId: string;
    startX: number;
    startY: number;
    original: Widget;
  } | null>(null);

  const gridHeight = useMemo(() => {
    if (widgets.length === 0) return 400;
    const maxRow = Math.max(...widgets.map((w) => w.y + w.h));
    return Math.max(400, maxRow * CELL_HEIGHT + (maxRow - 1) * GAP + 24);
  }, [widgets]);

  const getCellWidth = useCallback(() => {
    const el = containerRef.current;
    if (!el) return 0;
    const contentWidth = el.clientWidth - PADDING * 2;
    return (contentWidth - GAP * (GRID_COLS - 1)) / GRID_COLS;
  }, []);

  // Sync widgets to Supabase
  const syncWidgetsToSupabase = useCallback(async (userId: string, widgets: Widget[]) => {
    try {
      await supabase.from('user_widgets').delete().eq('user_id', userId);

      if (widgets.length > 0) {
        const widgetData = widgets.map(w => ({
          user_id: userId,
          widget_id: w.id,
          widget_type: w.type,
          position: { x: w.x, y: w.y },
          size: { w: w.w, h: w.h },
          config: {},
        }));

        await supabase.from('user_widgets').insert(widgetData);
      }
    } catch (error) {
      console.error('Failed to sync widgets to Supabase:', error);
    }
  }, []);

  // Save widgets with debounce
  const saveWidgets = useCallback(
    debounce(async (next: Widget[]) => {
      try {
        const sanitized = sanitizeWidgets(next);
        const packed = packWidgets(sanitized);
        setWidgets(packed);
        setPreferences({ ...preferences, widgets: packed });
        
        if (user) {
          await syncWidgetsToSupabase(user.id, packed);
        }
        
        setError(null);
      } catch (err) {
        console.error('Failed to save widgets:', err);
        setError('Failed to save layout');
        showError('Could not save widget layout');
      }
    }, DEBOUNCE_MS),
    [preferences, setPreferences, user, syncWidgetsToSupabase]
  );

  // Load widgets on mount - only once per user
  useEffect(() => {
    let isMounted = true;
    
    const loadWidgets = async () => {
      if (!isMounted) return;
      
      try {
        setIsLoading(true);
        setError(null);
        
        let initial: Widget[];
        
        if (user) {
          const { data: savedWidgets, error: loadError } = await supabase
            .from('user_widgets')
            .select('*')
            .eq('user_id', user.id);

          if (!isMounted) return;

          if (!loadError && savedWidgets && savedWidgets.length > 0) {
            initial = savedWidgets.map(w => ({
              id: w.widget_id,
              type: w.widget_type,
              x: w.position.x,
              y: w.position.y,
              w: w.size.w,
              h: w.size.h,
            }));
            
            const sanitized = sanitizeWidgets(initial);
            initial = packWidgets(sanitized);
          } else {
            initial = packWidgets(DEFAULT_WIDGETS);
            if (isMounted) {
              await syncWidgetsToSupabase(user.id, initial);
            }
          }
        } else {
          const saved = preferences.widgets;
          if (Array.isArray(saved) && saved.length > 0) {
            const sanitized = sanitizeWidgets(saved as Widget[]);
            initial = packWidgets(sanitized);
          } else {
            initial = packWidgets(DEFAULT_WIDGETS);
          }
        }
        
        if (isMounted) {
          setWidgets(initial);
        }
      } catch (err) {
        console.error('Failed to initialize widgets:', err);
        if (isMounted) {
          setError('Failed to load widgets');
          const fallback = packWidgets(DEFAULT_WIDGETS);
          setWidgets(fallback);
        }
      } finally {
        if (isMounted) {
          setIsLoading(false);
        }
      }
    };

    loadWidgets();
    
    return () => {
      isMounted = false;
    };
  }, [user?.id]);

  const resetLayout = useCallback(() => {
    try {
      saveWidgets(DEFAULT_WIDGETS);
      showSuccess("Layout reset");
      setError(null);
    } catch (err) {
      console.error('Failed to reset layout:', err);
      setError('Failed to reset layout');
      showError('Could not reset layout');
    }
  }, [saveWidgets]);

  const removeWidget = useCallback(
    (id: string) => {
      try {
        const widget = widgets.find(w => w.id === id);
        const filtered = widgets.filter((w) => w.id !== id);
        saveWidgets(filtered);
        showSuccess("Widget removed");
        
        if (widget && user) {
          trackWidgetInteraction(widget.type, "remove", {}, user.id);
        }
      } catch (err) {
        console.error('Failed to remove widget:', err);
        showError('Could not remove widget');
      }
    },
    [saveWidgets, widgets, user]
  );

  const addWidget = useCallback(
    (type: string, size: { w: number; h: number }) => {
      try {
        if (widgets.some((w) => w.type === type)) {
          showSuccess(`${type} already exists`);
          return;
        }

        const cfg = WIDGET_CONFIGS[type];
        if (!cfg) {
          showError(`Unknown widget type: ${type}`);
          return;
        }

        const w = Math.max(1, Math.min(GRID_COLS, cfg.defaultSize.w || size.w));
        const h = Math.max(1, cfg.defaultSize.h || size.h);

        const pos = findNextPosition(widgets, w, h);
        if (!pos) {
          showError('No space available for widget');
          return;
        }

        const next: Widget[] = [
          ...widgets,
          {
            id: `${type}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            type,
            x: pos.x,
            y: pos.y,
            w,
            h,
          },
        ];

        saveWidgets(next);
        showSuccess(`Added ${type}`);
        
        if (user) {
          trackWidgetInteraction(type, "add", { w, h }, user.id);
        }
      } catch (err) {
        console.error('Failed to add widget:', err);
        showError('Could not add widget');
      }
    },
    [saveWidgets, widgets, user]
  );

  useEffect(() => {
    (window as any).addWidgetToDashboard = addWidget;
    (window as any).removeWidgetFromDashboard = removeWidget;
    (window as any).getCurrentWidgets = () => widgets;
    (window as any).setWidgets = (newWidgets: Widget[]) => saveWidgets(newWidgets);
    
    return () => {
      delete (window as any).addWidgetToDashboard;
      delete (window as any).removeWidgetFromDashboard;
      delete (window as any).getCurrentWidgets;
      delete (window as any).setWidgets;
    };
  }, [addWidget, removeWidget, widgets, saveWidgets]);

  const beginResize = useCallback(
    (widget: Widget, dir: ResizeDir, clientX: number, clientY: number) => {
      if (!isEditMode) return;
      setActiveResize({
        widgetId: widget.id,
        dir,
        startX: clientX,
        startY: clientY,
        original: { ...widget },
      });
    },
    [isEditMode]
  );

  const beginDrag = useCallback(
    (widget: Widget, clientX: number, clientY: number) => {
      if (!isEditMode) return;
      setActiveDrag({
        widgetId: widget.id,
        startX: clientX,
        startY: clientY,
        original: { ...widget },
      });
    },
    [isEditMode]
  );

  useEffect(() => {
    if (!activeResize) return;

    const onMove = (e: PointerEvent) => {
      try {
        const cellW = getCellWidth();
        if (!cellW) return;

        const dx = e.clientX - activeResize.startX;
        const dy = e.clientY - activeResize.startY;

        const dCols = Math.round(dx / (cellW + GAP));
        const dRows = Math.round(dy / (CELL_HEIGHT + GAP));

        const cfg = WIDGET_CONFIGS[activeResize.original.type];
        const minW = cfg?.minSize.w ?? 1;
        const minH = cfg?.minSize.h ?? 1;
        const maxW = cfg?.maxSize.w ?? GRID_COLS;
        const maxH = cfg?.maxSize.h ?? 200;

        let nextW = activeResize.original.w;
        let nextH = activeResize.original.h;
        let nextX = activeResize.original.x;
        let nextY = activeResize.original.y;

        if (activeResize.dir === "e" || activeResize.dir === "se" || activeResize.dir === "ne") {
          nextW = activeResize.original.w + dCols;
        } else if (activeResize.dir === "w" || activeResize.dir === "sw" || activeResize.dir === "nw") {
          nextW = activeResize.original.w - dCols;
          nextX = activeResize.original.x + dCols;
        }

        if (activeResize.dir === "s" || activeResize.dir === "se" || activeResize.dir === "sw") {
          nextH = activeResize.original.h + dRows;
        } else if (activeResize.dir === "n" || activeResize.dir === "ne" || activeResize.dir === "nw") {
          nextH = activeResize.original.h - dRows;
          nextY = activeResize.original.y + dRows;
        }

        nextW = Math.max(minW, Math.min(maxW, nextW));
        nextH = Math.max(minH, Math.min(maxH, nextH));
        nextX = Math.max(0, Math.min(GRID_COLS - nextW, nextX));
        nextY = Math.max(0, nextY);

        if (nextW === activeResize.original.w && nextH === activeResize.original.h) return;

        const ok = canPlaceAt(widgets, nextX, nextY, nextW, nextH, activeResize.widgetId);
        if (!ok) return;

        setWidgets((prev) =>
          prev.map((w) =>
            w.id === activeResize.widgetId ? { ...w, x: nextX, y: nextY, w: nextW, h: nextH } : w
          )
        );
      } catch (err) {
        console.error('Resize error:', err);
      }
    };

    const onUp = () => {
      try {
        saveWidgets(widgets);
        
        if (user && activeResize) {
          const widget = widgets.find(w => w.id === activeResize.widgetId);
          if (widget) {
            trackWidgetInteraction(widget.type, "resize", {
              direction: activeResize.dir,
              newSize: { w: widget.w, h: widget.h }
            }, user.id);
          }
        }
        
        setActiveResize(null);
      } catch (err) {
        console.error('Resize save error:', err);
        setActiveResize(null);
      }
    };

    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp, { once: true });

    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp as any);
    };
  }, [activeResize, getCellWidth, saveWidgets, widgets, user]);

  useEffect(() => {
    if (!activeDrag) return;

    const onMove = (e: PointerEvent) => {
      try {
        const cellW = getCellWidth();
        if (!cellW) return;

        const dx = e.clientX - activeDrag.startX;
        const dy = e.clientY - activeDrag.startY;

        const dCols = Math.round(dx / (cellW + GAP));
        const dRows = Math.round(dy / (CELL_HEIGHT + GAP));

        let nextX = activeDrag.original.x + dCols;
        let nextY = activeDrag.original.y + dRows;

        nextX = Math.max(0, Math.min(GRID_COLS - activeDrag.original.w, nextX));
        nextY = Math.max(0, nextY);

        const ok = canPlaceAt(widgets, nextX, nextY, activeDrag.original.w, activeDrag.original.h, activeDrag.widgetId);
        if (!ok) return;

        setWidgets((prev) =>
          prev.map((w) =>
            w.id === activeDrag.widgetId ? { ...w, x: nextX, y: nextY } : w
          )
        );
      } catch (err) {
        console.error('Drag error:', err);
      }
    };

    const onUp = () => {
      try {
        saveWidgets(widgets);
        
        if (user && activeDrag) {
          const widget = widgets.find(w => w.id === activeDrag.widgetId);
          if (widget) {
            trackWidgetInteraction(widget.type, "move", {
              newPosition: { x: widget.x, y: widget.y }
            }, user.id);
          }
        }
        
        setActiveDrag(null);
      } catch (err) {
        console.error('Drag save error:', err);
        setActiveDrag(null);
      }
    };

    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp, { once: true });

    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp as any);
    };
  }, [activeDrag, getCellWidth, saveWidgets, widgets, user]);

  if (isLoading) {
    return (
      <div className="space-y-3">
        <div className="flex items-center justify-center min-h-[300px]">
          <div className="text-center text-slate-400">
            <GripVertical className="h-12 w-12 mx-auto mb-2 opacity-50 animate-pulse" />
            <p className="text-sm">Loading widgets...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm text-slate-300 font-medium">
            {isEditMode ? "Edit Mode" : "Widgets"}
          </p>
          <p className="text-xs text-slate-500">
            {isEditMode ? (
              activeResize ? `Resizing widget...` :
              activeDrag ? `Moving widget...` :
              "Drag to move, resize from handles"
            ) : `${widgets.length} widgets`}
          </p>
        </div>

        <div className="flex gap-2">
          {isEditMode && (
            <Button
              size="sm"
              variant="outline"
              onClick={resetLayout}
              className="border-slate-600 text-slate-300"
              title="Reset layout"
            >
              <RotateCcw className="h-4 w-4" />
            </Button>
          )}
          <Button
            size="sm"
            variant={isEditMode ? "default" : "outline"}
            onClick={() => setIsEditMode(!isEditMode)}
            aria-label={isEditMode ? "Finish editing widgets" : "Edit widget layout"}
            aria-pressed={isEditMode}
            className={isEditMode ? "bg-fuchsia-600 hover:bg-fuchsia-500" : "border-slate-600 text-slate-300"}
          >
            {isEditMode ? (
              "Done"
            ) : (
              <>
                <Plus className="h-4 w-4 mr-1" />
                Edit
              </>
            )}
          </Button>
        </div>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-900/20 border border-red-500/30">
          <AlertTriangle className="h-4 w-4 text-red-400" />
          <p className="text-sm text-red-300">{error}</p>
        </div>
      )}

      <div
        ref={containerRef}
        className={`relative rounded-xl border-2 p-3 transition-colors ${
          isEditMode
            ? activeResize || activeDrag
              ? "border-fuchsia-400 bg-fuchsia-500/10 border-solid"
              : "border-fuchsia-400/50 bg-fuchsia-500/5 border-dashed"
            : "border-slate-700/30 bg-transparent"
        }`}
        style={{ minHeight: gridHeight }}
      >
        {widgets.length === 0 ? (
          <div className="flex items-center justify-center min-h-[300px]">
            <div className="text-center text-slate-400">
              <GripVertical className="h-12 w-12 mx-auto mb-2 opacity-50" />
              <p className="text-sm">No widgets</p>
              <p className="text-xs text-slate-500 mt-1">Click Edit to add</p>
            </div>
          </div>
        ) : (
          <div
            className="grid"
            style={{
              gridTemplateColumns: `repeat(${GRID_COLS}, minmax(0, 1fr))`,
              gridAutoRows: `${CELL_HEIGHT}px`,
              gap: `${GAP}px`,
              alignContent: "start",
            }}
          >
            {widgets.map((widget) => (
              <div
                key={widget.id}
                className="min-h-0 min-w-0"
                style={{
                  gridColumn: `${widget.x + 1} / span ${widget.w}`,
                  gridRow: `${widget.y + 1} / span ${widget.h}`,
                }}
              >
                <WidgetCell
                  widget={widget}
                  isEditMode={isEditMode}
                  onRemove={() => removeWidget(widget.id)}
                  onResizeStart={(dir, x, y) => beginResize(widget, dir, x, y)}
                  onDragStart={(widget, x, y) => beginDrag(widget, x, y)}
                />
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { createContext, useContext, useEffect, useState, ReactNode } from "react";
import { User, Session } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";

interface AuthContextType {
  user: User | null;
  session: Session | null;
  loading: boolean;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  session: null,
  loading: true,
  signOut: async () => {},
});

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Get initial session
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setUser(session?.user ?? null);
      setLoading(false);
    });

    // Listen for auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      (_event, session) => {
        setSession(session);
        setUser(session?.user ?? null);
        setLoading(false);
      }
    );

    return () => subscription.unsubscribe();
  }, []);

  const signOut = async () => {
    await supabase.auth.signOut();
  };

  return (
    <AuthContext.Provider value={{ user, session, loading, signOut }}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);

import React, { createContext, useContext, useState, useCallback, useEffect, useRef } from 'react';
import { useAuth } from './AuthContext';
import { usePreferences } from '@/state/preferences';
import { showSuccess } from '@/utils/toast';

// Import modular hooks
import { useVoiceState } from '@/hooks/useVoiceState';
import { useVoiceConfig } from '@/hooks/useVoiceConfig';
import { useWakeWord } from '@/hooks/useWakeWord';
import { useVoiceCommands } from '@/hooks/useVoiceCommands';

// Lazy imports for heavy services to prevent blocking
let getLocationContext: any = null;
let initializeRAGKnowledge: any = null;
let conversationManager: any = null;
let voiceRecorder: any = null;
let voicePlayer: any = null;

// Initialize services lazily
async function initializeServices() {
  try {
    if (!getLocationContext) {
      const contextModule = await import('@/services/context');
      getLocationContext = contextModule.getLocationContext;
    }
    if (!initializeRAGKnowledge) {
      const ragModule = await import('@/services/rag-knowledge');
      initializeRAGKnowledge = ragModule.initializeRAGKnowledge;
    }
    if (!conversationManager || !voiceRecorder || !voicePlayer) {
      const voiceModule = await import('@/services/voice');
      conversationManager = voiceModule.conversationManager;
      voiceRecorder = voiceModule.voiceRecorder;
      voicePlayer = voiceModule.voicePlayer;
    }
    return true;
  } catch (error) {
    console.error('[VoiceContext] Failed to initialize services:', error);
    return false;
  }
}

// Location context type
interface LocationContext {
  city?: string;
  country?: string;
  timezone?: string;
  coordinates?: { lat: number; lng: number };
}

interface VoiceContextType {
  isListening: boolean;
  isProcessing: boolean;
  isSpeaking: boolean;
  isQuietMode: boolean;
  isConversationMode: boolean;
  lastTranscript: string;
  currentTranscript: string;
  lastResponse: string;
  startListening: () => Promise<void>;
  stopListening: () => void;
  speak: (text: string) => Promise<void>;
  stopSpeaking: () => void;
  processVoiceCommand: (text: string) => Promise<string>;
  enterQuietMode: (context?: string) => void;
  exitQuietMode: () => Promise<{ summary: string; bulletPoints: string[]; actionItems: string[] } | null>;
  startConversationMode: () => Promise<void>;
  stopConversationMode: () => void;
}

const VoiceContext = createContext<VoiceContextType | null>(null);

export function useVoice() {
  const context = useContext(VoiceContext);
  if (!context) {
    throw new Error('useVoice must be used within a VoiceProvider');
  }
  return context;
}

export function VoiceProvider({ children }: { children: React.ReactNode }) {
  const { user } = useAuth();
  const { preferences } = usePreferences();
  const config = useVoiceConfig();
  
  // Services initialized state
  const [servicesReady, setServicesReady] = useState(false);
  
  // Location state
  const [userLocation, setUserLocation] = useState<LocationContext | null>(null);
  
  // Voice state management
  const voiceState = useVoiceState();
  const {
    isListening,
    isProcessing,
    isSpeaking,
    isQuietMode,
    isConversationMode,
    lastTranscript,
    currentTranscript,
    lastResponse,
    setIsListening,
    setIsProcessing,
    setIsSpeaking,
    setIsQuietMode,
    setIsConversationMode,
    setLastTranscript,
    setCurrentTranscript,
    setLastResponse,
    conversationModeRef,
    isStartingRef,
  } = voiceState;

  // Ref to hold the startListening function for use in callbacks
  const startListeningRef = useRef<((isConversation: boolean) => Promise<void>) | null>(null);

  // Initialize services on mount
  useEffect(() => {
    initializeServices().then(ready => {
      setServicesReady(ready);
    });
  }, []);

  // Get location on mount (after services ready)
  useEffect(() => {
    if (!servicesReady || !getLocationContext) return;
    
    getLocationContext().then((loc: LocationContext | null) => {
      if (loc) setUserLocation(loc);
    }).catch(() => {});
  }, [servicesReady]);

  // Initialize RAG knowledge base (after services ready)
  useEffect(() => {
    if (!servicesReady || !user || !initializeRAGKnowledge) return;
    
    initializeRAGKnowledge(user.id);
  }, [user, servicesReady]);

  // Check quiet mode status on mount (after services ready)
  useEffect(() => {
    if (!servicesReady || !user || !conversationManager) return;
    
    const isActive = conversationManager.checkQuietModeStatus(user.id);
    setIsQuietMode(isActive);
  }, [user, setIsQuietMode, servicesReady]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      isStartingRef.current = false;
      if (voiceRecorder) voiceRecorder.stop();
      if (voicePlayer) voicePlayer.stop();
    };
  }, [isStartingRef]);

  // Stop speaking function
  const stopSpeaking = useCallback(() => {
    if (voicePlayer) voicePlayer.stop();
    setIsSpeaking(false);
  }, [setIsSpeaking]);

  // Speak function with auto-continue for conversation mode
  const speak = useCallback(async (text: string) => {
    if (!text?.trim() || !voicePlayer) return;

    stopSpeaking();

    try {
      setIsSpeaking(true);
      console.log('[Voice] Speaking:', text.substring(0, 50) + '...');
      
      await voicePlayer.speak(text, config.openaiApiKey, {
        voice: config.openaiVoice,
        rate: config.voiceSpeed,
        onEnd: () => {
          console.log('[Voice] Speech ended');
          setIsSpeaking(false);
          
          // Auto-continue conversation mode - start listening again
          if (conversationModeRef.current && !isStartingRef.current) {
            console.log('[Voice] Auto-continuing conversation mode, starting to listen...');
            setTimeout(() => {
              if (conversationModeRef.current && startListeningRef.current) {
                startListeningRef.current(true);
              }
            }, 300);
          }
        },
        onError: (error) => {
          console.error('[Voice] Speech error:', error);
          setIsSpeaking(false);
          
          // Even on error, try to continue conversation
          if (conversationModeRef.current && !isStartingRef.current) {
            setTimeout(() => {
              if (conversationModeRef.current && startListeningRef.current) {
                startListeningRef.current(true);
              }
            }, 500);
          }
        },
      });
    } catch (error: any) {
      console.error('[Voice] Speak error:', error);
      setIsSpeaking(false);
      
      // Even on error, try to continue conversation
      if (conversationModeRef.current && !isStartingRef.current) {
        setTimeout(() => {
          if (conversationModeRef.current && startListeningRef.current) {
            startListeningRef.current(true);
          }
        }, 500);
      }
    }
  }, [config.openaiApiKey, config.openaiVoice, config.voiceSpeed, stopSpeaking, setIsSpeaking, conversationModeRef, isStartingRef]);

  // Quiet mode handlers
  const enterQuietMode = useCallback((context?: string) => {
    if (!user || !conversationManager) return;
    conversationManager.enterQuietMode(user.id, context);
    setIsQuietMode(true);
    showSuccess(`Entering quiet mode${context ? ` for ${context}` : ''}. I'll just listen.`);
  }, [user, setIsQuietMode]);

  const exitQuietMode = useCallback(async () => {
    if (!user || !config.openaiApiKey || !conversationManager) {
      setIsQuietMode(false);
      return null;
    }

    const result = await conversationManager.exitQuietMode(user.id, config.openaiApiKey);
    setIsQuietMode(false);
    return result;
  }, [user, config.openaiApiKey, setIsQuietMode]);

  // Stop conversation mode
  const stopConversationMode = useCallback(() => {
    console.log('[Voice] Stopping conversation mode');
    conversationModeRef.current = false;
    setIsConversationMode(false);
    isStartingRef.current = false;
    if (conversationManager) conversationManager.stopConversation();
    
    if (voiceRecorder) voiceRecorder.stop();
    setIsListening(false);
    if (voicePlayer) voicePlayer.stop();
    setIsSpeaking(false);
  }, [conversationModeRef, isStartingRef, setIsConversationMode, setIsListening, setIsSpeaking]);

  // Voice commands hook
  const { processCommand, handleTranscription } = useVoiceCommands({
    userId: user?.id || null,
    config,
    userLocation,
    isQuietMode,
    onProcessingChange: setIsProcessing,
    onTranscriptChange: setLastTranscript,
    onResponseChange: setLastResponse,
    speak,
    stopConversationMode,
    enterQuietMode,
    exitQuietMode,
  });

  // Wrapped transcription handler that also sets current transcript
  const handleTranscriptionWithState = useCallback(async (text: string, isConversation: boolean) => {
    setCurrentTranscript(text);
    await handleTranscription(text, isConversation);
  }, [handleTranscription, setCurrentTranscript]);

  // Start listening function (internal)
  const startListeningInternal = useCallback(async (isConversation: boolean = false) => {
    if (isStartingRef.current || isListening) {
      console.log('[Voice] Already listening or starting');
      return;
    }

    if (!config.openaiApiKey) {
      console.log('[Voice] No API key');
      return;
    }

    if (!voiceRecorder) {
      console.log('[Voice] Voice recorder not ready');
      return;
    }

    isStartingRef.current = true;
    console.log(`[Voice] Starting listening (conversation: ${isConversation})`);

    voiceRecorder.start(
      {
        onStart: () => {
          setIsListening(true);
          isStartingRef.current = false;
          console.log(`[Voice] Recording started (${isConversation ? 'conversation' : 'single'} mode)`);
        },
        onStop: () => {
          console.log('[Voice] Recording stopped');
        },
        onData: async (blob) => {
          console.log(`[Voice] Recording complete, size: ${blob.size}`);
          setIsListening(false);
          
          // Check minimum size
          if (blob.size < 1000) {
            console.log('[Voice] Recording too small, likely no audio captured');
            // Continue conversation mode even on short recordings
            if (conversationModeRef.current && !isStartingRef.current) {
              console.log('[Voice] Continuing conversation mode after short recording...');
              setTimeout(() => startListeningRef.current?.(true), 500);
            }
            return;
          }

          try {
            // Import transcription function
            const { transcribeAudio } = await import('@/services/openai-voice');
            const result = await transcribeAudio(blob, config.openaiApiKey!);
            const text = (result.text || '').trim();
            
            console.log('[Voice] Transcription result:', text || '(empty)');
            
            if (!text) {
              console.log('[Voice] Empty transcription');
              // Continue conversation mode even on empty transcription
              if (conversationModeRef.current && !isStartingRef.current) {
                console.log('[Voice] Continuing conversation mode after empty transcription...');
                setTimeout(() => startListeningRef.current?.(true), 500);
              }
              return;
            }
            
            // Process the transcription
            await handleTranscriptionWithState(text, isConversation);
          } catch (error: any) {
            console.error('[Voice] Transcription error:', error);
            
            // Continue conversation mode even on transcription failure
            if (conversationModeRef.current && !isStartingRef.current) {
              console.log('[Voice] Continuing conversation mode after error...');
              setTimeout(() => startListeningRef.current?.(true), 1000);
            }
          }
        },
        onError: (error) => {
          console.error('[Voice] Recording error:', error);
          isStartingRef.current = false;
          setIsListening(false);
        },
        onSilenceDetected: isConversation ? () => {
          console.log('[Voice] Silence detected, stopping recording');
          voiceRecorder.stop();
        } : undefined,
      },
      isConversation // Enable silence detection for conversation mode
    );
  }, [config.openaiApiKey, isListening, isStartingRef, conversationModeRef, setIsListening, handleTranscriptionWithState]);

  // Update the ref whenever the function changes
  useEffect(() => {
    startListeningRef.current = startListeningInternal;
  }, [startListeningInternal]);

  // Stop listening
  const stopListening = useCallback(() => {
    console.log('[Voice] Stopping listening');
    isStartingRef.current = false;
    if (voiceRecorder) voiceRecorder.stop();
    setIsListening(false);
  }, [isStartingRef, setIsListening]);

  // Public start listening (single command mode)
  const startListening = useCallback(async () => {
    await startListeningInternal(false);
  }, [startListeningInternal]);

  // Start conversation mode
  const startConversationMode = useCallback(async () => {
    if (isConversationMode) return;
    
    console.log('[Voice] Starting conversation mode');
    setIsConversationMode(true);
    conversationModeRef.current = true;
    if (conversationManager) conversationManager.startConversation();
    
    // Get user's preferred name for personalized greeting
    const userName = preferences.preferredName?.trim();
    console.log('[Voice] User preferred name:', userName || '(not set)');
    
    // Personalized greeting - always use name if available
    let greeting: string;
    if (userName) {
      greeting = `Hi ${userName}! How can I help you?`;
    } else {
      greeting = `Hi there! How can I help you?`;
    }
    
    console.log('[Voice] Greeting:', greeting);
    
    // Speak greeting - the onEnd callback will automatically start listening
    await speak(greeting);
  }, [isConversationMode, speak, preferences.preferredName, setIsConversationMode, conversationModeRef]);

  // Wake word detection
  useWakeWord({
    enabled: preferences.wakeWordEnabled || false,
    wakeWord: preferences.wakeWord || 'echo',
    assistantName: config.assistantName,
    isListening,
    isProcessing,
    isSpeaking,
    isConversationMode,
    onWakeWordDetected: startConversationMode,
  });

  return (
    <VoiceContext.Provider
      value={{
        isListening,
        isProcessing,
        isSpeaking,
        isQuietMode,
        isConversationMode,
        lastTranscript,
        currentTranscript,
        lastResponse,
        startListening,
        stopListening,
        speak,
        stopSpeaking,
        processVoiceCommand: processCommand,
        enterQuietMode,
        exitQuietMode,
        startConversationMode,
        stopConversationMode,
      }}
    >
      {children}
    </VoiceContext.Provider>
  );
}

/**
 * useAsyncOperation Hook
 * Provides consistent handling for async operations with:
 * - Loading state management
 * - Error handling with user-friendly messages
 * - Success callbacks
 * - Automatic cleanup on unmount
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { showError, showSuccess } from '@/utils/toast';
import { logger } from '@/utils/logger';

export interface AsyncOperationState<T> {
  data: T | null;
  isLoading: boolean;
  error: string | null;
  isSuccess: boolean;
}

export interface AsyncOperationOptions<T> {
  onSuccess?: (data: T) => void;
  onError?: (error: string) => void;
  successMessage?: string;
  errorMessage?: string;
  showSuccessToast?: boolean;
  showErrorToast?: boolean;
  logErrors?: boolean;
}

export interface UseAsyncOperationReturn<T, P extends any[]> {
  execute: (...params: P) => Promise<T | null>;
  reset: () => void;
  data: T | null;
  isLoading: boolean;
  error: string | null;
  isSuccess: boolean;
}

const DEFAULT_OPTIONS: AsyncOperationOptions<any> = {
  showSuccessToast: false,
  showErrorToast: true,
  logErrors: true,
};

export function useAsyncOperation<T, P extends any[] = []>(
  asyncFn: (...params: P) => Promise<T>,
  options: AsyncOperationOptions<T> = {}
): UseAsyncOperationReturn<T, P> {
  const opts = { ...DEFAULT_OPTIONS, ...options };
  const [state, setState] = useState<AsyncOperationState<T>>({
    data: null,
    isLoading: false,
    error: null,
    isSuccess: false,
  });

  // Track if component is mounted
  const isMountedRef = useRef(true);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
      abortControllerRef.current?.abort();
    };
  }, []);

  const execute = useCallback(async (...params: P): Promise<T | null> => {
    // Abort any pending request
    abortControllerRef.current?.abort();
    abortControllerRef.current = new AbortController();

    setState(prev => ({
      ...prev,
      isLoading: true,
      error: null,
      isSuccess: false,
    }));

    try {
      const result = await asyncFn(...params);

      if (!isMountedRef.current) return null;

      setState({
        data: result,
        isLoading: false,
        error: null,
        isSuccess: true,
      });

      if (opts.showSuccessToast && opts.successMessage) {
        showSuccess(opts.successMessage);
      }

      opts.onSuccess?.(result);
      return result;
    } catch (err: any) {
      if (!isMountedRef.current) return null;

      // Ignore abort errors
      if (err.name === 'AbortError') return null;

      const errorMessage = opts.errorMessage || err.message || 'An error occurred';

      if (opts.logErrors) {
        logger.error('useAsyncOperation', errorMessage, { error: err });
      }

      setState({
        data: null,
        isLoading: false,
        error: errorMessage,
        isSuccess: false,
      });

      if (opts.showErrorToast) {
        showError(errorMessage);
      }

      opts.onError?.(errorMessage);
      return null;
    }
  }, [asyncFn, opts]);

  const reset = useCallback(() => {
    abortControllerRef.current?.abort();
    setState({
      data: null,
      isLoading: false,
      error: null,
      isSuccess: false,
    });
  }, []);

  return {
    execute,
    reset,
    ...state,
  };
}

/**
 * Hook for mutations (create, update, delete operations)
 */
export function useMutation<T, P extends any[] = []>(
  mutationFn: (...params: P) => Promise<T>,
  options: AsyncOperationOptions<T> = {}
) {
  return useAsyncOperation(mutationFn, {
    showSuccessToast: true,
    showErrorToast: true,
    ...options,
  });
}

/**
 * Hook for queries (read operations)
 */
export function useQuery<T, P extends any[] = []>(
  queryFn: (...params: P) => Promise<T>,
  options: AsyncOperationOptions<T> = {}
) {
  return useAsyncOperation(queryFn, {
    showSuccessToast: false,
    showErrorToast: true,
    ...options,
  });
}

/**
 * Debounce and Throttle Hooks
 * For optimizing performance in search, input, and scroll handlers
 */

import { useState, useEffect, useRef, useCallback, useMemo } from 'react';

/**
 * Debounce a value
 * Returns the value after it hasn't changed for the specified delay
 */
export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(timer);
    };
  }, [value, delay]);

  return debouncedValue;
}

/**
 * Debounce a callback function
 * Returns a memoized debounced version of the callback
 */
export function useDebouncedCallback<T extends (...args: any[]) => any>(
  callback: T,
  delay: number
): T {
  const callbackRef = useRef(callback);
  const timeoutRef = useRef<ReturnType<typeof setTimeout>>();

  // Update callback ref when callback changes
  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  const debouncedCallback = useCallback(
    (...args: Parameters<T>) => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }

      timeoutRef.current = setTimeout(() => {
        callbackRef.current(...args);
      }, delay);
    },
    [delay]
  ) as T;

  return debouncedCallback;
}

/**
 * Throttle a callback function
 * Ensures the callback is called at most once per specified interval
 */
export function useThrottledCallback<T extends (...args: any[]) => any>(
  callback: T,
  interval: number
): T {
  const callbackRef = useRef(callback);
  const lastCallRef = useRef<number>(0);
  const timeoutRef = useRef<ReturnType<typeof setTimeout>>();

  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  const throttledCallback = useCallback(
    (...args: Parameters<T>) => {
      const now = Date.now();
      const timeSinceLastCall = now - lastCallRef.current;

      if (timeSinceLastCall >= interval) {
        lastCallRef.current = now;
        callbackRef.current(...args);
      } else {
        // Schedule a call for the remaining time
        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }

        timeoutRef.current = setTimeout(() => {
          lastCallRef.current = Date.now();
          callbackRef.current(...args);
        }, interval - timeSinceLastCall);
      }
    },
    [interval]
  ) as T;

  return throttledCallback;
}

/**
 * Hook for search input with debouncing
 */
export function useSearchInput(initialValue: string = '', delay: number = 300) {
  const [value, setValue] = useState(initialValue);
  const debouncedValue = useDebounce(value, delay);

  const handleChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    setValue(e.target.value);
  }, []);

  const clear = useCallback(() => {
    setValue('');
  }, []);

  return {
    value,
    debouncedValue,
    onChange: handleChange,
    clear,
    setValue,
  };
}

/**
 * Hook for infinite scroll with throttling
 */
export function useInfiniteScroll(
  callback: () => void,
  options: {
    threshold?: number;
    throttleMs?: number;
    enabled?: boolean;
  } = {}
) {
  const { threshold = 100, throttleMs = 200, enabled = true } = options;
  const observerRef = useRef<IntersectionObserver | null>(null);
  const loadMoreRef = useRef<HTMLDivElement | null>(null);

  const throttledCallback = useThrottledCallback(callback, throttleMs);

  useEffect(() => {
    if (!enabled) return;

    observerRef.current = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          throttledCallback();
        }
      },
      {
        rootMargin: `${threshold}px`,
      }
    );

    if (loadMoreRef.current) {
      observerRef.current.observe(loadMoreRef.current);
    }

    return () => {
      observerRef.current?.disconnect();
    };
  }, [enabled, threshold, throttledCallback]);

  return { loadMoreRef };
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { offlineManager } from "@/services/offline-manager";
import { supabase } from "@/integrations/supabase/client";

interface UseOfflineSupportOptions {
  table: string;
  userId: string;
  autoCache?: boolean;
}

export function useOfflineSupport({ table, userId, autoCache = true }: UseOfflineSupportOptions) {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    return offlineManager.subscribe(setIsOnline);
  }, []);

  // Load data (from cache if offline, from server if online)
  const loadData = useCallback(async () => {
    setLoading(true);

    try {
      if (isOnline) {
        // Fetch from Supabase
        const { data: serverData, error } = await supabase
          .from(table)
          .select('*')
          .eq('user_id', userId);

        if (error) throw error;

        setData(serverData || []);

        // Cache for offline use
        if (autoCache) {
          await offlineManager.cacheData(table, serverData || []);
        }
      } else {
        // Load from cache
        const cachedData = await offlineManager.getCachedData(table);
        setData(cachedData || []);
      }
    } catch (error) {
      console.error(`Failed to load ${table}:`, error);
      
      // Try cache as fallback
      const cachedData = await offlineManager.getCachedData(table);
      if (cachedData) {
        setData(cachedData);
      }
    } finally {
      setLoading(false);
    }
  }, [table, userId, isOnline, autoCache]);

  // Create item (queue if offline)
  const createItem = useCallback(async (item: any) => {
    if (isOnline) {
      const { data: newItem, error } = await supabase
        .from(table)
        .insert({ ...item, user_id: userId })
        .select()
        .single();

      if (error) throw error;

      setData(prev => [...prev, newItem]);
      return newItem;
    } else {
      // Queue for sync
      await offlineManager.queueOperation(table, 'insert', { ...item, user_id: userId });
      
      // Optimistically update local state
      const tempItem = { ...item, id: `temp-${Date.now()}`, user_id: userId };
      setData(prev => [...prev, tempItem]);
      return tempItem;
    }
  }, [table, userId, isOnline]);

  // Update item (queue if offline)
  const updateItem = useCallback(async (id: string, updates: any) => {
    if (isOnline) {
      const { data: updatedItem, error } = await supabase
        .from(table)
        .update(updates)
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;

      setData(prev => prev.map(item => item.id === id ? updatedItem : item));
      return updatedItem;
    } else {
      // Queue for sync
      await offlineManager.queueOperation(table, 'update', { id, ...updates });
      
      // Optimistically update local state
      setData(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item));
      return { id, ...updates };
    }
  }, [table, isOnline]);

  // Delete item (queue if offline)
  const deleteItem = useCallback(async (id: string) => {
    if (isOnline) {
      const { error } = await supabase
        .from(table)
        .delete()
        .eq('id', id);

      if (error) throw error;

      setData(prev => prev.filter(item => item.id !== id));
    } else {
      // Queue for sync
      await offlineManager.queueOperation(table, 'delete', { id });
      
      // Optimistically update local state
      setData(prev => prev.filter(item => item.id !== id));
    }
  }, [table, isOnline]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  return {
    data,
    loading,
    isOnline,
    createItem,
    updateItem,
    deleteItem,
    refresh: loadData,
  };
}

