import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { showSuccess, showError } from "@/utils/toast";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Plus, Trash2, Calendar as CalendarIcon, Clock, MapPin, ChevronLeft, ChevronRight, Mic, Edit } from "lucide-react";
import VoiceHint from "@/components/VoiceHint";
import { format, startOfMonth, endOfMonth, eachDayOfInterval, isSameDay, addMonths, subMonths, isToday } from "date-fns";

interface CalendarEvent {
  id: string;
  title: string;
  description?: string;
  start_time: string;
  end_time: string;
  location?: string;
  created_at: string;
}

export default function Calendar() {
  const { user } = useAuth();
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [newDescription, setNewDescription] = useState("");
  const [newStartTime, setNewStartTime] = useState("");
  const [newEndTime, setNewEndTime] = useState("");
  const [newLocation, setNewLocation] = useState("");
  const [editingEvent, setEditingEvent] = useState<CalendarEvent | null>(null);

  useEffect(() => {
    if (user) loadEvents();
  }, [user, currentMonth]);

  const loadEvents = async () => {
    if (!user) return;
    setLoading(true);
    
    const start = startOfMonth(currentMonth);
    const end = endOfMonth(currentMonth);

    const { data, error } = await supabase
      .from("calendar_events")
      .select("*")
      .eq("user_id", user.id)
      .gte("start_time", start.toISOString())
      .lte("start_time", end.toISOString())
      .order("start_time", { ascending: true });

    if (error) {
      showError("Failed to load events");
    } else {
      setEvents(data || []);
    }
    setLoading(false);
  };

  const createEvent = async () => {
    if (!user || !newTitle.trim() || !newStartTime || !newEndTime) return;

    const { error } = await supabase.from("calendar_events").insert({
      user_id: user.id,
      title: newTitle.trim(),
      description: newDescription.trim() || null,
      start_time: new Date(newStartTime).toISOString(),
      end_time: new Date(newEndTime).toISOString(),
      location: newLocation.trim() || null,
    });

    if (error) {
      showError("Failed to create event");
    } else {
      loadEvents();
      resetForm();
      showSuccess("Event created!");
    }
  };

  const deleteEvent = async (id: string) => {
    const { error } = await supabase.from("calendar_events").delete().eq("id", id);

    if (error) {
      showError("Failed to delete event");
    } else {
      setEvents(events.filter(e => e.id !== id));
      showSuccess("Event deleted");
    }
  };

  const startEditEvent = (event: CalendarEvent) => {
    setEditingEvent(event);
    setNewTitle(event.title);
    setNewDescription(event.description || "");
    setNewStartTime(event.start_time.slice(0, 16));
    setNewEndTime(event.end_time ? event.end_time.slice(0, 16) : "");
    setNewLocation(event.location || "");
    setIsDialogOpen(true);
  };

  const updateEvent = async () => {
    if (!editingEvent) return;

    const updates = {
      title: newTitle.trim(),
      description: newDescription.trim() || null,
      start_time: new Date(newStartTime).toISOString(),
      end_time: newEndTime ? new Date(newEndTime).toISOString() : null,
      location: newLocation.trim() || null,
    };

    const { error } = await supabase
      .from("calendar_events")
      .update(updates)
      .eq("id", editingEvent.id);

    if (error) {
      showError("Failed to update event");
    } else {
      await loadEvents();
      resetForm();
      showSuccess("Event updated!");
    }
  };

  const resetForm = () => {
    setNewTitle("");
    setNewDescription("");
    setNewStartTime("");
    setNewEndTime("");
    setNewLocation("");
    setEditingEvent(null);
    setIsDialogOpen(false);
  };

  const openNewEvent = (date: Date) => {
    setEditingEvent(null);
    setNewTitle("");
    setNewDescription("");
    setNewLocation("");
    const start = new Date(date);
    start.setHours(9, 0, 0, 0);
    const end = new Date(date);
    end.setHours(10, 0, 0, 0);
    // Use local datetime-local format (YYYY-MM-DDTHH:MM)
    setNewStartTime(start.toISOString().slice(0, 16));
    setNewEndTime(end.toISOString().slice(0, 16));
    setIsDialogOpen(true);
  };

  const days = eachDayOfInterval({
    start: startOfMonth(currentMonth),
    end: endOfMonth(currentMonth),
  });

  const getEventsForDay = (day: Date) => {
    return events.filter(event => isSameDay(new Date(event.start_time), day));
  };

  const selectedDayEvents = selectedDate ? getEventsForDay(selectedDate) : [];

  return (
    <div className="min-h-[calc(100vh-56px)] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-4">
      <div className="mx-auto max-w-6xl space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white flex items-center gap-3">
              <CalendarIcon className="h-8 w-8 text-blue-400" />
              Calendar
            </h1>
            <VoiceHint
              commands={["Schedule meeting tomorrow at 2pm", "What's on my calendar?", "Read my events"]}
              className="mt-2"
            />
          </div>
          <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
            <DialogTrigger asChild>
              <Button className="bg-fuchsia-600 text-white hover:bg-fuchsia-500" onClick={() => openNewEvent(selectedDate || new Date())}>
                <Plus className="h-4 w-4 mr-2" /> New Event
              </Button>
            </DialogTrigger>
            <DialogContent className="bg-slate-900 border-slate-700">
              <DialogHeader>
                <DialogTitle className="text-white">{editingEvent ? "Edit Event" : "New Event"}</DialogTitle>
              </DialogHeader>
              <div className="space-y-4">
                <Input
                  placeholder="Event title"
                  className="bg-slate-800 border-slate-700 text-white"
                  value={newTitle}
                  onChange={(e) => setNewTitle(e.target.value)}
                />
                <Input
                  placeholder="Description (optional)"
                  className="bg-slate-800 border-slate-700 text-white"
                  value={newDescription}
                  onChange={(e) => setNewDescription(e.target.value)}
                />
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-sm text-slate-400">Start</label>
                    <Input
                      type="datetime-local"
                      className="bg-slate-800 border-slate-700 text-white"
                      value={newStartTime}
                      onChange={(e) => setNewStartTime(e.target.value)}
                    />
                  </div>
                  <div>
                    <label className="text-sm text-slate-400">End</label>
                    <Input
                      type="datetime-local"
                      className="bg-slate-800 border-slate-700 text-white"
                      value={newEndTime}
                      onChange={(e) => setNewEndTime(e.target.value)}
                    />
                  </div>
                </div>
                <Input
                  placeholder="Location (optional)"
                  className="bg-slate-800 border-slate-700 text-white"
                  value={newLocation}
                  onChange={(e) => setNewLocation(e.target.value)}
                />
                <div className="flex justify-end gap-2">
                  <Button variant="outline" onClick={resetForm} className="border-slate-600 text-slate-300">
                    Cancel
                  </Button>
                  <Button onClick={editingEvent ? updateEvent : createEvent} className="bg-fuchsia-600 text-white hover:bg-fuchsia-500">
                    {editingEvent ? "Update" : "Create"}
                  </Button>
                </div>
              </div>
            </DialogContent>
          </Dialog>
        </div>

        <div className="grid gap-6 lg:grid-cols-3">
          {/* Calendar Grid */}
          <Card className="lg:col-span-2 border-fuchsia-500/20 bg-black/40 backdrop-blur-lg">
            <CardHeader>
              <div className="flex items-center justify-between">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setCurrentMonth(subMonths(currentMonth, 1))}
                  className="text-slate-400 hover:text-white"
                >
                  <ChevronLeft className="h-5 w-5" />
                </Button>
                <CardTitle className="text-white">
                  {format(currentMonth, "MMMM yyyy")}
                </CardTitle>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setCurrentMonth(addMonths(currentMonth, 1))}
                  className="text-slate-400 hover:text-white"
                >
                  <ChevronRight className="h-5 w-5" />
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-7 gap-1 mb-2">
                {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => (
                  <div key={day} className="text-center text-sm text-slate-400 py-2">
                    {day}
                  </div>
                ))}
              </div>
              <div className="grid grid-cols-7 gap-1">
                {days.map((day) => {
                  const dayEvents = getEventsForDay(day);
                  const isSelected = selectedDate && isSameDay(day, selectedDate);
                  
                  return (
                    <button
                      key={day.toISOString()}
                      onClick={() => setSelectedDate(day)}
                      className={`p-2 rounded-lg text-center transition-colors min-h-[60px] ${
                        isSelected
                          ? "bg-fuchsia-600 text-white"
                          : isToday(day)
                          ? "bg-fuchsia-500/20 text-fuchsia-300"
                          : "hover:bg-slate-800 text-slate-300"
                      }`}
                    >
                      <span className="text-sm">{format(day, "d")}</span>
                      {dayEvents.length > 0 && (
                        <div className="flex justify-center mt-1">
                          <div className="w-1.5 h-1.5 rounded-full bg-blue-400" />
                        </div>
                      )}
                    </button>
                  );
                })}
              </div>
            </CardContent>
          </Card>

          {/* Selected Day Events */}
          <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg">
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle className="text-white">
                  {selectedDate ? format(selectedDate, "EEEE, MMMM d") : "Select a day"}
                </CardTitle>
                {selectedDate && (
                  <Button
                    size="sm"
                    variant="outline"
                    className="border-slate-600 text-slate-300"
                    onClick={() => openNewEvent(selectedDate)}
                  >
                    <Plus className="h-4 w-4 mr-1" />
                    Add
                  </Button>
                )}
              </div>
            </CardHeader>
            <CardContent>
              {selectedDate ? (
                selectedDayEvents.length > 0 ? (
                  <div className="space-y-3">
                    {selectedDayEvents.map((event) => (
                      <div
                        key={event.id}
                        className="p-3 rounded-lg bg-slate-800/50 border border-slate-700"
                      >
                        <div className="flex items-start justify-between">
                          <h4 className="font-medium text-white">{event.title}</h4>
                          <div className="flex items-center gap-1 -mt-1 -mr-1">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => startEditEvent(event)}
                              className="text-slate-400 hover:text-fuchsia-400"
                            >
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => deleteEvent(event.id)}
                              className="text-slate-400 hover:text-red-400"
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </div>
                        </div>
                        <div className="flex items-center gap-2 text-sm text-slate-400 mt-1">
                          <Clock className="h-3 w-3" />
                          {format(new Date(event.start_time), "h:mm a")} - {format(new Date(event.end_time), "h:mm a")}
                        </div>
                        {event.location && (
                          <div className="flex items-center gap-2 text-sm text-slate-400 mt-1">
                            <MapPin className="h-3 w-3" />
                            {event.location}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-slate-400 text-sm">No events for this day.</p>
                )
              ) : (
                <p className="text-slate-400 text-sm">Click on a day to see events.</p>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState, useRef } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import { Search, Send, Loader2, Wrench, Mic, Volume2 } from "lucide-react";
import { showError, showSuccess } from "@/utils/toast";
import { usePreferences } from "@/state/preferences";
import { useAuth } from "@/contexts/AuthContext";
import { useOpenAIKey } from "@/hooks/useOpenAIKey";
import { useVoice } from "@/contexts/VoiceContext";
import { supabase } from "@/integrations/supabase/client";
import type { Message, Conversation, Citation } from "@/types/models";
import { chat } from "@/services/brain";
import { searchWeb } from "@/services/search";
import { buildSystemPrompt, parseToolCalls, executeTool, ActionResult } from "@/services/orchestrator";
import { getLocationContext, LocationContext } from "@/services/context";
import ChatTips from "@/components/ChatTips";
import VoiceTranscriptDisplay from "@/components/VoiceTranscriptDisplay";
import { logChatMessage } from "@/services/ai-logging";

const STORAGE_KEY = "echo:conversation:default";

function loadConversation(): Conversation | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function saveConversation(conv: Conversation) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(conv));
}

export default function Chat() {
  const { preferences } = usePreferences();
  const { user } = useAuth();
  const { apiKey: openaiApiKey, hasKey: hasOpenAIKey } = useOpenAIKey();
  const { isListening, isProcessing, isSpeaking, startListening, stopListening, speak, lastResponse } = useVoice();
  const [conversation, setConversation] = useState<Conversation | null>(
    loadConversation()
  );
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messages = useMemo<Message[]>(
    () => conversation?.messages ?? [],
    [conversation]
  );
  const [userLocation, setUserLocation] = useState<LocationContext | null>(null);

  const isVoiceActive = isListening || isProcessing || isSpeaking;

  // Try to get user location on mount
  useEffect(() => {
    getLocationContext().then(loc => {
      if (loc) setUserLocation(loc);
    }).catch(() => {
      // Location not available, that's OK
    });
  }, []);

  useEffect(() => {
    if (!preferences.privateMode && conversation) {
      saveConversation(conversation);
    }
  }, [conversation, preferences.privateMode]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // Save message to database
  const saveMessageToDb = async (role: string, content: string) => {
    if (!user || preferences.privateMode) return;
    
    try {
      await supabase.from("chat_messages").insert({
        user_id: user.id,
        role,
        content,
      });
    } catch (error) {
      console.error("Failed to save message to database:", error);
    }
  };

  const appendMessage = async (msg: Message) => {
    setConversation((prev) => {
      const base: Conversation =
        prev ?? { id: "default", createdAt: Date.now(), title: "Echo", messages: [] };
      const next = { ...base, messages: [...base.messages, msg] };
      return next;
    });
    
    // Save to database
    await saveMessageToDb(msg.role, msg.content);
  };

  const clearConversation = async () => {
    setConversation(null);
    localStorage.removeItem(STORAGE_KEY);
    
    // Also clear from database
    if (user && !preferences.privateMode) {
      try {
        await supabase.from("chat_messages").delete().eq("user_id", user.id);
      } catch (error) {
        console.error("Failed to clear messages from database:", error);
      }
    }
    
    showSuccess("Conversation cleared");
  };

  const onSend = async () => {
    if (!input.trim() || isLoading) return;
    
    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: "user",
      content: input.trim(),
      createdAt: Date.now(),
    };
    appendMessage(userMsg);
    setInput("");
    setIsLoading(true);

    try {
      const systemPrompt = buildSystemPrompt(userLocation ? {
        lat: userLocation.lat,
        lng: userLocation.lng,
        city: userLocation.city,
      } : undefined);
      
      const chatMessages = [
        { role: "system" as const, content: systemPrompt },
        ...messages.concat(userMsg).map((m) => ({
          role: m.role as "user" | "assistant" | "system",
          content: m.content,
        })),
      ];

      const res = await chat(
        preferences.baseUrl,
        { messages: chatMessages },
        preferences.authToken,
        openaiApiKey
      );

      const toolCalls = parseToolCalls(res.content);
      const toolResults: ActionResult[] = [];
      let finalContent = res.content;

      if (toolCalls.length > 0 && user) {
        for (const toolCall of toolCalls) {
          const result = await executeTool(user.id, toolCall);
          toolResults.push(result);
        }

        if (toolResults.length > 0) {
          const toolResultsText = toolResults.map(r =>
            `Tool: ${r.tool}\nSuccess: ${r.success}\n${r.success ? `Result: ${JSON.stringify(r.data, null, 2)}` : `Error: ${r.error}`}`
          ).join("\n\n");

          const followUpMessages = [
            ...chatMessages,
            { role: "assistant" as const, content: res.content },
            { role: "user" as const, content: `Tool execution results:\n${toolResultsText}\n\nPlease provide a natural language summary of what was done.` },
          ];

          const followUp = await chat(
            preferences.baseUrl,
            { messages: followUpMessages },
            preferences.authToken,
            openaiApiKey
          );

          finalContent = followUp.content;
        }
      }

      const assistantMsg: Message = {
        id: crypto.randomUUID(),
        role: "assistant",
        content: finalContent,
        citations: res.citations as Citation[] | undefined,
        toolCall: toolResults.length > 0 ? {
          type: "orchestrator",
          input: toolCalls.map(t => t.tool).join(", "),
          outputMeta: { tools: toolResults.map(r => ({ tool: r.tool, success: r.success })) }
        } : undefined,
        createdAt: Date.now(),
      };
      
      appendMessage(assistantMsg);
      
      if (user) {
        logChatMessage(user.id, userMsg.content, finalContent);
      }
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : "Failed to send message";
      showError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const onSearch = async () => {
    if (!input.trim() || isLoading) return;
    setIsLoading(true);
    
    try {
      const results = await searchWeb(input.trim());
      const citations = results.map((r) => ({ title: r.title, url: r.url }));
      const assistantMsg: Message = {
        id: crypto.randomUUID(),
        role: "assistant",
        content: `Here are some findings on "${input.trim()}":\n\n${results.map((r, i) => `${i + 1}. **${r.title}**\n${r.snippet || ''}`).join('\n\n')}`,
        citations,
        toolCall: { type: "search", input: input.trim(), outputMeta: { count: results.length } },
        createdAt: Date.now(),
      };
      appendMessage(assistantMsg);
      setInput("");
      showSuccess("Search completed");
    } catch (e: any) {
      showError(e.message || "Search failed");
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      onSend();
    }
  };

  const handleVoiceToggle = async () => {
    if (isListening) {
      stopListening();
    } else {
      await startListening();
    }
  };

  const speakLastMessage = async () => {
    const lastAssistantMsg = [...messages].reverse().find(m => m.role === "assistant");
    if (lastAssistantMsg) {
      await speak(lastAssistantMsg.content);
    }
  };

  return (
    <div className="min-h-[calc(100vh-56px)] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-4">
      <div className="mx-auto max-w-4xl">
        {/* Voice Transcript Display - Shows above chat when voice is active */}
        {isVoiceActive && (
          <div className="mb-4">
            <VoiceTranscriptDisplay showResponse={true} />
          </div>
        )}

        <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg shadow-xl">
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle className="text-2xl font-bold text-white">
              Chat with Echo
            </CardTitle>
            <Button 
              variant="outline" 
              size="sm" 
              onClick={clearConversation}
              className="border-slate-600 text-slate-300 hover:bg-slate-800"
            >
              Clear
            </Button>
          </CardHeader>
          <CardContent>
            <ScrollArea className="h-[50vh] rounded-lg border border-slate-700 bg-slate-900/50 p-4">
              {messages.length === 0 ? (
                <div className="flex flex-col h-full">
                  <div className="flex flex-col items-center justify-center flex-1 text-center">
                    <div className="text-4xl mb-4">≡ƒæï</div>
                    <p className="text-lg text-white mb-2">Hello! I'm Echo, your AI assistant.</p>
                    <p className="text-sm text-slate-400 max-w-md mb-4">
                      I can help you search the web, create reminders, manage tasks, take notes, and schedule calendar events. Just ask!
                    </p>
                  </div>
                  <ChatTips onPromptClick={(prompt) => setInput(prompt)} />
                </div>
              ) : (
                messages.map((m) => (
                  <div
                    key={m.id}
                    className={`mb-4 max-w-[85%] rounded-2xl px-4 py-3 ${
                      m.role === "user"
                        ? "ml-auto bg-fuchsia-600/40 text-white"
                        : "bg-slate-800 text-slate-100 border border-slate-700"
                    }`}
                  >
                    <div className="flex items-center gap-2 text-[10px] text-slate-400">
                      <span>{m.role.toUpperCase()}</span>
                      <span>ΓÇó</span>
                      <span>{new Date(m.createdAt).toLocaleTimeString()}</span>
                      {m.toolCall && (
                        <>
                          <span>ΓÇó</span>
                          <span className="flex items-center gap-1 text-fuchsia-300">
                            <Wrench className="h-3 w-3" />
                            {m.toolCall.type}
                          </span>
                        </>
                      )}
                    </div>
                    <div className="mt-1 whitespace-pre-wrap">{m.content}</div>
                    {m.citations && m.citations.length > 0 && (
                      <>
                        <Separator className="my-2 bg-slate-600" />
                        <div className="space-y-1">
                          <div className="text-xs font-semibold text-slate-300">Sources</div>
                          {m.citations.map((c, idx) => (
                            <a
                              key={idx}
                              href={c.url}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="block text-xs text-fuchsia-300 hover:underline truncate"
                            >
                              {c.title}
                            </a>
                          ))}
                        </div>
                      </>
                    )}
                  </div>
                ))
              )}
              {isLoading && (
                <div className="flex items-center gap-2 text-slate-400 mb-4">
                  <Loader2 className="h-4 w-4 animate-spin" />
                  <span className="text-sm">Echo is thinking...</span>
                </div>
              )}
              <div ref={messagesEndRef} />
            </ScrollArea>
            
            {/* Input Area */}
            <div className="mt-3 flex gap-2">
              <Input
                className="bg-slate-800 border-slate-700 text-white placeholder:text-slate-500"
                placeholder="Ask Echo anything..."
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyDown}
                disabled={isLoading}
              />
              <Button 
                onClick={onSend} 
                className="bg-fuchsia-600 text-white hover:bg-fuchsia-500"
                disabled={isLoading || !input.trim()}
              >
                {isLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
              </Button>
              <Button 
                variant="secondary" 
                onClick={onSearch} 
                className="border-slate-600 bg-slate-800 text-white hover:bg-slate-700"
                disabled={isLoading || !input.trim()}
              >
                <Search className="mr-2 h-4 w-4" /> Search
              </Button>
            </div>

            {/* Voice Controls */}
            <div className="mt-3 flex items-center justify-between">
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleVoiceToggle}
                  className={`border-slate-600 ${
                    isListening 
                      ? "bg-red-500/20 text-red-400 border-red-500/50 animate-pulse" 
                      : "text-slate-300 hover:bg-slate-800"
                  }`}
                  disabled={isProcessing}
                >
                  <Mic className="mr-2 h-4 w-4" />
                  {isListening ? "Listening..." : "Voice Input"}
                </Button>
                {messages.length > 0 && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={speakLastMessage}
                    className={`border-slate-600 ${
                      isSpeaking 
                        ? "bg-green-500/20 text-green-400 border-green-500/50 animate-pulse" 
                        : "text-slate-300 hover:bg-slate-800"
                    }`}
                    disabled={isSpeaking}
                  >
                    <Volume2 className="mr-2 h-4 w-4" />
                    {isSpeaking ? "Speaking..." : "Read Last"}
                  </Button>
                )}
              </div>
              <p className="text-xs text-slate-500">
                Press Enter to send ΓÇó Click mic for voice
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

