import { useEffect, useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { showSuccess, showError } from "@/utils/toast";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Plus, Trash2, Users, Phone, Search, Edit, User, Mic, Mail } from "lucide-react";
import VoiceHint from "@/components/VoiceHint";
import { format } from "date-fns";

interface Contact {
  id: string;
  name: string;
  phone: string;
  email?: string;
  notes?: string;
  created_at: string;
}

export default function Contacts() {
  const { user } = useAuth();
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingContact, setEditingContact] = useState<Contact | null>(null);
  const [newName, setNewName] = useState("");
  const [newPhone, setNewPhone] = useState("");
  const [newEmail, setNewEmail] = useState("");
  const [newNotes, setNewNotes] = useState("");

  useEffect(() => {
    if (user) loadContacts();
  }, [user]);

  const loadContacts = async () => {
    if (!user) return;
    setLoading(true);
    
    const { data, error } = await supabase
      .from("contacts")
      .select("*")
      .eq("user_id", user.id)
      .order("name", { ascending: true });

    if (error) {
      showError("Failed to load contacts");
    } else {
      setContacts(data || []);
    }
    setLoading(false);
  };

  const saveContact = async () => {
    if (!user || !newName.trim() || !newPhone.trim()) {
      showError("Name and phone are required");
      return;
    }

    if (editingContact) {
      const { error } = await supabase
        .from("contacts")
        .update({
          name: newName.trim(),
          phone: newPhone.trim(),
          email: newEmail.trim() || null,
          notes: newNotes.trim() || null,
        })
        .eq("id", editingContact.id);

      if (error) {
        showError("Failed to update contact");
      } else {
        loadContacts();
        showSuccess("Contact updated!");
      }
    } else {
      const { error } = await supabase.from("contacts").insert({
        user_id: user.id,
        name: newName.trim(),
        phone: newPhone.trim(),
        email: newEmail.trim() || null,
        notes: newNotes.trim() || null,
      });

      if (error) {
        showError("Failed to create contact");
      } else {
        loadContacts();
        showSuccess("Contact added!");
      }
    }

    resetForm();
  };

  const resetForm = () => {
    setNewName("");
    setNewPhone("");
    setNewEmail("");
    setNewNotes("");
    setEditingContact(null);
    setIsDialogOpen(false);
  };

  const editContact = (contact: Contact) => {
    setEditingContact(contact);
    setNewName(contact.name);
    setNewPhone(contact.phone);
    setNewEmail(contact.email || "");
    setNewNotes(contact.notes || "");
    setIsDialogOpen(true);
  };

  const deleteContact = async (id: string) => {
    const { error } = await supabase.from("contacts").delete().eq("id", id);

    if (error) {
      showError("Failed to delete contact");
    } else {
      setContacts(contacts.filter(c => c.id !== id));
      showSuccess("Contact deleted");
    }
  };

  const filteredContacts = contacts.filter(contact =>
    contact.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    contact.phone.includes(searchQuery) ||
    (contact.email ? contact.email.toLowerCase().includes(searchQuery.toLowerCase()) : false)
  );

  const callContact = (phone: string) => {
    window.location.href = `tel:${phone}`;
  };

  return (
    <div className="min-h-[calc(100vh-56px)] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-4">
      <div className="mx-auto max-w-4xl space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white flex items-center gap-3">
              <Users className="h-8 w-8 text-blue-400" />
              Contacts
            </h1>
            <p className="text-slate-400 mt-1">{contacts.length} contacts</p>
            <VoiceHint
              commands={["Add contact John Doe", "Find contact Sarah", "Call John"]}
              className="mt-2"
            />
          </div>
          <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
            <DialogTrigger asChild>
              <Button className="bg-fuchsia-600 text-white hover:bg-fuchsia-500" onClick={() => resetForm()}>
                <Plus className="h-4 w-4 mr-2" /> Add Contact
              </Button>
            </DialogTrigger>
            <DialogContent className="bg-slate-900 border-slate-700">
              <DialogHeader>
                <DialogTitle className="text-white">
                  {editingContact ? "Edit Contact" : "New Contact"}
                </DialogTitle>
              </DialogHeader>
              <div className="space-y-4">
                <div>
                  <label className="text-sm text-slate-400">Name</label>
                  <Input
                    placeholder="John Doe"
                    className="bg-slate-800 border-slate-700 text-white"
                    value={newName}
                    onChange={(e) => setNewName(e.target.value)}
                  />
                </div>
                <div>
                  <label className="text-sm text-slate-400">Phone</label>
                  <Input
                    placeholder="+1 (555) 123-4567"
                    className="bg-slate-800 border-slate-700 text-white"
                    value={newPhone}
                    onChange={(e) => setNewPhone(e.target.value)}
                  />
                </div>
                <div>
                  <label className="text-sm text-slate-400">Email (optional)</label>
                  <Input
                    placeholder="john@example.com"
                    className="bg-slate-800 border-slate-700 text-white"
                    value={newEmail}
                    onChange={(e) => setNewEmail(e.target.value)}
                  />
                </div>
                <div>
                  <label className="text-sm text-slate-400">Notes (optional)</label>
                  <Textarea
                    placeholder="Add notes about this contact..."
                    className="bg-slate-800 border-slate-700 text-white"
                    value={newNotes}
                    onChange={(e) => setNewNotes(e.target.value)}
                  />
                </div>
                <div className="flex justify-end gap-2">
                  <Button variant="outline" onClick={resetForm} className="border-slate-600 text-slate-300">
                    Cancel
                  </Button>
                  <Button onClick={saveContact} className="bg-fuchsia-600 text-white hover:bg-fuchsia-500">
                    {editingContact ? "Update" : "Add"}
                  </Button>
                </div>
              </div>
            </DialogContent>
          </Dialog>
        </div>

        {/* Search */}
        <div className="relative max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
          <Input
            placeholder="Search contacts..."
            className="pl-10 bg-slate-800 border-slate-700 text-white placeholder:text-slate-500"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        {/* Contacts List */}
        <div className="space-y-2">
          {loading ? (
            <Card className="border-slate-700 bg-slate-800/50">
              <CardContent className="p-8 text-center text-slate-400">
                Loading contacts...
              </CardContent>
            </Card>
          ) : filteredContacts.length === 0 ? (
            <Card className="border-slate-700 bg-slate-800/50">
              <CardContent className="p-8 text-center">
                <Users className="h-12 w-12 text-slate-600 mx-auto mb-4" />
                <p className="text-slate-400">
                  {searchQuery ? "No contacts match your search." : "No contacts yet. Add one!"}
                </p>
              </CardContent>
            </Card>
          ) : (
            filteredContacts.map((contact) => (
              <Card
                key={contact.id}
                className="border-fuchsia-500/20 bg-black/30 backdrop-blur hover:border-fuchsia-500/40 transition-colors"
              >
                <CardContent className="p-4">
                  <div className="flex items-center gap-4">
                    <div className="h-12 w-12 rounded-full bg-gradient-to-br from-fuchsia-500 to-purple-600 flex items-center justify-center">
                      <User className="h-6 w-6 text-white" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h4 className="font-medium text-white">{contact.name}</h4>
                      <p className="text-sm text-slate-400 flex items-center gap-1">
                        <Phone className="h-3 w-3" />
                        {contact.phone}
                      </p>
                      {contact.email && (
                        <p className="text-sm text-slate-400 flex items-center gap-1">
                          <Mail className="h-3 w-3" />
                          {contact.email}
                        </p>
                      )}
                      {contact.notes && (
                        <p className="text-xs text-slate-500 mt-1 truncate">{contact.notes}</p>
                      )}
                    </div>
                    <div className="flex gap-1">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => callContact(contact.phone)}
                        className="text-green-400 hover:text-green-300 hover:bg-green-500/20"
                      >
                        <Phone className="h-4 w-4" />
                      </Button>
                      {contact.email && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => (window.location.href = `mailto:${contact.email}`)}
                          className="text-blue-400 hover:text-blue-300 hover:bg-blue-500/20"
                        >
                          <Mail className="h-4 w-4" />
                        </Button>
                      )}
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => editContact(contact)}
                        className="text-slate-400 hover:text-fuchsia-400"
                      >
                        <Edit className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => deleteContact(contact.id)}
                        className="text-slate-400 hover:text-red-400"
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useAuth } from "@/contexts/AuthContext";
import { downloadUserData, importUserData, getExportStats } from "@/services/data-export";
import { showSuccess, showError } from "@/utils/toast";
import { 
  Download, 
  Upload, 
  Database, 
  FileJson,
  AlertTriangle,
  CheckCircle,
  Loader2
} from "lucide-react";

export default function DataManagement() {
  const { user } = useAuth();
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState<any>(null);
  const [importing, setImporting] = useState(false);

  const handleExport = async () => {
    if (!user) return;
    setLoading(true);
    await downloadUserData(user.id);
    setLoading(false);
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!user || !e.target.files?.[0]) return;
    
    setImporting(true);
    const success = await importUserData(user.id, e.target.files[0]);
    setImporting(false);
    
    if (success) {
      setTimeout(() => window.location.reload(), 1000);
    }
  };

  const loadStats = async () => {
    if (!user) return;
    const exportStats = await getExportStats(user.id);
    setStats(exportStats);
  };

  useState(() => {
    loadStats();
  });

  return (
    <div className="min-h-[calc(100vh-56px)] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-4">
      <div className="mx-auto max-w-4xl space-y-6">
        <div>
          <h1 className="text-3xl font-bold text-white flex items-center gap-3">
            <Database className="h-8 w-8 text-fuchsia-400" />
            Data Management
          </h1>
          <p className="text-slate-400 mt-1">
            Export, import, and manage your data
          </p>
        </div>

        {/* Export Section */}
        <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <Download className="h-5 w-5 text-green-400" />
              Export Data
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-sm text-slate-300">
              Download all your data as a JSON file. This includes tasks, reminders, notes, events, contacts, and more.
            </p>

            {stats && (
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700">
                  <p className="text-xs text-slate-400">Total Items</p>
                  <p className="text-2xl font-bold text-white">{stats.totalItems}</p>
                </div>
                <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700">
                  <p className="text-xs text-slate-400">Tasks</p>
                  <p className="text-2xl font-bold text-white">{stats.breakdown.tasks}</p>
                </div>
                <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700">
                  <p className="text-xs text-slate-400">Notes</p>
                  <p className="text-2xl font-bold text-white">{stats.breakdown.notes}</p>
                </div>
                <div className="p-3 rounded-lg bg-slate-800/50 border border-slate-700">
                  <p className="text-xs text-slate-400">File Size</p>
                  <p className="text-lg font-bold text-white">{stats.estimatedSize}</p>
                </div>
              </div>
            )}

            <Button
              onClick={handleExport}
              disabled={loading}
              className="w-full bg-green-600 text-white hover:bg-green-500"
            >
              {loading ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Exporting...
                </>
              ) : (
                <>
                  <Download className="h-4 w-4 mr-2" />
                  Export All Data
                </>
              )}
            </Button>
          </CardContent>
        </Card>

        {/* Import Section */}
        <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <Upload className="h-5 w-5 text-blue-400" />
              Import Data
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="p-4 rounded-lg bg-yellow-900/20 border border-yellow-500/30">
              <div className="flex items-start gap-3">
                <AlertTriangle className="h-5 w-5 text-yellow-400 shrink-0 mt-0.5" />
                <div>
                  <p className="text-sm text-yellow-300 font-medium">Important</p>
                  <p className="text-xs text-yellow-400/80 mt-1">
                    Importing will merge with your existing data. Duplicate items may be created.
                  </p>
                </div>
              </div>
            </div>

            <div className="space-y-2">
              <label className="block">
                <Input
                  type="file"
                  accept=".json"
                  onChange={handleImport}
                  disabled={importing}
                  className="bg-slate-800 border-slate-700 text-white file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-fuchsia-600 file:text-white hover:file:bg-fuchsia-500"
                />
              </label>
              {importing && (
                <div className="flex items-center gap-2 text-sm text-blue-400">
                  <Loader2 className="h-4 w-4 animate-spin" />
                  Importing data...
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Data Safety */}
        <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <CheckCircle className="h-5 w-5 text-green-400" />
              Data Safety
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            <div className="flex items-start gap-3">
              <FileJson className="h-5 w-5 text-fuchsia-400 shrink-0 mt-0.5" />
              <div>
                <p className="text-sm text-white font-medium">JSON Format</p>
                <p className="text-xs text-slate-400">
                  Your data is exported in standard JSON format, readable by any text editor.
                </p>
              </div>
            </div>
            <div className="flex items-start gap-3">
              <Database className="h-5 w-5 text-blue-400 shrink-0 mt-0.5" />
              <div>
                <p className="text-sm text-white font-medium">Secure Storage</p>
                <p className="text-xs text-slate-400">
                  All data is stored securely in Supabase with Row Level Security enabled.
                </p>
              </div>
            </div>
            <div className="flex items-start gap-3">
              <CheckCircle className="h-5 w-5 text-green-400 shrink-0 mt-0.5" />
              <div>
                <p className="text-sm text-white font-medium">Regular Backups</p>
                <p className="text-xs text-slate-400">
                  We recommend exporting your data weekly as a backup.
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { ScrollArea } from "@/components/ui/scroll-area";
import { usePreferences } from "../state/preferences";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { showError, showSuccess } from "@/utils/toast";
import {
  Bug,
  Mic,
  MapPin,
  Database,
  Wifi,
  CheckCircle,
  XCircle,
  RefreshCw,
  Smartphone,
  Globe,
  Key,
  Server,
  Zap,
  Clock,
  TestTube,
  Activity,
  Heart,
  Beaker,
  Video,
  Brain,
  BarChart3
} from "lucide-react";
import { getTimeContext } from "@/services/context";
import { AVAILABLE_TOOLS } from "@/services/orchestrator";
import { runSmokeTests, SmokeTestReport } from "@/services/smoke-test";
import { runHealthCheck, SystemHealthReport } from "@/services/system-health";
import { selfHealing } from "@/services/self-healing";
import { advancedAnalytics } from "@/services/advanced-analytics";
import { predictiveCache } from "@/services/predictive-caching";
import { performanceDashboard } from "@/services/performance-dashboard";
import { abTesting } from "@/services/ab-testing";
import { sessionRecording } from "@/services/session-recording";
import { mlErrorPredictor } from "@/services/ml-error-predictor";

interface SystemCheck {
  name: string;
  status: "checking" | "ok" | "error" | "warning";
  message: string;
  icon: React.ReactNode;
}

export default function Debug() {
  const { preferences } = usePreferences();
  const { user } = useAuth();
  const [systemChecks, setSystemChecks] = useState<SystemCheck[]>([]);
  const [isRunningChecks, setIsRunningChecks] = useState(false);
  const [dbStats, setDbStats] = useState<any>(null);
  const [smokeTestReport, setSmokeTestReport] = useState<SmokeTestReport | null>(null);
  const [healthReport, setHealthReport] = useState<SystemHealthReport | null>(null);
  const [isRunningSmokeTests, setIsRunningSmokeTests] = useState(false);
  const [isRunningHealthCheck, setIsRunningHealthCheck] = useState(false);
  const [performanceMetrics, setPerformanceMetrics] = useState<any>(null);
  const [abExperiments, setAbExperiments] = useState<any[]>([]);
  const [sessionInfo, setSessionInfo] = useState<any>(null);
  const [errorPredictions, setErrorPredictions] = useState<any[]>([]);

  useEffect(() => {
    runAllChecks();
    if (user) loadDbStats();
    
    // Initialize 130% services
    const metrics = performanceDashboard.getLatestMetrics();
    setPerformanceMetrics(metrics);
    
    const experiments = abTesting.getAllExperiments();
    setAbExperiments(experiments);
    
    const recording = sessionRecording.getCurrentRecording();
    if (recording) {
      setSessionInfo(sessionRecording.generateSessionSummary(recording));
    }
    
    const predictions = mlErrorPredictor.getRecentPredictions();
    setErrorPredictions(predictions);
  }, [user]);

  const loadDbStats = async () => {
    if (!user) return;

    try {
      const [tasks, notes, reminders, contacts, notifications, knowledge, calendarEvents, apiProviders] = await Promise.all([
        supabase.from("tasks").select("*", { count: "exact", head: true }).eq("user_id", user.id),
        supabase.from("notes").select("*", { count: "exact", head: true }).eq("user_id", user.id),
        supabase.from("reminders").select("*", { count: "exact", head: true }).eq("user_id", user.id),
        supabase.from("contacts").select("*", { count: "exact", head: true }).eq("user_id", user.id),
        supabase.from("notifications").select("*", { count: "exact", head: true }).eq("user_id", user.id),
        supabase.from("knowledge").select("*", { count: "exact", head: true }).eq("user_id", user.id),
        supabase.from("calendar_events").select("*", { count: "exact", head: true }).eq("user_id", user.id),
        supabase.from("api_providers").select("*", { count: "exact", head: true }).eq("user_id", user.id).eq("is_enabled", true),
      ]);

      setDbStats({
        tasks: tasks.count || 0,
        notes: notes.count || 0,
        reminders: reminders.count || 0,
        contacts: contacts.count || 0,
        notifications: notifications.count || 0,
        knowledge: knowledge.count || 0,
        events: calendarEvents.count || 0,
        providers: apiProviders.count || 0,
      });
    } catch (error) {
      console.error("Failed to load DB stats:", error);
    }
  };

  const runAllChecks = async () => {
    setIsRunningChecks(true);
    const checks: SystemCheck[] = [];

    // Check microphone
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach((t) => t.stop());
      checks.push({
        name: "Microphone",
        status: "ok",
        message: "Microphone access granted",
        icon: <Mic className="h-4 w-4" />,
      });
    } catch {
      checks.push({
        name: "Microphone",
        status: "error",
        message: "Microphone access denied or unavailable",
        icon: <Mic className="h-4 w-4" />,
      });
    }

    // Check location
    if ("geolocation" in navigator) {
      try {
        await new Promise((resolve, reject) => {
          navigator.geolocation.getCurrentPosition(resolve, reject, { timeout: 5000 });
        });
        checks.push({
          name: "Location",
          status: "ok",
          message: "Location access granted",
          icon: <MapPin className="h-4 w-4" />,
        });
      } catch {
        checks.push({
          name: "Location",
          status: "warning",
          message: "Location access denied (optional)",
          icon: <MapPin className="h-4 w-4" />,
        });
      }
    } else {
      checks.push({
        name: "Location",
        status: "warning",
        message: "Geolocation not supported",
        icon: <MapPin className="h-4 w-4" />,
      });
    }

    // Check Supabase connection
    try {
      const { error } = await supabase.from("profiles").select("id").limit(1);
      if (error) throw error;
      checks.push({
        name: "Database",
        status: "ok",
        message: "Supabase connection successful",
        icon: <Database className="h-4 w-4" />,
      });
    } catch {
      checks.push({
        name: "Database",
        status: "error",
        message: "Supabase connection failed",
        icon: <Database className="h-4 w-4" />,
      });
    }

    // Check OpenAI API key
    if (preferences.openaiApiKey) {
      checks.push({
        name: "OpenAI API Key",
        status: "ok",
        message: "API key configured",
        icon: <Key className="h-4 w-4" />,
      });
    } else {
      checks.push({
        name: "OpenAI API Key",
        status: "error",
        message: "API key not set - voice features disabled",
        icon: <Key className="h-4 w-4" />,
      });
    }

    // Check network
    if (navigator.onLine) {
      checks.push({
        name: "Network",
        status: "ok",
        message: "Online",
        icon: <Wifi className="h-4 w-4" />,
      });
    } else {
      checks.push({
        name: "Network",
        status: "error",
        message: "Offline",
        icon: <Wifi className="h-4 w-4" />,
      });
    }

    // Check browser features
    const hasMediaRecorder = "MediaRecorder" in window;
    const hasSpeechSynthesis = "speechSynthesis" in window;
    checks.push({
      name: "Browser Features",
      status: hasMediaRecorder && hasSpeechSynthesis ? "ok" : "warning",
      message: `MediaRecorder: ${hasMediaRecorder ? "Γ£ô" : "Γ£ù"}, SpeechSynthesis: ${hasSpeechSynthesis ? "Γ£ô" : "Γ£ù"}`,
      icon: <Globe className="h-4 w-4" />,
    });

    // Check Brain API (if configured)
    if (preferences.baseUrl) {
      try {
        const res = await fetch(`${preferences.baseUrl}/health`, { method: "GET" });
        checks.push({
          name: "Brain API",
          status: res.ok ? "ok" : "warning",
          message: res.ok ? "Brain API reachable" : `Status: ${res.status}`,
          icon: <Server className="h-4 w-4" />,
        });
      } catch {
        checks.push({
          name: "Brain API",
          status: "warning",
          message: "Brain API not reachable (optional)",
          icon: <Server className="h-4 w-4" />,
        });
      }
    }

    setSystemChecks(checks);
    setIsRunningChecks(false);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "ok": return "bg-green-500/20 text-green-300 border-green-500/50";
      case "error": return "bg-red-500/20 text-red-300 border-red-500/50";
      case "warning": return "bg-yellow-500/20 text-yellow-300 border-yellow-500/50";
      default: return "bg-slate-500/20 text-slate-300 border-slate-500/50";
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "ok": return <CheckCircle className="h-4 w-4 text-green-400" />;
      case "error": return <XCircle className="h-4 w-4 text-red-400" />;
      case "warning": return <XCircle className="h-4 w-4 text-yellow-400" />;
      default: return <RefreshCw className="h-4 w-4 text-slate-400 animate-spin" />;
    }
  };

  const runSmokeTestsHandler = async () => {
    setIsRunningSmokeTests(true);
    try {
      const report = await runSmokeTests();
      setSmokeTestReport(report);
      if (report.failed === 0) {
        showSuccess(`All ${report.total} smoke tests passed!`);
      } else {
        showError(`${report.failed} of ${report.total} tests failed`);
      }
    } catch (error: any) {
      showError(error.message || 'Smoke tests failed');
    } finally {
      setIsRunningSmokeTests(false);
    }
  };

  const runHealthCheckHandler = async () => {
    setIsRunningHealthCheck(true);
    try {
      const report = await runHealthCheck(preferences.openaiApiKey || undefined);
      setHealthReport(report);
      if (report.overall === 'healthy') {
        showSuccess('System is healthy!');
      } else if (report.overall === 'degraded') {
        showSuccess('System is degraded - some features may be limited');
      } else {
        showError('System health issues detected');
      }
    } catch (error: any) {
      showError(error.message || 'Health check failed');
    } finally {
      setIsRunningHealthCheck(false);
    }
  };

  const clearAllData = async () => {
    if (!confirm("Are you sure you want to clear all local data? This cannot be undone.")) return;
    
    localStorage.clear();
    showSuccess("Local data cleared. Please refresh the page.");
  };

  return (
    <div className="min-h-[calc(100vh-56px)] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-4">
      <div className="mx-auto max-w-4xl space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white flex items-center gap-3">
              <Bug className="h-8 w-8 text-fuchsia-400" />
              Debug Console
            </h1>
            <p className="text-slate-400 mt-1">System diagnostics and debugging tools</p>
          </div>
          <Button
            onClick={runAllChecks}
            disabled={isRunningChecks}
            className="bg-fuchsia-600 text-white hover:bg-fuchsia-500"
          >
            <RefreshCw className={`h-4 w-4 mr-2 ${isRunningChecks ? "animate-spin" : ""}`} />
            Run Checks
          </Button>
        </div>

        {/* System Checks */}
        <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg shadow-xl">
          <CardHeader>
            <CardTitle className="text-xl font-bold text-white">System Status</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid gap-3 md:grid-cols-2">
              {systemChecks.map((check) => (
                <div
                  key={check.name}
                  className="flex items-center gap-3 p-3 rounded-lg border border-slate-700 bg-slate-800/50"
                >
                  <div className="text-slate-400">{check.icon}</div>
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <span className="font-medium text-white">{check.name}</span>
                      {getStatusIcon(check.status)}
                    </div>
                    <p className="text-xs text-slate-400">{check.message}</p>
                  </div>
                  <Badge className={getStatusColor(check.status)}>
                    {check.status}
                  </Badge>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Database Stats */}
        {dbStats && (
          <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg shadow-xl">
            <CardHeader>
              <CardTitle className="text-xl font-bold text-white flex items-center gap-2">
                <Database className="h-5 w-5 text-fuchsia-400" />
                Database Statistics
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-5 gap-4">
                {Object.entries(dbStats).map(([key, value]) => (
                  <div key={key} className="text-center p-3 rounded-lg bg-slate-800/50 border border-slate-700">
                    <div className="text-2xl font-bold text-fuchsia-400">{value as number}</div>
                    <div className="text-xs text-slate-400 capitalize">{key}</div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        {/* User Info */}
        <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg shadow-xl">
          <CardHeader>
            <CardTitle className="text-xl font-bold text-white">User Session</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="text-slate-400">User ID:</span>
                <span className="text-white font-mono">{user?.id || "Not logged in"}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-400">Email:</span>
                <span className="text-white">{user?.email || "N/A"}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-400">Auth Provider:</span>
                <span className="text-white">{user?.app_metadata?.provider || "N/A"}</span>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Preferences */}
        <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg shadow-xl">
          <CardHeader>
            <CardTitle className="text-xl font-bold text-white">Preferences</CardTitle>
          </CardHeader>
          <CardContent>
            <ScrollArea className="h-48">
              <pre className="rounded-lg border border-slate-700 bg-slate-800/50 p-3 text-xs text-slate-300 overflow-auto">
                {JSON.stringify({
                  ...preferences,
                  openaiApiKey: preferences.openaiApiKey ? "***" + preferences.openaiApiKey.slice(-4) : null,
                  authToken: preferences.authToken ? "***" : null,
                  pinCode: preferences.pinCode ? "****" : null,
                }, null, 2)}
              </pre>
