import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Brain, Plus, Trash2, Search, Tag, Folder } from "lucide-react";
import { showError, showSuccess } from "@/utils/toast";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";

interface KnowledgeItem {
  id: string;
  category: string;
  key: string;
  value: string;
  created_at: string;
}

const CATEGORIES = [
  "Personal",
  "Work",
  "Preferences",
  "Contacts",
  "Health",
  "Finance",
  "Travel",
  "Other",
];

export default function Knowledge() {
  const { user } = useAuth();
  const [items, setItems] = useState<KnowledgeItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterCategory, setFilterCategory] = useState<string>("all");
  
  // New item form
  const [newCategory, setNewCategory] = useState("Personal");
  const [newKey, setNewKey] = useState("");
  const [newValue, setNewValue] = useState("");

  useEffect(() => {
    if (user) loadKnowledge();
  }, [user]);

  const loadKnowledge = async () => {
    if (!user) return;
    setLoading(true);

    const { data, error } = await supabase
      .from("knowledge")
      .select("*")
      .eq("user_id", user.id)
      .order("created_at", { ascending: false });

    if (error) {
      showError("Failed to load knowledge");
    } else {
      setItems(data || []);
    }
    setLoading(false);
  };

  const addKnowledge = async () => {
    if (!user || !newKey.trim() || !newValue.trim()) {
      showError("Please fill in all fields");
      return;
    }

    const { data, error } = await supabase.from("knowledge").insert({
      user_id: user.id,
      category: newCategory,
      key: newKey.trim(),
      value: newValue.trim(),
    }).select().single();

    if (error) {
      showError("Failed to add knowledge");
    } else {
      setItems([data, ...items]);
      setNewKey("");
      setNewValue("");
      showSuccess("Knowledge added!");
    }
  };

  const deleteKnowledge = async (id: string) => {
    const { error } = await supabase.from("knowledge").delete().eq("id", id);

    if (error) {
      showError("Failed to delete");
    } else {
      setItems(items.filter(k => k.id !== id));
      showSuccess("Deleted");
    }
  };

  const filteredItems = items.filter(item => {
    const matchesSearch = 
      item.key.toLowerCase().includes(searchQuery.toLowerCase()) ||
      item.value.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesCategory = filterCategory === "all" || item.category === filterCategory;
    return matchesSearch && matchesCategory;
  });

  const groupedItems = filteredItems.reduce((acc, item) => {
    if (!acc[item.category]) {
      acc[item.category] = [];
    }
    acc[item.category].push(item);
    return acc;
  }, {} as Record<string, KnowledgeItem[]>);

  const getCategoryColor = (category: string) => {
    const colors: Record<string, string> = {
      Personal: "bg-blue-500/20 text-blue-300 border-blue-500/50",
      Work: "bg-purple-500/20 text-purple-300 border-purple-500/50",
      Preferences: "bg-green-500/20 text-green-300 border-green-500/50",
      Contacts: "bg-cyan-500/20 text-cyan-300 border-cyan-500/50",
      Health: "bg-red-500/20 text-red-300 border-red-500/50",
      Finance: "bg-yellow-500/20 text-yellow-300 border-yellow-500/50",
      Travel: "bg-orange-500/20 text-orange-300 border-orange-500/50",
      Other: "bg-slate-500/20 text-slate-300 border-slate-500/50",
    };
    return colors[category] || colors.Other;
  };

  return (
    <div className="min-h-[calc(100vh-56px)] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-4">
      <div className="mx-auto max-w-5xl space-y-6">
        {/* Header */}
        <div>
          <h1 className="text-3xl font-bold text-white flex items-center gap-3">
            <Brain className="h-8 w-8 text-fuchsia-400" />
            Knowledge Base
          </h1>
          <p className="text-slate-400 mt-1">
            Store facts and preferences that Echo should remember about you
          </p>
        </div>

        {/* Add New Knowledge */}
        <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg shadow-xl">
          <CardHeader>
            <CardTitle className="text-lg font-bold text-white flex items-center gap-2">
              <Plus className="h-5 w-5 text-fuchsia-400" />
              Add Knowledge
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid gap-4 md:grid-cols-4">
              <div>
                <Label className="text-slate-300">Category</Label>
                <Select value={newCategory} onValueChange={setNewCategory}>
                  <SelectTrigger className="bg-slate-800 border-slate-700 text-white">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-slate-800 border-slate-700">
                    {CATEGORIES.map(cat => (
                      <SelectItem key={cat} value={cat} className="text-white">
                        {cat}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label className="text-slate-300">Key / Topic</Label>
                <Input
                  className="bg-slate-800 border-slate-700 text-white placeholder:text-slate-500"
                  placeholder="e.g., Favorite color"
                  value={newKey}
                  onChange={(e) => setNewKey(e.target.value)}
                />
              </div>
              <div className="md:col-span-2">
                <Label className="text-slate-300">Value / Information</Label>
                <div className="flex gap-2">
                  <Input
                    className="bg-slate-800 border-slate-700 text-white placeholder:text-slate-500"
                    placeholder="e.g., Blue"
                    value={newValue}
                    onChange={(e) => setNewValue(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && addKnowledge()}
                  />
                  <Button onClick={addKnowledge} className="bg-fuchsia-600 text-white hover:bg-fuchsia-500">
                    <Plus className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            </div>
            <p className="text-xs text-slate-500">
              Examples: "My birthday is March 15", "I prefer morning meetings", "My doctor's name is Dr. Smith"
            </p>
          </CardContent>
        </Card>

        {/* Search and Filter */}
        <div className="flex flex-wrap gap-4">
          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            <Input
              className="pl-10 bg-slate-800 border-slate-700 text-white placeholder:text-slate-500"
              placeholder="Search knowledge..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <Select value={filterCategory} onValueChange={setFilterCategory}>
            <SelectTrigger className="w-40 bg-slate-800 border-slate-700 text-white">
              <Folder className="h-4 w-4 mr-2" />
              <SelectValue />
            </SelectTrigger>
            <SelectContent className="bg-slate-800 border-slate-700">
              <SelectItem value="all" className="text-white">All Categories</SelectItem>
              {CATEGORIES.map(cat => (
                <SelectItem key={cat} value={cat} className="text-white">
                  {cat}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Knowledge Items */}
        {loading ? (
          <Card className="border-slate-700 bg-slate-800/50">
            <CardContent className="p-8 text-center text-slate-400">
              Loading knowledge...
            </CardContent>
          </Card>
        ) : filteredItems.length === 0 ? (
          <Card className="border-slate-700 bg-slate-800/50">
            <CardContent className="p-8 text-center">
              <Brain className="h-12 w-12 text-slate-600 mx-auto mb-4" />
              <p className="text-slate-400">
                {searchQuery || filterCategory !== "all" 
                  ? "No knowledge matches your search." 
                  : "No knowledge stored yet. Add some facts about yourself!"}
              </p>
            </CardContent>
          </Card>
        ) : (
          <div className="space-y-6">
            {Object.entries(groupedItems).map(([category, categoryItems]) => (
              <div key={category}>
                <h3 className="text-lg font-semibold text-white mb-3 flex items-center gap-2">
                  <Tag className="h-4 w-4 text-fuchsia-400" />
                  {category}
                  <Badge variant="outline" className="border-slate-600 text-slate-400 ml-2">
                    {categoryItems.length}
                  </Badge>
                </h3>
                <div className="grid gap-2 md:grid-cols-2">
                  {categoryItems.map((item) => (
                    <Card
                      key={item.id}
                      className="border-fuchsia-500/20 bg-black/30 backdrop-blur"
                    >
                      <CardContent className="p-4">
                        <div className="flex items-start justify-between">
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1">
                              <span className="font-medium text-white">{item.key}</span>
                              <Badge className={getCategoryColor(item.category)}>
                                {item.category}
                              </Badge>
                            </div>
                            <p className="text-slate-300">{item.value}</p>
                          </div>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => deleteKnowledge(item.id)}
                            className="text-slate-400 hover:text-red-400 ml-2"
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Stats */}
        {items.length > 0 && (
          <Card className="border-slate-700 bg-slate-800/50">
            <CardContent className="p-4">
              <div className="flex flex-wrap gap-4 justify-center">
                <div className="text-center">
                  <p className="text-2xl font-bold text-fuchsia-400">{items.length}</p>
                  <p className="text-xs text-slate-400">Total Items</p>
                </div>
                <Separator orientation="vertical" className="h-12 bg-slate-700" />
                <div className="text-center">
                  <p className="text-2xl font-bold text-fuchsia-400">
                    {new Set(items.map(i => i.category)).size}
                  </p>
                  <p className="text-xs text-slate-400">Categories</p>
                </div>
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { 
  BookOpen, Plus, Search, Trash2, FileText, 
  Brain, Sparkles, ChevronDown, ChevronUp 
} from "lucide-react";
import { useAuth } from "@/contexts/AuthContext";
import { showError, showSuccess } from "@/utils/toast";
import { 
  listDocuments, 
  addDocument, 
  deleteDocument, 
  searchKnowledge,
  RAGDocument,
  SearchResult 
} from "@/services/rag-knowledge";
import VoiceHint from "@/components/VoiceHint";

export default function KnowledgeBase() {
  const { user } = useAuth();
  const [documents, setDocuments] = useState<RAGDocument[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [expandedDoc, setExpandedDoc] = useState<string | null>(null);
  
  // New document form
  const [isAddDialogOpen, setIsAddDialogOpen] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [newContent, setNewContent] = useState("");
  const [newCategory, setNewCategory] = useState("");
  const [newTags, setNewTags] = useState("");

  useEffect(() => {
    if (user) {
      loadDocuments();
    }
  }, [user]);

  const loadDocuments = async () => {
    if (!user) return;
    setIsLoading(true);
    try {
      const docs = await listDocuments(user.id);
      setDocuments(docs);
    } catch (error) {
      showError("Failed to load documents");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSearch = async () => {
    if (!user || !searchQuery.trim()) return;
    
    setIsSearching(true);
    try {
      const results = await searchKnowledge(user.id, searchQuery, { limit: 10 });
      setSearchResults(results);
    } catch (error) {
      showError("Search failed");
    } finally {
      setIsSearching(false);
    }
  };

  const handleAddDocument = async () => {
    if (!user || !newTitle.trim() || !newContent.trim()) {
      showError("Title and content are required");
      return;
    }

    try {
      const result = await addDocument(user.id, {
        title: newTitle,
        content: newContent,
        sourceType: "manual",
        metadata: {
          category: newCategory || undefined,
          tags: newTags ? newTags.split(",").map(t => t.trim()) : undefined,
        },
      });

      if (result.success) {
        showSuccess("Document added to knowledge base");
        setIsAddDialogOpen(false);
        setNewTitle("");
        setNewContent("");
        setNewCategory("");
        setNewTags("");
        loadDocuments();
      } else {
        showError(result.error || "Failed to add document");
      }
    } catch (error) {
      showError("Failed to add document");
    }
  };

  const handleDeleteDocument = async (docId: string) => {
    if (!user) return;

    try {
      const result = await deleteDocument(user.id, docId);
      if (result.success) {
        showSuccess("Document deleted");
        loadDocuments();
      } else {
        showError(result.error || "Failed to delete document");
      }
    } catch (error) {
      showError("Failed to delete document");
    }
  };

  return (
    <div className="min-h-[calc(100vh-56px)] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-4">
      <div className="mx-auto max-w-4xl space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-white flex items-center gap-2">
              <Brain className="h-6 w-6 text-fuchsia-400" />
              Knowledge Base
            </h1>
            <p className="text-slate-400 text-sm mt-1">
              Store and search your personal knowledge for AI-enhanced responses
            </p>
          </div>
          <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
            <DialogTrigger asChild>
              <Button className="bg-fuchsia-600 hover:bg-fuchsia-500">
                <Plus className="h-4 w-4 mr-2" />
                Add Document
              </Button>
            </DialogTrigger>
            <DialogContent className="bg-slate-900 border-slate-700">
              <DialogHeader>
                <DialogTitle className="text-white">Add to Knowledge Base</DialogTitle>
              </DialogHeader>
              <div className="space-y-4 pt-4">
                <div>
                  <Label className="text-slate-300">Title</Label>
                  <Input
                    value={newTitle}
                    onChange={(e) => setNewTitle(e.target.value)}
                    placeholder="Document title"
                    className="bg-slate-800 border-slate-700 text-white mt-1"
                  />
                </div>
                <div>
                  <Label className="text-slate-300">Content</Label>
                  <Textarea
                    value={newContent}
                    onChange={(e) => setNewContent(e.target.value)}
                    placeholder="Enter your knowledge content..."
                    className="bg-slate-800 border-slate-700 text-white mt-1 min-h-[200px]"
                  />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label className="text-slate-300">Category (optional)</Label>
                    <Input
                      value={newCategory}
                      onChange={(e) => setNewCategory(e.target.value)}
                      placeholder="e.g., AI/ML, Business"
                      className="bg-slate-800 border-slate-700 text-white mt-1"
                    />
                  </div>
                  <div>
                    <Label className="text-slate-300">Tags (comma-separated)</Label>
                    <Input
                      value={newTags}
                      onChange={(e) => setNewTags(e.target.value)}
                      placeholder="e.g., RAG, LLM, tutorial"
                      className="bg-slate-800 border-slate-700 text-white mt-1"
                    />
                  </div>
                </div>
                <Button onClick={handleAddDocument} className="w-full bg-fuchsia-600 hover:bg-fuchsia-500">
                  Add Document
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </div>

        <VoiceHint 
          commands={[
            "Search knowledge base for [topic]",
            "What do you know about [topic]?",
            "Add to knowledge base: [content]",
          ]}
        />

        {/* Search */}
        <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur">
          <CardContent className="pt-6">
            <div className="flex gap-2">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                <Input
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && handleSearch()}
                  placeholder="Search your knowledge base..."
                  className="pl-10 bg-slate-800 border-slate-700 text-white"
                />
              </div>
              <Button 
                onClick={handleSearch} 
                disabled={isSearching}
                className="bg-fuchsia-600 hover:bg-fuchsia-500"
              >
                {isSearching ? "Searching..." : "Search"}
              </Button>
            </div>

            {/* Search Results */}
            {searchResults.length > 0 && (
              <div className="mt-4 space-y-3">
                <h3 className="text-sm font-medium text-slate-300">
                  Found {searchResults.length} result{searchResults.length > 1 ? "s" : ""}
                </h3>
                {searchResults.map((result, idx) => (
                  <div 
                    key={idx}
                    className="p-3 rounded-lg bg-slate-800/50 border border-slate-700"
                  >
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-sm font-medium text-white">{result.document.title}</span>
                      <Badge variant="outline" className="text-xs border-fuchsia-500/50 text-fuchsia-300">
                        {Math.round(result.relevanceScore * 100)}% match
                      </Badge>
                    </div>
                    <p className="text-sm text-slate-400 line-clamp-3">{result.chunk.content}</p>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Documents List */}
        <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <BookOpen className="h-5 w-5 text-fuchsia-400" />
              Your Documents
            </CardTitle>
            <CardDescription className="text-slate-400">
              {documents.length} document{documents.length !== 1 ? "s" : ""} in your knowledge base
            </CardDescription>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <div className="text-center py-8 text-slate-400">Loading...</div>
            ) : documents.length === 0 ? (
              <div className="text-center py-8">
                <FileText className="h-12 w-12 mx-auto text-slate-600 mb-3" />
                <p className="text-slate-400">No documents yet</p>
                <p className="text-sm text-slate-500 mt-1">
                  Add documents to enhance AI responses with your knowledge
                </p>
              </div>
            ) : (
              <ScrollArea className="h-[400px]">
                <div className="space-y-3">
                  {documents.map((doc) => (
                    <div
                      key={doc.id}
                      className="p-4 rounded-lg bg-slate-800/50 border border-slate-700"
                    >
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <h3 className="font-medium text-white">{doc.title}</h3>
                            {doc.metadata?.category && (
                              <Badge variant="outline" className="text-xs border-slate-600 text-slate-400">
                                {doc.metadata.category}
                              </Badge>
                            )}
                          </div>
                          <p className="text-xs text-slate-500 mt-1">
                            {doc.chunks?.length || 0} chunks ΓÇó Added {new Date(doc.createdAt).toLocaleDateString()}
                          </p>
                          {doc.metadata?.tags && (
                            <div className="flex gap-1 mt-2">
                              {doc.metadata.tags.map((tag: string, idx: number) => (
                                <Badge key={idx} variant="secondary" className="text-xs bg-slate-700 text-slate-300">
                                  {tag}
                                </Badge>
                              ))}
                            </div>
                          )}
                        </div>
                        <div className="flex items-center gap-2">
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => setExpandedDoc(expandedDoc === doc.id ? null : doc.id)}
                            className="text-slate-400 hover:text-white h-8 w-8"
                          >
                            {expandedDoc === doc.id ? (
                              <ChevronUp className="h-4 w-4" />
                            ) : (
                              <ChevronDown className="h-4 w-4" />
                            )}
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => handleDeleteDocument(doc.id)}
                            className="text-slate-400 hover:text-red-400 h-8 w-8"
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>
                      
                      {expandedDoc === doc.id && (
                        <div className="mt-3 pt-3 border-t border-slate-700">
                          <p className="text-sm text-slate-300 whitespace-pre-wrap max-h-[300px] overflow-y-auto">
                            {doc.content}
                          </p>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </ScrollArea>
            )}
          </CardContent>
        </Card>

        {/* RAG Info */}
        <Card className="border-blue-500/20 bg-blue-950/20 backdrop-blur">
          <CardContent className="pt-6">
            <div className="flex items-start gap-3">
              <Sparkles className="h-5 w-5 text-blue-400 mt-0.5" />
              <div>
                <h3 className="font-medium text-white">How Knowledge Base Works</h3>
                <p className="text-sm text-slate-400 mt-1">
                  Documents you add are automatically chunked and indexed. When you ask Echo questions, 
                  relevant knowledge is retrieved and used to provide more accurate, personalized responses.
                  This is called Retrieval-Augmented Generation (RAG).
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { useAuth } from "@/contexts/AuthContext";
import { getPastSessions, ListeningSession } from "@/services/quiet-mode";
import {
  EarOff,
  Clock,
  FileText,
  CheckSquare,
  Calendar,
  Trash2,
  RefreshCw,
} from "lucide-react";
import { format, formatDistanceToNow } from "date-fns";
import { supabase } from "@/integrations/supabase/client";
import { showSuccess, showError } from "@/utils/toast";

export default function ListeningSessions() {
  const { user } = useAuth();
  const [sessions, setSessions] = useState<ListeningSession[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (user) {
      loadSessions();
    }
  }, [user]);

  const loadSessions = async () => {
    if (!user) return;
    setLoading(true);
    const data = await getPastSessions(user.id, 20);
    setSessions(data);
    setLoading(false);
  };

  const deleteSession = async (sessionId: string) => {
    try {
      const { error } = await supabase
        .from("ai_logs")
        .delete()
        .eq("id", sessionId);

      if (error) throw error;

      setSessions((prev) => prev.filter((s) => s.id !== sessionId));
      showSuccess("Session deleted");
    } catch (error) {
      showError("Failed to delete session");
    }
  };

  const getDuration = (session: ListeningSession) => {
    if (!session.endTime) return "In progress";
    const minutes = Math.round(
      (session.endTime.getTime() - session.startTime.getTime()) / 1000 / 60
    );
    return `${minutes} min`;
  };

  return (
    <div className="min-h-[calc(100vh-56px)] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900">
      <div className="mx-auto max-w-4xl p-4 md:p-6">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-3xl font-bold text-white flex items-center gap-3">
              <EarOff className="h-8 w-8 text-purple-400" />
              Listening Sessions
            </h1>
            <p className="text-slate-400 mt-1">
              Review past quiet mode sessions and their summaries
            </p>
          </div>
          <Button
            variant="outline"
            onClick={loadSessions}
            className="border-slate-600 text-slate-300 hover:bg-slate-800"
          >
            <RefreshCw className="h-4 w-4 mr-2" />
            Refresh
          </Button>
        </div>

        {loading ? (
          <div className="grid gap-4">
            {[1, 2, 3].map((i) => (
              <Card
                key={i}
                className="border-slate-700 bg-slate-800/50 animate-pulse"
              >
                <CardContent className="p-6">
                  <div className="h-24 bg-slate-700/50 rounded" />
                </CardContent>
              </Card>
            ))}
          </div>
        ) : sessions.length === 0 ? (
          <Card className="border-slate-700 bg-slate-800/50">
            <CardContent className="p-12 text-center">
              <EarOff className="h-16 w-16 text-slate-600 mx-auto mb-4" />
              <h3 className="text-xl font-semibold text-white mb-2">
                No Listening Sessions Yet
              </h3>
              <p className="text-slate-400 max-w-md mx-auto">
                Use quiet mode during meetings or conversations. Say "Go quiet"
                or "Listening mode" to start, then "Echo summarize" when done.
              </p>
            </CardContent>
          </Card>
        ) : (
          <ScrollArea className="h-[calc(100vh-200px)]">
            <Accordion type="single" collapsible className="space-y-4">
              {sessions.map((session) => (
                <AccordionItem
                  key={session.id}
                  value={session.id}
                  className="border-slate-700 bg-slate-800/50 rounded-lg overflow-hidden"
                >
                  <AccordionTrigger className="px-6 py-4 hover:no-underline hover:bg-slate-800/80">
                    <div className="flex items-center justify-between w-full pr-4">
                      <div className="flex items-center gap-4">
                        <div className="p-2 rounded-lg bg-purple-500/20">
                          <EarOff className="h-5 w-5 text-purple-400" />
                        </div>
                        <div className="text-left">
                          <p className="font-medium text-white">
                            {session.context || "Listening Session"}
                          </p>
                          <div className="flex items-center gap-3 text-sm text-slate-400">
                            <span className="flex items-center gap-1">
                              <Calendar className="h-3 w-3" />
                              {format(session.startTime, "MMM d, yyyy")}
                            </span>
                            <span className="flex items-center gap-1">
                              <Clock className="h-3 w-3" />
                              {format(session.startTime, "h:mm a")}
                            </span>
                            <Badge
                              variant="outline"
                              className="border-purple-500/50 text-purple-400"
                            >
                              {getDuration(session)}
                            </Badge>
                          </div>
                        </div>
                      </div>
                      <span className="text-xs text-slate-500">
                        {formatDistanceToNow(session.startTime, {
                          addSuffix: true,
                        })}
                      </span>
                    </div>
                  </AccordionTrigger>
                  <AccordionContent className="px-6 pb-4">
                    <div className="space-y-4 pt-2">
                      {/* Summary */}
                      {session.summary && (
                        <div>
                          <h4 className="text-sm font-medium text-slate-300 mb-2 flex items-center gap-2">
                            <FileText className="h-4 w-4 text-blue-400" />
                            Summary
                          </h4>
                          <p className="text-sm text-white bg-slate-900/50 p-3 rounded-lg border border-slate-700">
                            {session.summary}
                          </p>
                        </div>
                      )}

                      {/* Bullet Points */}
                      {session.bulletPoints &&
                        session.bulletPoints.length > 0 && (
                          <div>
                            <h4 className="text-sm font-medium text-slate-300 mb-2 flex items-center gap-2">
                              <CheckSquare className="h-4 w-4 text-green-400" />
                              Key Points
                            </h4>
                            <ul className="space-y-1">
                              {session.bulletPoints.map((point, idx) => (
                                <li
                                  key={idx}
                                  className="text-sm text-slate-300 flex items-start gap-2"
                                >
                                  <span className="text-purple-400 mt-1">ΓÇó</span>
                                  {point}
                                </li>
                              ))}
                            </ul>
                          </div>
                        )}

                      {/* Action Items */}
                      {session.actionItems &&
                        session.actionItems.length > 0 && (
                          <div>
                            <h4 className="text-sm font-medium text-slate-300 mb-2 flex items-center gap-2">
                              <CheckSquare className="h-4 w-4 text-fuchsia-400" />
                              Action Items
                            </h4>
                            <ul className="space-y-1">
                              {session.actionItems.map((item, idx) => (
                                <li
                                  key={idx}
                                  className="text-sm text-white bg-fuchsia-500/10 p-2 rounded flex items-start gap-2 border border-fuchsia-500/30"
                                >
                                  <span className="text-fuchsia-400">ΓåÆ</span>
                                  {item}
                                </li>
                              ))}
                            </ul>
                          </div>
                        )}

                      {/* Transcript Count */}
                      <div className="flex items-center justify-between pt-2 border-t border-slate-700">
                        <span className="text-xs text-slate-500">
                          {session.transcripts.length} transcript segments
                          recorded
                        </span>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => deleteSession(session.id)}
                          className="text-red-400 hover:text-red-300 hover:bg-red-500/10"
                        >
                          <Trash2 className="h-4 w-4 mr-1" />
                          Delete
                        </Button>
                      </div>
                    </div>
                  </AccordionContent>
                </AccordionItem>
              ))}
            </Accordion>
          </ScrollArea>
        )}
      </div>
    </div>
  );
}

