import { useEffect, useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { showSuccess, showError } from "@/utils/toast";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Plus, Trash2, Bell, Clock, Check, X, Mic } from "lucide-react";
import VoiceHint from "@/components/VoiceHint";
import { format } from "date-fns";

interface Reminder {
  id: string;
  text: string;
  due_time: string;
  channel: string;
  status: string;
  created_at: string;
}

export default function Reminders() {
  const { user } = useAuth();
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [loading, setLoading] = useState(true);
  const [newText, setNewText] = useState("");
  const [newTime, setNewTime] = useState("");
  const [newChannel, setNewChannel] = useState("push");

  useEffect(() => {
    if (user) loadReminders();
  }, [user]);

  const loadReminders = async () => {
    if (!user) return;
    setLoading(true);
    
    const { data, error } = await supabase
      .from("reminders")
      .select("*")
      .eq("user_id", user.id)
      .order("due_time", { ascending: true });

    if (error) {
      showError("Failed to load reminders");
    } else {
      setReminders(data || []);
    }
    setLoading(false);
  };

  const addReminder = async () => {
    if (!user || !newText.trim() || !newTime) return;

    const { data, error } = await supabase.from("reminders").insert({
      user_id: user.id,
      text: newText.trim(),
      due_time: new Date(newTime).toISOString(),
      channel: newChannel,
      status: "pending",
    }).select().single();

    if (error) {
      showError("Failed to create reminder");
    } else {
      setReminders([...reminders, data].sort((a, b) => 
        new Date(a.due_time).getTime() - new Date(b.due_time).getTime()
      ));
      setNewText("");
      setNewTime("");
      showSuccess("Reminder created!");
    }
  };

  const dismissReminder = async (id: string) => {
    const { error } = await supabase
      .from("reminders")
      .update({ status: "dismissed" })
      .eq("id", id);

    if (error) {
      showError("Failed to dismiss reminder");
    } else {
      setReminders(reminders.map(r => r.id === id ? { ...r, status: "dismissed" } : r));
    }
  };

  const deleteReminder = async (id: string) => {
    const { error } = await supabase.from("reminders").delete().eq("id", id);

    if (error) {
      showError("Failed to delete reminder");
    } else {
      setReminders(reminders.filter(r => r.id !== id));
      showSuccess("Reminder deleted");
    }
  };

  const getStatusColor = (status: string, dueTime: string) => {
    if (status === "dismissed") return "bg-slate-500/20 text-slate-400";
    if (status === "sent") return "bg-green-500/20 text-green-300";
    if (new Date(dueTime) < new Date()) return "bg-red-500/20 text-red-300";
    return "bg-yellow-500/20 text-yellow-300";
  };

  const pendingReminders = reminders.filter(r => r.status === "pending");
  const pastReminders = reminders.filter(r => r.status !== "pending");

  return (
    <div className="min-h-[calc(100vh-56px)] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-4">
      <div className="mx-auto max-w-4xl space-y-6">
        {/* Header */}
        <div>
          <h1 className="text-3xl font-bold text-white flex items-center gap-3">
            <Bell className="h-8 w-8 text-yellow-400" />
            Reminders
          </h1>
          <p className="text-slate-400 mt-1">
            {pendingReminders.length} pending reminders
          </p>
          <VoiceHint
            commands={["Remind me to call mom at 5pm", "Read my reminders", "Dismiss first reminder"]}
            className="mt-2"
          />
        </div>

        {/* Add Reminder */}
        <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg">
          <CardContent className="p-4">
            <div className="flex flex-wrap gap-3">
              <Input
                placeholder="Remind me to..."
                className="bg-slate-800 border-slate-700 text-white placeholder:text-slate-500 flex-1 min-w-[200px]"
                value={newText}
                onChange={(e) => setNewText(e.target.value)}
              />
              <Input
                type="datetime-local"
                className="bg-slate-800 border-slate-700 text-white w-48"
                value={newTime}
                onChange={(e) => setNewTime(e.target.value)}
              />
              <Select value={newChannel} onValueChange={setNewChannel}>
                <SelectTrigger className="w-28 bg-slate-800 border-slate-700 text-white">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="bg-slate-800 border-slate-700">
                  <SelectItem value="push" className="text-white">Push</SelectItem>
                  <SelectItem value="email" className="text-white">Email</SelectItem>
                  <SelectItem value="sms" className="text-white">SMS</SelectItem>
                </SelectContent>
              </Select>
              <Button onClick={addReminder} className="bg-fuchsia-600 text-white hover:bg-fuchsia-500">
                <Plus className="h-4 w-4 mr-2" /> Add
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Pending Reminders */}
        {pendingReminders.length > 0 && (
          <div>
            <h2 className="text-lg font-semibold text-white mb-3">Upcoming</h2>
            <div className="space-y-2">
              {pendingReminders.map((reminder) => (
                <Card key={reminder.id} className="border-fuchsia-500/20 bg-black/30 backdrop-blur">
                  <CardContent className="p-4">
                    <div className="flex items-center gap-4">
                      <Bell className="h-5 w-5 text-yellow-400" />
                      <div className="flex-1">
                        <p className="text-white">{reminder.text}</p>
                        <p className="text-sm text-slate-400 flex items-center gap-2 mt-1">
                          <Clock className="h-3 w-3" />
                          {format(new Date(reminder.due_time), "PPp")}
                        </p>
                      </div>
                      <Badge className={getStatusColor(reminder.status, reminder.due_time)}>
                        {new Date(reminder.due_time) < new Date() ? "Overdue" : "Pending"}
                      </Badge>
                      <Badge variant="outline" className="border-slate-600 text-slate-400">
                        {reminder.channel}
                      </Badge>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => dismissReminder(reminder.id)}
                        className="text-slate-400 hover:text-green-400"
                      >
                        <Check className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => deleteReminder(reminder.id)}
                        className="text-slate-400 hover:text-red-400"
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </div>
        )}

        {/* Past Reminders */}
        {pastReminders.length > 0 && (
          <div>
            <h2 className="text-lg font-semibold text-slate-400 mb-3">Past</h2>
            <div className="space-y-2 opacity-60">
              {pastReminders.map((reminder) => (
                <Card key={reminder.id} className="border-slate-700 bg-slate-800/30">
                  <CardContent className="p-4">
                    <div className="flex items-center gap-4">
                      <Bell className="h-5 w-5 text-slate-500" />
                      <div className="flex-1">
                        <p className="text-slate-400">{reminder.text}</p>
                        <p className="text-sm text-slate-500">
                          {format(new Date(reminder.due_time), "PPp")}
                        </p>
                      </div>
                      <Badge className="bg-slate-600/20 text-slate-400">
                        {reminder.status}
                      </Badge>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => deleteReminder(reminder.id)}
                        className="text-slate-500 hover:text-red-400"
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </div>
        )}

        {reminders.length === 0 && !loading && (
          <Card className="border-slate-700 bg-slate-800/50">
            <CardContent className="p-8 text-center text-slate-400">
              No reminders yet. Add one above!
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { 
  Brain, 
  Mic, 
  MicOff, 
  Languages, 
  Users2, 
  ShieldCheck,
  Search,
  MessageSquare,
  ListChecks,
  Settings,
  Activity,
  Volume2,
  Clock,
  Trash2,
  Download
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Slider } from "@/components/ui/slider";
import { useSecondBrain } from "@/hooks/useSecondBrain";
import { speakerIdentification } from "@/services/second-brain/speaker-identification";
import { whisperMode } from "@/services/second-brain/whisper-mode";
import { translationService } from "@/services/second-brain/translation";
import { toast } from "sonner";
import SecondBrainVoiceCommands from "@/components/SecondBrainVoiceCommands";

export default function SecondBrain() {
  const [state, actions] = useSecondBrain();
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const [speakers, setSpeakers] = useState<any[]>([]);
  const [whisperVolume, setWhisperVolume] = useState(30);
  const [whisperRate, setWhisperRate] = useState(120);

  // Load speakers
  useEffect(() => {
    const interval = setInterval(() => {
      setSpeakers(speakerIdentification.getAllSpeakers());
    }, 2000);

    return () => clearInterval(interval);
  }, []);

  // Handle search
  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    
    const results = await actions.searchConversations(searchQuery);
    setSearchResults(results);
    toast.success(`Found ${results.length} conversations`);
  };

  // Handle whisper volume change
  const handleVolumeChange = (value: number[]) => {
    const vol = value[0];
    setWhisperVolume(vol);
    whisperMode.setVolume(vol / 100);
  };

  // Handle whisper rate change
  const handleRateChange = (value: number[]) => {
    const rate = value[0];
    setWhisperRate(rate);
    whisperMode.setRate(rate / 100);
  };

  // Test whisper
  const testWhisper = () => {
    whisperMode.whisper("This is a test whisper. Can you hear me clearly?", "normal");
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-6">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-4">
            <div className={`p-3 rounded-xl ${state.isActive ? 'bg-purple-500/20' : 'bg-slate-700/50'}`}>
              <Brain className={`h-8 w-8 ${state.isActive ? 'text-purple-400' : 'text-slate-400'}`} />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-white">Second Brain</h1>
              <p className="text-slate-400">
                {state.isActive ? 'Active and listening' : 'Inactive'}
              </p>
            </div>
          </div>
          <Button
            onClick={() => state.isActive ? actions.stop() : actions.start()}
            className={state.isActive ? 'bg-red-600 hover:bg-red-700' : 'bg-purple-600 hover:bg-purple-700'}
          >
            {state.isActive ? (
              <>
                <MicOff className="h-4 w-4 mr-2" />
                Stop Second Brain
              </>
            ) : (
              <>
                <Brain className="h-4 w-4 mr-2" />
                Start Second Brain
              </>
            )}
          </Button>
        </div>

        {/* Status Cards */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
          <StatusCard
            icon={state.isPrivacyMode ? MicOff : Mic}
            title="Listening"
            value={state.isPrivacyMode ? 'Privacy Mode' : state.isActive ? 'Active' : 'Inactive'}
            color={state.isPrivacyMode ? 'yellow' : state.isActive ? 'green' : 'slate'}
          />
          <StatusCard
            icon={Users2}
            title="Speakers"
            value={`${state.speakerCount} detected`}
            color="blue"
          />
          <StatusCard
            icon={MessageSquare}
            title="Segments"
            value={`${state.segmentCount} captured`}
            color="purple"
          />
          <StatusCard
            icon={Activity}
            title="Fact Checking"
            value={state.isFactCheckingEnabled ? 'Enabled' : 'Disabled'}
            color={state.isFactCheckingEnabled ? 'green' : 'slate'}
          />
        </div>

        {/* Main Content */}
        <Tabs defaultValue="conversations" className="space-y-6">
          <TabsList className="bg-slate-800/50">
            <TabsTrigger value="conversations">Conversations</TabsTrigger>
            <TabsTrigger value="speakers">Speakers</TabsTrigger>
            <TabsTrigger value="settings">Settings</TabsTrigger>
          </TabsList>

          {/* Conversations Tab */}
          <TabsContent value="conversations">
            <Card className="bg-slate-800/50 border-slate-700">
              <CardHeader>
                <CardTitle className="text-white">Conversation Search</CardTitle>
                <CardDescription>
                  Search through your indexed conversations by keyword, person, or topic
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="flex gap-2 mb-6">
                  <Input
                    placeholder="Search conversations..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                    className="bg-slate-900/50 border-slate-600"
                  />
                  <Button onClick={handleSearch}>
                    <Search className="h-4 w-4 mr-2" />
                    Search
                  </Button>
                </div>

                {/* Search Results */}
                {searchResults.length > 0 ? (
                  <div className="space-y-4">
                    {searchResults.map((result, index) => (
                      <div
                        key={index}
                        className="p-4 rounded-lg bg-slate-900/50 border border-slate-700"
                      >
                        <div className="flex items-center justify-between mb-2">
                          <div className="flex items-center gap-2">
                            <Users2 className="h-4 w-4 text-purple-400" />
                            <span className="font-medium text-white">
                              {result.speakerName || 'Unknown Speaker'}
                            </span>
                          </div>
                          <span className="text-xs text-slate-400">
                            {new Date(result.startTime).toLocaleDateString()}
                          </span>
                        </div>
                        <p className="text-sm text-slate-300 mb-2">{result.summary}</p>
