            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Whisper Settings */}
              <Card className="bg-slate-800/50 border-slate-700">
                <CardHeader>
                  <CardTitle className="text-white flex items-center gap-2">
                    <Volume2 className="h-5 w-5 text-purple-400" />
                    Whisper Mode
                  </CardTitle>
                  <CardDescription>
