                      showError(error.message || "Failed to remove model");
                    }
                  }}
                  className="w-full border-red-500/30 text-red-400 hover:bg-red-500/10"
                >
                  <Trash2 className="mr-2 h-4 w-4" />
                  Remove Local AI Model
