import { useEffect, useState, useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import { showSuccess, showError } from "@/utils/toast";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Plus, Trash2, CheckSquare, Clock, AlertTriangle, Mic, CalendarIcon, Search, SortAsc, SortDesc, RefreshCw } from "lucide-react";
import VoiceHint from "@/components/VoiceHint";
import { format, isToday, isTomorrow, isPast, parseISO, isThisWeek, addDays } from "date-fns";

interface Task {
  id: string;
  title: string;
  description?: string;
  priority: string;
  status: string;
  due_date?: string;
  tags?: string[];
  created_at: string;
  completed_at?: string;
}

type SortOption = "created" | "due" | "priority" | "alpha";
type FilterOption = "all" | "pending" | "completed" | "overdue" | "today" | "week";

export default function Tasks() {
  const { user } = useAuth();
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [newTask, setNewTask] = useState("");
  const [newPriority, setNewPriority] = useState("medium");
  const [newDueDate, setNewDueDate] = useState<Date | undefined>(undefined);
  const [filter, setFilter] = useState<FilterOption>("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [sortBy, setSortBy] = useState<SortOption>("created");
  const [sortAsc, setSortAsc] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  useEffect(() => {
    if (user) loadTasks();
  }, [user]);

  const loadTasks = async () => {
    if (!user) return;
    setLoading(true);
    
    const { data, error } = await supabase
      .from("tasks")
      .select("*")
      .eq("user_id", user.id)
      .order("created_at", { ascending: false });

    if (error) {
      showError("Failed to load tasks");
    } else {
      setTasks(data || []);
    }
    setLoading(false);
  };

  const handleRefresh = async () => {
    setIsRefreshing(true);
    await loadTasks();
    setIsRefreshing(false);
  };

  const addTask = async () => {
    if (!user || !newTask.trim()) return;

    const { data, error } = await supabase.from("tasks").insert({
      user_id: user.id,
      title: newTask.trim(),
      priority: newPriority,
      status: "pending",
      due_date: newDueDate ? newDueDate.toISOString() : null,
    }).select().single();

    if (error) {
      showError("Failed to create task");
    } else {
      setTasks([data, ...tasks]);
      setNewTask("");
      setNewDueDate(undefined);
      showSuccess("Task created!");
    }
  };

  const toggleTask = async (task: Task) => {
    const newStatus = task.status === "completed" ? "pending" : "completed";
    const completedAt = newStatus === "completed" ? new Date().toISOString() : null;

    const { error } = await supabase
      .from("tasks")
      .update({ status: newStatus, completed_at: completedAt })
      .eq("id", task.id);

    if (error) {
      showError("Failed to update task");
    } else {
      setTasks(tasks.map(t => 
        t.id === task.id ? { ...t, status: newStatus, completed_at: completedAt } : t
      ));
    }
  };

  const deleteTask = async (taskId: string) => {
    const { error } = await supabase.from("tasks").delete().eq("id", taskId);

    if (error) {
      showError("Failed to delete task");
    } else {
      setTasks(tasks.filter(t => t.id !== taskId));
      showSuccess("Task deleted");
    }
  };

  // Filter and sort tasks
  const filteredTasks = useMemo(() => {
    let result = tasks.filter(task => {
      // Search filter
      if (searchQuery) {
        const query = searchQuery.toLowerCase();
        if (!task.title.toLowerCase().includes(query) &&
            !task.description?.toLowerCase().includes(query)) {
          return false;
        }
      }

      // Status filter
      switch (filter) {
        case "pending":
          return task.status === "pending";
        case "completed":
          return task.status === "completed";
        case "overdue":
          return task.status === "pending" && task.due_date && isPast(parseISO(task.due_date));
        case "today":
          return task.due_date && isToday(parseISO(task.due_date));
        case "week":
          return task.due_date && isThisWeek(parseISO(task.due_date));
        default:
          return true;
      }
    });

    // Sort
    result.sort((a, b) => {
      let comparison = 0;
      switch (sortBy) {
        case "due":
          if (!a.due_date && !b.due_date) comparison = 0;
          else if (!a.due_date) comparison = 1;
          else if (!b.due_date) comparison = -1;
          else comparison = new Date(a.due_date).getTime() - new Date(b.due_date).getTime();
          break;
        case "priority":
          const priorityOrder = { urgent: 0, high: 1, medium: 2, low: 3 };
          comparison = (priorityOrder[a.priority as keyof typeof priorityOrder] || 2) -
                       (priorityOrder[b.priority as keyof typeof priorityOrder] || 2);
          break;
        case "alpha":
          comparison = a.title.localeCompare(b.title);
          break;
        default:
          comparison = new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
      }
      return sortAsc ? comparison : -comparison;
    });

    return result;
  }, [tasks, filter, searchQuery, sortBy, sortAsc]);

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case "urgent": return "bg-red-500/20 text-red-300 border-red-500/50";
      case "high": return "bg-orange-500/20 text-orange-300 border-orange-500/50";
      case "medium": return "bg-yellow-500/20 text-yellow-300 border-yellow-500/50";
      case "low": return "bg-green-500/20 text-green-300 border-green-500/50";
      default: return "bg-slate-500/20 text-slate-300 border-slate-500/50";
    }
  };

  const formatDueDate = (dueDate: string) => {
    const date = parseISO(dueDate);
    if (isToday(date)) return "Today";
    if (isTomorrow(date)) return "Tomorrow";
    if (isPast(date)) return `Overdue (${format(date, "MMM d")})`;
    return format(date, "MMM d");
  };

  const getDueDateColor = (dueDate: string) => {
    const date = parseISO(dueDate);
    if (isPast(date)) return "text-red-400";
    if (isToday(date)) return "text-yellow-400";
    if (isTomorrow(date)) return "text-orange-400";
    return "text-slate-400";
  };

  const pendingCount = tasks.filter(t => t.status === "pending").length;
  const completedCount = tasks.filter(t => t.status === "completed").length;
  const overdueCount = tasks.filter(t => t.status === "pending" && t.due_date && isPast(parseISO(t.due_date))).length;
  const todayCount = tasks.filter(t => t.due_date && isToday(parseISO(t.due_date))).length;

  return (
    <div className="min-h-[calc(100vh-56px)] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-4">
      <div className="mx-auto max-w-4xl space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white flex items-center gap-3">
              <CheckSquare className="h-8 w-8 text-green-400" />
              Tasks
            </h1>
            <p className="text-slate-400 mt-1">
              {pendingCount} pending ΓÇó {completedCount} completed
            </p>
            <VoiceHint
              commands={["Add task buy groceries", "Mark first task done", "Read my tasks"]}
              className="mt-2"
            />
          </div>
        </div>

        {/* Add Task */}
        <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg">
          <CardContent className="p-4">
            <div className="flex flex-wrap gap-3">
              <Input
                placeholder="Add a new task..."
                className="bg-slate-800 border-slate-700 text-white placeholder:text-slate-500 flex-1 min-w-[200px]"
                value={newTask}
                onChange={(e) => setNewTask(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && addTask()}
              />
              <Select value={newPriority} onValueChange={setNewPriority}>
                <SelectTrigger className="w-28 bg-slate-800 border-slate-700 text-white">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="bg-slate-800 border-slate-700">
                  <SelectItem value="low" className="text-green-300">Low</SelectItem>
                  <SelectItem value="medium" className="text-yellow-300">Medium</SelectItem>
                  <SelectItem value="high" className="text-orange-300">High</SelectItem>
                  <SelectItem value="urgent" className="text-red-300">Urgent</SelectItem>
                </SelectContent>
              </Select>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={`w-32 justify-start text-left font-normal bg-slate-800 border-slate-700 ${
                      newDueDate ? "text-white" : "text-slate-500"
                    }`}
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {newDueDate ? format(newDueDate, "MMM d") : "Due date"}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0 bg-slate-900 border-slate-700" align="start">
                  <Calendar
                    mode="single"
                    selected={newDueDate}
                    onSelect={setNewDueDate}
                    initialFocus
                    className="bg-slate-900"
                  />
                  <div className="p-2 border-t border-slate-700 flex gap-2">
                    <Button
                      size="sm"
                      variant="ghost"
                      className="text-xs"
                      onClick={() => setNewDueDate(new Date())}
                    >
                      Today
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      className="text-xs"
                      onClick={() => setNewDueDate(addDays(new Date(), 1))}
                    >
                      Tomorrow
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      className="text-xs"
                      onClick={() => setNewDueDate(undefined)}
                    >
                      Clear
                    </Button>
                  </div>
                </PopoverContent>
              </Popover>
              <Button onClick={addTask} className="bg-fuchsia-600 text-white hover:bg-fuchsia-500">
                <Plus className="h-4 w-4" />
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Search and Sort */}
        <Card className="border-slate-700 bg-slate-800/50">
          <CardContent className="p-3">
            <div className="flex flex-wrap gap-3 items-center">
              <div className="relative flex-1 min-w-[200px]">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                <Input
                  placeholder="Search tasks..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-10 bg-slate-900 border-slate-600 text-white placeholder:text-slate-500"
                />
              </div>
              <Select value={sortBy} onValueChange={(v) => setSortBy(v as SortOption)}>
                <SelectTrigger className="w-32 bg-slate-900 border-slate-600 text-white">
                  <SelectValue placeholder="Sort by" />
                </SelectTrigger>
                <SelectContent className="bg-slate-900 border-slate-700">
                  <SelectItem value="created">Created</SelectItem>
                  <SelectItem value="due">Due Date</SelectItem>
                  <SelectItem value="priority">Priority</SelectItem>
                  <SelectItem value="alpha">Alphabetical</SelectItem>
                </SelectContent>
              </Select>
              <Button
                variant="outline"
                size="icon"
                onClick={() => setSortAsc(!sortAsc)}
                className="border-slate-600 text-slate-300 hover:bg-slate-800"
              >
                {sortAsc ? <SortAsc className="h-4 w-4" /> : <SortDesc className="h-4 w-4" />}
              </Button>
              <Button
                variant="outline"
                size="icon"
                onClick={handleRefresh}
                disabled={isRefreshing}
                className="border-slate-600 text-slate-300 hover:bg-slate-800"
              >
                <RefreshCw className={`h-4 w-4 ${isRefreshing ? "animate-spin" : ""}`} />
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Filters */}
        <Tabs value={filter} onValueChange={(v) => setFilter(v as FilterOption)}>
          <TabsList className="bg-slate-800 flex-wrap h-auto gap-1 p-1">
            <TabsTrigger value="all" className="data-[state=active]:bg-fuchsia-600">
              All ({tasks.length})
            </TabsTrigger>
            <TabsTrigger value="pending" className="data-[state=active]:bg-fuchsia-600">
              Pending ({pendingCount})
            </TabsTrigger>
            {overdueCount > 0 && (
              <TabsTrigger value="overdue" className="data-[state=active]:bg-red-600 text-red-400 data-[state=active]:text-white">
                Overdue ({overdueCount})
              </TabsTrigger>
            )}
            {todayCount > 0 && (
              <TabsTrigger value="today" className="data-[state=active]:bg-yellow-600">
                Today ({todayCount})
              </TabsTrigger>
            )}
            <TabsTrigger value="week" className="data-[state=active]:bg-fuchsia-600">
              This Week
            </TabsTrigger>
            <TabsTrigger value="completed" className="data-[state=active]:bg-fuchsia-600">
              Completed ({completedCount})
            </TabsTrigger>
          </TabsList>
        </Tabs>

        {/* Task List */}
        <div className="space-y-2">
          {loading ? (
            <Card className="border-slate-700 bg-slate-800/50">
              <CardContent className="p-8 text-center text-slate-400">
                Loading tasks...
              </CardContent>
            </Card>
          ) : filteredTasks.length === 0 ? (
            <Card className="border-slate-700 bg-slate-800/50">
              <CardContent className="p-8 text-center text-slate-400">
                No tasks found. Add one above!
              </CardContent>
            </Card>
          ) : (
            filteredTasks.map((task) => (
              <Card
                key={task.id}
                className={`border-fuchsia-500/20 bg-black/30 backdrop-blur transition-all ${
                  task.status === "completed" ? "opacity-60" : ""
                }`}
              >
                <CardContent className="p-4">
                  <div className="flex items-center gap-4">
                    <Checkbox
                      checked={task.status === "completed"}
                      onCheckedChange={() => toggleTask(task)}
                      className="border-slate-500 data-[state=checked]:bg-green-500 data-[state=checked]:border-green-500"
                    />
                    <div className="flex-1 min-w-0">
                      <p className={`text-white ${task.status === "completed" ? "line-through text-slate-400" : ""}`}>
                        {task.title}
                      </p>
                      {task.description && (
                        <p className="text-sm text-slate-400 mt-1 truncate">{task.description}</p>
                      )}
                      {task.due_date && task.status !== "completed" && (
                        <p className={`text-xs mt-1 flex items-center gap-1 ${getDueDateColor(task.due_date)}`}>
                          <Clock className="h-3 w-3" />
                          {formatDueDate(task.due_date)}
                        </p>
                      )}
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge className={getPriorityColor(task.priority)}>
                        {task.priority}
                      </Badge>
                    </div>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => deleteTask(task.id)}
                      className="text-slate-400 hover:text-red-400 hover:bg-red-500/20"
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { showError, showSuccess } from "@/utils/toast";
import { searchWeb, getWeather, findNearbyPlaces, geocodeAddress } from "../services/search";
import { getCurrentLocation } from "../services/location";
import { openAppleMaps } from "../services/maps";
import { 
  Search, 
  MapPin, 
  Cloud, 
  Calculator, 
  Clock, 
  Globe,
  Thermometer,
  Wind,
  Droplets,
  Navigation,
  ExternalLink
} from "lucide-react";

interface WeatherData {
  temperature: number;
  feelsLike: number;
  humidity: number;
  description: string;
  windSpeed: number;
  location: string;
}

export default function Tools() {
  const [activeTab, setActiveTab] = useState("search");
  
  // Search state
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<
    Array<{ title: string; url: string; snippet?: string; source: string }>
  >([]);
  const [searchLoading, setSearchLoading] = useState(false);
  
  // Nearby state
  const [nearbyQuery, setNearbyQuery] = useState("");
  const [nearby, setNearby] = useState<
    Array<{ name: string; lat: number; lon: number; distanceMeters: number; type?: string }>
  >([]);
  const [nearbyLoading, setNearbyLoading] = useState(false);
  
  // Weather state
  const [weatherLocation, setWeatherLocation] = useState("");
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [weatherLoading, setWeatherLoading] = useState(false);
  
  // Calculator state
  const [calcExpression, setCalcExpression] = useState("");
  const [calcResult, setCalcResult] = useState<string | null>(null);
  
  // Timezone state
  const [timezones] = useState([
    { name: "New York", tz: "America/New_York" },
    { name: "Los Angeles", tz: "America/Los_Angeles" },
    { name: "London", tz: "Europe/London" },
    { name: "Paris", tz: "Europe/Paris" },
    { name: "Tokyo", tz: "Asia/Tokyo" },
    { name: "Sydney", tz: "Australia/Sydney" },
    { name: "Dubai", tz: "Asia/Dubai" },
    { name: "Singapore", tz: "Asia/Singapore" },
  ]);

  const doSearch = async () => {
    if (!searchQuery.trim()) return;
    setSearchLoading(true);
    try {
      const res = await searchWeb(searchQuery.trim());
      setSearchResults(res);
    } catch (e: any) {
      showError(e.message || "Search failed");
    }
    setSearchLoading(false);
  };

  const doNearby = async () => {
    if (!nearbyQuery.trim()) return;
    setNearbyLoading(true);
    try {
      const loc = await getCurrentLocation();
      const places = await findNearbyPlaces(nearbyQuery.trim(), loc);
      setNearby(places);
    } catch (e: any) {
      showError(e.message || "Nearby search failed");
    }
    setNearbyLoading(false);
  };

  const doWeather = async () => {
    setWeatherLoading(true);
    try {
      let lat: number, lon: number;
      let locationName = "Your Location";
      
      if (weatherLocation.trim()) {
        const geocoded = await geocodeAddress(weatherLocation.trim());
        if (!geocoded) {
          showError("Could not find that location");
          setWeatherLoading(false);
          return;
        }
        lat = geocoded.lat;
        lon = geocoded.lon;
        locationName = weatherLocation.trim();
      } else {
        const loc = await getCurrentLocation();
        lat = loc.lat;
        lon = loc.lng;
      }
      
      const weatherData = await getWeather(lat, lon);
      setWeather({ ...weatherData, location: locationName });
    } catch (e: any) {
      showError(e.message || "Weather fetch failed");
    }
    setWeatherLoading(false);
  };

  const doCalculate = () => {
    try {
      // Safe evaluation using Function constructor
      const sanitized = calcExpression.replace(/[^0-9+\-*/().%\s]/g, "");
      if (!sanitized) {
        setCalcResult("Invalid expression");
        return;
      }
      const result = new Function(`return ${sanitized}`)();
      setCalcResult(String(result));
    } catch {
      setCalcResult("Error");
    }
  };

  const getTimeInZone = (tz: string) => {
    try {
      return new Date().toLocaleTimeString("en-US", {
        timeZone: tz,
        hour: "2-digit",
        minute: "2-digit",
        hour12: true,
      });
    } catch {
      return "N/A";
    }
  };

  const getDateInZone = (tz: string) => {
    try {
      return new Date().toLocaleDateString("en-US", {
        timeZone: tz,
        weekday: "short",
        month: "short",
        day: "numeric",
      });
    } catch {
      return "";
    }
  };

  return (
    <div className="min-h-[calc(100vh-56px)] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-4">
      <div className="mx-auto max-w-5xl space-y-6">
        {/* Header */}
        <div>
          <h1 className="text-3xl font-bold text-white flex items-center gap-3">
            <Globe className="h-8 w-8 text-fuchsia-400" />
            Tools
          </h1>
          <p className="text-slate-400 mt-1">Useful utilities at your fingertips</p>
        </div>

        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList className="bg-slate-800 flex-wrap h-auto gap-1 p-1">
            <TabsTrigger value="search" className="data-[state=active]:bg-fuchsia-600">
              <Search className="h-4 w-4 mr-2" /> Search
            </TabsTrigger>
            <TabsTrigger value="weather" className="data-[state=active]:bg-fuchsia-600">
              <Cloud className="h-4 w-4 mr-2" /> Weather
            </TabsTrigger>
            <TabsTrigger value="nearby" className="data-[state=active]:bg-fuchsia-600">
              <MapPin className="h-4 w-4 mr-2" /> Nearby
            </TabsTrigger>
            <TabsTrigger value="calculator" className="data-[state=active]:bg-fuchsia-600">
              <Calculator className="h-4 w-4 mr-2" /> Calculator
            </TabsTrigger>
            <TabsTrigger value="time" className="data-[state=active]:bg-fuchsia-600">
              <Clock className="h-4 w-4 mr-2" /> World Clock
            </TabsTrigger>
          </TabsList>

          {/* Search Tab */}
          <TabsContent value="search" className="mt-4">
            <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg shadow-xl">
              <CardHeader>
                <CardTitle className="text-xl font-bold text-white flex items-center gap-2">
                  <Search className="h-5 w-5 text-fuchsia-400" />
                  Web Search
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex gap-2">
                  <Input
                    className="bg-slate-800 border-slate-700 text-white placeholder:text-slate-500"
                    placeholder="Search the web..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && doSearch()}
                  />
                  <Button 
                    onClick={doSearch} 
                    className="bg-fuchsia-600 text-white hover:bg-fuchsia-500"
                    disabled={searchLoading}
                  >
                    {searchLoading ? "..." : "Search"}
                  </Button>
                </div>
                <div className="space-y-2">
                  {searchResults.map((r, idx) => (
                    <div key={idx} className="rounded-lg border border-slate-700 bg-slate-800/50 p-3">
                      <div className="flex items-start justify-between">
                        <a
                          className="font-medium text-fuchsia-300 hover:underline"
                          href={r.url}
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          {r.title}
                        </a>
                        <Badge variant="outline" className="border-slate-600 text-slate-400 text-xs ml-2">
                          {r.source}
                        </Badge>
                      </div>
                      {r.snippet && (
                        <p className="text-sm text-slate-400 mt-1 line-clamp-2">{r.snippet}</p>
                      )}
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* Weather Tab */}
          <TabsContent value="weather" className="mt-4">
            <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg shadow-xl">
              <CardHeader>
                <CardTitle className="text-xl font-bold text-white flex items-center gap-2">
                  <Cloud className="h-5 w-5 text-fuchsia-400" />
                  Weather
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex gap-2">
                  <Input
                    className="bg-slate-800 border-slate-700 text-white placeholder:text-slate-500"
                    placeholder="Enter city name (or leave empty for current location)"
                    value={weatherLocation}
                    onChange={(e) => setWeatherLocation(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && doWeather()}
                  />
                  <Button 
                    onClick={doWeather} 
                    className="bg-fuchsia-600 text-white hover:bg-fuchsia-500"
                    disabled={weatherLoading}
                  >
                    {weatherLoading ? "..." : "Get Weather"}
                  </Button>
                </div>
                
                {weather && (
                  <div className="rounded-xl border border-slate-700 bg-gradient-to-br from-blue-900/30 to-purple-900/30 p-6">
                    <div className="flex items-center justify-between mb-4">
                      <div>
                        <h3 className="text-2xl font-bold text-white">{weather.location}</h3>
                        <p className="text-slate-400">{weather.description}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-5xl font-bold text-white">{weather.temperature}┬░C</p>
                        <p className="text-sm text-slate-400">Feels like {weather.feelsLike}┬░C</p>
                      </div>
                    </div>
                    <div className="grid grid-cols-3 gap-4">
                      <div className="flex items-center gap-2 text-slate-300">
                        <Thermometer className="h-5 w-5 text-orange-400" />
                        <div>
                          <p className="text-xs text-slate-500">Feels Like</p>
                          <p className="font-medium">{weather.feelsLike}┬░C</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2 text-slate-300">
                        <Droplets className="h-5 w-5 text-blue-400" />
                        <div>
                          <p className="text-xs text-slate-500">Humidity</p>
                          <p className="font-medium">{weather.humidity}%</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2 text-slate-300">
                        <Wind className="h-5 w-5 text-cyan-400" />
                        <div>
                          <p className="text-xs text-slate-500">Wind</p>
                          <p className="font-medium">{weather.windSpeed} km/h</p>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* Nearby Tab */}
          <TabsContent value="nearby" className="mt-4">
            <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg shadow-xl">
              <CardHeader>
                <CardTitle className="text-xl font-bold text-white flex items-center gap-2">
                  <MapPin className="h-5 w-5 text-fuchsia-400" />
                  Nearby Places
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex gap-2">
                  <Input
                    className="bg-slate-800 border-slate-700 text-white placeholder:text-slate-500"
                    placeholder='Search nearby (e.g., "coffee", "gas station", "pharmacy")'
                    value={nearbyQuery}
                    onChange={(e) => setNearbyQuery(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && doNearby()}
                  />
                  <Button 
                    onClick={doNearby} 
                    className="bg-fuchsia-600 text-white hover:bg-fuchsia-500"
                    disabled={nearbyLoading}
                  >
                    {nearbyLoading ? "..." : "Find"}
                  </Button>
                </div>
                <div className="space-y-2">
                  {nearby.map((p, idx) => (
                    <div key={idx} className="rounded-lg border border-slate-700 bg-slate-800/50 p-3">
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="font-medium text-white">{p.name.split(",")[0]}</div>
                          <div className="text-sm text-slate-400 mt-1">
                            {(p.distanceMeters / 1000).toFixed(1)} km away
                            {p.type && <span className="ml-2 text-slate-500">ΓÇó {p.type}</span>}
                          </div>
                        </div>
                        <Button
                          size="sm"
                          variant="outline"
                          className="border-slate-600 text-slate-300 hover:bg-slate-700"
                          onClick={() => openAppleMaps(p.lat, p.lon, p.name)}
                        >
                          <Navigation className="h-4 w-4 mr-1" /> Navigate
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* Calculator Tab */}
          <TabsContent value="calculator" className="mt-4">
            <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg shadow-xl">
              <CardHeader>
                <CardTitle className="text-xl font-bold text-white flex items-center gap-2">
                  <Calculator className="h-5 w-5 text-fuchsia-400" />
                  Calculator
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex gap-2">
                  <Input
                    className="bg-slate-800 border-slate-700 text-white placeholder:text-slate-500 font-mono text-lg"
                    placeholder="Enter expression (e.g., 2 + 2 * 3)"
                    value={calcExpression}
                    onChange={(e) => setCalcExpression(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && doCalculate()}
                  />
                  <Button 
                    onClick={doCalculate} 
                    className="bg-fuchsia-600 text-white hover:bg-fuchsia-500"
                  >
                    =
                  </Button>
                </div>
                {calcResult !== null && (
                  <div className="rounded-lg border border-slate-700 bg-slate-800/50 p-4">
                    <p className="text-sm text-slate-400">Result:</p>
                    <p className="text-3xl font-bold text-white font-mono">{calcResult}</p>
                  </div>
                )}
                <div className="grid grid-cols-4 gap-2">
                  {["7", "8", "9", "/", "4", "5", "6", "*", "1", "2", "3", "-", "0", ".", "(", "+", ")", "%", "C", "="].map((btn) => (
                    <Button
                      key={btn}
                      variant="outline"
                      className="border-slate-600 text-white hover:bg-slate-700 h-12 text-lg font-mono"
                      onClick={() => {
                        if (btn === "C") {
                          setCalcExpression("");
                          setCalcResult(null);
                        } else if (btn === "=") {
                          doCalculate();
                        } else {
                          setCalcExpression(prev => prev + btn);
                        }
                      }}
                    >
                      {btn}
                    </Button>
                  ))}
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* World Clock Tab */}
          <TabsContent value="time" className="mt-4">
            <Card className="border-fuchsia-500/20 bg-black/40 backdrop-blur-lg shadow-xl">
              <CardHeader>
                <CardTitle className="text-xl font-bold text-white flex items-center gap-2">
                  <Clock className="h-5 w-5 text-fuchsia-400" />
                  World Clock
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid gap-3 md:grid-cols-2 lg:grid-cols-4">
                  {timezones.map((tz) => (
                    <div
                      key={tz.tz}
                      className="rounded-lg border border-slate-700 bg-slate-800/50 p-4 text-center"
                    >
                      <p className="text-sm text-slate-400">{tz.name}</p>
                      <p className="text-2xl font-bold text-white mt-1">{getTimeInZone(tz.tz)}</p>
                      <p className="text-xs text-slate-500 mt-1">{getDateInZone(tz.tz)}</p>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

