import { useEffect, useRef, useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Mic, MicOff, Volume2, Loader2, Phone, PhoneOff, Wrench, Navigation, Settings, VolumeX } from "lucide-react";
import { showError, showSuccess } from "@/utils/toast";
import { usePreferences } from "../state/preferences";
import { useAuth } from "@/contexts/AuthContext";
import { useOpenAIKey } from "@/hooks/useOpenAIKey";
import { transcribeAudio, synthesizeSpeech } from "../services/openai-voice";
import { DEMO_MODE_SENTINEL_KEY } from "@/services/demo-mode";
import { proxyChat } from "@/services/ai-proxy";
import { useVoiceRecorder } from "../hooks/useVoiceRecorder";
import { buildSystemPrompt, parseToolCalls, executeTool, ActionResult } from "@/services/orchestrator";
import { getLocationContext, LocationContext } from "@/services/context";
import { normalizeSpeechInput } from "@/services/conversation-manager";
import { generateMorningBriefing, configureVoiceNotifications } from "@/services/voice-notifications";
import { supabase } from "@/integrations/supabase/client";
import VoiceCommandExamples from "@/components/VoiceCommandExamples";
import VoiceHistory, { saveVoiceInteraction } from "@/components/VoiceHistory";
import QuietModeControl from "@/components/QuietModeControl";
import type { Message } from "../types/models";

type ConversationState = "idle" | "listening" | "processing" | "speaking";

// Direct OpenAI chat function for voice
async function chatWithOpenAITools(
  messages: { role: string; content: string }[],
  apiKey: string
): Promise<string> {
  // Demo Mode: server-side proxy (no client key)
  if (apiKey === DEMO_MODE_SENTINEL_KEY) {
    const res = await proxyChat({
      model: 'gpt-4o-mini',
      messages: messages.map(m => ({
        role: m.role === 'system' || m.role === 'assistant' ? m.role : 'user',
        content: m.content,
      })),
      max_tokens: 1024,
    });
    return res.content;
  }

  const response = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: "gpt-4o-mini",
      messages,
      max_tokens: 1024,
    }),
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`OpenAI API error: ${error}`);
  }

  const data = await response.json();
  return data.choices[0].message.content;
}

export default function VoiceChat() {
  const navigate = useNavigate();
  const { preferences } = usePreferences();
  const { user } = useAuth();
  const { apiKey: openaiApiKey, hasKey: hasOpenAIKey } = useOpenAIKey();
  const [conversationState, setConversationState] = useState<ConversationState>("idle");
  const [messages, setMessages] = useState<Message[]>([]);
  const [currentTranscript, setCurrentTranscript] = useState("");
  const [isConversationActive, setIsConversationActive] = useState(false);
  const [lastToolsUsed, setLastToolsUsed] = useState<string[]>([]);
  const [isMuted, setIsMuted] = useState(false);
  const [pendingNavigation, setPendingNavigation] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const [userLocation, setUserLocation] = useState<LocationContext | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Try to get user location on mount
  useEffect(() => {
    getLocationContext().then(loc => {
      if (loc) setUserLocation(loc);
    }).catch(() => {
      // Location not available
    });
  }, []);

  // Configure voice notifications
  useEffect(() => {
    if (openaiApiKey) {
      configureVoiceNotifications({
        apiKey: openaiApiKey,
        voice: preferences.openaiVoice,
        enabled: true,
      });
    }
  }, [openaiApiKey, preferences.openaiVoice]);

  // Morning briefing function
  const playMorningBriefing = async () => {
    if (!openaiApiKey || !user) {
      showError("Please set your OpenAI API key in Settings");
      return;
    }

    setConversationState("processing");
    try {
      const briefing = await generateMorningBriefing(user.id, supabase);
      
      const assistantMessage: Message = {
        id: crypto.randomUUID(),
        role: "assistant",
        content: briefing,
        createdAt: Date.now(),
      };
      setMessages((prev) => [...prev, assistantMessage]);

      if (!isMuted) {
        setConversationState("speaking");
        await speakText(briefing);
      }

      if (isConversationActive && preferences.conversationMode) {
        startListening();
      } else {
        setConversationState("idle");
      }
    } catch (err: any) {
      showError(err.message || "Failed to generate briefing");
      setConversationState("idle");
    }
  };

  // Speak text with proper error handling
  const speakText = async (text: string): Promise<void> => {
    if (!openaiApiKey || !text.trim()) return;

    try {
      console.log("Synthesizing speech for:", text.substring(0, 50) + "...");
      const speechBlob = await synthesizeSpeech(text, openaiApiKey, preferences.openaiVoice || "nova");
      
      if (speechBlob.size === 0) {
        console.error("Empty speech blob received");
        return;
      }

      console.log("Speech blob size:", speechBlob.size);
      
      const audio = new Audio();
      audioRef.current = audio;
      const audioUrl = URL.createObjectURL(speechBlob);
      audio.src = audioUrl;
      audio.volume = 1.0;
      
      await new Promise<void>((resolve, reject) => {
        const cleanup = () => {
          URL.revokeObjectURL(audioUrl);
          if (audioRef.current === audio) {
            audioRef.current = null;
          }
        };

        audio.onended = () => {
          console.log("Audio playback ended");
          cleanup();
          resolve();
        };
        
        audio.onerror = (e) => {
          console.error("Audio playback error:", e);
          cleanup();
          reject(new Error("Audio playback failed"));
        };

        audio.oncanplaythrough = () => {
          console.log("Audio ready, starting playback");
          audio.play().catch((err) => {
            console.error("Play failed:", err);
            cleanup();
            reject(err);
          });
        };

        // Fallback timeout
        setTimeout(() => {
          if (audio.readyState >= 3) {
            audio.play().catch(reject);
          }
        }, 100);
      });
    } catch (err) {
      console.error("Speech synthesis error:", err);
    }
  };

  // Handle pending navigation after speaking
  useEffect(() => {
    if (pendingNavigation && conversationState === "idle") {
      const timer = setTimeout(() => {
        navigate(pendingNavigation);
        setPendingNavigation(null);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [pendingNavigation, conversationState, navigate]);

  const handleSilenceDetected = useCallback(() => {
    if (conversationState === "listening") {
      stopRecording();
    }
  }, [conversationState]);

  const { isRecording, audioBlob, startRecording, stopRecording, error: recorderError } = useVoiceRecorder({
    silenceThreshold: preferences.silenceThreshold,
    silenceTimeout: preferences.silenceTimeout,
    onSilenceDetected: preferences.conversationMode ? handleSilenceDetected : undefined,
  });

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  useEffect(() => {
    if (audioBlob && conversationState === "listening") {
      processAudio(audioBlob);
    }
  }, [audioBlob]);

  const stopCurrentAudio = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
      if (audioRef.current.src) {
        URL.revokeObjectURL(audioRef.current.src);
      }
      audioRef.current = null;
    }
  };

  const processAudio = async (blob: Blob) => {
    if (!openaiApiKey) {
      showError("Please set your OpenAI API key in Settings");
      setConversationState("idle");
      return;
    }

    setConversationState("processing");
    setLastToolsUsed([]);

    try {
      console.log("Transcribing audio, blob size:", blob.size);
      const transcription = await transcribeAudio(blob, openaiApiKey);
      let userText = transcription.text.trim();

      console.log("Transcription result:", userText);

      if (!userText) {
        if (isConversationActive && preferences.conversationMode) {
          startListening();
        } else {
          setConversationState("idle");
        }
        return;
      }

      // Normalize speech input for better understanding
      const normalizedText = normalizeSpeechInput(userText);
      setCurrentTranscript(userText);

      const userMessage: Message = {
        id: crypto.randomUUID(),
        role: "user",
        content: userText,
        createdAt: Date.now(),
      };
      setMessages((prev) => [...prev, userMessage]);

      // Build messages with system prompt for tool usage (location-aware)
      const systemPrompt = buildSystemPrompt(userLocation ? {
        lat: userLocation.lat,
        lng: userLocation.lng,
        city: userLocation.city,
      } : undefined);
      const chatMessages = [
        { role: "system", content: systemPrompt },
        ...messages.slice(-10).map((m) => ({ role: m.role, content: m.content })),
        { role: "user", content: normalizedText },
      ];

      let response = await chatWithOpenAITools(chatMessages, openaiApiKey);

      // Check for tool calls and execute them
      const toolCalls = parseToolCalls(response);
      let toolResults: ActionResult[] = [];
      let navigationPath: string | null = null;

      if (toolCalls.length > 0 && user) {
        for (const toolCall of toolCalls) {
          const result = await executeTool(user.id, toolCall);
          toolResults.push(result);

          // Check for navigation
          if (toolCall.tool === "navigate_to" && result.success && result.data?.path) {
            navigationPath = result.data.path;
          }
        }

        setLastToolsUsed(toolResults.map(r => r.tool));

        // Get a follow-up response summarizing what was done
        if (toolResults.length > 0) {
          const toolResultsText = toolResults.map(r => {
            if (r.tool === "navigate_to") {
              return `Navigation: ${r.success ? `Going to ${r.data?.description}` : r.error}`;
            }
            if (r.data?.voiceText) {
              return `Tool: ${r.tool}\nResult: ${r.data.voiceText}`;
            }
            return `Tool: ${r.tool}\nSuccess: ${r.success}\n${r.success ? `Result: ${JSON.stringify(r.data, null, 2)}` : `Error: ${r.error}`}`;
          }).join("\n\n");

          const followUpMessages = [
            ...chatMessages,
            { role: "assistant", content: response },
            { role: "user", content: `Tool execution results:\n${toolResultsText}\n\nProvide a BRIEF, conversational voice response (1-2 sentences max). If there's voice text in the results, use that. Don't repeat JSON or technical details.` },
          ];

          response = await chatWithOpenAITools(followUpMessages, openaiApiKey);
        }
      }

      // Clean response for speech (remove JSON blocks and markdown)
      let cleanResponse = response
        .replace(/```json[\s\S]*?```/g, '')
        .replace(/```[\s\S]*?```/g, '')
        .replace(/\*\*/g, '')
        .replace(/\*/g, '')
        .replace(/#{1,6}\s/g, '')
        .trim();

      // If we have voice text from tools, prefer that
      const voiceTextResult = toolResults.find(r => r.data?.voiceText);
      if (voiceTextResult?.data?.voiceText) {
        cleanResponse = voiceTextResult.data.voiceText;
      }

      const assistantMessage: Message = {
        id: crypto.randomUUID(),
        role: "assistant",
        content: cleanResponse,
        toolCall: toolResults.length > 0 ? {
          type: "orchestrator",
          input: toolCalls.map(t => t.tool).join(", "),
          outputMeta: { tools: toolResults.map(r => ({ tool: r.tool, success: r.success })) }
        } : undefined,
        createdAt: Date.now(),
      };
      setMessages((prev) => [...prev, assistantMessage]);

      // Speak the response (unless muted)
      if (!isMuted) {
        setConversationState("speaking");
        await speakText(cleanResponse);
      }

      // Save to voice history
      saveVoiceInteraction({
        userText: userText,
        assistantText: cleanResponse,
        timestamp: Date.now(),
        toolsUsed: toolResults.map(r => r.tool),
      });

      // Show success toast for tool actions
      if (toolResults.length > 0) {
        const successCount = toolResults.filter(r => r.success).length;
        if (successCount > 0) {
          showSuccess(`Completed ${successCount} action${successCount > 1 ? 's' : ''}`);
        }
      }

      // Handle navigation after speaking
      if (navigationPath) {
        setPendingNavigation(navigationPath);
      }

      if (isConversationActive && preferences.conversationMode && !navigationPath) {
        startListening();
      } else {
        setConversationState("idle");
      }
    } catch (err: any) {
      console.error("Voice processing error:", err);
      showError(err.message || "Voice processing failed");
      setConversationState("idle");
    }
  };

  const startListening = async () => {
    setCurrentTranscript("");
    setConversationState("listening");
    await startRecording();
  };

  const startConversation = async () => {
    if (!openaiApiKey) {
      showError("Please set your OpenAI API key in Settings");
      return;
    }
    setIsConversationActive(true);
    await startListening();
  };

  const endConversation = () => {
    setIsConversationActive(false);
    stopRecording();
    stopCurrentAudio();
    setConversationState("idle");
  };

  const toggleListening = async () => {
    if (conversationState === "listening") {
      stopRecording();
    } else if (conversationState === "idle") {
      await startListening();
    } else if (conversationState === "speaking") {
      // Stop speaking and start listening
      stopCurrentAudio();
      await startListening();
    }
  };

  const toggleMute = () => {
    if (!isMuted && conversationState === "speaking") {
      stopCurrentAudio();
      setConversationState("idle");
    }
    setIsMuted(!isMuted);
  };

  const clearMessages = () => {
    setMessages([]);
    showSuccess("Conversation cleared");
  };

  const getStateIcon = () => {
    switch (conversationState) {
      case "listening":
        return <Mic className="h-12 w-12 animate-pulse" />;
      case "processing":
        return <Loader2 className="h-12 w-12 animate-spin" />;
      case "speaking":
        return <Volume2 className="h-12 w-12 animate-pulse" />;
      default:
        return <MicOff className="h-12 w-12" />;
    }
  };

  const getStateText = () => {
    switch (conversationState) {
      case "listening":
        return "Listening...";
      case "processing":
        return "Thinking...";
      case "speaking":
        return "Speaking...";
      default:
        return "Ready";
    }
  };

  const getStateColor = () => {
    switch (conversationState) {
      case "listening":
        return "from-fuchsia-500 to-purple-600";
      case "processing":
        return "from-blue-500 to-cyan-600";
      case "speaking":
        return "from-green-500 to-emerald-600";
      default:
        return "from-slate-600 to-slate-700";
    }
  };

  return (
    <div className="min-h-[calc(100vh-56px)] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-4">
      <div className="mx-auto max-w-2xl flex flex-col h-[calc(100vh-88px)]">
        <Card className="flex-1 border-fuchsia-500/20 bg-black/40 backdrop-blur-lg shadow-xl flex flex-col">
          <CardContent className="flex-1 flex flex-col p-6">
            {/* Header with controls */}
            <div className="flex justify-between items-center mb-4">
              <div className="flex items-center gap-2">
                <h2 className="text-lg font-semibold text-white">Voice Chat</h2>
                {isConversationActive && (
                  <Badge variant="outline" className="border-green-500 text-green-400 text-xs">
                    Active
                  </Badge>
                )}
              </div>
              <div className="flex items-center gap-2">
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={toggleMute}
                  className={`h-8 w-8 ${isMuted ? 'text-red-400' : 'text-slate-400'} hover:text-white`}
                  title={isMuted ? "Unmute" : "Mute"}
                >
                  {isMuted ? <VolumeX className="h-4 w-4" /> : <Volume2 className="h-4 w-4" />}
                </Button>
                {messages.length > 0 && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={clearMessages}
                    className="border-slate-600 text-slate-300 hover:bg-slate-800"
                  >
                    Clear
                  </Button>
                )}
              </div>
            </div>

            {/* Live Transcript Display */}
            {(conversationState === "listening" || conversationState === "processing") && (
              <div className="mb-4 p-4 rounded-lg bg-slate-800/50 border border-fuchsia-500/30">
                <div className="flex items-center gap-2 mb-2">
                  {conversationState === "listening" ? (
                    <Badge className="bg-red-500/20 text-red-400 border-red-500/50 animate-pulse">
                      <Mic className="h-3 w-3 mr-1" />
                      Listening...
                    </Badge>
                  ) : (
                    <Badge className="bg-yellow-500/20 text-yellow-400 border-yellow-500/50">
                      <Loader2 className="h-3 w-3 mr-1 animate-spin" />
                      Processing...
                    </Badge>
                  )}
                </div>
                {currentTranscript && (
                  <p className="text-white text-sm">
                    <span className="text-slate-400">You said: </span>
                    "{currentTranscript}"
                  </p>
                )}
                {!currentTranscript && conversationState === "listening" && (
                  <p className="text-slate-400 text-sm italic">Speak now...</p>
                )}
              </div>
            )}

            {/* Messages Area */}
            <div className="flex-1 overflow-y-auto space-y-4 mb-6">
              {messages.length === 0 ? (
                <div className="flex flex-col h-full">
                  <div className="flex flex-col items-center justify-center flex-1 text-center">
                    <div className="text-4xl mb-4">≡ƒÄÖ∩╕Å</div>
                    <p className="text-lg text-white mb-2">Voice-First AI Assistant</p>
                    <p className="text-sm text-slate-400 max-w-md mb-2">
                      Speak naturally to Echo. I can navigate the app, read your tasks and reminders, give you daily summaries, and much more.
                    </p>
                    <div className="flex flex-wrap gap-2 justify-center mt-2">
                      <Badge variant="outline" className="border-fuchsia-500/50 text-fuchsia-300 text-xs">
                        <Navigation className="h-3 w-3 mr-1" />
                        "Open my tasks"
                      </Badge>
                      <Badge variant="outline" className="border-fuchsia-500/50 text-fuchsia-300 text-xs">
                        "Read my reminders"
                      </Badge>
                      <Badge variant="outline" className="border-fuchsia-500/50 text-fuchsia-300 text-xs">
                        "Summarize my day"
                      </Badge>
                    </div>
                  </div>
                  <VoiceCommandExamples />
                </div>
              ) : (
                messages.map((m) => (
                  <div
                    key={m.id}
                    className={`max-w-[85%] rounded-2xl px-4 py-3 ${
                      m.role === "user"
                        ? "ml-auto bg-fuchsia-600/40 text-white"
                        : "bg-slate-800 text-slate-100 border border-slate-700"
                    }`}
                  >
                    <div className="flex items-center gap-2 text-[10px] text-slate-400 mb-1">
                      <span>{m.role === "user" ? "You" : "Echo"}</span>
                      <span>ΓÇó</span>
                      <span>{new Date(m.createdAt).toLocaleTimeString()}</span>
                      {m.toolCall && (
                        <>
                          <span>ΓÇó</span>
                          <span className="flex items-center gap-1 text-fuchsia-300">
                            <Wrench className="h-3 w-3" />
                            {m.toolCall.input}
                          </span>
                        </>
                      )}
                    </div>
                    <div className="whitespace-pre-wrap">{m.content}</div>
                  </div>
                ))
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Tools Used Indicator */}
            {lastToolsUsed.length > 0 && conversationState === "processing" && (
              <div className="mb-4 flex items-center gap-2 text-sm text-fuchsia-300">
                <Wrench className="h-4 w-4 animate-spin" />
                <span>Executing: {lastToolsUsed.join(", ")}</span>
              </div>
            )}

            {/* Pending Navigation Indicator */}
            {pendingNavigation && (
              <div className="mb-4 flex items-center gap-2 text-sm text-green-300">
                <Navigation className="h-4 w-4" />
                <span>Navigating to {pendingNavigation}...</span>
              </div>
            )}

            {/* Voice Control Area */}
            <div className="flex flex-col items-center space-y-4">
              {/* State Indicator */}
              <div className="text-center">
                <button
                  onClick={toggleListening}
                  disabled={conversationState === "processing"}
                  className={`w-28 h-28 rounded-full bg-gradient-to-br ${getStateColor()} flex items-center justify-center shadow-2xl transition-all ${
                    conversationState === "listening" ? "ring-4 ring-fuchsia-400/50 scale-110" : ""
                  } ${conversationState !== "processing" ? "hover:scale-105 active:scale-95 cursor-pointer" : "cursor-not-allowed"}`}
                >
                  <div className="text-white">{getStateIcon()}</div>
                </button>
                <p className="mt-3 text-lg font-medium text-white">{getStateText()}</p>
                {conversationState === "speaking" && (
                  <p className="text-xs text-slate-400 mt-1">Tap to interrupt</p>
                )}
              </div>

              {/* Control Buttons */}
              <div className="flex flex-wrap gap-3 justify-center">
                {!isConversationActive ? (
                  <>
                    <Button
                      size="lg"
                      onClick={startConversation}
                      className="bg-fuchsia-600 text-white hover:bg-fuchsia-500 px-6"
                      disabled={conversationState !== "idle"}
                    >
                      <Phone className="mr-2 h-5 w-5" />
                      Start Conversation
                    </Button>
                    <Button
                      size="lg"
                      onClick={toggleListening}
                      variant="outline"
                      className="border-slate-600 text-white hover:bg-slate-700"
                      disabled={conversationState !== "idle"}
                    >
                      <Mic className="mr-2 h-5 w-5" />
                      Push to Talk
                    </Button>
                    <Button
                      size="lg"
                      onClick={playMorningBriefing}
                      variant="outline"
                      className="border-blue-500/50 text-blue-300 hover:bg-blue-500/20"
                      disabled={conversationState !== "idle"}
                    >
                      <Volume2 className="mr-2 h-5 w-5" />
                      Daily Briefing
                    </Button>
                    <QuietModeControl />
                  </>
                ) : (
                  <Button
                    size="lg"
                    onClick={endConversation}
                    variant="destructive"
                    className="px-8"
                  >
                    <PhoneOff className="mr-2 h-5 w-5" />
                    End Conversation
                  </Button>
                )}
              </div>

              {/* Conversation Mode Indicator */}
              {isConversationActive && (
                <p className="text-sm text-fuchsia-300 text-center">
                  Conversation mode active ΓÇó Speak naturally, Echo will respond automatically
                  {isMuted && " ΓÇó Audio muted"}
                </p>
              )}

              {/* Quick Tips */}
              {!isConversationActive && conversationState === "idle" && (
                <div className="text-center text-xs text-slate-500 max-w-md">
                  <p>Try: "Open my tasks" ΓÇó "Read my reminders" ΓÇó "What's on my calendar?" ΓÇó "Summarize my day"</p>
                </div>
              )}

              {recorderError && (
                <p className="text-sm text-red-400">{recorderError}</p>
              )}
            </div>
          </CardContent>
        </Card>
        
        {/* Voice History */}
        {messages.length === 0 && (
          <VoiceHistory maxItems={3} showClear={false} className="mt-4" />
        )}
      </div>
    </div>
  );
}

// Server-only helpers for Vercel Functions under /api/ai/*
// NOTE: Do not import this from client/browser code.

export type SupabaseAuthUser = {
  id: string;
  email?: string;
};

export type SupabaseEnv = {
  url: string;
  anonKey: string;
};

export function getSupabaseEnv(): { env: SupabaseEnv | null; missing: string[] } {
  // Support both server-style and existing VITE_ prefixed env vars.
  // In Vercel, both are available to serverless functions if configured.
  const url = process.env.SUPABASE_URL || process.env.VITE_SUPABASE_URL || '';
  const anonKey = process.env.SUPABASE_ANON_KEY || process.env.VITE_SUPABASE_ANON_KEY || '';

  const missing: string[] = [];
  if (!url) missing.push('SUPABASE_URL (or VITE_SUPABASE_URL)');
  if (!anonKey) missing.push('SUPABASE_ANON_KEY (or VITE_SUPABASE_ANON_KEY)');

  if (!url || !anonKey) {
    return { env: null, missing };
  }

  return { env: { url, anonKey }, missing: [] };
}

export function getOpenAIEnv(): { apiKey: string | null } {
  const apiKey = process.env.OPENAI_API_KEY || '';
  return { apiKey: apiKey ? apiKey : null };
}

export function getBearerToken(req: any): string | null {
  const header = (req?.headers?.authorization || req?.headers?.Authorization || '') as string;
  if (!header) return null;

  const match = header.match(/^Bearer\s+(.+)$/i);
  if (!match) return null;

  const token = match[1]?.trim();
  return token ? token : null;
}

export async function verifySupabaseJwt(token: string): Promise<SupabaseAuthUser | null> {
  const { env } = getSupabaseEnv();
  if (!env) return null;

  // Validate token by calling Supabase Auth user endpoint.
  // This does not require service role key; anon key is sufficient.
  const url = `${env.url.replace(/\/$/, '')}/auth/v1/user`;

  const resp = await fetch(url, {
    method: 'GET',
    headers: {
      apikey: env.anonKey,
      Authorization: `Bearer ${token}`,
    },
  });

  if (!resp.ok) {
    return null;
  }

  const data: any = await resp.json();
  if (!data?.id) return null;

  return { id: data.id, email: data.email };
}

export function sendJson(res: any, status: number, body: any): void {
  res.statusCode = status;
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store');
  res.end(JSON.stringify(body));
}

export function sendText(res: any, status: number, text: string): void {
  res.statusCode = status;
  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store');
  res.end(text);
}

export async function readBody(req: any, maxBytes: number): Promise<Buffer> {
  const chunks: Buffer[] = [];
  let total = 0;

  for await (const chunk of req) {
    const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    total += buf.length;
    if (total > maxBytes) {
      throw new Error(`Request body too large (>${maxBytes} bytes)`);
    }
    chunks.push(buf);
  }

  return Buffer.concat(chunks);
}

export async function readJson(req: any, maxBytes: number): Promise<any> {
  const body = await readBody(req, maxBytes);
  if (!body.length) return null;

  try {
    return JSON.parse(body.toString('utf-8'));
  } catch {
    throw new Error('Invalid JSON');
  }
}

export function clampNumber(n: any, min: number, max: number, fallback: number): number {
  const num = typeof n === 'number' ? n : Number(n);
  if (!Number.isFinite(num)) return fallback;
  return Math.min(max, Math.max(min, num));
}

export function truncateString(s: any, maxLen: number): string {
  const str = typeof s === 'string' ? s : '';
  if (str.length <= maxLen) return str;
  return str.slice(0, maxLen);
}

"use client";

// A/B Testing Framework
// Enables feature experimentation and optimization

interface Experiment {
  id: string;
  name: string;
  description: string;
  variants: Variant[];
  status: 'draft' | 'running' | 'paused' | 'completed';
  startDate?: number;
  endDate?: number;
  targetPercentage: number;
  metrics: string[];
  results?: ExperimentResults;
}

interface Variant {
  id: string;
  name: string;
  weight: number; // 0-100, must sum to 100 across all variants
  config: Record<string, any>;
}

interface ExperimentResults {
  totalParticipants: number;
  variantResults: Record<string, VariantResult>;
  winner?: string;
  confidence: number;
}

interface VariantResult {
  participants: number;
  conversions: number;
  conversionRate: number;
  metrics: Record<string, number>;
}

interface UserAssignment {
  experimentId: string;
  variantId: string;
  assignedAt: number;
}

class ABTestingService {
  private experiments: Map<string, Experiment> = new Map();
  private userAssignments: Map<string, UserAssignment[]> = new Map();
  private conversions: Map<string, { experimentId: string; variantId: string; metric: string; value: number; timestamp: number }[]> = new Map();
  private userId: string = '';

  initialize(userId: string): void {
    this.userId = userId;
    this.loadAssignments();
    console.log('[ab-testing] Initialized for user:', userId);
  }

  private loadAssignments(): void {
    try {
      const stored = localStorage.getItem(`ab_assignments_${this.userId}`);
      if (stored) {
        const assignments = JSON.parse(stored);
        this.userAssignments.set(this.userId, assignments);
      }
    } catch (error) {
      console.error('[ab-testing] Failed to load assignments:', error);
    }
  }

  private saveAssignments(): void {
    try {
      const assignments = this.userAssignments.get(this.userId) || [];
      localStorage.setItem(`ab_assignments_${this.userId}`, JSON.stringify(assignments));
    } catch (error) {
      console.error('[ab-testing] Failed to save assignments:', error);
    }
  }

  createExperiment(experiment: Omit<Experiment, 'status' | 'results'>): Experiment {
    const newExperiment: Experiment = {
      ...experiment,
      status: 'draft'
    };
    
    // Validate variant weights sum to 100
    const totalWeight = experiment.variants.reduce((sum, v) => sum + v.weight, 0);
    if (totalWeight !== 100) {
      throw new Error('Variant weights must sum to 100');
    }
    
    this.experiments.set(experiment.id, newExperiment);
    console.log('[ab-testing] Created experiment:', experiment.name);
    
    return newExperiment;
  }

  startExperiment(experimentId: string): void {
    const experiment = this.experiments.get(experimentId);
    if (!experiment) {
      throw new Error(`Experiment ${experimentId} not found`);
    }
    
    experiment.status = 'running';
    experiment.startDate = Date.now();
    
    console.log('[ab-testing] Started experiment:', experiment.name);
  }

  pauseExperiment(experimentId: string): void {
    const experiment = this.experiments.get(experimentId);
    if (!experiment) return;
    
    experiment.status = 'paused';
    console.log('[ab-testing] Paused experiment:', experiment.name);
  }

  completeExperiment(experimentId: string): void {
    const experiment = this.experiments.get(experimentId);
    if (!experiment) return;
    
    experiment.status = 'completed';
    experiment.endDate = Date.now();
    experiment.results = this.calculateResults(experimentId);
    
    console.log('[ab-testing] Completed experiment:', experiment.name);
  }

  getVariant(experimentId: string): Variant | null {
    const experiment = this.experiments.get(experimentId);
    if (!experiment || experiment.status !== 'running') {
      return null;
    }
    
    // Check if user is already assigned
    const assignments = this.userAssignments.get(this.userId) || [];
    const existingAssignment = assignments.find(a => a.experimentId === experimentId);
    
    if (existingAssignment) {
      return experiment.variants.find(v => v.id === existingAssignment.variantId) || null;
    }
    
    // Check if user should be in experiment (based on target percentage)
    const userHash = this.hashUserId(this.userId + experimentId);
    if (userHash > experiment.targetPercentage) {
      return null; // User not in experiment
    }
    
    // Assign user to variant based on weights
    const variant = this.selectVariant(experiment.variants, userHash);
    
    // Save assignment
    assignments.push({
      experimentId,
      variantId: variant.id,
      assignedAt: Date.now()
    });
    this.userAssignments.set(this.userId, assignments);
    this.saveAssignments();
    
    console.log('[ab-testing] Assigned user to variant:', variant.name);
    
    return variant;
  }

  private hashUserId(input: string): number {
    let hash = 0;
    for (let i = 0; i < input.length; i++) {
      const char = input.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash;
    }
    return Math.abs(hash % 100);
  }

  private selectVariant(variants: Variant[], hash: number): Variant {
    let cumulative = 0;
    const normalizedHash = hash % 100;
    
    for (const variant of variants) {
      cumulative += variant.weight;
      if (normalizedHash < cumulative) {
        return variant;
      }
    }
    
    return variants[variants.length - 1];
  }

  trackConversion(experimentId: string, metric: string, value: number = 1): void {
    const assignments = this.userAssignments.get(this.userId) || [];
    const assignment = assignments.find(a => a.experimentId === experimentId);
    
    if (!assignment) {
      console.log('[ab-testing] User not in experiment, skipping conversion');
      return;
    }
    
    const userConversions = this.conversions.get(this.userId) || [];
    userConversions.push({
      experimentId,
      variantId: assignment.variantId,
      metric,
      value,
      timestamp: Date.now()
    });
    this.conversions.set(this.userId, userConversions);
    
    console.log('[ab-testing] Tracked conversion:', { experimentId, metric, value });
  }

  private calculateResults(experimentId: string): ExperimentResults {
    const experiment = this.experiments.get(experimentId);
    if (!experiment) {
      return { totalParticipants: 0, variantResults: {}, confidence: 0 };
    }
    
    const variantResults: Record<string, VariantResult> = {};
    let totalParticipants = 0;
    
    // Initialize results for each variant
    experiment.variants.forEach(variant => {
      variantResults[variant.id] = {
        participants: 0,
        conversions: 0,
        conversionRate: 0,
        metrics: {}
      };
    });
    
    // Count participants and conversions
    this.userAssignments.forEach((assignments, userId) => {
      const assignment = assignments.find(a => a.experimentId === experimentId);
      if (assignment) {
        totalParticipants++;
        variantResults[assignment.variantId].participants++;
        
        // Count conversions
        const userConversions = this.conversions.get(userId) || [];
        const experimentConversions = userConversions.filter(c => c.experimentId === experimentId);
        
        if (experimentConversions.length > 0) {
          variantResults[assignment.variantId].conversions++;
          
          // Aggregate metrics
          experimentConversions.forEach(c => {
            const current = variantResults[assignment.variantId].metrics[c.metric] || 0;
            variantResults[assignment.variantId].metrics[c.metric] = current + c.value;
          });
        }
      }
    });
    
    // Calculate conversion rates
    Object.values(variantResults).forEach(result => {
      result.conversionRate = result.participants > 0 
        ? (result.conversions / result.participants) * 100 
        : 0;
    });
    
    // Determine winner (simple comparison for now)
    let winner: string | undefined;
    let highestRate = 0;
    
    Object.entries(variantResults).forEach(([variantId, result]) => {
      if (result.conversionRate > highestRate) {
        highestRate = result.conversionRate;
        winner = variantId;
      }
    });
    
    // Calculate confidence (simplified)
    const confidence = totalParticipants > 100 ? 95 : totalParticipants > 50 ? 80 : 60;
    
    return {
      totalParticipants,
      variantResults,
      winner,
      confidence
    };
  }

  getExperiment(experimentId: string): Experiment | undefined {
    return this.experiments.get(experimentId);
  }

  getAllExperiments(): Experiment[] {
    return Array.from(this.experiments.values());
  }

  getRunningExperiments(): Experiment[] {
    return this.getAllExperiments().filter(e => e.status === 'running');
  }

  // Pre-built experiments for Echo
  setupDefaultExperiments(): void {
    // Voice UI experiment
    this.createExperiment({
      id: 'voice-ui-style',
      name: 'Voice UI Style',
      description: 'Test different voice button styles',
      variants: [
        { id: 'control', name: 'Current Design', weight: 50, config: { style: 'current' } },
        { id: 'minimal', name: 'Minimal Design', weight: 50, config: { style: 'minimal' } }
      ],
      targetPercentage: 100,
      metrics: ['voice_activation', 'session_duration', 'task_completion']
    });
    
    // Onboarding flow experiment
    this.createExperiment({
      id: 'onboarding-flow',
      name: 'Onboarding Flow',
      description: 'Test different onboarding experiences',
      variants: [
        { id: 'guided', name: 'Guided Tour', weight: 33, config: { type: 'guided' } },
        { id: 'video', name: 'Video Tutorial', weight: 33, config: { type: 'video' } },
        { id: 'interactive', name: 'Interactive Demo', weight: 34, config: { type: 'interactive' } }
      ],
      targetPercentage: 100,
      metrics: ['onboarding_completion', 'first_task_created', 'day_7_retention']
    });
    
    // Widget layout experiment
    this.createExperiment({
      id: 'widget-layout',
      name: 'Widget Layout',
      description: 'Test different default widget layouts',
      variants: [
        { id: 'compact', name: 'Compact Layout', weight: 50, config: { layout: 'compact' } },
        { id: 'spacious', name: 'Spacious Layout', weight: 50, config: { layout: 'spacious' } }
      ],
      targetPercentage: 50,
      metrics: ['widget_interactions', 'customization_rate', 'satisfaction_score']
    });
    
    console.log('[ab-testing] Default experiments created');
  }
}

export const abTesting = new ABTestingService();

