import { supabase } from "@/integrations/supabase/client";

export interface ActionRecord {
  id: string;
  userId: string;
  actionType: "create" | "update" | "delete" | "complete";
  entityType: "task" | "reminder" | "note" | "calendar_event" | "contact";
  entityId: string;
  previousState: any;
  newState: any;
  canUndo: boolean;
  undone: boolean;
  createdAt: Date;
}

// In-memory cache for recent actions (for quick undo)
const recentActions: ActionRecord[] = [];
const MAX_CACHED_ACTIONS = 20;

/**
 * Record an action for potential undo
 */
export async function recordAction(
  userId: string,
  actionType: ActionRecord["actionType"],
  entityType: ActionRecord["entityType"],
  entityId: string,
  previousState: any,
  newState: any
): Promise<ActionRecord | null> {
  try {
    const { data, error } = await supabase
      .from("action_history")
      .insert({
        user_id: userId,
        action_type: actionType,
        entity_type: entityType,
        entity_id: entityId,
        previous_state: previousState,
        new_state: newState,
        can_undo: true,
        undone: false,
      })
      .select()
      .single();

    if (error) throw error;

    const record: ActionRecord = {
      id: data.id,
      userId: data.user_id,
      actionType: data.action_type,
      entityType: data.entity_type,
      entityId: data.entity_id,
      previousState: data.previous_state,
      newState: data.new_state,
      canUndo: data.can_undo,
      undone: data.undone,
      createdAt: new Date(data.created_at),
    };

    // Add to cache
    recentActions.unshift(record);
    if (recentActions.length > MAX_CACHED_ACTIONS) {
      recentActions.pop();
    }

    return record;
  } catch (error) {
    console.error("Failed to record action:", error);
    return null;
  }
}

/**
 * Get the last undoable action
 */
export async function getLastUndoableAction(userId: string): Promise<ActionRecord | null> {
  // Check cache first
  const cachedAction = recentActions.find(
    a => a.userId === userId && a.canUndo && !a.undone
  );
  if (cachedAction) return cachedAction;

  try {
    const { data, error } = await supabase
      .from("action_history")
      .select("*")
      .eq("user_id", userId)
      .eq("can_undo", true)
      .eq("undone", false)
      .order("created_at", { ascending: false })
      .limit(1)
      .single();

    if (error || !data) return null;

    return {
      id: data.id,
      userId: data.user_id,
      actionType: data.action_type,
      entityType: data.entity_type,
      entityId: data.entity_id,
      previousState: data.previous_state,
      newState: data.new_state,
      canUndo: data.can_undo,
      undone: data.undone,
      createdAt: new Date(data.created_at),
    };
  } catch (error) {
    console.error("Failed to get last action:", error);
    return null;
  }
}

/**
 * Undo the last action
 */
export async function undoLastAction(userId: string): Promise<{
  success: boolean;
  message: string;
  action?: ActionRecord;
}> {
  const lastAction = await getLastUndoableAction(userId);

  if (!lastAction) {
    return { success: false, message: "Nothing to undo" };
  }

  // Check if action is too old (more than 5 minutes)
  const fiveMinutesAgo = new Date(Date.now() - 5 * 60 * 1000);
  if (lastAction.createdAt < fiveMinutesAgo) {
    return { success: false, message: "This action is too old to undo" };
  }

  try {
    const tableName = getTableName(lastAction.entityType);

    switch (lastAction.actionType) {
      case "create":
        // Delete the created entity
        await supabase
          .from(tableName)
          .delete()
          .eq("id", lastAction.entityId)
          .eq("user_id", userId);
        break;

      case "update":
      case "complete":
        // Restore previous state
        await supabase
          .from(tableName)
          .update(lastAction.previousState)
          .eq("id", lastAction.entityId)
          .eq("user_id", userId);
        break;

      case "delete":
        // Re-create the deleted entity
        const { id, ...restOfState } = lastAction.previousState;
        await supabase
          .from(tableName)
          .insert({ ...restOfState, user_id: userId });
        break;
    }

    // Mark action as undone
    await supabase
      .from("action_history")
      .update({ undone: true })
      .eq("id", lastAction.id);

    // Update cache
    const cachedIndex = recentActions.findIndex(a => a.id === lastAction.id);
    if (cachedIndex !== -1) {
      recentActions[cachedIndex].undone = true;
    }

    const actionDescription = getActionDescription(lastAction);
    return {
      success: true,
      message: `Undone: ${actionDescription}`,
      action: lastAction,
    };
  } catch (error: any) {
    console.error("Failed to undo action:", error);
    return { success: false, message: `Failed to undo: ${error.message}` };
  }
}

/**
 * Get recent actions for a user
 */
export async function getRecentActions(
  userId: string,
  limit: number = 10
): Promise<ActionRecord[]> {
  try {
    const { data, error } = await supabase
      .from("action_history")
      .select("*")
      .eq("user_id", userId)
      .order("created_at", { ascending: false })
      .limit(limit);

    if (error) throw error;

    return (data || []).map(d => ({
      id: d.id,
      userId: d.user_id,
      actionType: d.action_type,
      entityType: d.entity_type,
      entityId: d.entity_id,
      previousState: d.previous_state,
      newState: d.new_state,
      canUndo: d.can_undo,
      undone: d.undone,
      createdAt: new Date(d.created_at),
    }));
  } catch (error) {
    console.error("Failed to get recent actions:", error);
    return [];
  }
}

// Helper functions
function getTableName(entityType: ActionRecord["entityType"]): string {
  const tableMap: Record<string, string> = {
    task: "tasks",
    reminder: "reminders",
    note: "notes",
    calendar_event: "calendar_events",
    contact: "contacts",
  };
  return tableMap[entityType] || entityType;
}

function getActionDescription(action: ActionRecord): string {
  const entityName = action.newState?.title || action.newState?.text || action.newState?.name || action.entityType;
  
  switch (action.actionType) {
    case "create":
      return `Created ${action.entityType} "${entityName}"`;
    case "update":
      return `Updated ${action.entityType} "${entityName}"`;
    case "delete":
      return `Deleted ${action.entityType} "${entityName}"`;
    case "complete":
      return `Completed ${action.entityType} "${entityName}"`;
    default:
      return `${action.actionType} ${action.entityType}`;
  }
}

/**
 * Clear old action history (older than 24 hours)
 */
export async function cleanupOldActions(userId: string): Promise<void> {
  const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);

  try {
    await supabase
      .from("action_history")
      .delete()
      .eq("user_id", userId)
      .lt("created_at", oneDayAgo.toISOString());
  } catch (error) {
    console.error("Failed to cleanup old actions:", error);
  }
}

/**
 * Advanced Analytics Service
 * Real-time performance dashboards and user behavior insights
 */

import { logger } from '@/utils/logger';

interface AnalyticsEvent {
  name: string;
  category: string;
  timestamp: number;
  properties: Record<string, any>;
  userId?: string;
  sessionId: string;
}

interface UserSession {
  id: string;
  startTime: number;
  endTime?: number;
  events: AnalyticsEvent[];
  pageViews: string[];
  voiceCommands: number;
  toolsUsed: string[];
}

interface AnalyticsInsight {
  type: 'trend' | 'anomaly' | 'recommendation';
  title: string;
  description: string;
  metric: string;
  value: number;
  change?: number;
  timestamp: number;
}

class AdvancedAnalyticsService {
  private events: AnalyticsEvent[] = [];
  private sessions: Map<string, UserSession> = new Map();
  private currentSessionId: string;
  private insights: AnalyticsInsight[] = [];
  private maxEvents = 10000;

  constructor() {
    this.currentSessionId = this.generateSessionId();
    this.startSession();
  }

  /**
   * Generate unique session ID
   */
  private generateSessionId(): string {
    return `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Start new session
   */
  private startSession(): void {
    const session: UserSession = {
      id: this.currentSessionId,
      startTime: Date.now(),
      events: [],
      pageViews: [],
      voiceCommands: 0,
      toolsUsed: [],
    };
    this.sessions.set(this.currentSessionId, session);
  }

  /**
   * Track event
   */
  track(
    name: string,
    category: string,
    properties: Record<string, any> = {},
    userId?: string
  ): void {
    const event: AnalyticsEvent = {
      name,
      category,
      timestamp: Date.now(),
      properties,
      userId,
      sessionId: this.currentSessionId,
    };

    this.events.push(event);

    // Update session
    const session = this.sessions.get(this.currentSessionId);
    if (session) {
      session.events.push(event);
      
      if (category === 'voice') {
        session.voiceCommands++;
      }
      
      if (category === 'tool' && properties.toolName) {
        if (!session.toolsUsed.includes(properties.toolName)) {
          session.toolsUsed.push(properties.toolName);
        }
      }
      
      if (category === 'navigation' && properties.page) {
        session.pageViews.push(properties.page);
      }
    }

    // Trim old events
    if (this.events.length > this.maxEvents) {
      this.events = this.events.slice(-this.maxEvents);
    }

    // Check for anomalies
    this.detectAnomalies(event);
  }

  /**
   * Track page view
   */
  trackPageView(page: string, userId?: string): void {
    this.track('page_view', 'navigation', { page }, userId);
  }

  /**
   * Track voice command
   */
  trackVoiceCommand(command: string, success: boolean, duration: number, userId?: string): void {
    this.track('voice_command', 'voice', { command, success, duration }, userId);
  }

  /**
   * Track tool usage
   */
  trackToolUsage(toolName: string, success: boolean, duration: number, userId?: string): void {
    this.track('tool_usage', 'tool', { toolName, success, duration }, userId);
  }

  /**
   * Detect anomalies in events
   */
  private detectAnomalies(event: AnalyticsEvent): void {
    // Check for error spikes
    const recentErrors = this.events
      .filter(e => e.timestamp > Date.now() - 60000 && e.properties.error)
      .length;

    if (recentErrors > 10) {
      this.addInsight({
        type: 'anomaly',
        title: 'Error Spike Detected',
        description: `${recentErrors} errors in the last minute`,
        metric: 'errors_per_minute',
        value: recentErrors,
        timestamp: Date.now(),
      });
    }

    // Check for slow performance
    if (event.category === 'voice' && event.properties.duration > 5000) {
      this.addInsight({
        type: 'anomaly',
        title: 'Slow Voice Response',
        description: `Voice command took ${event.properties.duration}ms`,
        metric: 'voice_latency',
        value: event.properties.duration,
        timestamp: Date.now(),
      });
    }
  }

  /**
   * Add insight
   */
  private addInsight(insight: AnalyticsInsight): void {
    this.insights.push(insight);
    
    // Keep only recent insights
    if (this.insights.length > 100) {
      this.insights = this.insights.slice(-100);
    }
    
    logger.log('Analytics', `Insight: ${insight.title}`);
  }

  /**
   * Get event count by category
   */
  getEventCountByCategory(timeRange: number = 3600000): Record<string, number> {
    const cutoff = Date.now() - timeRange;
    const counts: Record<string, number> = {};
    
    this.events
      .filter(e => e.timestamp > cutoff)
      .forEach(e => {
        counts[e.category] = (counts[e.category] || 0) + 1;
      });
    
    return counts;
  }

  /**
   * Get top tools used
   */
  getTopTools(limit: number = 10): { tool: string; count: number }[] {
    const toolCounts: Record<string, number> = {};
    
    this.events
      .filter(e => e.category === 'tool')
      .forEach(e => {
        const tool = e.properties.toolName;
        if (tool) {
          toolCounts[tool] = (toolCounts[tool] || 0) + 1;
        }
      });
    
    return Object.entries(toolCounts)
      .map(([tool, count]) => ({ tool, count }))
      .sort((a, b) => b.count - a.count)
      .slice(0, limit);
  }

  /**
   * Get voice command success rate
   */
  getVoiceSuccessRate(timeRange: number = 3600000): number {
    const cutoff = Date.now() - timeRange;
    const voiceEvents = this.events.filter(
      e => e.category === 'voice' && e.timestamp > cutoff
    );
    
    if (voiceEvents.length === 0) return 100;
    
    const successful = voiceEvents.filter(e => e.properties.success).length;
    return (successful / voiceEvents.length) * 100;
  }

  /**
   * Get average response time
   */
  getAverageResponseTime(category: string, timeRange: number = 3600000): number {
    const cutoff = Date.now() - timeRange;
    const events = this.events.filter(
      e => e.category === category && e.timestamp > cutoff && e.properties.duration
    );
    
    if (events.length === 0) return 0;
    
    const total = events.reduce((sum, e) => sum + e.properties.duration, 0);
    return total / events.length;
  }

  /**
   * Get session summary
   */
  getSessionSummary(): {
    totalSessions: number;
    currentSession: UserSession | undefined;
    avgSessionDuration: number;
    avgVoiceCommandsPerSession: number;
  } {
    const sessions = Array.from(this.sessions.values());
    const currentSession = this.sessions.get(this.currentSessionId);
    
    const completedSessions = sessions.filter(s => s.endTime);
    const avgDuration = completedSessions.length > 0
      ? completedSessions.reduce((sum, s) => sum + (s.endTime! - s.startTime), 0) / completedSessions.length
      : 0;
    
    const avgVoiceCommands = sessions.length > 0
      ? sessions.reduce((sum, s) => sum + s.voiceCommands, 0) / sessions.length
      : 0;
    
    return {
      totalSessions: sessions.length,
      currentSession,
      avgSessionDuration: avgDuration,
      avgVoiceCommandsPerSession: avgVoiceCommands,
    };
  }

  /**
   * Get insights
   */
  getInsights(limit: number = 10): AnalyticsInsight[] {
    return this.insights.slice(-limit);
  }

  /**
   * Get real-time dashboard data
   */
  getDashboardData(): {
    eventCounts: Record<string, number>;
    topTools: { tool: string; count: number }[];
    voiceSuccessRate: number;
    avgVoiceLatency: number;
    avgToolLatency: number;
    insights: AnalyticsInsight[];
    sessionSummary: ReturnType<typeof this.getSessionSummary>;
  } {
    return {
      eventCounts: this.getEventCountByCategory(),
      topTools: this.getTopTools(5),
      voiceSuccessRate: this.getVoiceSuccessRate(),
      avgVoiceLatency: this.getAverageResponseTime('voice'),
      avgToolLatency: this.getAverageResponseTime('tool'),
      insights: this.getInsights(5),
      sessionSummary: this.getSessionSummary(),
    };
  }

  /**
   * Generate recommendations
   */
  generateRecommendations(): AnalyticsInsight[] {
    const recommendations: AnalyticsInsight[] = [];
    
    // Check voice success rate
    const voiceRate = this.getVoiceSuccessRate();
    if (voiceRate < 90) {
      recommendations.push({
        type: 'recommendation',
        title: 'Improve Voice Recognition',
        description: 'Voice command success rate is below 90%. Consider speaking more clearly or checking microphone settings.',
        metric: 'voice_success_rate',
        value: voiceRate,
        timestamp: Date.now(),
      });
    }
    
    // Check latency
    const avgLatency = this.getAverageResponseTime('voice');
    if (avgLatency > 3000) {
      recommendations.push({
        type: 'recommendation',
        title: 'Optimize Performance',
        description: 'Average voice response time is high. Consider enabling offline AI for faster responses.',
        metric: 'avg_voice_latency',
        value: avgLatency,
        timestamp: Date.now(),
      });
    }
    
    // Check tool diversity
    const topTools = this.getTopTools(3);
    if (topTools.length < 3) {
      recommendations.push({
        type: 'recommendation',
        title: 'Explore More Features',
        description: 'You\'re only using a few tools. Try voice commands like "create reminder" or "search notes".',
        metric: 'tool_diversity',
        value: topTools.length,
        timestamp: Date.now(),
      });
    }
    
    return recommendations;
  }

  /**
   * End current session
   */
  endSession(): void {
    const session = this.sessions.get(this.currentSessionId);
    if (session) {
      session.endTime = Date.now();
    }
    
    // Start new session
    this.currentSessionId = this.generateSessionId();
    this.startSession();
  }

  /**
   * Export analytics data
   */
  exportData(): {
    events: AnalyticsEvent[];
    sessions: UserSession[];
    insights: AnalyticsInsight[];
  } {
    return {
      events: this.events,
      sessions: Array.from(this.sessions.values()),
      insights: this.insights,
    };
  }

  /**
   * Clear all data
   */
  clear(): void {
    this.events = [];
    this.sessions.clear();
    this.insights = [];
    this.startSession();
  }
}

export const advancedAnalytics = new AdvancedAnalyticsService();

"use client";

/**
 * Advanced Telemetry Service
 * Comprehensive system monitoring and diagnostics
 */

interface TelemetryEvent {
  id: string;
  category: 'performance' | 'error' | 'user' | 'system' | 'network' | 'voice';
  name: string;
  timestamp: number;
  duration?: number;
  metadata: Record<string, any>;
  tags: string[];
}

interface PerformanceMetric {
  name: string;
  values: number[];
  timestamps: number[];
  unit: string;
}

interface SystemSnapshot {
  timestamp: number;
  memory: {
    used: number;
    total: number;
    percentage: number;
  };
  performance: {
    fcp: number;
    lcp: number;
    fid: number;
    cls: number;
  };
  network: {
    online: boolean;
    effectiveType: string;
    downlink: number;
    rtt: number;
  };
  errors: number;
  warnings: number;
}

interface TelemetryReport {
  period: { start: number; end: number };
  summary: {
    totalEvents: number;
    errorRate: number;
    avgResponseTime: number;
    userSessions: number;
  };
  topEvents: { name: string; count: number }[];
  errorBreakdown: { type: string; count: number }[];
  performanceTrends: { metric: string; trend: 'improving' | 'stable' | 'degrading' }[];
}

class AdvancedTelemetryService {
  private events: TelemetryEvent[] = [];
  private metrics: Map<string, PerformanceMetric> = new Map();
  private snapshots: SystemSnapshot[] = [];
  private sessionId: string;
  private sessionStart: number;
  private readonly MAX_EVENTS = 10000;
  private readonly MAX_SNAPSHOTS = 100;
  private snapshotInterval: NodeJS.Timeout | null = null;

  constructor() {
    this.sessionId = this.generateSessionId();
    this.sessionStart = Date.now();
    this.initializeMetrics();
  }

  /**
   * Generate unique session ID
   */
  private generateSessionId(): string {
    return `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Initialize default metrics
   */
  private initializeMetrics(): void {
    const defaultMetrics = [
      'page_load_time',
      'api_response_time',
      'voice_processing_time',
      'render_time',
      'memory_usage',
      'error_count'
    ];

    defaultMetrics.forEach(name => {
      this.metrics.set(name, {
        name,
        values: [],
        timestamps: [],
        unit: name.includes('time') ? 'ms' : name.includes('memory') ? 'MB' : 'count'
      });
    });
  }

  /**
   * Start automatic snapshot collection
   */
  startMonitoring(intervalMs: number = 60000): void {
    if (this.snapshotInterval) return;

    this.snapshotInterval = setInterval(() => {
      this.captureSnapshot();
    }, intervalMs);

    // Capture initial snapshot
    this.captureSnapshot();

    console.log('[advanced-telemetry] Monitoring started');
  }

  /**
   * Stop automatic snapshot collection
   */
  stopMonitoring(): void {
    if (this.snapshotInterval) {
      clearInterval(this.snapshotInterval);
      this.snapshotInterval = null;
    }

    console.log('[advanced-telemetry] Monitoring stopped');
  }

  /**
   * Capture system snapshot
   */
  private captureSnapshot(): void {
    const snapshot: SystemSnapshot = {
      timestamp: Date.now(),
      memory: this.getMemoryInfo(),
      performance: this.getPerformanceMetrics(),
      network: this.getNetworkInfo(),
      errors: this.getRecentErrorCount(),
      warnings: this.getRecentWarningCount()
    };

    this.snapshots.push(snapshot);

    // Trim old snapshots
    if (this.snapshots.length > this.MAX_SNAPSHOTS) {
      this.snapshots = this.snapshots.slice(-this.MAX_SNAPSHOTS);
    }
  }

  /**
   * Get memory information
   */
  private getMemoryInfo(): SystemSnapshot['memory'] {
    if ('memory' in performance) {
      const memory = (performance as any).memory;
      return {
        used: Math.round(memory.usedJSHeapSize / 1024 / 1024),
        total: Math.round(memory.jsHeapSizeLimit / 1024 / 1024),
        percentage: Math.round((memory.usedJSHeapSize / memory.jsHeapSizeLimit) * 100)
      };
    }
    return { used: 0, total: 0, percentage: 0 };
  }

  /**
   * Get Core Web Vitals
   */
  private getPerformanceMetrics(): SystemSnapshot['performance'] {
    const metrics = { fcp: 0, lcp: 0, fid: 0, cls: 0 };

    try {
      const paintEntries = performance.getEntriesByType('paint');
      const fcpEntry = paintEntries.find(e => e.name === 'first-contentful-paint');
      if (fcpEntry) metrics.fcp = Math.round(fcpEntry.startTime);

      // LCP, FID, CLS would require PerformanceObserver in production
    } catch (error) {
      // Ignore errors
    }

    return metrics;
  }

  /**
   * Get network information
   */
  private getNetworkInfo(): SystemSnapshot['network'] {
    const connection = (navigator as any).connection;
    
    return {
      online: navigator.onLine,
      effectiveType: connection?.effectiveType || 'unknown',
      downlink: connection?.downlink || 0,
      rtt: connection?.rtt || 0
    };
  }

  /**
   * Get recent error count
   */
  private getRecentErrorCount(): number {
    const fiveMinutesAgo = Date.now() - 5 * 60 * 1000;
    return this.events.filter(e => 
      e.category === 'error' && e.timestamp > fiveMinutesAgo
    ).length;
  }

  /**
   * Get recent warning count
   */
  private getRecentWarningCount(): number {
    const fiveMinutesAgo = Date.now() - 5 * 60 * 1000;
    return this.events.filter(e => 
      e.tags.includes('warning') && e.timestamp > fiveMinutesAgo
    ).length;
  }

  /**
   * Track an event
   */
  track(
    category: TelemetryEvent['category'],
    name: string,
    metadata: Record<string, any> = {},
    tags: string[] = []
  ): string {
    const event: TelemetryEvent = {
      id: `event_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      category,
      name,
      timestamp: Date.now(),
      metadata: {
        ...metadata,
        sessionId: this.sessionId
      },
      tags
    };

    this.events.push(event);

    // Trim old events
    if (this.events.length > this.MAX_EVENTS) {
      this.events = this.events.slice(-this.MAX_EVENTS);
    }

    return event.id;
  }

  /**
   * Track a timed operation
   */
  trackTimed(
    category: TelemetryEvent['category'],
    name: string,
    operation: () => Promise<any> | any,
    metadata: Record<string, any> = {}
  ): Promise<any> {
    const startTime = performance.now();

    const complete = (result: any, error?: Error) => {
      const duration = performance.now() - startTime;
      
      this.track(category, name, {
        ...metadata,
        duration,
        success: !error,
        error: error?.message
      }, error ? ['error'] : []);

      // Record metric
      this.recordMetric(`${name}_time`, duration);

      if (error) throw error;
      return result;
    };

    try {
      const result = operation();
      if (result instanceof Promise) {
        return result.then(r => complete(r)).catch(e => complete(null, e));
      }
      return Promise.resolve(complete(result));
    } catch (error) {
      return Promise.reject(complete(null, error as Error));
    }
  }

  /**
   * Record a metric value
   */
  recordMetric(name: string, value: number): void {
    let metric = this.metrics.get(name);
    
    if (!metric) {
      metric = {
        name,
        values: [],
        timestamps: [],
        unit: name.includes('time') ? 'ms' : 'count'
      };
      this.metrics.set(name, metric);
    }

    metric.values.push(value);
    metric.timestamps.push(Date.now());

    // Keep only last 1000 values
    if (metric.values.length > 1000) {
      metric.values = metric.values.slice(-1000);
      metric.timestamps = metric.timestamps.slice(-1000);
    }
  }

  /**
   * Get metric statistics
   */
  getMetricStats(name: string): {
    current: number;
    avg: number;
    min: number;
    max: number;
    p50: number;
    p95: number;
    p99: number;
    trend: 'up' | 'down' | 'stable';
  } | null {
    const metric = this.metrics.get(name);
    if (!metric || metric.values.length === 0) return null;

    const values = [...metric.values].sort((a, b) => a - b);
    const n = values.length;

    const avg = values.reduce((a, b) => a + b, 0) / n;
    const p50 = values[Math.floor(n * 0.5)];
    const p95 = values[Math.floor(n * 0.95)];
    const p99 = values[Math.floor(n * 0.99)];

    // Calculate trend
    let trend: 'up' | 'down' | 'stable' = 'stable';
    if (n >= 10) {
      const recentAvg = values.slice(-5).reduce((a, b) => a + b, 0) / 5;
      const olderAvg = values.slice(-10, -5).reduce((a, b) => a + b, 0) / 5;
      
      if (recentAvg > olderAvg * 1.1) trend = 'up';
      else if (recentAvg < olderAvg * 0.9) trend = 'down';
    }

    return {
      current: values[n - 1],
      avg: Math.round(avg * 100) / 100,
      min: values[0],
      max: values[n - 1],
      p50,
      p95,
      p99,
      trend
    };
  }

  /**
   * Generate telemetry report
   */
  generateReport(periodHours: number = 24): TelemetryReport {
    const periodStart = Date.now() - periodHours * 60 * 60 * 1000;
    const periodEnd = Date.now();

    const periodEvents = this.events.filter(e => 
      e.timestamp >= periodStart && e.timestamp <= periodEnd
    );

    // Count events by name
    const eventCounts: Record<string, number> = {};
    periodEvents.forEach(e => {
      eventCounts[e.name] = (eventCounts[e.name] || 0) + 1;
    });

    // Count errors by type
    const errorCounts: Record<string, number> = {};
    periodEvents
      .filter(e => e.category === 'error')
      .forEach(e => {
        const type = e.metadata.errorType || 'unknown';
        errorCounts[type] = (errorCounts[type] || 0) + 1;
      });

    // Calculate error rate
    const totalEvents = periodEvents.length;
    const errorEvents = periodEvents.filter(e => e.category === 'error').length;
    const errorRate = totalEvents > 0 ? (errorEvents / totalEvents) * 100 : 0;

    // Calculate average response time
    const responseTimes = periodEvents
      .filter(e => e.duration !== undefined)
      .map(e => e.duration!);
    const avgResponseTime = responseTimes.length > 0
      ? responseTimes.reduce((a, b) => a + b, 0) / responseTimes.length
      : 0;

    // Get performance trends
    const performanceTrends: TelemetryReport['performanceTrends'] = [];
    ['page_load_time', 'api_response_time', 'voice_processing_time'].forEach(metric => {
      const stats = this.getMetricStats(metric);
      if (stats) {
        performanceTrends.push({
          metric,
          trend: stats.trend === 'up' ? 'degrading' : 
                 stats.trend === 'down' ? 'improving' : 'stable'
        });
      }
    });

    return {
      period: { start: periodStart, end: periodEnd },
      summary: {
        totalEvents,
        errorRate: Math.round(errorRate * 100) / 100,
        avgResponseTime: Math.round(avgResponseTime),
        userSessions: 1 // Would be calculated from unique session IDs
      },
      topEvents: Object.entries(eventCounts)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 10)
        .map(([name, count]) => ({ name, count })),
      errorBreakdown: Object.entries(errorCounts)
        .sort((a, b) => b[1] - a[1])
        .map(([type, count]) => ({ type, count })),
      performanceTrends
    };
  }

  /**
   * Get recent snapshots
   */
  getSnapshots(limit: number = 10): SystemSnapshot[] {
    return this.snapshots.slice(-limit);
  }

  /**
   * Get events by category
   */
  getEventsByCategory(category: TelemetryEvent['category'], limit: number = 100): TelemetryEvent[] {
    return this.events
      .filter(e => e.category === category)
      .slice(-limit);
  }

  /**
   * Get session info
   */
  getSessionInfo(): {
    sessionId: string;
    duration: number;
    eventCount: number;
    errorCount: number;
  } {
    return {
      sessionId: this.sessionId,
      duration: Date.now() - this.sessionStart,
      eventCount: this.events.length,
      errorCount: this.events.filter(e => e.category === 'error').length
    };
  }

  /**
   * Export telemetry data
   */
  exportData(): {
    events: TelemetryEvent[];
    metrics: Record<string, PerformanceMetric>;
    snapshots: SystemSnapshot[];
    session: ReturnType<typeof this.getSessionInfo>;
  } {
    return {
      events: this.events,
      metrics: Object.fromEntries(this.metrics),
      snapshots: this.snapshots,
      session: this.getSessionInfo()
    };
  }

  /**
   * Clear all data
   */
  clear(): void {
    this.events = [];
    this.snapshots = [];
    this.metrics.forEach(m => {
      m.values = [];
      m.timestamps = [];
    });
    
    console.log('[advanced-telemetry] Cleared all data');
  }
}

