/**
 * Automated Backup Service
 * Automatically backs up user data
 */
class AutomatedBackupService {
  private backupInterval: NodeJS.Timeout | null = null;
  private lastBackup: number = 0;

  /**
   * Start automated backups
   */
  startAutomatedBackups(userId: string, intervalHours: number = 24): void {
    if (this.backupInterval) {
      logger.warn('AutoBackup', 'Already running');
      return;
    }

    // Check if backup is due
    const checkAndBackup = async () => {
      const now = Date.now();
      const hoursSinceLastBackup = (now - this.lastBackup) / (1000 * 60 * 60);

      if (hoursSinceLastBackup >= intervalHours) {
        await this.performBackup(userId);
      }
    };

    // Initial check
    checkAndBackup();

    // Schedule periodic checks (every hour)
    this.backupInterval = setInterval(checkAndBackup, 60 * 60 * 1000);

    logger.log('AutoBackup', `Started automated backups (every ${intervalHours} hours)`);
  }

  /**
   * Stop automated backups
   */
  stopAutomatedBackups(): void {
    if (this.backupInterval) {
      clearInterval(this.backupInterval);
      this.backupInterval = null;
      logger.log('AutoBackup', 'Stopped automated backups');
    }
  }

  /**
   * Perform backup
   */
  private async performBackup(userId: string): Promise<void> {
    try {
      logger.log('AutoBackup', 'Starting backup...');

      const data = await exportUserData(userId);
      
      if (!data) {
        logger.error('AutoBackup', 'Failed to export data');
        return;
      }

      // Save to IndexedDB as backup
      const db = await this.openBackupDB();
      await db.put('backups', {
        userId,
        data,
        timestamp: Date.now(),
      });

      this.lastBackup = Date.now();
      
      logger.log('AutoBackup', 'Backup completed successfully');
    } catch (error) {
      logger.error('AutoBackup', 'Backup failed:', error);
    }
  }

  /**
   * Open backup database
   */
  private async openBackupDB(): Promise<any> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open('echo-backups', 1);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);

      request.onupgradeneeded = (event) => {
        const db = (event.target as any).result;
        if (!db.objectStoreNames.contains('backups')) {
          db.createObjectStore('backups', { keyPath: 'userId' });
        }
      };
    });
  }

  /**
   * Get last backup time
   */
  getLastBackupTime(): number {
    return this.lastBackup;
  }

  /**
   * Manually trigger backup
   */
  async manualBackup(userId: string): Promise<void> {
    await this.performBackup(userId);
  }
}

export const automatedBackup = new AutomatedBackupService();

import type { Message } from "@/types/models";
import { DEMO_MODE_SENTINEL_KEY } from "@/services/demo-mode";
import { proxyChat } from "@/services/ai-proxy";

export interface ChatRequest {
  messages: { role: Message["role"]; content: string }[];
  model?: string;
  maxTokens?: number;
}

export interface ChatResponse {
  content: string;
  citations?: { title: string; url: string }[];
}

// Chat with custom Brain API
async function chatWithBrain(
  baseUrl: string,
  req: ChatRequest,
  token?: string
): Promise<ChatResponse> {
  const res = await fetch(`${baseUrl}/v1/brain/chat`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: JSON.stringify(req),
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Brain API error: ${res.status} ${text}`);
  }
  return res.json();
}

// Chat with OpenAI directly
async function chatWithOpenAI(
  apiKey: string,
  req: ChatRequest
): Promise<ChatResponse> {
  // Demo Mode: use secure server-side proxy instead of client key
  if (apiKey === DEMO_MODE_SENTINEL_KEY) {
    const result = await proxyChat({
      model: req.model || 'gpt-4o-mini',
      messages: req.messages as any,
      max_tokens: req.maxTokens || 1024,
    });
    return { content: result.content };
  }

  const res = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: req.model || "gpt-4o-mini",
      messages: req.messages,
      max_tokens: req.maxTokens || 1024,
    }),
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`OpenAI API error: ${res.status} ${text}`);
  }

  const data = await res.json();
  return {
    content: data.choices[0].message.content,
  };
}

// Main chat function - uses Brain API if configured, otherwise OpenAI
export async function chat(
  baseUrl: string,
  req: ChatRequest,
  token?: string,
  openaiApiKey?: string
): Promise<ChatResponse> {
  // If Brain URL is configured, use it
  if (baseUrl) {
    return chatWithBrain(baseUrl, req, token);
  }
  
  // Otherwise, use OpenAI directly
  if (openaiApiKey) {
    return chatWithOpenAI(openaiApiKey, req);
  }
  
  throw new Error("No AI provider configured. Please set your OpenAI API key in Settings.");
}

