// Common speech recognition corrections
const SPEECH_CORRECTIONS: Record<string, string> = {
  "to do": "todo",
  "to-do": "todo",
  "to dos": "todos",
  "to-dos": "todos",
  "remind me": "create reminder",
  "set a reminder": "create reminder",
  "set reminder": "create reminder",
  "add a task": "create task",
  "add task": "create task",
  "new task": "create task",
  "make a note": "create note",
  "take a note": "create note",
  "note that": "create note",
  "schedule": "create calendar event",
  "book": "create calendar event",
  "set up a meeting": "create calendar event",
  "what's on my": "get",
  "what is on my": "get",
  "read my": "get",
  "show my": "get",
  "list my": "get",
  "tell me my": "get",
  "summarize": "daily summary",
  "summary": "daily summary",
  "how's my day": "daily summary",
  "what's my day like": "daily summary",
  "go to": "navigate",
  "open": "navigate",
  "show me": "navigate",
  "take me to": "navigate",
};

// Normalize speech input for better understanding
export function normalizeSpeechInput(text: string): string {
  let normalized = text.toLowerCase().trim();
  
  // Apply corrections
  for (const [pattern, replacement] of Object.entries(SPEECH_CORRECTIONS)) {
    normalized = normalized.replace(new RegExp(pattern, "gi"), replacement);
  }
  
  // Remove filler words
  const fillers = ["um", "uh", "like", "you know", "basically", "actually", "so", "well"];
  for (const filler of fillers) {
    normalized = normalized.replace(new RegExp(`\\b${filler}\\b`, "gi"), "");
  }
  
  // Clean up extra spaces
  normalized = normalized.replace(/\s+/g, " ").trim();
  
  return normalized;
}

// Extract time expressions from text using smart parser
export function extractTimeExpression(text: string): {
  time: Date | null;
  remaining: string;
  isRecurring?: boolean;
  recurrenceRule?: any;
} {
  // Use the enhanced smart time parser
  const parsed = parseNaturalTime(text);
  
  if (parsed) {
    return {
      time: parsed.date,
      remaining: parsed.remainingText,
      isRecurring: parsed.isRecurring,
      recurrenceRule: parsed.recurrenceRule,
    };
  }
  
  return { time: null, remaining: text };
}

// Enhanced time extraction with recurrence support
export function extractTimeWithRecurrence(text: string): ParsedTime | null {
  return parseNaturalTime(text);
}

// Extract priority from text
export function extractPriority(text: string): { priority: string; remaining: string } {
  const priorityPatterns = [
    { pattern: /\b(urgent|urgently|asap|immediately)\b/i, priority: "urgent" },
    { pattern: /\b(high priority|important|critical)\b/i, priority: "high" },
    { pattern: /\b(low priority|whenever|not urgent)\b/i, priority: "low" },
  ];
  
  for (const { pattern, priority } of priorityPatterns) {
    if (pattern.test(text)) {
      return { priority, remaining: text.replace(pattern, "").trim() };
    }
  }
  
  return { priority: "medium", remaining: text };
}

// Build conversation context for AI
export function buildConversationContext(
  messages: Message[],
  maxMessages: number = 10
): { role: string; content: string }[] {
  const recentMessages = messages.slice(-maxMessages);
  return recentMessages.map(m => ({
    role: m.role,
    content: m.content,
  }));
}

// Generate contextual follow-up suggestions
export function generateFollowUpSuggestions(lastIntent: string, lastTool?: string): string[] {
  const suggestions: Record<string, string[]> = {
    "create_task": [
      "Would you like to set a reminder for this task?",
      "Should I add this to your calendar as well?",
    ],
    "create_reminder": [
      "Would you like me to create a task for this too?",
      "Should I set another reminder?",
    ],
    "get_tasks": [
      "Would you like me to mark any of these as complete?",
      "Should I reschedule any overdue tasks?",
    ],
    "daily_summary": [
      "Would you like more details on any of these?",
      "Should I read your tasks or reminders?",
    ],
    "navigate": [
      "Is there anything else you'd like me to help with?",
    ],
  };
  
  return suggestions[lastIntent] || suggestions[lastTool || ""] || [];
}

// Detect if user is asking for confirmation
export function isConfirmation(text: string): boolean {
  const confirmPatterns = /\b(yes|yeah|yep|sure|ok|okay|confirm|do it|go ahead|please|correct|right)\b/i;
  return confirmPatterns.test(text);
}

// Detect if user is declining
export function isDeclination(text: string): boolean {
  const declinePatterns = /\b(no|nope|nah|cancel|stop|don't|never mind|forget it)\b/i;
  return declinePatterns.test(text);
}

"use client";

import { supabase } from "@/integrations/supabase/client";
import { showSuccess, showError } from "@/utils/toast";

interface ExportData {
  version: string;
  exportDate: string;
  userId: string;
  profile: any;
  tasks: any[];
  reminders: any[];
  notes: any[];
  calendarEvents: any[];
  contacts: any[];
  messages: any[];
  knowledge: any[];
  preferences: any;
}

/**
 * Export all user data as JSON
 */
export async function exportUserData(userId: string): Promise<ExportData | null> {
  try {
    const [
      profile,
      tasks,
      reminders,
      notes,
      calendarEvents,
      contacts,
      emailLogs,
      smsLogs,
      knowledge,
    ] = await Promise.all([
      supabase.from("profiles").select("*").eq("id", userId).single(),
      supabase.from("tasks").select("*").eq("user_id", userId),
      supabase.from("reminders").select("*").eq("user_id", userId),
      supabase.from("notes").select("*").eq("user_id", userId),
      supabase.from("calendar_events").select("*").eq("user_id", userId),
      supabase.from("contacts").select("*").eq("user_id", userId),
      supabase.from("email_logs").select("*").eq("user_id", userId),
      supabase.from("sms_logs").select("*").eq("user_id", userId),
      supabase.from("knowledge").select("*").eq("user_id", userId),
    ]);

    const messages = [
      ...(emailLogs.data || []).map(e => ({ ...e, type: "email" })),
      ...(smsLogs.data || []).map(s => ({ ...s, type: "sms" })),
    ];

    const preferences = localStorage.getItem("echo:prefs");

    const exportData: ExportData = {
      version: "1.0.0",
      exportDate: new Date().toISOString(),
      userId,
      profile: profile.data,
      tasks: tasks.data || [],
      reminders: reminders.data || [],
      notes: notes.data || [],
      calendarEvents: calendarEvents.data || [],
      contacts: contacts.data || [],
      messages,
      knowledge: knowledge.data || [],
      preferences: preferences ? JSON.parse(preferences) : null,
    };

    return exportData;
  } catch (error) {
    console.error("Failed to export data:", error);
    return null;
  }
}

/**
 * Download exported data as JSON file
 */
export async function downloadUserData(userId: string) {
  try {
    const data = await exportUserData(userId);
    
    if (!data) {
      showError("Failed to export data");
      return;
    }

    const blob = new Blob([JSON.stringify(data, null, 2)], {
      type: "application/json",
    });

    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `echo-backup-${new Date().toISOString().split("T")[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    showSuccess("Data exported successfully!");
  } catch (error) {
    console.error("Failed to download data:", error);
    showError("Failed to download data");
  }
}

/**
 * Import user data from JSON file
 */
export async function importUserData(
  userId: string,
  file: File
): Promise<boolean> {
  try {
    const text = await file.text();
    const data: ExportData = JSON.parse(text);

    // Validate data structure
    if (!data.version || !data.userId || !data.exportDate) {
      showError("Invalid backup file format");
      return false;
    }

    // Confirm with user
    const confirmed = window.confirm(
      `This will import data from ${new Date(data.exportDate).toLocaleDateString()}. Continue?`
    );

    if (!confirmed) return false;

    // Import data (this will merge with existing data)
    const promises = [];

    if (data.tasks?.length > 0) {
      promises.push(
        ...data.tasks.map(task =>
          supabase.from("tasks").upsert({ ...task, user_id: userId })
        )
      );
    }

    if (data.reminders?.length > 0) {
      promises.push(
        ...data.reminders.map(reminder =>
          supabase.from("reminders").upsert({ ...reminder, user_id: userId })
        )
      );
    }

    if (data.notes?.length > 0) {
      promises.push(
        ...data.notes.map(note =>
          supabase.from("notes").upsert({ ...note, user_id: userId })
        )
      );
    }

    if (data.calendarEvents?.length > 0) {
      promises.push(
        ...data.calendarEvents.map(event =>
          supabase.from("calendar_events").upsert({ ...event, user_id: userId })
        )
      );
    }

    if (data.contacts?.length > 0) {
      promises.push(
        ...data.contacts.map(contact =>
          supabase.from("contacts").upsert({ ...contact, user_id: userId })
        )
      );
    }

    await Promise.all(promises);

    // Import preferences
    if (data.preferences) {
      localStorage.setItem("echo:prefs", JSON.stringify(data.preferences));
    }

    showSuccess("Data imported successfully!");
    return true;
  } catch (error) {
    console.error("Failed to import data:", error);
    showError("Failed to import data");
    return false;
  }
}

/**
 * Get export statistics
 */
export async function getExportStats(userId: string): Promise<{
  totalItems: number;
  breakdown: Record<string, number>;
  estimatedSize: string;
} | null> {
  try {
    const data = await exportUserData(userId);
    
    if (!data) return null;

    const breakdown = {
      tasks: data.tasks.length,
      reminders: data.reminders.length,
      notes: data.notes.length,
      events: data.calendarEvents.length,
      contacts: data.contacts.length,
      messages: data.messages.length,
      knowledge: data.knowledge.length,
    };

    const totalItems = Object.values(breakdown).reduce((sum, count) => sum + count, 0);
    const jsonSize = new Blob([JSON.stringify(data)]).size;
    const estimatedSize = jsonSize < 1024 
      ? `${jsonSize} bytes`
      : jsonSize < 1024 * 1024
      ? `${(jsonSize / 1024).toFixed(2)} KB`
      : `${(jsonSize / (1024 * 1024)).toFixed(2)} MB`;

    return {
      totalItems,
      breakdown,
      estimatedSize,
    };
  } catch (error) {
    console.error("Failed to get export stats:", error);
    return null;
  }
}

/**
 * Centralized Database Service
 * Provides a consistent interface for all database operations with:
 * - Automatic retry on transient failures
 * - Connection health monitoring
 * - Query result caching
 * - Consistent error handling
 * - Type-safe operations
 */

import { supabase } from '@/integrations/supabase/client';
import { logger } from '@/utils/logger';

export interface DatabaseResult<T> {
  data: T | null;
  error: string | null;
  count?: number;
}

export interface QueryOptions {
  cache?: boolean;
  cacheTTL?: number; // milliseconds
  retries?: number;
}

// Simple in-memory cache
const queryCache = new Map<string, { data: any; timestamp: number; ttl: number }>();

// Default options
const DEFAULT_OPTIONS: Required<QueryOptions> = {
  cache: false,
  cacheTTL: 60000, // 1 minute
  retries: 3,
};

/**
 * Generate cache key for a query
 */
function getCacheKey(table: string, operation: string, params: any): string {
  return `${table}:${operation}:${JSON.stringify(params)}`;
}

/**
 * Get cached result if valid
 */
function getCachedResult<T>(key: string): T | null {
  const cached = queryCache.get(key);
  if (cached && Date.now() - cached.timestamp < cached.ttl) {
    logger.debug('DatabaseService', 'Cache hit', { key });
    return cached.data;
  }
  if (cached) {
    queryCache.delete(key);
  }
  return null;
}

/**
 * Set cache result
 */
function setCacheResult(key: string, data: any, ttl: number): void {
  queryCache.set(key, { data, timestamp: Date.now(), ttl });
}

/**
 * Clear cache for a table (call after mutations)
 */
export function clearTableCache(table: string): void {
  for (const key of queryCache.keys()) {
    if (key.startsWith(`${table}:`)) {
      queryCache.delete(key);
    }
  }
}

/**
 * Clear all cache
 */
export function clearAllCache(): void {
  queryCache.clear();
}

/**
 * Execute a database operation with retry logic
 */
async function executeWithRetry<T>(
  operation: () => Promise<{ data: T | null; error: any }>,
  retries: number
): Promise<DatabaseResult<T>> {
  let lastError: any = null;

  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      const { data, error } = await operation();

      if (error) {
        // Check if error is retryable
        const isRetryable = 
          error.code === 'PGRST301' || // Connection error
          error.code === '40001' || // Serialization failure
          error.code === '40P01' || // Deadlock
          error.message?.includes('network') ||
          error.message?.includes('timeout');

        if (isRetryable && attempt < retries) {
          logger.warn('DatabaseService', `Retryable error (attempt ${attempt}/${retries})`, { error: error.message });
          await new Promise(resolve => setTimeout(resolve, 1000 * attempt));
          continue;
        }

        return {
          data: null,
          error: error.message || 'Database operation failed',
        };
      }

      return { data, error: null };
    } catch (err: any) {
      lastError = err;
      if (attempt < retries) {
        logger.warn('DatabaseService', `Exception (attempt ${attempt}/${retries})`, { error: err.message });
        await new Promise(resolve => setTimeout(resolve, 1000 * attempt));
      }
    }
  }

  return {
    data: null,
    error: lastError?.message || 'Database operation failed after retries',
  };
}

/**
 * Database service for a specific table
 */
export function createTableService<T extends Record<string, any>>(tableName: string) {
  return {
    /**
     * Select records
     */
    async select(
      columns: string = '*',
      filters?: Record<string, any>,
      options: QueryOptions = {}
    ): Promise<DatabaseResult<T[]>> {
      const opts = { ...DEFAULT_OPTIONS, ...options };
      const cacheKey = getCacheKey(tableName, 'select', { columns, filters });

      // Check cache
      if (opts.cache) {
        const cached = getCachedResult<T[]>(cacheKey);
        if (cached) return { data: cached, error: null };
      }

      const result = await executeWithRetry<T[]>(async () => {
        let query = supabase.from(tableName).select(columns);

        if (filters) {
          for (const [key, value] of Object.entries(filters)) {
            if (value === null) {
              query = query.is(key, null);
            } else if (Array.isArray(value)) {
              query = query.in(key, value);
            } else if (typeof value === 'object' && value.operator) {
              // Handle special operators
              switch (value.operator) {
                case 'gt':
                  query = query.gt(key, value.value);
                  break;
                case 'gte':
                  query = query.gte(key, value.value);
                  break;
                case 'lt':
                  query = query.lt(key, value.value);
                  break;
                case 'lte':
                  query = query.lte(key, value.value);
                  break;
                case 'like':
                  query = query.like(key, value.value);
                  break;
                case 'ilike':
                  query = query.ilike(key, value.value);
                  break;
                case 'neq':
                  query = query.neq(key, value.value);
                  break;
              }
            } else {
              query = query.eq(key, value);
            }
          }
        }

        return query;
      }, opts.retries);

      // Cache successful results
      if (opts.cache && result.data) {
        setCacheResult(cacheKey, result.data, opts.cacheTTL);
      }

      return result;
    },

    /**
     * Select a single record
     */
    async selectOne(
      columns: string = '*',
      filters: Record<string, any>,
      options: QueryOptions = {}
    ): Promise<DatabaseResult<T>> {
      const opts = { ...DEFAULT_OPTIONS, ...options };
      const cacheKey = getCacheKey(tableName, 'selectOne', { columns, filters });

      if (opts.cache) {
        const cached = getCachedResult<T>(cacheKey);
        if (cached) return { data: cached, error: null };
      }

      const result = await executeWithRetry<T>(async () => {
        let query = supabase.from(tableName).select(columns);

        for (const [key, value] of Object.entries(filters)) {
          query = query.eq(key, value);
        }

        return query.single();
      }, opts.retries);

      if (opts.cache && result.data) {
        setCacheResult(cacheKey, result.data, opts.cacheTTL);
      }

      return result;
    },

    /**
     * Insert a record
     */
    async insert(
      data: Partial<T>,
      options: QueryOptions = {}
    ): Promise<DatabaseResult<T>> {
      const opts = { ...DEFAULT_OPTIONS, ...options };

      const result = await executeWithRetry<T>(async () => {
        return supabase.from(tableName).insert(data).select().single();
      }, opts.retries);

      // Clear cache on mutation
      if (result.data) {
        clearTableCache(tableName);
      }

      return result;
    },

    /**
     * Insert multiple records
     */
    async insertMany(
      data: Partial<T>[],
      options: QueryOptions = {}
    ): Promise<DatabaseResult<T[]>> {
      const opts = { ...DEFAULT_OPTIONS, ...options };

      const result = await executeWithRetry<T[]>(async () => {
        return supabase.from(tableName).insert(data).select();
      }, opts.retries);

      if (result.data) {
        clearTableCache(tableName);
      }

      return result;
    },

    /**
     * Update records
     */
    async update(
      data: Partial<T>,
      filters: Record<string, any>,
      options: QueryOptions = {}
    ): Promise<DatabaseResult<T>> {
      const opts = { ...DEFAULT_OPTIONS, ...options };

      const result = await executeWithRetry<T>(async () => {
        let query = supabase.from(tableName).update(data);

        for (const [key, value] of Object.entries(filters)) {
          query = query.eq(key, value);
        }

        return query.select().single();
      }, opts.retries);

      if (result.data) {
        clearTableCache(tableName);
      }

      return result;
    },

    /**
     * Upsert a record
     */
    async upsert(
      data: Partial<T>,
      options: QueryOptions = {}
    ): Promise<DatabaseResult<T>> {
      const opts = { ...DEFAULT_OPTIONS, ...options };

      const result = await executeWithRetry<T>(async () => {
        return supabase.from(tableName).upsert(data).select().single();
      }, opts.retries);

      if (result.data) {
        clearTableCache(tableName);
      }

      return result;
    },

    /**
     * Delete records
     */
    async delete(
      filters: Record<string, any>,
      options: QueryOptions = {}
    ): Promise<DatabaseResult<null>> {
      const opts = { ...DEFAULT_OPTIONS, ...options };

      const result = await executeWithRetry<null>(async () => {
        let query = supabase.from(tableName).delete();

        for (const [key, value] of Object.entries(filters)) {
          query = query.eq(key, value);
        }

        return query;
      }, opts.retries);

      clearTableCache(tableName);

      return result;
    },

    /**
     * Count records
     */
    async count(
      filters?: Record<string, any>,
      options: QueryOptions = {}
    ): Promise<DatabaseResult<number>> {
      const opts = { ...DEFAULT_OPTIONS, ...options };

      const result = await executeWithRetry<{ count: number }>(async () => {
        let query = supabase.from(tableName).select('*', { count: 'exact', head: true });

        if (filters) {
          for (const [key, value] of Object.entries(filters)) {
            query = query.eq(key, value);
          }
        }

        const { count, error } = await query;
        return { data: { count: count || 0 }, error };
      }, opts.retries);

      return {
        data: result.data?.count ?? null,
        error: result.error,
      };
    },
  };
}

