import React from 'react';

"use client";

interface WeatherCache {
  location: {
    lat: number;
    lng: number;
    city?: string;
  };
  data: any;
  timestamp: number;
  expiresAt: number;
}

const CACHE_DURATION = 24 * 60 * 60 * 1000; // 24 hours
const CACHE_KEY = 'weather-cache';

class OfflineWeather {
  /**
   * Get weather with 24-hour caching
   */
  async getWeather(lat: number, lng: number, fetchFn: () => Promise<any>): Promise<{
    data: any;
    cached: boolean;
    stale: boolean;
    lastUpdated: number;
  }> {
    const cached = await this.getCached(lat, lng);
    const now = Date.now();

    // Return fresh cache if available and not expired
    if (cached && now < cached.expiresAt) {
      console.log('[Offline Weather] Using fresh cache');
      return {
        data: cached.data,
        cached: true,
        stale: false,
        lastUpdated: cached.timestamp,
      };
    }

    // Try to fetch fresh data if online
    if (navigator.onLine) {
      try {
        const freshData = await fetchFn();
        await this.cache(lat, lng, freshData);
        
        console.log('[Offline Weather] Fetched fresh data');
        return {
          data: freshData,
          cached: false,
          stale: false,
          lastUpdated: now,
        };
      } catch (error) {
        console.error('[Offline Weather] Fetch failed, using stale cache');
        // Fall through to stale cache
      }
    }

    // Return stale cache if available (offline or fetch failed)
    if (cached) {
      console.log('[Offline Weather] Using stale cache');
      return {
        data: cached.data,
        cached: true,
        stale: true,
        lastUpdated: cached.timestamp,
      };
    }

    throw new Error('No weather data available');
  }

  /**
   * Cache weather data
   */
  private async cache(lat: number, lng: number, data: any, city?: string) {
    try {
      const cacheData: WeatherCache = {
        location: { lat, lng, city },
        data,
        timestamp: Date.now(),
        expiresAt: Date.now() + CACHE_DURATION,
      };

      const allCaches = await this.getAllCaches();
      const key = this.getCacheKey(lat, lng);
      allCaches[key] = cacheData;

      // Limit to 50 locations
      const keys = Object.keys(allCaches);
      if (keys.length > 50) {
        // Remove oldest
        const oldest = keys.sort((a, b) => 
          allCaches[a].timestamp - allCaches[b].timestamp
        )[0];
        delete allCaches[oldest];
      }

      localStorage.setItem(CACHE_KEY, JSON.stringify(allCaches));
    } catch (error) {
      console.error('[Offline Weather] Cache failed:', error);
    }
  }

  /**
   * Get cached weather for location
   */
  private async getCached(lat: number, lng: number): Promise<WeatherCache | null> {
    try {
      const allCaches = await this.getAllCaches();
      const key = this.getCacheKey(lat, lng);
      return allCaches[key] || null;
    } catch (error) {
      return null;
    }
  }

  /**
   * Get all cached weather data
   */
  private async getAllCaches(): Promise<Record<string, WeatherCache>> {
    try {
      const stored = localStorage.getItem(CACHE_KEY);
      return stored ? JSON.parse(stored) : {};
    } catch (error) {
      return {};
    }
  }

  /**
   * Generate cache key from coordinates
   */
  private getCacheKey(lat: number, lng: number): string {
    // Round to 2 decimal places for cache key
    return `${lat.toFixed(2)},${lng.toFixed(2)}`;
  }

  /**
   * Clear all weather caches
   */
  async clearCache() {
    localStorage.removeItem(CACHE_KEY);
  }

  /**
   * Get cache statistics
   */
  async getStats(): Promise<{
    totalLocations: number;
    freshCount: number;
    staleCount: number;
  }> {
    const allCaches = await this.getAllCaches();
    const now = Date.now();
    
    let freshCount = 0;
    let staleCount = 0;

    Object.values(allCaches).forEach(cache => {
      if (now < cache.expiresAt) {
        freshCount++;
      } else {
        staleCount++;
      }
    });

    return {
      totalLocations: Object.keys(allCaches).length,
      freshCount,
      staleCount,
    };
  }
}

export const offlineWeather = new OfflineWeather();

import type { OpenAIVoice } from "../types/models";
import { DEMO_MODE_SENTINEL_KEY } from "@/services/demo-mode";
import { proxySTT, proxyTTS, proxyChat } from "@/services/ai-proxy";

const OPENAI_API_BASE = "https://api.openai.com/v1";

export interface TranscriptionResult {
  text: string;
}

export async function transcribeAudio(
  audioBlob: Blob,
  apiKey: string
): Promise<TranscriptionResult> {
  console.log('[Whisper] Original blob type:', audioBlob.type);
  console.log('[Whisper] Original blob size:', audioBlob.size);
  
  // OpenAI Whisper accepts these formats directly without conversion
  // Let's send the original WebM/Opus which is actually supported
  let filename = "audio.webm";
  const mimeType = audioBlob.type.toLowerCase();
  
  // Map MIME types to filenames that OpenAI accepts
  if (mimeType.includes('webm')) {
    filename = "audio.webm";
  } else if (mimeType.includes('mp4') || mimeType.includes('m4a')) {
    filename = "audio.mp4";
  } else if (mimeType.includes('mpeg') || mimeType.includes('mp3') || mimeType.includes('mpga')) {
    filename = "audio.mp3";
  } else if (mimeType.includes('ogg') || mimeType.includes('oga')) {
    filename = "audio.ogg";
  } else if (mimeType.includes('wav')) {
    filename = "audio.wav";
  } else if (mimeType.includes('flac')) {
    filename = "audio.flac";
  } else {
    // Default to webm if unknown
    console.warn('[Whisper] Unknown MIME type, defaulting to webm:', mimeType);
    filename = "audio.webm";
  }
  
  console.log('[Whisper] Using filename:', filename);
  console.log('[Whisper] Sending blob size:', audioBlob.size);
  
  // Validate blob size
  if (audioBlob.size === 0) {
    throw new Error('Audio recording is empty. Please try speaking again.');
  }
  
  if (audioBlob.size < 1000) {
    console.warn('[Whisper] Audio blob is very small, might be too short');
  }
  
  // Demo Mode: send audio to server-side proxy (requires Supabase session)
  if (apiKey === DEMO_MODE_SENTINEL_KEY) {
    const result = await proxySTT({ file: audioBlob, filename, model: 'whisper-1' });
    return { text: result.text || '' };
  }

  const formData = new FormData();
  formData.append("file", audioBlob, filename);
  formData.append("model", "whisper-1");
  
  // Don't force language - let Whisper auto-detect for better accuracy
  // formData.append("language", "en");

  const response = await fetch(`${OPENAI_API_BASE}/audio/transcriptions`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
    },
    body: formData,
  });

  if (!response.ok) {
    const errorText = await response.text();
    console.error('[Whisper] Transcription failed:', errorText);
    
    let errorMessage = 'Transcription failed';
    try {
      const errorJson = JSON.parse(errorText);
      errorMessage = errorJson.error?.message || errorText;
    } catch {
      errorMessage = errorText;
    }
    
    throw new Error(errorMessage);
  }

  const result = await response.json();
  const transcribedText = result.text || '';
  console.log('[Whisper] Transcription result:', transcribedText || '(empty)');
  
  // Don't throw an error for empty results - let the caller handle it
  // This allows the system to continue listening instead of stopping
  if (!transcribedText || transcribedText.trim().length === 0) {
    console.log('[Whisper] No speech detected in audio - this may be due to:');
    console.log('[Whisper] - Microphone not picking up voice clearly');
    console.log('[Whisper] - Background noise being filtered out');
    console.log('[Whisper] - Speaking too quietly or too far from microphone');
  }
  
  return { text: transcribedText };
}

// Valid OpenAI TTS voices as of the API
const VALID_OPENAI_VOICES = ["alloy", "ash", "coral", "echo", "fable", "nova", "onyx", "sage", "shimmer"];

export async function synthesizeSpeech(
  text: string,
  apiKey: string,
  voice: OpenAIVoice = "nova"
): Promise<Blob> {
  // Validate voice - fall back to nova if invalid
  const validatedVoice = VALID_OPENAI_VOICES.includes(voice) ? voice : "nova";
  
  if (voice !== validatedVoice) {
    console.warn(`[OpenAI TTS] Invalid voice "${voice}" - falling back to "${validatedVoice}"`);
  }
  
  console.log(`[OpenAI TTS] Synthesizing speech with voice: ${validatedVoice}`);
  console.log(`[OpenAI TTS] Text length: ${text.length} characters`);
  
  // Truncate very long text to avoid API issues
  const maxLength = 4096;
  const truncatedText = text.length > maxLength ? text.substring(0, maxLength) + "..." : text;
  
  // Demo Mode: server-side proxy (no client key)
  if (apiKey === DEMO_MODE_SENTINEL_KEY) {
    return proxyTTS({
      input: truncatedText,
      voice: validatedVoice,
      model: 'tts-1',
      speed: 1.0,
    });
  }

  const response = await fetch(`${OPENAI_API_BASE}/audio/speech`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: "tts-1", // Use standard model for faster response
      input: truncatedText,
      voice: validatedVoice,
      response_format: "mp3",
      speed: 1.0,
    }),
  });

  if (!response.ok) {
    const error = await response.text();
    console.error(`[OpenAI TTS] Synthesis failed:`, error);
    throw new Error(`Speech synthesis failed: ${error}`);
  }

  // Get the raw array buffer first
  const arrayBuffer = await response.arrayBuffer();
  console.log(`[OpenAI TTS] Received ${arrayBuffer.byteLength} bytes`);
  
  // Create blob with explicit MP3 MIME type
  const blob = new Blob([arrayBuffer], { type: 'audio/mpeg' });
  console.log(`[OpenAI TTS] Created blob with type: ${blob.type}, size: ${blob.size} bytes`);
  
  if (blob.size === 0) {
    throw new Error('Empty audio response from TTS API');
  }
  
  return blob;
}

export async function chatWithOpenAI(
  messages: { role: string; content: string }[],
  apiKey: string
): Promise<string> {
  // Demo Mode: server-side proxy (no client key)
  if (apiKey === DEMO_MODE_SENTINEL_KEY) {
    const res = await proxyChat({
      model: 'gpt-4o-mini',
      messages: messages.map(m => ({
        role: m.role === 'system' || m.role === 'assistant' ? m.role : 'user',
        content: m.content,
      })),
      max_tokens: 1000,
    });
    return res.content;
  }

  const response = await fetch(`${OPENAI_API_BASE}/chat/completions`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: "gpt-4o-mini",
      messages: messages,
      max_tokens: 1000,
    }),
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Chat failed: ${error}`);
  }

  const data = await response.json();
  return data.choices[0]?.message?.content || "";
}

export function createAudioContext(): AudioContext {
  return new (window.AudioContext || (window as any).webkitAudioContext)();
}

export async function playAudioBlob(blob: Blob): Promise<void> {
  return new Promise((resolve, reject) => {
    console.log(`[Audio Player] Playing audio blob of size: ${blob.size} bytes`);
    
    const audio = new Audio();
    const url = URL.createObjectURL(blob);
    audio.src = url;
    
    audio.onloadedmetadata = () => {
      console.log(`[Audio Player] Audio loaded, duration: ${audio.duration}s`);
    };
    
    audio.onended = () => {
      console.log(`[Audio Player] Playback completed`);
      URL.revokeObjectURL(url);
      resolve();
    };
    
    audio.onerror = (e) => {
      console.error(`[Audio Player] Playback error:`, e);
      URL.revokeObjectURL(url);
      reject(new Error("Audio playback failed"));
    };
    
    audio.play()
      .then(() => console.log(`[Audio Player] Playback started`))
      .catch((e) => {
        console.error(`[Audio Player] Play failed:`, e);
        URL.revokeObjectURL(url);
        reject(e);
      });
  });
}

/**
 * Orchestrator Advanced Widget Extension
 * Adds voice control for widget positioning and configuration
 */

import type { ActionResult } from "./orchestrator/types";
import type { Widget } from "@/types/widgets";
import { executeVoiceMoveCommand, parseMoveVoiceCommand } from "./voice-widget-positioning";

/**
 * Move a widget on the dashboard
 */
export async function executeMoveWidget(
  widgetType: string,
  destination: string
): Promise<ActionResult> {
  const currentWidgets = (window as any).getCurrentWidgets?.() || [];
  const setWidgets = (window as any).setWidgets;
  
  if (!setWidgets) {
    return {
      tool: "move_widget",
      success: false,
      error: "Widget system not ready",
    };
  }

  // Construct a pseudo-command string to reuse the parser logic
  // or manually construct the command object
  let commandText = `move ${widgetType} ${destination}`;
  const command = parseMoveVoiceCommand(commandText);
  
  if (!command) {
    // Fallback if parser fails (e.g. strict matching issues)
    // Here we map "top left" etc manually if needed, but parser should handle it
     return {
      tool: "move_widget",
      success: false,
      error: `Could not understand move command for ${widgetType} to ${destination}`,
    };
  }
  
  // Override widgetType from parameter just in case parser got it wrong or user was specific
  command.widgetType = widgetType;

  const result = executeVoiceMoveCommand(command, currentWidgets, setWidgets);

  if (result.success && result.action) {
    result.action();
    return {
      tool: "move_widget",
      success: true,
      data: {
        voiceText: result.voiceResponse,
      },
    };
  }

  return {
    tool: "move_widget",
    success: false,
    error: result.message,
    data: {
      voiceText: result.voiceResponse,
    },
  };
}

