export async function executeGetKnowledge(
  userId: string,
  category?: string,
  search?: string
): Promise<ActionResult> {
  try {
    let query = supabase.from("knowledge").select("*").eq("user_id", userId);
    
    if (category) {
      query = query.eq("category", category);
    }
    
    if (search) {
      query = query.or(`key.ilike.%${search}%,value.ilike.%${search}%`);
    }
    
    const { data, error } = await query.order("created_at", { ascending: false });

    if (error) throw error;

    const voiceText = data && data.length > 0
      ? `I found ${data.length} piece${data.length > 1 ? 's' : ''} of information${search ? ` about "${search}"` : ""}.`
      : `I don't have any information${search ? ` about "${search}"` : ""} stored.`;

    return {
      tool: "get_knowledge",
      success: true,
      data: {
        knowledge: data?.map(k => ({ category: k.category, key: k.key, value: k.value })) || [],
        voiceText,
      },
    };
  } catch (error: any) {
    return {
      tool: "get_knowledge",
      success: false,
      error: error.message,
    };
  }
}

export async function executeSaveMemory(
  userId: string,
  category: string,
  key: string,
  value: string
): Promise<ActionResult> {
  try {
    // Check if this memory already exists
    const { data: existing } = await supabase
      .from("knowledge")
      .select("*")
      .eq("user_id", userId)
      .eq("category", category)
      .eq("key", key)
      .single();

    let data;
    if (existing) {
      // Update existing
      const { data: updated, error } = await supabase
        .from("knowledge")
        .update({ value })
        .eq("id", existing.id)
        .select()
        .single();
      
      if (error) throw error;
      data = updated;
    } else {
      // Create new
      const { data: created, error } = await supabase.from("knowledge").insert({
        user_id: userId,
        category,
        key,
        value,
      }).select().single();

      if (error) throw error;
      data = created;
    }

    return {
      tool: "save_memory",
      success: true,
      data: {
        memory: data,
        voiceText: `Got it! I'll remember that ${key} is ${value}.`,
      },
    };
  } catch (error: any) {
    return {
      tool: "save_memory",
      success: false,
      error: error.message,
    };
  }
}

