export async function executeGetNotes(
  userId: string,
  search?: string,
  limit: number = 10,
  pinnedOnly: boolean = false
): Promise<ActionResult> {
  try {
    let query = supabase.from("notes").select("*").eq("user_id", userId);
    
    if (search) {
      query = query.or(`title.ilike.%${search}%,content.ilike.%${search}%`);
    }
    
    if (pinnedOnly) {
      query = query.eq("pinned", true);
    }
    
    const { data, error } = await query
      .order("pinned", { ascending: false })
      .order("created_at", { ascending: false })
      .limit(limit);

    if (error) throw error;

    const voiceText = data && data.length > 0
      ? `Found ${data.length} note${data.length > 1 ? 's' : ''}${search ? ` matching "${search}"` : ""}.`
      : `No notes found${search ? ` matching "${search}"` : ""}.`;

    return {
      tool: "get_notes",
      success: true,
      data: {
        notes: data?.map(n => ({
          id: n.id,
          title: n.title,
          content: n.content.substring(0, 200) + (n.content.length > 200 ? "..." : ""),
          tags: n.tags,
          pinned: n.pinned,
          created_at: n.created_at,
        })) || [],
        voiceText,
      },
    };
  } catch (error: any) {
    return {
      tool: "get_notes",
      success: false,
      error: error.message,
    };
  }
}

