"use client";

import { logger } from "@/utils/logger";

interface PerformanceMetric {
  operation: string;
  duration: number;
  timestamp: number;
  success: boolean;
  metadata?: Record<string, any>;
}

interface PerformanceThresholds {
  [key: string]: number;
}

const DEFAULT_THRESHOLDS: PerformanceThresholds = {
  'transcribe': 2000,      // 2s
  'process_ai': 3000,      // 3s
  'speak': 2000,           // 2s
  'tool_execution': 1000,  // 1s
  'database_query': 500,   // 500ms
  'total_voice': 5000,     // 5s total
};

/**
 * Performance Monitoring Service
 * Tracks operation latency and alerts on slow performance
 */
class PerformanceMonitorService {
  private metrics: PerformanceMetric[] = [];
  private maxMetrics = 1000;
  private thresholds = DEFAULT_THRESHOLDS;
  private alertCallbacks: Set<(metric: PerformanceMetric) => void> = new Set();

  /**
   * Track an operation
   */
  track(
    operation: string,
    duration: number,
    success: boolean = true,
    metadata?: Record<string, any>
  ): void {
    const metric: PerformanceMetric = {
      operation,
      duration,
      timestamp: Date.now(),
      success,
      metadata,
    };

    this.metrics.push(metric);

    // Keep only recent metrics
    if (this.metrics.length > this.maxMetrics) {
      this.metrics = this.metrics.slice(-this.maxMetrics);
    }

    // Check threshold
    const threshold = this.thresholds[operation];
    if (threshold && duration > threshold) {
      logger.warn('Performance', `${operation} is slow: ${duration}ms (threshold: ${threshold}ms)`);
      this.alertCallbacks.forEach(cb => cb(metric));
    }

    // Log in development
    logger.debug('Performance', `${operation}: ${duration}ms`);
  }

  /**
   * Start timing an operation
   */
  startTimer(operation: string): () => void {
    const start = Date.now();
    
    return (success: boolean = true, metadata?: Record<string, any>) => {
      const duration = Date.now() - start;
      this.track(operation, duration, success, metadata);
    };
  }

  /**
   * Get average duration for operation
   */
  getAverage(operation: string, last: number = 10): number {
    const relevant = this.metrics
      .filter(m => m.operation === operation && m.success)
      .slice(-last);

    if (relevant.length === 0) return 0;

    const sum = relevant.reduce((acc, m) => acc + m.duration, 0);
    return sum / relevant.length;
  }

  /**
   * Get percentile
   */
  getPercentile(operation: string, percentile: number = 95): number {
    const relevant = this.metrics
      .filter(m => m.operation === operation && m.success)
      .map(m => m.duration)
      .sort((a, b) => a - b);

    if (relevant.length === 0) return 0;

    const index = Math.ceil((percentile / 100) * relevant.length) - 1;
    return relevant[index];
  }

  /**
   * Get all metrics for operation
   */
  getMetrics(operation: string): {
    count: number;
    avg: number;
    min: number;
    max: number;
    p50: number;
    p95: number;
    p99: number;
    successRate: number;
  } {
    const relevant = this.metrics.filter(m => m.operation === operation);
    
    if (relevant.length === 0) {
      return {
        count: 0,
        avg: 0,
        min: 0,
        max: 0,
        p50: 0,
        p95: 0,
        p99: 0,
        successRate: 0,
      };
    }

    const durations = relevant.map(m => m.duration).sort((a, b) => a - b);
    const successful = relevant.filter(m => m.success).length;

    return {
      count: relevant.length,
      avg: durations.reduce((a, b) => a + b, 0) / durations.length,
      min: durations[0],
      max: durations[durations.length - 1],
      p50: durations[Math.floor(durations.length * 0.5)],
      p95: durations[Math.floor(durations.length * 0.95)],
      p99: durations[Math.floor(durations.length * 0.99)],
      successRate: (successful / relevant.length) * 100,
    };
  }

  /**
   * Get overall performance summary
   */
  getSummary(): {
    operations: Record<string, ReturnType<typeof this.getMetrics>>;
    totalOperations: number;
    avgLatency: number;
  } {
    const operations: Record<string, ReturnType<typeof this.getMetrics>> = {};
    const uniqueOps = new Set(this.metrics.map(m => m.operation));

    uniqueOps.forEach(op => {
      operations[op] = this.getMetrics(op);
    });

    const avgLatency = this.metrics.length > 0
      ? this.metrics.reduce((acc, m) => acc + m.duration, 0) / this.metrics.length
      : 0;

    return {
      operations,
      totalOperations: this.metrics.length,
      avgLatency,
    };
  }

  /**
   * Subscribe to performance alerts
   */
  onAlert(callback: (metric: PerformanceMetric) => void): () => void {
    this.alertCallbacks.add(callback);
    return () => this.alertCallbacks.delete(callback);
  }

  /**
   * Update thresholds
   */
  setThreshold(operation: string, threshold: number): void {
    this.thresholds[operation] = threshold;
  }

  /**
   * Clear metrics
   */
  clear(): void {
    this.metrics = [];
  }
}

export const performanceMonitor = new PerformanceMonitorService();

/**
 * Performance Optimizer Service
 * Provides utilities for optimizing app performance
 */

// Lazy load heavy modules
export async function preloadCriticalModules(): Promise<void> {
  // Preload orchestrator tools in background
  const preloadPromises = [
    import('@/services/orchestrator/tools'),
    import('@/services/orchestrator/executor'),
  ];
  
  await Promise.all(preloadPromises);
}

// Memory cleanup utility
export function cleanupMemory(): void {
  // Clear any cached data that's no longer needed
  if ('gc' in window && typeof (window as any).gc === 'function') {
    (window as any).gc();
  }
}

// Debounce utility with proper typing
export function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: ReturnType<typeof setTimeout> | null = null;
  
  return (...args: Parameters<T>) => {
    if (timeout) clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), wait);
  };
}

// Throttle utility
export function throttle<T extends (...args: any[]) => any>(
  func: T,
  limit: number
): (...args: Parameters<T>) => void {
  let inThrottle = false;
  
  return (...args: Parameters<T>) => {
    if (!inThrottle) {
      func(...args);
      inThrottle = true;
      setTimeout(() => (inThrottle = false), limit);
    }
  };
}

// Request idle callback polyfill
export function requestIdleCallback(
  callback: () => void,
  options?: { timeout: number }
): number {
  if ('requestIdleCallback' in window) {
    return (window as any).requestIdleCallback(callback, options);
  }
  
  // Fallback for browsers without requestIdleCallback
  return setTimeout(callback, options?.timeout || 1) as unknown as number;
}

// Cancel idle callback polyfill
export function cancelIdleCallback(id: number): void {
  if ('cancelIdleCallback' in window) {
    (window as any).cancelIdleCallback(id);
  } else {
    clearTimeout(id);
  }
}

// Measure performance
export function measurePerformance(name: string): () => number {
  const start = performance.now();
  
  return () => {
    const duration = performance.now() - start;
    console.log(`[Performance] ${name}: ${duration.toFixed(2)}ms`);
    return duration;
  };
}

// Check if device is low-end
export function isLowEndDevice(): boolean {
  // Check for low memory
  if ('deviceMemory' in navigator) {
    const memory = (navigator as any).deviceMemory;
    if (memory && memory < 4) return true;
  }
  
  // Check for slow CPU
  if ('hardwareConcurrency' in navigator) {
    if (navigator.hardwareConcurrency < 4) return true;
  }
  
  return false;
}

// Optimize images for device
export function getOptimalImageSize(): 'small' | 'medium' | 'large' {
  const width = window.innerWidth;
  const dpr = window.devicePixelRatio || 1;
  const effectiveWidth = width * dpr;
  
  if (effectiveWidth < 640) return 'small';
  if (effectiveWidth < 1280) return 'medium';
  return 'large';
}

// Preconnect to critical origins
export function preconnectOrigins(): void {
  const origins = [
    'https://api.openai.com',
    'https://fjhvhjlicrujksplxzyh.supabase.co',
  ];
  
  origins.forEach(origin => {
    const link = document.createElement('link');
    link.rel = 'preconnect';
    link.href = origin;
    link.crossOrigin = 'anonymous';
    document.head.appendChild(link);
  });
}

// Initialize performance optimizations
export function initializePerformanceOptimizations(): void {
  // Preconnect to critical origins
  preconnectOrigins();
  
  // Preload critical modules when idle
  requestIdleCallback(() => {
    preloadCriticalModules();
  }, { timeout: 5000 });
  
  // Log device capabilities
  if (process.env.NODE_ENV === 'development') {
    console.log('[Performance] Low-end device:', isLowEndDevice());
    console.log('[Performance] Optimal image size:', getOptimalImageSize());
  }
}

