// RAG Architecture Knowledge from the PDF
const RAG_ARCHITECTURES_KNOWLEDGE = `
# 9 RAG Architectures Every AI Developer Must Know

## 1. Simple RAG (Naive RAG)
The foundational architecture that retrieves relevant documents and passes them to an LLM.
- Components: Document Store, Retriever, LLM
- Flow: Query ΓåÆ Retrieve ΓåÆ Generate
- Best for: Simple Q&A, basic document search
- Limitations: No query refinement, single retrieval step

## 2. Simple RAG with Memory
Extends Simple RAG by maintaining conversation history.
- Adds: Conversation Memory, Context Window Management
- Benefits: Multi-turn conversations, context awareness
- Use cases: Chatbots, customer support

## 3. Branched RAG Pipeline
Uses multiple specialized retrievers for different document types.
- Components: Query Router, Multiple Retrievers, Result Merger
- Benefits: Optimized retrieval per document type
- Use cases: Multi-source knowledge bases, heterogeneous data

## 4. Adaptive RAG
Dynamically adjusts retrieval strategy based on query complexity.
- Features: Query Classifier, Strategy Selector, Fallback Mechanisms
- Benefits: Efficient resource usage, better accuracy
- Use cases: Variable complexity queries, production systems

## 5. Corrective RAG (CRAG)
Implements self-correction mechanisms for retrieved content.
- Components: Relevance Evaluator, Correction Module, Web Search Fallback
- Flow: Retrieve ΓåÆ Evaluate ΓåÆ Correct/Fallback ΓåÆ Generate
- Benefits: Higher accuracy, handles retrieval failures
- Use cases: High-stakes applications, factual accuracy critical

## 6. Self-RAG
The LLM critiques and refines its own outputs.
- Features: Self-Reflection, Output Scoring, Iterative Refinement
- Benefits: Improved response quality, reduced hallucinations
- Use cases: Research, complex reasoning tasks

## 7. Agentic RAG
Combines RAG with autonomous agents for complex tasks.
- Components: Planning Agent, Tool Use, Multi-step Reasoning
- Benefits: Complex task handling, dynamic tool selection
- Use cases: Research assistants, complex workflows

## 8. Graph RAG
Uses knowledge graphs for structured relationship retrieval.
- Components: Knowledge Graph, Graph Traversal, Entity Linking
- Benefits: Relationship-aware retrieval, structured knowledge
- Use cases: Entity-rich domains, relationship queries

## 9. Modular RAG
Highly customizable architecture with interchangeable components.
- Features: Plugin Architecture, Component Registry, Dynamic Assembly
- Benefits: Maximum flexibility, easy experimentation
- Use cases: Research, custom enterprise solutions

## Key Concepts

### Chunking Strategies
- Fixed-size chunks: Simple, consistent
- Semantic chunking: Meaning-preserving
- Recursive chunking: Hierarchical structure
- Sentence-based: Natural boundaries

### Embedding Models
- OpenAI text-embedding-ada-002
- Sentence Transformers
- Cohere Embed
- Custom fine-tuned models

### Vector Databases
- Pinecone: Managed, scalable
- Weaviate: Open-source, GraphQL
- Chroma: Lightweight, local
- Qdrant: High-performance
- Milvus: Enterprise-grade

### Retrieval Strategies
- Dense retrieval: Semantic similarity
- Sparse retrieval: Keyword matching (BM25)
- Hybrid: Combines both approaches
- Re-ranking: Two-stage retrieval

### Evaluation Metrics
- Retrieval: Precision, Recall, MRR, NDCG
- Generation: BLEU, ROUGE, BERTScore
- End-to-end: Answer accuracy, faithfulness

## Best Practices
1. Start simple, add complexity as needed
2. Evaluate retrieval quality separately from generation
3. Use hybrid retrieval for production systems
4. Implement caching for common queries
5. Monitor and log retrieval performance
6. Consider query expansion for better recall
7. Use metadata filtering when applicable
8. Implement fallback mechanisms
`;

// Track initialization to prevent duplicates
const initializationCache = new Map<string, Promise<void>>();

/**
 * Initialize RAG knowledge base with built-in knowledge
 */
export async function initializeRAGKnowledge(userId: string): Promise<void> {
  // Check if already initializing or initialized
  if (initializationCache.has(userId)) {
    return initializationCache.get(userId);
  }
  
  const initPromise = (async () => {
    try {
      console.log(`[RAG] Initializing knowledge base for user: ${userId}`);
      
      // Initialize offline knowledge cache
      await offlineKnowledge.initialize(userId);
    
    // Check if RAG architectures knowledge already exists
    const { data: existing, error: checkError } = await supabase
      .from("rag_documents")
      .select("id")
      .eq("user_id", userId)
      .eq("title", "RAG Architectures Guide")
      .maybeSingle();

    // Ignore PGRST116 error (no rows found)
    if (checkError && checkError.code !== 'PGRST116') {
      console.error("Error checking RAG document:", checkError);
    }

    if (!existing) {
      // Add the RAG architectures knowledge
      await addDocument(userId, {
        title: "RAG Architectures Guide",
        content: RAG_ARCHITECTURES_KNOWLEDGE,
        sourceType: "manual",
        metadata: {
          category: "AI/ML",
          tags: ["RAG", "AI", "architecture", "retrieval", "LLM"],
        },
      });
    }
    
    // Cache all documents for offline use
    const documents = await listDocuments(userId);
    await offlineKnowledge.cacheDocuments(userId, documents);
    
    console.log(`[RAG] Knowledge base initialized successfully`);
  } catch (error) {
    console.error("Failed to initialize RAG knowledge:", error);
    initializationCache.delete(userId); // Allow retry on error
  }
  })();
  
  initializationCache.set(userId, initPromise);
  return initPromise;
}

/**
 * Add a document to the knowledge base
 */
export async function addDocument(
  userId: string,
  doc: {
    title: string;
    content: string;
    sourceType: "manual" | "pdf" | "url" | "file";
    sourceUrl?: string;
    filePath?: string;
    metadata?: Record<string, any>;
  }
): Promise<{ success: boolean; document?: RAGDocument; error?: string }> {
  try {
    // Chunk the document
    const chunks = chunkDocument(doc.content);

    const { data, error } = await supabase
      .from("rag_documents")
      .insert({
        user_id: userId,
        title: doc.title,
        content: doc.content,
        source_type: doc.sourceType,
        source_url: doc.sourceUrl,
        file_path: doc.filePath,
        chunks: chunks,
        metadata: doc.metadata || {},
      })
      .select()
      .single();

    if (error) throw error;

    const document: RAGDocument = {
      id: data.id,
      userId: data.user_id,
      title: data.title,
      content: data.content,
      sourceType: data.source_type,
      sourceUrl: data.source_url,
      filePath: data.file_path,
      chunks: data.chunks,
      metadata: data.metadata,
      createdAt: new Date(data.created_at),
    };
    
    // Update offline cache
    const allDocs = await listDocuments(userId);
    await offlineKnowledge.cacheDocuments(userId, allDocs);

    return { success: true, document };
  } catch (error: any) {
    return { success: false, error: error.message };
  }
}

/**
 * Search the knowledge base (with offline support)
 */
export async function searchKnowledge(
  userId: string,
  query: string,
  options: {
    limit?: number;
    category?: string;
    tags?: string[];
  } = {}
): Promise<SearchResult[]> {
  const { limit = 5, category, tags } = options;
  const isOnline = navigator.onLine;
  
  // Use offline knowledge if not online
  if (!isOnline) {
    const offlineResults = offlineKnowledge.searchOffline(query, limit);
    return offlineResults.map(doc => ({
      document: {
        id: doc.id,
        userId,
        title: doc.title,
        content: doc.content,
        sourceType: 'manual' as const,
        chunks: [],
        metadata: { category: doc.category },
        createdAt: new Date(doc.timestamp),
      },
      chunk: {
        id: 'chunk-0',
        content: doc.content,
        startIndex: 0,
        endIndex: doc.content.length,
      },
      relevanceScore: 0.8,
    }));
  }
  
  const results: SearchResult[] = [];

  try {
    let dbQuery = supabase
      .from("rag_documents")
      .select("*")
      .eq("user_id", userId);

    if (category) {
      dbQuery = dbQuery.contains("metadata", { category });
    }

    const { data: documents } = await dbQuery;

    if (!documents) return results;

    // Simple keyword-based search (in production, use vector similarity)
    const queryTerms = query.toLowerCase().split(/\s+/);

    for (const doc of documents) {
      const chunks: DocumentChunk[] = doc.chunks || [];

      for (const chunk of chunks) {
        const chunkLower = chunk.content.toLowerCase();
        let score = 0;

        // Calculate relevance score based on term matches
        for (const term of queryTerms) {
          if (chunkLower.includes(term)) {
            score += 1;
            // Bonus for exact phrase match
            if (chunkLower.includes(query.toLowerCase())) {
              score += 2;
            }
          }
        }

        if (score > 0) {
          results.push({
            chunk,
            document: {
              id: doc.id,
              userId: doc.user_id,
              title: doc.title,
              content: doc.content,
              sourceType: doc.source_type,
              sourceUrl: doc.source_url,
              filePath: doc.file_path,
              chunks: doc.chunks,
              metadata: doc.metadata,
              createdAt: new Date(doc.created_at),
            },
            relevanceScore: score / queryTerms.length,
          });
        }
      }
    }

    // Sort by relevance and limit
    results.sort((a, b) => b.relevanceScore - a.relevanceScore);
    return results.slice(0, limit);
  } catch (error) {
    console.error("Knowledge search failed:", error);
    return [];
  }
}

/**
 * Get knowledge context for AI prompts
 */
export async function getKnowledgeContext(
  userId: string,
  query: string,
  maxTokens: number = 2000
): Promise<string> {
  const results = await searchKnowledge(userId, query, { limit: 3 });

  if (results.length === 0) {
    return "";
  }

  let context = "Relevant knowledge from your documents:\n\n";
  let tokenEstimate = 0;

  for (const result of results) {
    const chunkText = `From "${result.document.title}":\n${result.chunk.content}\n\n`;
    const chunkTokens = chunkText.length / 4; // Rough estimate

    if (tokenEstimate + chunkTokens > maxTokens) break;

    context += chunkText;
    tokenEstimate += chunkTokens;
  }

  return context;
}

/**
 * Chunk a document into smaller pieces
 */
function chunkDocument(content: string, chunkSize: number = 500, overlap: number = 50): DocumentChunk[] {
  const chunks: DocumentChunk[] = [];
  const paragraphs = content.split(/\n\n+/);

  let currentChunk = "";
  let startIndex = 0;
  let chunkId = 0;

  for (const paragraph of paragraphs) {
    if (currentChunk.length + paragraph.length > chunkSize && currentChunk.length > 0) {
      // Save current chunk
      chunks.push({
        id: `chunk-${chunkId++}`,
        content: currentChunk.trim(),
        startIndex,
        endIndex: startIndex + currentChunk.length,
      });

      // Start new chunk with overlap
      const overlapText = currentChunk.slice(-overlap);
      startIndex = startIndex + currentChunk.length - overlap;
      currentChunk = overlapText;
    }

    currentChunk += (currentChunk ? "\n\n" : "") + paragraph;
  }

  // Don't forget the last chunk
  if (currentChunk.trim()) {
    chunks.push({
      id: `chunk-${chunkId}`,
      content: currentChunk.trim(),
      startIndex,
      endIndex: startIndex + currentChunk.length,
    });
  }

  return chunks;
}

/**
 * Delete a document from the knowledge base
 */
export async function deleteDocument(
  userId: string,
  documentId: string
): Promise<{ success: boolean; error?: string }> {
  try {
    const { error } = await supabase
      .from("rag_documents")
      .delete()
      .eq("id", documentId)
      .eq("user_id", userId);

    if (error) throw error;
    
    // Update offline cache
    const allDocs = await listDocuments(userId);
    await offlineKnowledge.cacheDocuments(userId, allDocs);

    return { success: true };
  } catch (error: any) {
    return { success: false, error: error.message };
  }
}

/**
 * List all documents in the knowledge base
 */
export async function listDocuments(userId: string): Promise<RAGDocument[]> {
  try {
    const { data, error } = await supabase
      .from("rag_documents")
      .select("*")
      .eq("user_id", userId)
      .order("created_at", { ascending: false });

    if (error) throw error;

    return (data || []).map(doc => ({
      id: doc.id,
      userId: doc.user_id,
      title: doc.title,
      content: doc.content,
      sourceType: doc.source_type,
      sourceUrl: doc.source_url,
      filePath: doc.file_path,
      chunks: doc.chunks || [],
      metadata: doc.metadata || {},
      createdAt: new Date(doc.created_at),
    }));
  } catch (error) {
    console.error("Failed to list documents:", error);
    return [];
  }
}

"use client";

/**
 * Real-time Collaboration Service
 * Enables multi-user support and real-time synchronization
 * Foundation for future collaborative features
 */

interface CollaborationUser {
  id: string;
  name: string;
  email: string;
  avatar?: string;
  status: 'online' | 'away' | 'offline';
  lastSeen: number;
  cursor?: { x: number; y: number; page: string };
}

interface CollaborationEvent {
  id: string;
  type: 'join' | 'leave' | 'update' | 'cursor' | 'action' | 'message';
  userId: string;
  timestamp: number;
  data: Record<string, any>;
}

interface SharedState {
  version: number;
  lastModified: number;
  modifiedBy: string;
  data: Record<string, any>;
}

interface CollaborationRoom {
  id: string;
  name: string;
  users: Map<string, CollaborationUser>;
  state: SharedState;
  events: CollaborationEvent[];
  createdAt: number;
}

type EventCallback = (event: CollaborationEvent) => void;
type StateCallback = (state: SharedState) => void;

class RealTimeCollaborationService {
  private currentUser: CollaborationUser | null = null;
  private rooms: Map<string, CollaborationRoom> = new Map();
  private activeRoom: string | null = null;
  private eventListeners: Map<string, Set<EventCallback>> = new Map();
  private stateListeners: Map<string, Set<StateCallback>> = new Map();
  private heartbeatInterval: NodeJS.Timeout | null = null;
  private isConnected = false;

  /**
   * Initialize the collaboration service
   */
  initialize(user: { id: string; name: string; email: string; avatar?: string }): void {
    this.currentUser = {
      ...user,
      status: 'online',
      lastSeen: Date.now()
    };
    
    this.startHeartbeat();
    this.isConnected = true;
    
    console.log('[real-time-collaboration] Initialized for user:', user.name);
  }

  /**
   * Start heartbeat to maintain presence
   */
  private startHeartbeat(): void {
    this.heartbeatInterval = setInterval(() => {
      if (this.currentUser) {
        this.currentUser.lastSeen = Date.now();
        this.broadcastPresence();
      }
    }, 30000); // Every 30 seconds
  }

  /**
   * Stop heartbeat
   */
  private stopHeartbeat(): void {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }
  }

  /**
   * Broadcast presence to active room
   */
  private broadcastPresence(): void {
    if (!this.activeRoom || !this.currentUser) return;
    
    this.emitEvent(this.activeRoom, {
      type: 'update',
      data: { status: this.currentUser.status, lastSeen: this.currentUser.lastSeen }
    });
  }

  /**
   * Create a new collaboration room
   */
  createRoom(name: string): CollaborationRoom {
    const roomId = `room_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    
    const room: CollaborationRoom = {
      id: roomId,
      name,
      users: new Map(),
      state: {
        version: 0,
        lastModified: Date.now(),
        modifiedBy: this.currentUser?.id || 'system',
        data: {}
      },
      events: [],
      createdAt: Date.now()
    };
    
    this.rooms.set(roomId, room);
    console.log('[real-time-collaboration] Created room:', name);
    
    return room;
  }

  /**
   * Join a collaboration room
   */
  joinRoom(roomId: string): boolean {
    const room = this.rooms.get(roomId);
    if (!room || !this.currentUser) return false;
    
    // Add user to room
    room.users.set(this.currentUser.id, this.currentUser);
    this.activeRoom = roomId;
    
    // Emit join event
    this.emitEvent(roomId, {
      type: 'join',
      data: { user: this.currentUser }
    });
    
    console.log('[real-time-collaboration] Joined room:', room.name);
    return true;
  }

  /**
   * Leave current room
   */
  leaveRoom(): void {
    if (!this.activeRoom || !this.currentUser) return;
    
    const room = this.rooms.get(this.activeRoom);
    if (room) {
      // Emit leave event
      this.emitEvent(this.activeRoom, {
        type: 'leave',
        data: { userId: this.currentUser.id }
      });
      
      // Remove user from room
      room.users.delete(this.currentUser.id);
      console.log('[real-time-collaboration] Left room:', room.name);
    }
    
    this.activeRoom = null;
  }

  /**
   * Update shared state
   */
  updateState(path: string, value: any): void {
    if (!this.activeRoom || !this.currentUser) return;
    
    const room = this.rooms.get(this.activeRoom);
    if (!room) return;
    
    // Update state
    const pathParts = path.split('.');
    let current = room.state.data;
    
    for (let i = 0; i < pathParts.length - 1; i++) {
      if (!current[pathParts[i]]) {
        current[pathParts[i]] = {};
      }
      current = current[pathParts[i]];
    }
    
    current[pathParts[pathParts.length - 1]] = value;
    
    // Update metadata
    room.state.version++;
    room.state.lastModified = Date.now();
    room.state.modifiedBy = this.currentUser.id;
    
    // Emit update event
    this.emitEvent(this.activeRoom, {
      type: 'update',
      data: { path, value, version: room.state.version }
    });
    
    // Notify state listeners
    this.notifyStateListeners(this.activeRoom, room.state);
  }

  /**
   * Get shared state
   */
  getState(path?: string): any {
    if (!this.activeRoom) return null;
    
    const room = this.rooms.get(this.activeRoom);
    if (!room) return null;
    
    if (!path) return room.state.data;
    
    const pathParts = path.split('.');
    let current = room.state.data;
    
    for (const part of pathParts) {
      if (current[part] === undefined) return undefined;
      current = current[part];
    }
    
    return current;
  }

  /**
   * Update cursor position
   */
  updateCursor(x: number, y: number, page: string): void {
    if (!this.activeRoom || !this.currentUser) return;
    
    this.currentUser.cursor = { x, y, page };
    
    this.emitEvent(this.activeRoom, {
      type: 'cursor',
      data: { cursor: this.currentUser.cursor }
    });
  }

  /**
   * Send a message to the room
   */
  sendMessage(content: string): void {
    if (!this.activeRoom || !this.currentUser) return;
    
    this.emitEvent(this.activeRoom, {
      type: 'message',
      data: { content, sender: this.currentUser.name }
    });
  }

  /**
   * Emit an event to a room
   */
  private emitEvent(roomId: string, eventData: Omit<CollaborationEvent, 'id' | 'userId' | 'timestamp'>): void {
    const room = this.rooms.get(roomId);
    if (!room || !this.currentUser) return;
    
    const event: CollaborationEvent = {
      id: `event_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      userId: this.currentUser.id,
      timestamp: Date.now(),
      ...eventData
    };
    
    // Store event
    room.events.push(event);
    
    // Keep only last 1000 events
    if (room.events.length > 1000) {
      room.events = room.events.slice(-1000);
    }
    
    // Notify listeners
    this.notifyEventListeners(roomId, event);
  }

  /**
   * Subscribe to room events
   */
  onEvent(roomId: string, callback: EventCallback): () => void {
    if (!this.eventListeners.has(roomId)) {
      this.eventListeners.set(roomId, new Set());
    }
    
    this.eventListeners.get(roomId)!.add(callback);
    
    return () => {
      this.eventListeners.get(roomId)?.delete(callback);
    };
  }

  /**
   * Subscribe to state changes
   */
  onStateChange(roomId: string, callback: StateCallback): () => void {
    if (!this.stateListeners.has(roomId)) {
      this.stateListeners.set(roomId, new Set());
    }
    
    this.stateListeners.get(roomId)!.add(callback);
    
    return () => {
      this.stateListeners.get(roomId)?.delete(callback);
    };
  }

  /**
   * Notify event listeners
   */
  private notifyEventListeners(roomId: string, event: CollaborationEvent): void {
    this.eventListeners.get(roomId)?.forEach(callback => {
      try {
        callback(event);
      } catch (error) {
        console.error('[real-time-collaboration] Event listener error:', error);
      }
    });
  }

  /**
   * Notify state listeners
   */
  private notifyStateListeners(roomId: string, state: SharedState): void {
    this.stateListeners.get(roomId)?.forEach(callback => {
      try {
        callback(state);
      } catch (error) {
        console.error('[real-time-collaboration] State listener error:', error);
      }
    });
  }

  /**
   * Get users in a room
   */
  getRoomUsers(roomId?: string): CollaborationUser[] {
    const targetRoom = roomId || this.activeRoom;
    if (!targetRoom) return [];
    
    const room = this.rooms.get(targetRoom);
    return room ? Array.from(room.users.values()) : [];
  }

  /**
   * Get online users count
   */
  getOnlineCount(roomId?: string): number {
    const users = this.getRoomUsers(roomId);
    return users.filter(u => u.status === 'online').length;
  }

  /**
   * Set user status
   */
  setStatus(status: 'online' | 'away' | 'offline'): void {
    if (!this.currentUser) return;
    
    this.currentUser.status = status;
    this.broadcastPresence();
  }

  /**
   * Get room info
   */
  getRoomInfo(roomId?: string): CollaborationRoom | null {
    const targetRoom = roomId || this.activeRoom;
    if (!targetRoom) return null;
    
    return this.rooms.get(targetRoom) || null;
  }

  /**
   * Get all rooms
   */
  getAllRooms(): CollaborationRoom[] {
    return Array.from(this.rooms.values());
  }

  /**
   * Get recent events
   */
  getRecentEvents(roomId?: string, limit: number = 50): CollaborationEvent[] {
    const targetRoom = roomId || this.activeRoom;
    if (!targetRoom) return [];
    
    const room = this.rooms.get(targetRoom);
    return room ? room.events.slice(-limit) : [];
  }

  /**
   * Check if connected
   */
  isActive(): boolean {
    return this.isConnected && this.currentUser !== null;
  }

  /**
   * Get current user
   */
  getCurrentUser(): CollaborationUser | null {
    return this.currentUser;
  }

  /**
   * Disconnect and cleanup
   */
  disconnect(): void {
    this.leaveRoom();
    this.stopHeartbeat();
    
    if (this.currentUser) {
      this.currentUser.status = 'offline';
    }
    
    this.isConnected = false;
    this.currentUser = null;
    
    console.log('[real-time-collaboration] Disconnected');
  }

  /**
   * Get collaboration stats
   */
  getStats(): {
    isConnected: boolean;
    activeRoom: string | null;
    totalRooms: number;
    totalUsers: number;
    recentEvents: number;
  } {
    let totalUsers = 0;
    let recentEvents = 0;
    
    this.rooms.forEach(room => {
      totalUsers += room.users.size;
      recentEvents += room.events.filter(e => 
        Date.now() - e.timestamp < 3600000 // Last hour
      ).length;
    });
    
    return {
      isConnected: this.isConnected,
      activeRoom: this.activeRoom,
      totalRooms: this.rooms.size,
      totalUsers,
      recentEvents
    };
  }
}

export const realTimeCollaboration = new RealTimeCollaborationService();

