  try {
    // Just check critical systems
    const toolsOk = AVAILABLE_TOOLS.length > 50;
    const storageOk = (() => {
      try {
        localStorage.setItem('__test__', '1');
        localStorage.removeItem('__test__');
        return true;
      } catch {
        return false;
      }
    })();
    
    return toolsOk && storageOk;
  } catch {
    return false;
  }
}

/**
 * System Health Check Service
 * Provides utilities for monitoring system health and diagnostics
 */

import { supabase } from '@/integrations/supabase/client';
// Dynamic import for web-llm to prevent blocking
let webLLMModule: { webLLM: any; isWebLLMSupported: () => boolean } | null = null;

async function getWebLLMModule() {
  if (!webLLMModule) {
    try {
      const module = await import('./web-llm');
      webLLMModule = {
        webLLM: module.webLLM,
        isWebLLMSupported: module.isWebLLMSupported,
      };
    } catch (error) {
      console.warn('[SystemHealth] Failed to load web-llm module:', error);
      webLLMModule = {
        webLLM: null,
        isWebLLMSupported: () => false,
      };
    }
  }
  return webLLMModule;
}

export interface HealthCheckResult {
  component: string;
  status: 'healthy' | 'degraded' | 'unhealthy';
  latency?: number;
  message?: string;
  details?: Record<string, any>;
}

export interface SystemHealthReport {
  timestamp: string;
  overall: 'healthy' | 'degraded' | 'unhealthy';
  checks: HealthCheckResult[];
  metrics: {
    memoryUsage?: number;
    connectionCount?: number;
    cacheSize?: number;
  };
}

// Check Supabase connection
async function checkSupabase(): Promise<HealthCheckResult> {
  const start = performance.now();
  
  try {
    const { error } = await supabase.from('profiles').select('id').limit(1);
    const latency = performance.now() - start;
    
    if (error) {
      return {
        component: 'Supabase',
        status: 'unhealthy',
        latency,
        message: error.message,
      };
    }
    
    return {
      component: 'Supabase',
      status: latency < 1000 ? 'healthy' : 'degraded',
      latency,
      message: latency < 1000 ? 'Connected' : 'Slow response',
    };
  } catch (error: any) {
    return {
      component: 'Supabase',
      status: 'unhealthy',
      latency: performance.now() - start,
      message: error.message || 'Connection failed',
    };
  }
}

// Check OpenAI API
async function checkOpenAI(apiKey?: string): Promise<HealthCheckResult> {
  if (!apiKey) {
    return {
      component: 'OpenAI',
      status: 'degraded',
      message: 'API key not configured',
    };
  }
  
  const start = performance.now();
  
  try {
    const response = await fetch('https://api.openai.com/v1/models', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
      },
    });
    
    const latency = performance.now() - start;
    
    if (!response.ok) {
      return {
        component: 'OpenAI',
        status: 'unhealthy',
        latency,
        message: `API error: ${response.status}`,
      };
    }
    
    return {
      component: 'OpenAI',
      status: latency < 2000 ? 'healthy' : 'degraded',
      latency,
      message: 'Connected',
    };
  } catch (error: any) {
    return {
      component: 'OpenAI',
      status: 'unhealthy',
      latency: performance.now() - start,
      message: error.message || 'Connection failed',
    };
  }
}

// Check WebLLM (offline AI)
async function checkWebLLM(): Promise<HealthCheckResult> {
  try {
    const { webLLM, isWebLLMSupported } = await getWebLLMModule();
    
    if (!isWebLLMSupported()) {
      return {
        component: 'WebLLM',
        status: 'degraded',
        message: 'WebGPU not supported',
      };
    }
    
    if (!webLLM) {
      return {
        component: 'WebLLM',
        status: 'degraded',
        message: 'WebLLM module not available',
      };
    }
    
    const cached = await webLLM.isModelCached();
    const status = webLLM.getStatus();
    
    return {
      component: 'WebLLM',
      status: cached ? 'healthy' : 'degraded',
      message: cached ? 'Model cached and ready' : 'Model not downloaded',
      details: {
        modelId: status.modelId,
        isInitialized: status.isInitialized,
      },
    };
  } catch (error: any) {
    return {
      component: 'WebLLM',
      status: 'degraded',
      message: error.message || 'Check failed',
    };
  }
}

// Check browser capabilities
function checkBrowserCapabilities(): HealthCheckResult {
  const capabilities = {
    webGPU: 'gpu' in navigator,
    serviceWorker: 'serviceWorker' in navigator,
    indexedDB: 'indexedDB' in window,
    webSpeech: 'webkitSpeechRecognition' in window || 'SpeechRecognition' in window,
    mediaRecorder: 'MediaRecorder' in window,
    geolocation: 'geolocation' in navigator,
  };
  
  const supported = Object.values(capabilities).filter(Boolean).length;
  const total = Object.keys(capabilities).length;
  
  return {
    component: 'Browser',
    status: supported >= total - 1 ? 'healthy' : supported >= total - 2 ? 'degraded' : 'unhealthy',
    message: `${supported}/${total} capabilities supported`,
    details: capabilities,
  };
}

// Check network status
function checkNetwork(): HealthCheckResult {
  const online = navigator.onLine;
  const connection = (navigator as any).connection;
  
  const details: Record<string, any> = {
    online,
  };
  
  if (connection) {
    details.effectiveType = connection.effectiveType;
    details.downlink = connection.downlink;
    details.rtt = connection.rtt;
  }
  
  let status: 'healthy' | 'degraded' | 'unhealthy' = 'healthy';
  let message = 'Online';
  
  if (!online) {
    status = 'degraded';
    message = 'Offline mode';
  } else if (connection?.effectiveType === '2g' || connection?.effectiveType === 'slow-2g') {
    status = 'degraded';
    message = 'Slow connection';
  }
  
  return {
    component: 'Network',
    status,
    message,
    details,
  };
}

// Check memory usage
function checkMemory(): HealthCheckResult {
  const memory = (performance as any).memory;
  
  if (!memory) {
    return {
      component: 'Memory',
      status: 'healthy',
      message: 'Memory API not available',
    };
  }
  
  const usedMB = Math.round(memory.usedJSHeapSize / 1024 / 1024);
  const totalMB = Math.round(memory.jsHeapSizeLimit / 1024 / 1024);
  const usagePercent = Math.round((memory.usedJSHeapSize / memory.jsHeapSizeLimit) * 100);
  
  let status: 'healthy' | 'degraded' | 'unhealthy' = 'healthy';
  if (usagePercent > 80) status = 'unhealthy';
  else if (usagePercent > 60) status = 'degraded';
  
  return {
    component: 'Memory',
    status,
    message: `${usedMB}MB / ${totalMB}MB (${usagePercent}%)`,
    details: {
      usedMB,
      totalMB,
      usagePercent,
    },
  };
}

// Check voice system
function checkVoiceSystem(): HealthCheckResult {
  const hasMediaRecorder = 'MediaRecorder' in window;
  const hasAudioContext = 'AudioContext' in window || 'webkitAudioContext' in window;
  const hasSpeechSynthesis = 'speechSynthesis' in window;
  
  const allSupported = hasMediaRecorder && hasAudioContext && hasSpeechSynthesis;
  
  return {
    component: 'Voice',
    status: allSupported ? 'healthy' : 'degraded',
    message: allSupported ? 'All voice features supported' : 'Some features unavailable',
    details: {
      mediaRecorder: hasMediaRecorder,
      audioContext: hasAudioContext,
      speechSynthesis: hasSpeechSynthesis,
    },
  };
}

// Run full health check
export async function runHealthCheck(openaiApiKey?: string): Promise<SystemHealthReport> {
  const checks: HealthCheckResult[] = [];
  
  // Run all checks
  checks.push(checkNetwork());
  checks.push(checkBrowserCapabilities());
  checks.push(checkMemory());
  checks.push(checkVoiceSystem());
  checks.push(await checkSupabase());
  checks.push(await checkWebLLM());
  
  // Only check OpenAI if key provided
  if (openaiApiKey) {
    checks.push(await checkOpenAI(openaiApiKey));
  }
  
  // Determine overall status
  const unhealthyCount = checks.filter(c => c.status === 'unhealthy').length;
  const degradedCount = checks.filter(c => c.status === 'degraded').length;
  
  let overall: 'healthy' | 'degraded' | 'unhealthy' = 'healthy';
  if (unhealthyCount > 0) overall = 'unhealthy';
  else if (degradedCount > 1) overall = 'degraded';
  
  // Gather metrics
  const memory = (performance as any).memory;
  const metrics: SystemHealthReport['metrics'] = {};
  
  if (memory) {
    metrics.memoryUsage = Math.round(memory.usedJSHeapSize / 1024 / 1024);
  }
  
  return {
    timestamp: new Date().toISOString(),
    overall,
    checks,
    metrics,
  };
}

// Quick health check (synchronous, no network calls)
export function quickHealthCheck(): {
  status: 'healthy' | 'degraded' | 'unhealthy';
  issues: string[];
} {
  const issues: string[] = [];
  
  if (!navigator.onLine) {
    issues.push('Offline');
  }
  
  if (!('MediaRecorder' in window)) {
    issues.push('Voice recording unavailable');
  }
  
  if (!('gpu' in navigator)) {
    issues.push('Offline AI unavailable');
  }
  
  const memory = (performance as any).memory;
  if (memory && memory.usedJSHeapSize / memory.jsHeapSizeLimit > 0.8) {
    issues.push('High memory usage');
  }
  
  return {
    status: issues.length === 0 ? 'healthy' : issues.length <= 2 ? 'degraded' : 'unhealthy',
    issues,
  };
}

// Log health report to console
export function logHealthReport(report: SystemHealthReport): void {
  console.group(`[Health Check] ${report.overall.toUpperCase()} - ${report.timestamp}`);
  
  report.checks.forEach(check => {
    const icon = check.status === 'healthy' ? 'Γ£à' : check.status === 'degraded' ? 'ΓÜá∩╕Å' : 'Γ¥î';
    console.log(`${icon} ${check.component}: ${check.message}${check.latency ? ` (${check.latency.toFixed(0)}ms)` : ''}`);
  });
  
  if (Object.keys(report.metrics).length > 0) {
    console.log('Metrics:', report.metrics);
  }
  
  console.groupEnd();
}

"use client";

import { logger } from "@/utils/logger";
import { supabase } from "@/integrations/supabase/client";
import { intelligentScheduler } from "./intelligent-scheduler";
import { contextualAssistant } from "./contextual-assistant";
import { smartNotifications } from "./smart-notifications";
import { habitTracker } from "./habit-tracker";

interface VoiceNotification {
  id: string;
  type: 'traffic' | 'departure' | 'errand' | 'reminder' | 'event' | 'task' | 'system';
  message: string;
  priority: 'low' | 'medium' | 'high' | 'urgent';
  timestamp: number;
  spoken: boolean;
  metadata?: Record<string, any>;
}

/**
 * Unified Notification System
 * All notifications are spoken by Echo - no silent badges
 * Wired from location, time, traffic, calendar, tasks, etc.
 */
class UnifiedNotificationSystem {
  private queue: VoiceNotification[] = [];
  private isProcessing = false;
  private monitoringInterval: NodeJS.Timeout | null = null;

  /**
   * Start monitoring all systems
   */
  async startMonitoring(userId: string): Promise<void> {
    if (this.monitoringInterval) {
      logger.warn('UnifiedNotifications', 'Already monitoring');
      return;
    }

    logger.log('UnifiedNotifications', 'Started monitoring all systems');

    // Check every minute
    this.monitoringInterval = setInterval(async () => {
      await this.checkAllSystems(userId);
    }, 60000);

    // Initial check
    await this.checkAllSystems(userId);
  }

  /**
   * Stop monitoring
   */
  stopMonitoring(): void {
    if (this.monitoringInterval) {
      clearInterval(this.monitoringInterval);
      this.monitoringInterval = null;
      logger.log('UnifiedNotifications', 'Stopped monitoring');
    }
  }

  /**
   * Check all systems for notifications
   */
  private async checkAllSystems(userId: string): Promise<void> {
    // 1. Check traffic & departure times
    await this.checkTrafficAndDeparture(userId);

    // 2. Check time-based reminders
    await this.checkTimeBasedReminders(userId);

    // 3. Check location-based notifications
    await this.checkLocationNotifications(userId);

    // 4. Check calendar events
    await this.checkCalendarEvents(userId);

    // 5. Check task deadlines
    await this.checkTaskDeadlines(userId);

    // 6. Check errands on route
    await this.checkErrandsOnRoute(userId);

    // Process queue
    await this.processQueue();
  }

  /**
   * Check traffic and departure times (Your office to school scenario)
   */
  private async checkTrafficAndDeparture(userId: string): Promise<void> {
    try {
      // Get next event
      const { data: nextEvent } = await supabase
        .from('calendar_events')
        .select('*')
        .eq('user_id', userId)
        .gte('start_time', new Date().toISOString())
        .order('start_time', { ascending: true })
        .limit(1)
        .single();

      if (!nextEvent || !nextEvent.location) return;

      const eventTime = new Date(nextEvent.start_time).getTime();
      const now = Date.now();
      const minutesUntilEvent = (eventTime - now) / 60000;

      // Only check if event is within next 2 hours
      if (minutesUntilEvent > 120) return;

      // Get current location
      const currentLocation = await this.getCurrentLocation();
      if (!currentLocation) return;

      // Calculate travel time with traffic
      const travelTime = await intelligentScheduler['calculateTravelTime'](
        currentLocation,
        { lat: 0, lng: 0 }, // Event location (would geocode in production)
        eventTime
      );

      const travelMinutes = travelTime.duration / 60000;
      const bufferMinutes = 5;
      const shouldLeaveIn = minutesUntilEvent - travelMinutes - bufferMinutes;

      // Notify if should leave soon
      if (shouldLeaveIn <= 10 && shouldLeaveIn > 0) {
        const trafficStatus = travelTime.traffic === 'heavy' ? 'Traffic is heavy!' : 
                             travelTime.traffic === 'moderate' ? 'Moderate traffic.' : 
                             'Traffic is light.';

        this.queueNotification({
          type: 'departure',
          message: `Time to leave in ${Math.round(shouldLeaveIn)} minutes for ${nextEvent.title}. ${Math.round(travelMinutes)} minute drive. ${trafficStatus}`,
          priority: travelTime.traffic === 'heavy' ? 'urgent' : 'high',
          metadata: {
            eventId: nextEvent.id,
            travelTime: travelMinutes,
            traffic: travelTime.traffic,
          },
        });
      } else if (shouldLeaveIn <= 0) {
        this.queueNotification({
          type: 'departure',
          message: `Leave NOW for ${nextEvent.title}! ${Math.round(travelMinutes)} minute drive with ${travelTime.traffic} traffic.`,
          priority: 'urgent',
          metadata: {
            eventId: nextEvent.id,
            travelTime: travelMinutes,
            traffic: travelTime.traffic,
          },
        });
      }
    } catch (error) {
      logger.error('UnifiedNotifications', 'Traffic check failed:', error);
    }
  }

  /**
   * Check time-based reminders
   */
  private async checkTimeBasedReminders(userId: string): Promise<void> {
    try {
      const now = new Date();
      const fiveMinutesFromNow = new Date(now.getTime() + 5 * 60 * 1000);

      const { data: reminders } = await supabase
        .from('reminders')
        .select('*')
        .eq('user_id', userId)
        .eq('status', 'pending')
        .gte('due_time', now.toISOString())
        .lte('due_time', fiveMinutesFromNow.toISOString());

      if (reminders && reminders.length > 0) {
        reminders.forEach(reminder => {
          const dueTime = new Date(reminder.due_time);
          const minutesUntil = Math.round((dueTime.getTime() - now.getTime()) / 60000);

          this.queueNotification({
            type: 'reminder',
            message: `Reminder: ${reminder.text}. Due in ${minutesUntil} minute${minutesUntil !== 1 ? 's' : ''}.`,
            priority: minutesUntil <= 1 ? 'urgent' : 'high',
            metadata: { reminderId: reminder.id },
          });
        });
      }
    } catch (error) {
      logger.error('UnifiedNotifications', 'Reminder check failed:', error);
    }
  }

  /**
   * Check location-based notifications
   */
  private async checkLocationNotifications(userId: string): Promise<void> {
    // Check if user is near saved locations
    const currentLocation = await this.getCurrentLocation();
    if (!currentLocation) return;

    // This would check saved places and notify when nearby
    // "You're near the grocery store. Want to stop for milk?"
  }

  /**
   * Check calendar events
   */
  private async checkCalendarEvents(userId: string): Promise<void> {
    try {
      const now = new Date();
      const thirtyMinutesFromNow = new Date(now.getTime() + 30 * 60 * 1000);

      const { data: events } = await supabase
        .from('calendar_events')
        .select('*')
        .eq('user_id', userId)
        .gte('start_time', now.toISOString())
        .lte('start_time', thirtyMinutesFromNow.toISOString());

      if (events && events.length > 0) {
        events.forEach(event => {
          const startTime = new Date(event.start_time);
          const minutesUntil = Math.round((startTime.getTime() - now.getTime()) / 60000);

          this.queueNotification({
            type: 'event',
            message: `${event.title} starts in ${minutesUntil} minutes${event.location ? ` at ${event.location}` : ''}.`,
            priority: minutesUntil <= 10 ? 'high' : 'medium',
            metadata: { eventId: event.id },
          });
        });
      }
    } catch (error) {
      logger.error('UnifiedNotifications', 'Event check failed:', error);
    }
  }

  /**
   * Check task deadlines
   */
  private async checkTaskDeadlines(userId: string): Promise<void> {
    try {
      const now = new Date();
      const oneHourFromNow = new Date(now.getTime() + 60 * 60 * 1000);

      const { data: tasks } = await supabase
        .from('tasks')
        .select('*')
        .eq('user_id', userId)
        .eq('status', 'pending')
        .gte('due_date', now.toISOString())
        .lte('due_date', oneHourFromNow.toISOString());

      if (tasks && tasks.length > 0) {
        tasks.forEach(task => {
          const dueDate = new Date(task.due_date);
          const minutesUntil = Math.round((dueDate.getTime() - now.getTime()) / 60000);

          this.queueNotification({
            type: 'task',
            message: `Task "${task.title}" is due in ${minutesUntil} minutes.`,
            priority: task.priority === 'urgent' ? 'urgent' : 'medium',
            metadata: { taskId: task.id },
          });
        });
      }
    } catch (error) {
      logger.error('UnifiedNotifications', 'Task check failed:', error);
    }
  }

  /**
   * Check errands on route (Your milk scenario)
   */
  private async checkErrandsOnRoute(userId: string): Promise<void> {
    // Get pending errands from contextual assistant
    const context = contextualAssistant.getContext();
    
    if (context.pendingErrands.length > 0) {
      // Check if user is leaving (would need location tracking)
      // For now, notify when next event is coming up
      
      this.queueNotification({
        type: 'errand',
        message: `Before you go, remember to ${context.pendingErrands.join(', ')}.`,
        priority: 'high',
        metadata: { errands: context.pendingErrands },
      });
    }
  }

  /**
   * Queue notification
   */
  private queueNotification(notification: Omit<VoiceNotification, 'id' | 'timestamp' | 'spoken'>): void {
    const fullNotification: VoiceNotification = {
      ...notification,
      id: `notif-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      timestamp: Date.now(),
      spoken: false,
    };

    // Insert based on priority
    if (notification.priority === 'urgent') {
      this.queue.unshift(fullNotification);
    } else {
      this.queue.push(fullNotification);
    }

    logger.log('UnifiedNotifications', `Queued: ${notification.message}`);
  }

  /**
   * Process notification queue
   */
  private async processQueue(): Promise<void> {
    if (this.isProcessing || this.queue.length === 0) return;

    this.isProcessing = true;

    while (this.queue.length > 0) {
      const notification = this.queue.shift()!;
      
      if (notification.spoken) continue;

      // Speak notification
      await this.speakNotification(notification);
      
      notification.spoken = true;

      // Small delay between notifications
      await new Promise(resolve => setTimeout(resolve, 1000));
    }

    this.isProcessing = false;
  }

  /**
   * Speak notification with appropriate voice settings
   */
  private async speakNotification(notification: VoiceNotification): Promise<void> {
    const utterance = new SpeechSynthesisUtterance(notification.message);

    // Set voice parameters based on priority
    switch (notification.priority) {
      case 'urgent':
        utterance.volume = 1.0;
        utterance.rate = 1.0;
        utterance.pitch = 1.1; // Slightly higher pitch for urgency
        break;
      case 'high':
        utterance.volume = 0.9;
        utterance.rate = 1.0;
        utterance.pitch = 1.0;
        break;
      case 'medium':
        utterance.volume = 0.7;
        utterance.rate = 1.1;
        utterance.pitch = 1.0;
        break;
      case 'low':
        utterance.volume = 0.5;
        utterance.rate = 1.2;
        utterance.pitch = 0.9;
        break;
    }

    // Speak
    window.speechSynthesis.speak(utterance);

    // Also show browser notification
    if ('Notification' in window && Notification.permission === 'granted') {
      new Notification('Echo AI', {
        body: notification.message,
        icon: '/favicon.ico',
        tag: notification.id,
      });
    }

    logger.log('UnifiedNotifications', `Spoke: ${notification.message}`);
  }

  /**
   * Get current location
   */
  private async getCurrentLocation(): Promise<{ lat: number; lng: number } | null> {
    try {
      const position = await new Promise<GeolocationPosition>((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject);
      });

      return {
        lat: position.coords.latitude,
        lng: position.coords.longitude,
      };
    } catch (error) {
      return null;
    }
  }

  /**
   * Manually trigger notification
   */
  async notify(
    type: VoiceNotification['type'],
    message: string,
    priority: VoiceNotification['priority'] = 'medium',
    metadata?: Record<string, any>
  ): Promise<void> {
    this.queueNotification({ type, message, priority, metadata });
    await this.processQueue();
  }

  /**
   * Get pending notifications
   */
  getPending(): VoiceNotification[] {
    return this.queue.filter(n => !n.spoken);
  }

  /**
   * Clear queue
   */
  clearQueue(): void {
    this.queue = [];
  }
}

