// Get greeting based on time of day
export function getTimeBasedGreeting(): string {
  const hour = new Date().getHours();
  if (hour < 6) return "Hello";
  if (hour < 12) return "Good morning";
  if (hour < 17) return "Good afternoon";
  if (hour < 21) return "Good evening";
  return "Hello";
}

// Generate a morning briefing
export async function generateMorningBriefing(
  userId: string,
  supabase: any
): Promise<string> {
  const greeting = getTimeBasedGreeting();
  const parts: string[] = [greeting + "!"];

  try {
    // Get today's tasks
    const { data: tasks } = await supabase
      .from("tasks")
      .select("*")
      .eq("user_id", userId)
      .eq("status", "pending");

    if (tasks && tasks.length > 0) {
      parts.push(`You have ${tasks.length} pending task${tasks.length > 1 ? "s" : ""}.`);
    }

    // Get today's reminders
    const now = new Date();
    const endOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59);
    
    const { data: reminders } = await supabase
      .from("reminders")
      .select("*")
      .eq("user_id", userId)
      .eq("status", "pending")
      .lte("due_time", endOfDay.toISOString());

    if (reminders && reminders.length > 0) {
      parts.push(`${reminders.length} reminder${reminders.length > 1 ? "s" : ""} for today.`);
    }

    // Get today's events
    const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    
    const { data: events } = await supabase
      .from("calendar_events")
      .select("*")
      .eq("user_id", userId)
      .gte("start_time", startOfDay.toISOString())
      .lte("start_time", endOfDay.toISOString());

    if (events && events.length > 0) {
      parts.push(`${events.length} event${events.length > 1 ? "s" : ""} on your calendar.`);
    }

    if (parts.length === 1) {
      parts.push("Your schedule is clear for today.");
    }

    parts.push("How can I help you?");
  } catch (error) {
    console.error("Failed to generate briefing:", error);
    parts.push("How can I help you today?");
  }

  return parts.join(" ");
}

/**
 * Voice Quality Optimizer
 * Automatically adjusts voice settings based on environment and device
 */

import { logger } from '@/utils/logger';

interface AudioEnvironment {
  noiseLevel: 'quiet' | 'moderate' | 'noisy';
  deviceType: 'mobile' | 'desktop' | 'tablet';
  connectionQuality: 'excellent' | 'good' | 'poor';
  batteryLevel?: number;
}

interface VoiceQualitySettings {
  sampleRate: number;
  bitRate: number;
  noiseReduction: boolean;
  echoCancellation: boolean;
  autoGainControl: boolean;
  voiceSpeed: number;
  voiceVolume: number;
}

class VoiceQualityOptimizerService {
  private currentEnvironment: AudioEnvironment | null = null;
  private audioContext: AudioContext | null = null;
  private analyser: AnalyserNode | null = null;
  private noiseHistory: number[] = [];

  /**
   * Initialize audio analysis
   */
  async initialize(): Promise<void> {
    try {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      this.analyser = this.audioContext.createAnalyser();
      this.analyser.fftSize = 256;
      
      logger.log('VoiceQualityOptimizer', 'Initialized');
    } catch (error) {
      logger.error('VoiceQualityOptimizer', 'Failed to initialize:', error);
    }
  }

  /**
   * Analyze current environment
   */
  async analyzeEnvironment(): Promise<AudioEnvironment> {
    const deviceType = this.detectDeviceType();
    const connectionQuality = await this.measureConnectionQuality();
    const noiseLevel = await this.measureNoiseLevel();
    const batteryLevel = await this.getBatteryLevel();

    this.currentEnvironment = {
      noiseLevel,
      deviceType,
      connectionQuality,
      batteryLevel,
    };

    logger.log('VoiceQualityOptimizer', 'Environment analyzed:', this.currentEnvironment);
    
    return this.currentEnvironment;
  }

  /**
   * Detect device type
   */
  private detectDeviceType(): 'mobile' | 'desktop' | 'tablet' {
    const ua = navigator.userAgent.toLowerCase();
    
    if (/ipad|tablet|playbook|silk/i.test(ua)) {
      return 'tablet';
    }
    
    if (/mobile|iphone|ipod|android|blackberry|opera mini|iemobile/i.test(ua)) {
      return 'mobile';
    }
    
    return 'desktop';
  }

  /**
   * Measure connection quality
   */
  private async measureConnectionQuality(): Promise<'excellent' | 'good' | 'poor'> {
    const connection = (navigator as any).connection;
    
    if (!connection) {
      return 'good'; // Default assumption
    }

    const effectiveType = connection.effectiveType;
    const downlink = connection.downlink;

    if (effectiveType === '4g' && downlink > 5) {
      return 'excellent';
    }
    
    if (effectiveType === '4g' || (effectiveType === '3g' && downlink > 1)) {
      return 'good';
    }
    
    return 'poor';
  }

  /**
   * Measure ambient noise level
   */
  private async measureNoiseLevel(): Promise<'quiet' | 'moderate' | 'noisy'> {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      
      if (!this.audioContext || !this.analyser) {
        await this.initialize();
      }

      const source = this.audioContext!.createMediaStreamSource(stream);
      source.connect(this.analyser!);

      const dataArray = new Uint8Array(this.analyser!.frequencyBinCount);
      
      // Sample for 500ms
      await new Promise(resolve => setTimeout(resolve, 500));
      
      this.analyser!.getByteFrequencyData(dataArray);
      
      // Calculate average amplitude
      const average = dataArray.reduce((a, b) => a + b, 0) / dataArray.length;
      
      // Stop stream
      stream.getTracks().forEach(track => track.stop());
      source.disconnect();

      // Store in history
      this.noiseHistory.push(average);
      if (this.noiseHistory.length > 10) {
        this.noiseHistory.shift();
      }

      // Determine noise level
      if (average < 30) return 'quiet';
      if (average < 60) return 'moderate';
      return 'noisy';
    } catch (error) {
      logger.warn('VoiceQualityOptimizer', 'Could not measure noise level');
      return 'moderate';
    }
  }

  /**
   * Get battery level
   */
  private async getBatteryLevel(): Promise<number | undefined> {
    try {
      const battery = await (navigator as any).getBattery?.();
      return battery?.level ? Math.round(battery.level * 100) : undefined;
    } catch {
      return undefined;
    }
  }

  /**
   * Get optimized voice settings
   */
  getOptimizedSettings(): VoiceQualitySettings {
    const env = this.currentEnvironment || {
      noiseLevel: 'moderate',
      deviceType: 'desktop',
      connectionQuality: 'good',
    };

    const settings: VoiceQualitySettings = {
      sampleRate: 16000,
      bitRate: 128000,
      noiseReduction: true,
      echoCancellation: true,
      autoGainControl: true,
      voiceSpeed: 1.0,
      voiceVolume: 0.8,
    };

    // Adjust based on noise level
    if (env.noiseLevel === 'noisy') {
      settings.noiseReduction = true;
      settings.autoGainControl = true;
      settings.voiceVolume = 1.0; // Louder in noisy environments
      settings.voiceSpeed = 0.9; // Slightly slower for clarity
    } else if (env.noiseLevel === 'quiet') {
      settings.voiceVolume = 0.6; // Quieter in quiet environments
    }

    // Adjust based on device type
    if (env.deviceType === 'mobile') {
      settings.sampleRate = 16000; // Lower for mobile
      settings.bitRate = 64000;
    }

    // Adjust based on connection quality
    if (env.connectionQuality === 'poor') {
      settings.sampleRate = 8000;
      settings.bitRate = 32000;
    } else if (env.connectionQuality === 'excellent') {
      settings.sampleRate = 24000;
      settings.bitRate = 192000;
    }

    // Adjust for low battery
    if (env.batteryLevel !== undefined && env.batteryLevel < 20) {
      settings.sampleRate = Math.min(settings.sampleRate, 16000);
      settings.bitRate = Math.min(settings.bitRate, 64000);
    }

    return settings;
  }

  /**
   * Get MediaRecorder constraints
   */
  getRecorderConstraints(): MediaTrackConstraints {
    const settings = this.getOptimizedSettings();
    
    return {
      echoCancellation: settings.echoCancellation,
      noiseSuppression: settings.noiseReduction,
      autoGainControl: settings.autoGainControl,
      sampleRate: settings.sampleRate,
    };
  }

  /**
   * Get speech synthesis settings
   */
  getSpeechSettings(): { rate: number; volume: number; pitch: number } {
    const settings = this.getOptimizedSettings();
    
    return {
      rate: settings.voiceSpeed,
      volume: settings.voiceVolume,
      pitch: 1.0,
    };
  }

  /**
   * Get current environment
   */
  getEnvironment(): AudioEnvironment | null {
    return this.currentEnvironment;
  }

  /**
   * Get noise trend
   */
  getNoiseTrend(): 'increasing' | 'decreasing' | 'stable' {
    if (this.noiseHistory.length < 3) return 'stable';
    
    const recent = this.noiseHistory.slice(-3);
    const trend = recent[2] - recent[0];
    
    if (trend > 10) return 'increasing';
    if (trend < -10) return 'decreasing';
    return 'stable';
  }

  /**
   * Cleanup
   */
  cleanup(): void {
    if (this.audioContext) {
      this.audioContext.close();
      this.audioContext = null;
    }
    this.analyser = null;
    this.noiseHistory = [];
  }
}

export const voiceQualityOptimizer = new VoiceQualityOptimizerService();

/**
 * Voice Settings Control Service
 * Enables complete voice control of application settings
 */

import type { Preferences } from "@/types/models";
import type { OpenAIVoice } from "@/types/models";

export interface VoiceSettingsCommand {
  action: "change_voice" | "toggle_wake_word" | "set_assistant_name" | "toggle_memory" | "get_settings";
  value?: string | boolean;
}

export interface VoiceSettingsResult {
  success: boolean;
  message: string;
  voiceResponse: string;
  settingChanged?: string;
  newValue?: any;
}

/**
 * Parse voice command for settings operations
 */
export function parseSettingsVoiceCommand(text: string): VoiceSettingsCommand | null {
  const lower = text.toLowerCase().trim();

  // Change voice
  if (lower.includes("change") && (lower.includes("voice") || lower.includes("sound"))) {
    const voices = ["alloy", "echo", "fable", "onyx", "nova", "shimmer"];
    for (const voice of voices) {
      if (lower.includes(voice)) {
        return {
          action: "change_voice",
          value: voice,
        };
      }
    }
    return { action: "change_voice" }; // Will prompt for voice
  }

  // Toggle wake word
  if (lower.includes("wake word") || lower.includes("hey echo")) {
    if (lower.includes("enable") || lower.includes("turn on") || lower.includes("activate")) {
      return { action: "toggle_wake_word", value: true };
    }
    if (lower.includes("disable") || lower.includes("turn off") || lower.includes("deactivate")) {
      return { action: "toggle_wake_word", value: false };
    }
    return { action: "toggle_wake_word" }; // Will toggle
  }

  // Set assistant name
  if (lower.includes("call you") || lower.includes("your name")) {
    const nameMatch = lower.match(/call you (\w+)/i) || lower.match(/name (?:is |to )?(\w+)/i);
    if (nameMatch) {
      return {
        action: "set_assistant_name",
        value: nameMatch[1],
      };
    }
  }

  // Toggle memory
  if (lower.includes("memory")) {
    if (lower.includes("enable") || lower.includes("turn on")) {
      return { action: "toggle_memory", value: true };
    }
    if (lower.includes("disable") || lower.includes("turn off")) {
      return { action: "toggle_memory", value: false };
    }
  }

  // Get settings
  if (lower.includes("what are my settings") || lower.includes("show settings") || lower.includes("current settings")) {
    return { action: "get_settings" };
  }

  return null;
}

/**
 * Execute voice settings command
 */
export function executeVoiceSettingsCommand(
  command: VoiceSettingsCommand,
  currentPreferences: Preferences,
  updatePreferences: (prefs: Preferences) => void
): VoiceSettingsResult {
  switch (command.action) {
    case "change_voice":
      return handleChangeVoice(command, currentPreferences, updatePreferences);
    case "toggle_wake_word":
      return handleToggleWakeWord(command, currentPreferences, updatePreferences);
    case "set_assistant_name":
      return handleSetAssistantName(command, currentPreferences, updatePreferences);
    case "toggle_memory":
      return handleToggleMemory(command, currentPreferences, updatePreferences);
    case "get_settings":
      return handleGetSettings(currentPreferences);
    default:
      return {
        success: false,
        message: "Unknown settings command",
        voiceResponse: "I didn't understand that settings command.",
      };
  }
}

/**
 * Handle change voice command
 */
function handleChangeVoice(
  command: VoiceSettingsCommand,
  prefs: Preferences,
  updatePrefs: (p: Preferences) => void
): VoiceSettingsResult {
  if (!command.value) {
    const currentVoice = prefs.openaiVoice || "nova";
    return {
      success: false,
      message: "Voice not specified",
      voiceResponse: `My current voice is ${currentVoice}. Which voice would you like? Available voices are: Alloy, Echo, Fable, Onyx, Nova, and Shimmer.`,
    };
  }

  const newVoice = command.value as OpenAIVoice;
  const validVoices: OpenAIVoice[] = ["alloy", "echo", "fable", "onyx", "nova", "shimmer"];
  
  if (!validVoices.includes(newVoice)) {
    return {
      success: false,
      message: `Invalid voice: ${newVoice}`,
      voiceResponse: `I don't have a voice called ${newVoice}. Available voices are: Alloy, Echo, Fable, Onyx, Nova, and Shimmer.`,
    };
  }

  updatePrefs({ ...prefs, openaiVoice: newVoice });

  return {
    success: true,
    message: `Voice changed to ${newVoice}`,
    voiceResponse: `I've changed my voice to ${newVoice}. How do I sound?`,
    settingChanged: "openaiVoice",
    newValue: newVoice,
  };
}

/**
 * Handle toggle wake word command
 */
function handleToggleWakeWord(
  command: VoiceSettingsCommand,
  prefs: Preferences,
  updatePrefs: (p: Preferences) => void
): VoiceSettingsResult {
  const newValue = command.value !== undefined ? command.value : !prefs.wakeWordEnabled;
  
  updatePrefs({ ...prefs, wakeWordEnabled: newValue as boolean });

  return {
    success: true,
    message: `Wake word ${newValue ? 'enabled' : 'disabled'}`,
    voiceResponse: newValue
      ? `Wake word enabled. You can now say "${prefs.wakeWord || 'Echo'}" to activate me anytime.`
      : "Wake word disabled. You'll need to use the microphone button to talk to me.",
    settingChanged: "wakeWordEnabled",
    newValue,
  };
}

/**
 * Handle set assistant name command
 */
function handleSetAssistantName(
  command: VoiceSettingsCommand,
  prefs: Preferences,
  updatePrefs: (p: Preferences) => void
): VoiceSettingsResult {
  if (!command.value) {
    return {
      success: false,
      message: "Name not specified",
      voiceResponse: "What would you like to call me?",
    };
  }

  const newName = String(command.value).charAt(0).toUpperCase() + String(command.value).slice(1);
  
  updatePrefs({ ...prefs, assistantName: newName });

  return {
    success: true,
    message: `Assistant name changed to ${newName}`,
    voiceResponse: `Great! You can call me ${newName} from now on.`,
    settingChanged: "assistantName",
    newValue: newName,
  };
}

/**
 * Handle toggle memory command
 */
function handleToggleMemory(
  command: VoiceSettingsCommand,
  prefs: Preferences,
  updatePrefs: (p: Preferences) => void
): VoiceSettingsResult {
  const newValue = command.value !== undefined ? command.value : !prefs.enableMemory;
  
  updatePrefs({ ...prefs, enableMemory: newValue as boolean });

  return {
    success: true,
    message: `Memory ${newValue ? 'enabled' : 'disabled'}`,
    voiceResponse: newValue
      ? "Memory enabled. I'll remember important information you tell me."
      : "Memory disabled. I won't save new information, but existing memories are still available.",
    settingChanged: "enableMemory",
    newValue,
  };
}

/**
 * Handle get settings command
 */
function handleGetSettings(prefs: Preferences): VoiceSettingsResult {
  const settings = [
    `My voice is ${prefs.openaiVoice || 'Nova'}`,
    `My name is ${prefs.assistantName || 'Echo'}`,
    `Wake word is ${prefs.wakeWordEnabled ? 'enabled' : 'disabled'}`,
