    console.log('[ConversationManager] Conversation started');
  }

  stopConversation(): void {
    this.isConversationActive = false;
    console.log('[ConversationManager] Conversation stopped');
  }

  enterQuietMode(userId: string, context?: string): void {
    startListeningSession(userId, context);
    this.isQuietModeActive = true;
    console.log('[ConversationManager] Quiet mode entered');
  }

  async exitQuietMode(userId: string, apiKey: string): Promise<{
    summary: string;
    bulletPoints: string[];
    actionItems: string[];
  } | null> {
    try {
      const result = await endListeningSession(userId, apiKey);
      this.isQuietModeActive = false;
      
      if (result.success) {
        return {
          summary: result.summary || '',
          bulletPoints: result.bulletPoints || [],
          actionItems: result.actionItems || [],
        };
      }
    } catch (error) {
      console.error('[ConversationManager] Failed to exit quiet mode:', error);
    }
    
    this.isQuietModeActive = false;
    return null;
  }

  checkQuietModeStatus(userId: string): boolean {
    const status = getSessionStatus(userId);
    this.isQuietModeActive = status.isActive;
    return status.isActive;
  }

  addQuietModeTranscript(userId: string, text: string): void {
    if (this.isQuietModeActive) {
      addTranscript(userId, text);
    }
  }

  handleTranscript(userId: string, text: string): TranscriptHandlerResult {
    // Check for exit phrases in conversation mode
    // Only exit if the message is primarily an exit phrase
    const normalizedText = text.toLowerCase().trim();
    
    // Exact exit phrases (must match exactly or be the primary content)
    const exactExitPhrases = [
      'goodbye', 'bye', 'bye bye', 'stop', 'exit', 'quit',
      'end conversation', "that's all", 'good bye', 'see you',
      'see ya', 'later', 'talk later', "i'm done", 'done',
      "that's it", 'nothing else', 'end', 'close', 'finish'
    ];
    
    // Phrases that indicate exit when they're the main content
    const exitIndicators = ['thank you', 'thanks', 'ok thanks', 'okay thanks'];
    
    // Check for exact match first
    const isExactMatch = exactExitPhrases.includes(normalizedText);
    
    // Check if it's a short message (< 25 chars) that contains an exit phrase
    const isShortExitMessage = normalizedText.length < 25 &&
      exactExitPhrases.some(phrase => normalizedText.includes(phrase));
    
    // Check for thank you variants only if they're standalone (not part of a longer request)
    const isThankYouExit = normalizedText.length < 30 &&
      exitIndicators.some(phrase => normalizedText.includes(phrase)) &&
      !normalizedText.includes('can you') &&
      !normalizedText.includes('please') &&
      !normalizedText.includes('help');
    
    const shouldExit = isExactMatch || isShortExitMessage || isThankYouExit;
    
    if (this.isConversationActive && shouldExit) {
      console.log('[ConversationManager] Exit phrase detected:', normalizedText);
      return {
        handled: true,
        action: 'exit',
        message: 'Goodbye! Let me know if you need anything else.',
      };
    }

    // Check for quiet mode entry
    if (isEnterPhrase(text)) {
      const contextMatch = text.match(/for\s+(.+?)(?:\s*$|,)/i);
      const context = contextMatch ? contextMatch[1] : undefined;
      return {
        handled: true,
        action: 'quiet-enter',
        message: `Entering quiet mode${context ? ` for ${context}` : ''}. I'll stay quiet and just listen.`,
        data: { context },
      };
    }

    // Check for quiet mode exit
    if (isExitPhrase(text) && this.isQuietModeActive) {
      return {
        handled: true,
        action: 'quiet-exit',
      };
    }

    // If in quiet mode, just record
    if (this.isQuietModeActive) {
      return {
        handled: true,
        action: 'quiet-enter',
      };
    }

    // Check for multi-step conversation
    if (hasActiveFlow(userId)) {
      const flowResult = processMultiStepResponse(userId, text);
      if (flowResult.complete && flowResult.collectedData) {
        return {
          handled: true,
          action: 'multi-step',
          data: {
            complete: true,
            intent: flowResult.state?.intent,
            collectedData: flowResult.collectedData,
          },
        };
      } else if (flowResult.nextPrompt) {
        return {
          handled: true,
          action: 'multi-step',
          message: flowResult.nextPrompt,
          data: { complete: false },
        };
      }
    }

    // Check for inline modifications
    const modResult = handleInlineModification(userId, text);
    if (modResult.handled && modResult.message) {
      return {
        handled: true,
        action: 'modification',
        message: modResult.message,
      };
    }

    // Check if user wants to start a multi-step flow
    const multiStepIntent = detectMultiStepIntent(text);
    if (multiStepIntent) {
      const flowStart = startMultiStepFlow(userId, multiStepIntent);
      if (flowStart) {
        return {
          handled: true,
          action: 'multi-step',
          message: flowStart.prompt,
          data: { complete: false },
        };
      }
    }

    // Check for cancel/undo commands
    if (/\b(cancel|stop|never\s*mind)\b/i.test(text) && hasActiveFlow(userId)) {
      cancelFlow(userId);
      return {
        handled: true,
        action: 'cancel',
        message: 'Cancelled. What else can I help with?',
      };
    }

    return { handled: false };
  }

  get conversationActive(): boolean {
    return this.isConversationActive;
  }

  get quietModeActive(): boolean {
    return this.isQuietModeActive;
  }
}

export const conversationManager = new ConversationManager();

import { synthesizeSpeech } from '@/services/openai-voice';
import { offlineVoice, isOfflineVoiceSupported } from '@/services/offline-voice';
import { SpeechOptions } from './types';

export class VoicePlayer {
  private currentAudio: HTMLAudioElement | null = null;
  private isSpeaking = false;
  private pendingOnEnd: (() => void) | null = null;

  async speak(
    text: string,
    apiKey: string | null,
    options: SpeechOptions = {}
  ): Promise<void> {
    if (!text || text.trim().length === 0) {
      console.warn('[VoicePlayer] Empty text provided');
      // Still call onEnd to continue conversation flow
      options.onEnd?.();
      return;
    }

    // Stop any current audio
    this.stop();

    // Store the onEnd callback for later use
    this.pendingOnEnd = options.onEnd || null;

    const isOnline = navigator.onLine;
    const hasApiKey = !!apiKey;
    const hasOfflineVoice = isOfflineVoiceSupported();

    // Use offline voice if offline or no API key
    if ((!isOnline || !hasApiKey) && hasOfflineVoice) {
      return this.speakOffline(text, options);
    }

    // Use OpenAI TTS
    if (!apiKey) {
      console.error('[VoicePlayer] No API key, calling onEnd');
      this.pendingOnEnd = null;
      options.onEnd?.();
      throw new Error('OpenAI API key not configured');
    }

    return this.speakOnline(text, apiKey, options);
  }

  private async speakOffline(text: string, options: SpeechOptions): Promise<void> {
    console.log('[VoicePlayer] Using offline TTS (Web Speech API)');
    
    this.isSpeaking = true;
    options.onStart?.();

    try {
      await offlineVoice.speak(text, {
        rate: options.rate || 1.0,
      });
      
      this.isSpeaking = false;
      console.log('[VoicePlayer] Offline speech ended, calling onEnd');
      this.pendingOnEnd = null;
      options.onEnd?.();
    } catch (error: any) {
      this.isSpeaking = false;
      console.error('[VoicePlayer] Offline speech error:', error);
      this.pendingOnEnd = null;
      options.onError?.(error);
      // Still call onEnd to continue conversation flow
      options.onEnd?.();
      throw error;
    }
  }

  private async speakOnline(
    text: string,
    apiKey: string,
    options: SpeechOptions
  ): Promise<void> {
    console.log('[VoicePlayer] Using OpenAI TTS');

    try {
      this.isSpeaking = true;
      options.onStart?.();

      const speechBlob = await synthesizeSpeech(
        text,
        apiKey,
        (options.voice as any) || 'nova'
      );

      if (speechBlob.size === 0) {
        throw new Error('Empty audio blob received');
      }

      console.log('[VoicePlayer] Speech blob received:', {
        size: speechBlob.size,
        type: speechBlob.type,
      });

      await this.playBlob(speechBlob, options);
    } catch (error: any) {
      console.error('[VoicePlayer] OpenAI TTS error:', error);
      this.isSpeaking = false;

      // Fallback to offline voice
      if (isOfflineVoiceSupported()) {
        console.log('[VoicePlayer] Falling back to Web Speech API');
        return this.speakOffline(text, options);
      }

      this.pendingOnEnd = null;
      options.onError?.(error);
      // Still call onEnd to continue conversation flow even on error
      options.onEnd?.();
      throw error;
    }
  }

  private async playBlob(blob: Blob, options: SpeechOptions): Promise<void> {
    return new Promise((resolve, reject) => {
      const audio = new Audio();
      this.currentAudio = audio;
      const audioUrl = URL.createObjectURL(blob);

      audio.src = audioUrl;
      audio.volume = 1.0;

      let resolved = false;

      const cleanup = () => {
        if (resolved) return;
        resolved = true;
        URL.revokeObjectURL(audioUrl);
        if (this.currentAudio === audio) {
          this.currentAudio = null;
        }
        this.isSpeaking = false;
      };

      audio.onended = () => {
        console.log('[VoicePlayer] Playback ended naturally');
        cleanup();
        this.pendingOnEnd = null;
        options.onEnd?.();
        resolve();
      };

      audio.onerror = (e) => {
        console.error('[VoicePlayer] Playback error:', e);
        cleanup();
        const error = new Error(`Audio playback failed: ${audio.error?.message || 'Unknown error'}`);
        this.pendingOnEnd = null;
        options.onError?.(error);
        // Still call onEnd to continue conversation flow
        options.onEnd?.();
        reject(error);
      };

      audio.oncanplay = () => {
        console.log('[VoicePlayer] Audio ready, starting playback');
        audio.play()
          .then(() => console.log('[VoicePlayer] Playback started successfully'))
          .catch((err) => {
            console.error('[VoicePlayer] Play failed:', err);
            cleanup();
            this.pendingOnEnd = null;
            options.onError?.(err);
            // Still call onEnd to continue conversation flow
            options.onEnd?.();
            reject(err);
          });
      };

      // Timeout fallback - if audio doesn't load in 10 seconds, fail gracefully
      setTimeout(() => {
        if (!resolved) {
          if (audio.readyState >= 2) {
            audio.play()
              .catch((err) => {
                cleanup();
                this.pendingOnEnd = null;
                options.onEnd?.();
                reject(err);
              });
          } else {
            console.warn('[VoicePlayer] Audio loading timeout, continuing conversation');
            cleanup();
            this.pendingOnEnd = null;
            options.onEnd?.();
            reject(new Error('Audio loading timeout'));
          }
        }
      }, 10000);
    });
  }

  stop(): void {
    console.log('[VoicePlayer] Stop called');
    if (this.currentAudio) {
      this.currentAudio.pause();
      this.currentAudio.currentTime = 0;
      try {
        URL.revokeObjectURL(this.currentAudio.src);
      } catch (e) {
        // Ignore URL revoke errors
      }
      this.currentAudio = null;
    }
    this.isSpeaking = false;
    
    // If there was a pending onEnd callback, call it now
    if (this.pendingOnEnd) {
      console.log('[VoicePlayer] Calling pending onEnd after stop');
      const onEnd = this.pendingOnEnd;
      this.pendingOnEnd = null;
      onEnd();
    }
  }

  get speaking(): boolean {
    return this.isSpeaking;
  }
}

export const voicePlayer = new VoicePlayer();

import { transcribeAudio } from '@/services/openai-voice';
import { buildSystemPrompt, parseToolCalls, executeTool, ActionResult } from '@/services/orchestrator';
import { DEMO_MODE_SENTINEL_KEY } from '@/services/demo-mode';
import { proxyChat } from '@/services/ai-proxy';
import { normalizeSpeechInput } from '@/services/conversation-manager';
import { getMemoryContext } from '@/services/memory';
import { saveChatMessage, getChatContext } from '@/services/chat-history';
import { webLLM, isWebLLMSupported } from '@/services/web-llm';
import { voiceRateLimiter, openAIRateLimiter } from '@/services/rate-limiter';
import { trackVoiceCommand, trackError } from '@/services/analytics';
import { LocationContext } from '@/services/context';
import { ProcessingResult, VoiceConfig } from './types';

export class VoiceProcessor {
  async transcribe(audioBlob: Blob, apiKey: string): Promise<string> {
    // Lower the minimum size threshold - even short recordings might have speech
    if (audioBlob.size < 1000) {
      console.log('[VoiceProcessor] Recording very small:', audioBlob.size, 'bytes');
      throw new Error('Recording too short. Please speak for at least 1 second.');
    }

    console.log('[VoiceProcessor] Transcribing audio, size:', audioBlob.size);
    
    const result = await transcribeAudio(audioBlob, apiKey);
    const text = (result.text || '').trim();
    
    console.log('[VoiceProcessor] Transcription result:', text || '(empty)');
    
    // If transcription is empty, throw a user-friendly error
    if (!text) {
      throw new Error('No speech detected. Please speak clearly and try again. Make sure your microphone is working and you are close to it.');
    }
    
    return text;
  }

  async processCommand(
    text: string,
    userId: string,
    apiKey: string | null,
    config: VoiceConfig,
    location: LocationContext | null,
    onNavigate?: (path: string) => void
  ): Promise<ProcessingResult> {
    // Check rate limits
    const voiceCheck = voiceRateLimiter.checkLimit(userId);
    if (!voiceCheck.allowed) {
      const waitTime = Math.ceil((voiceCheck.resetAt - Date.now()) / 1000);
      throw new Error(`Too many voice commands. Please wait ${waitTime} seconds.`);
    }

    const isOnline = navigator.onLine;
    const hasApiKey = !!apiKey;
    const hasWebLLM = isWebLLMSupported();
    const useLocalAI = !isOnline || !hasApiKey;

    if (!hasApiKey && !hasWebLLM) {
      throw new Error('Please add your OpenAI API key in Settings or enable offline AI');
    }

    const normalizedText = normalizeSpeechInput(text);

    // Use local AI if offline or no API key
    if (useLocalAI && hasWebLLM) {
      return this.processWithLocalAI(normalizedText, userId, config, location);
    }

    // Check OpenAI rate limit
    if (!useLocalAI) {
      const apiCheck = openAIRateLimiter.checkLimit(userId, 0.01);
      if (!apiCheck.allowed) {
        throw new Error(apiCheck.reason || 'API rate limit exceeded');
      }
    }

    return this.processWithOpenAI(normalizedText, userId, apiKey!, config, location, onNavigate);
  }

  private async processWithLocalAI(
    text: string,
    userId: string,
    config: VoiceConfig,
    location: LocationContext | null
  ): Promise<ProcessingResult> {
    console.log('[VoiceProcessor] Using local WebLLM');

    const modelCached = await webLLM.isModelCached();
    if (!modelCached) {
      throw new Error('Offline AI not downloaded. Please download the model in Settings.');
    }

    await webLLM.initialize();

    const systemPrompt = `You are ${config.assistantName || 'Echo'}, a helpful AI assistant.
Current time: ${new Date().toLocaleString()}
Location: ${location?.city || 'Unknown'}

Parse the user's command and respond naturally.`;

    const response = await webLLM.chat([
      { role: 'system', content: systemPrompt },
      { role: 'user', content: text },
    ]);

    const toolCalls = parseToolCalls(response);
    const toolResults: ActionResult[] = [];

    for (const toolCall of toolCalls) {
      const result = await executeTool(userId, toolCall);
      toolResults.push(result);
    }

    const toolsUsed = toolCalls.map(tc => tc.tool);
    trackVoiceCommand(text, true, userId);

    return { response, toolResults, toolsUsed };
  }

  private async processWithOpenAI(
    text: string,
    userId: string,
    apiKey: string,
    config: VoiceConfig,
    location: LocationContext | null,
    onNavigate?: (path: string) => void
  ): Promise<ProcessingResult> {
    console.log('[VoiceProcessor] Using OpenAI');

    // Get context
    let memoryContext = '';
    if (config.enableMemory) {
      memoryContext = await getMemoryContext(userId);
    }

    let chatHistory: { role: 'user' | 'assistant'; content: string }[] = [];
    if (config.enableChatHistory) {
      chatHistory = await getChatContext(userId, Math.min(config.chatHistoryLimit || 10, 20));
    }

    const systemPrompt = buildSystemPrompt(
      location ? { lat: location.lat, lng: location.lng, city: location.city } : undefined,
      config.assistantName,
      memoryContext
    );

    const messages = [
      { role: 'system' as const, content: systemPrompt },
      ...chatHistory.map((m) => ({ role: m.role as 'user' | 'assistant', content: m.content })),
      { role: 'user' as const, content: text },
    ];

    // Save user message
    if (config.enableChatHistory && !config.privateMode) {
      saveChatMessage(userId, 'user', text);
    }

    // Call OpenAI (direct) or Demo Mode server proxy
    let aiResponse: string;

    if (apiKey === DEMO_MODE_SENTINEL_KEY) {
      const proxyRes = await proxyChat({
        model: 'gpt-4o-mini',
        messages: messages as any,
        max_tokens: 1024,
      });
      aiResponse = proxyRes.content;
    } else {
      const response = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify({
          model: 'gpt-4o-mini',
          messages,
          max_tokens: 1024,
        }),
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`AI request failed: ${errorText}`);
      }

      const data = await response.json();
      aiResponse = data.choices[0].message.content;
    }

    // Execute tool calls
    const toolCalls = parseToolCalls(aiResponse);
    const toolResults: ActionResult[] = [];
    let navigateTo: string | undefined;

    for (const toolCall of toolCalls) {
      const result = await executeTool(userId, toolCall);
      toolResults.push(result);

      if (toolCall.tool === 'navigate_to' && result.success && result.data?.path) {
        navigateTo = result.data.path;
        onNavigate?.(result.data.path);
      }
    }

    // Get follow-up response if tools were executed
    if (toolResults.length > 0) {
      const toolResultsText = toolResults
        .map((r) => (r.data?.voiceText ? r.data.voiceText : `${r.tool}: ${r.success ? 'Success' : r.error}`))
        .join('\n');

      const followUpMessages = [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: text },
        { role: 'assistant', content: aiResponse },
        { role: 'user', content: `Results: ${toolResultsText}\n\nGive a brief voice response.` },
      ];

      if (apiKey === DEMO_MODE_SENTINEL_KEY) {
        const follow = await proxyChat({
          model: 'gpt-4o-mini',
          messages: followUpMessages as any,
          max_tokens: 256,
        });
        aiResponse = follow.content;
      } else {
        const followUpResponse = await fetch('https://api.openai.com/v1/chat/completions', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${apiKey}`,
          },
          body: JSON.stringify({
            model: 'gpt-4o-mini',
            messages: followUpMessages,
            max_tokens: 256,
          }),
        });

        if (followUpResponse.ok) {
          const followUpData = await followUpResponse.json();
          aiResponse = followUpData.choices[0].message.content;
        }
      }
    }

    // Clean response
    const cleanResponse = aiResponse
      .replace(/```json[\s\S]*?```/g, '')
      .replace(/```[\s\S]*?```/g, '')
      .replace(/\*\*/g, '')
      .trim();

    const voiceTextResult = toolResults.find((r) => r.data?.voiceText);
    const finalResponse = voiceTextResult?.data?.voiceText || cleanResponse;

    // Save assistant response
    if (config.enableChatHistory && !config.privateMode) {
      saveChatMessage(userId, 'assistant', finalResponse);
    }

    const toolsUsed = toolCalls.map(tc => tc.tool);
    trackVoiceCommand(text, true, userId);

    return { response: finalResponse, toolResults, toolsUsed, navigateTo };
  }
}

export const voiceProcessor = new VoiceProcessor();

import { RecordingCallbacks } from './types';

export class VoiceRecorder {
  private mediaRecorder: MediaRecorder | null = null;
  private audioContext: AudioContext | null = null;
  private analyser: AnalyserNode | null = null;
  private stream: MediaStream | null = null;
  private chunks: Blob[] = [];
  private isRecording = false;
  private isStarting = false;
  private silenceTimeout: NodeJS.Timeout | null = null;
  private silenceStart: number | null = null;
  private mimeType = 'audio/webm';
  private recordingStartTime: number = 0;
  private hasDetectedSpeech: boolean = false;

  async start(callbacks: RecordingCallbacks, enableSilenceDetection = false): Promise<void> {
    // Prevent duplicate starts
    if (this.isStarting || this.isRecording) {
      console.log('[VoiceRecorder] Already recording or starting');
      return;
    }

    this.isStarting = true;
    this.hasDetectedSpeech = false;

    try {
      // Clean up any existing recording
      await this.cleanup();

      // Get microphone access
      this.stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
        },
      });

      // Set up audio context for silence detection
      if (enableSilenceDetection) {
        this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        const source = this.audioContext.createMediaStreamSource(this.stream);
        this.analyser = this.audioContext.createAnalyser();
        this.analyser.fftSize = 2048;
        source.connect(this.analyser);
        this.silenceStart = null;
      }

      // Determine best audio format for OpenAI Whisper
      this.mimeType = this.getBestMimeType();
      console.log(`[VoiceRecorder] Using format: ${this.mimeType}`);

      // Create MediaRecorder
      const recorderOptions: MediaRecorderOptions = {
        audioBitsPerSecond: 128000,
      };
      
      if (this.mimeType !== 'audio/webm') {
        recorderOptions.mimeType = this.mimeType;
      }

      this.mediaRecorder = new MediaRecorder(this.stream, recorderOptions);
      this.chunks = [];

      this.mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          this.chunks.push(event.data);
        }
      };

      this.mediaRecorder.onstop = () => {
        const blob = new Blob(this.chunks, { type: this.mimeType });
        console.log(`[VoiceRecorder] Recording stopped. Blob size: ${blob.size}`);
        callbacks.onData(blob);
        callbacks.onStop();
        this.isRecording = false;
      };

      this.mediaRecorder.onerror = (event: any) => {
        console.error('[VoiceRecorder] Error:', event.error);
        callbacks.onError(event.error || new Error('Recording failed'));
        this.isRecording = false;
      };

      // Start recording
      this.mediaRecorder.start(1000);
      this.isRecording = true;
      this.isStarting = false;
      this.recordingStartTime = Date.now();
      callbacks.onStart();

      console.log('[VoiceRecorder] Recording started');

      // Start silence detection if enabled
      if (enableSilenceDetection && callbacks.onSilenceDetected) {
        this.startSilenceDetection(callbacks.onSilenceDetected);
      }
    } catch (error: any) {
      console.error('[VoiceRecorder] Failed to start:', error);
      this.isStarting = false;
      this.isRecording = false;
      callbacks.onError(error);
    }
  }

  stop(): void {
    console.log('[VoiceRecorder] Stopping...');
    
    this.isStarting = false;
    
    if (this.silenceTimeout) {
      clearTimeout(this.silenceTimeout);
      this.silenceTimeout = null;
    }

    if (this.mediaRecorder && this.mediaRecorder.state !== 'inactive') {
      try {
        this.mediaRecorder.stop();
      } catch (e) {
        console.warn('[VoiceRecorder] Error stopping MediaRecorder:', e);
      }
    }

    this.cleanup();
  }

  private async cleanup(): Promise<void> {
    if (this.audioContext) {
      try {
        await this.audioContext.close();
      } catch (e) {
        console.warn('[VoiceRecorder] Error closing AudioContext:', e);
      }
      this.audioContext = null;
    }

    if (this.stream) {
      this.stream.getTracks().forEach((track) => {
        try {
          track.stop();
        } catch (e) {
          console.warn('[VoiceRecorder] Error stopping track:', e);
        }
      });
      this.stream = null;
    }

    this.analyser = null;
    this.silenceStart = null;
    this.hasDetectedSpeech = false;
  }

  private getBestMimeType(): string {
    // WebM with Opus is best for OpenAI Whisper
    const formats = [
      'audio/webm;codecs=opus',
      'audio/webm',
      'audio/ogg;codecs=opus',
    ];

    for (const format of formats) {
      if (MediaRecorder.isTypeSupported(format)) {
        return format;
      }
    }

    return 'audio/webm';
  }

  private startSilenceDetection(onSilenceDetected: () => void): void {
    // Configuration for hands-free conversation mode
    // TUNED FOR BETTER ACCURACY - less sensitive to brief pauses
    const SPEECH_THRESHOLD = 12; // Audio level to consider as speech (lowered for sensitivity)
    const SILENCE_THRESHOLD = 6; // Audio level to consider as silence (lowered)
    const MIN_RECORDING_TIME = 2000; // Must record at least 2 seconds before checking silence
    const SILENCE_DURATION_AFTER_SPEECH = 2500; // 2.5 seconds of silence after speech to stop
    const MAX_RECORDING_TIME = 45000; // Maximum 45 seconds recording
    const INITIAL_WAIT_TIME = 800; // Wait 800ms before starting detection
    const NO_SPEECH_TIMEOUT = 10000; // 10 seconds without speech before stopping
    
    const checkSilence = () => {
      if (!this.analyser || !this.mediaRecorder || this.mediaRecorder.state !== 'recording') {
        return;
      }

      const dataArray = new Uint8Array(this.analyser.frequencyBinCount);
      this.analyser.getByteFrequencyData(dataArray);

      // Calculate average volume level
      const average = dataArray.reduce((a, b) => a + b, 0) / dataArray.length;
      
      // Also check the max value to detect any speech
      const maxValue = Math.max(...dataArray);
      
      const timeSinceStart = Date.now() - this.recordingStartTime;

      // Check for maximum recording time
      if (timeSinceStart > MAX_RECORDING_TIME) {
        console.log('[VoiceRecorder] Maximum recording time reached, stopping');
        onSilenceDetected();
        return;
      }

      // Don't check for silence until minimum recording time has passed
      if (timeSinceStart < MIN_RECORDING_TIME) {
        this.silenceTimeout = setTimeout(checkSilence, 100);
        return;
      }

      // Detect if user is speaking
      const isSpeaking = average > SPEECH_THRESHOLD || maxValue > 40;
      const isSilent = average < SILENCE_THRESHOLD && maxValue < 25;

      // Log audio levels occasionally for debugging
      if (Math.random() < 0.1) {
        console.log(`[VoiceRecorder] Audio level - avg: ${average.toFixed(1)}, max: ${maxValue}, time: ${(timeSinceStart/1000).toFixed(1)}s, speech: ${this.hasDetectedSpeech}`);
      }

      if (isSpeaking) {
        // User is speaking - mark that we've detected speech and reset silence timer
        if (!this.hasDetectedSpeech) {
          console.log('[VoiceRecorder] Speech detected!');
        }
        this.hasDetectedSpeech = true;
        this.silenceStart = null;
      } else if (isSilent && this.hasDetectedSpeech) {
        // User has stopped speaking - start silence timer
        if (this.silenceStart === null) {
          this.silenceStart = Date.now();
          console.log('[VoiceRecorder] Silence started after speech...');
        } else if (Date.now() - this.silenceStart > SILENCE_DURATION_AFTER_SPEECH) {
          // Enough silence after speech - stop recording
          console.log('[VoiceRecorder] Silence detected after speech, auto-stopping');
          onSilenceDetected();
          return;
        }
      } else if (!this.hasDetectedSpeech && timeSinceStart > NO_SPEECH_TIMEOUT) {
        // No speech detected for timeout period - stop to avoid hanging
        console.log(`[VoiceRecorder] No speech detected for ${NO_SPEECH_TIMEOUT/1000} seconds, stopping`);
        onSilenceDetected();
        return;
      }

      this.silenceTimeout = setTimeout(checkSilence, 100);
    };

    // Start checking after initial wait
    this.silenceTimeout = setTimeout(checkSilence, INITIAL_WAIT_TIME);
  }

  get recording(): boolean {
    return this.isRecording;
  }

  get starting(): boolean {
    return this.isStarting;
  }
}

