import { describe, it, expect, beforeEach } from 'vitest';

describe('Analytics Integration', () => {
  describe('Event Tracking', () => {
    let events: { name: string; properties: Record<string, any>; timestamp: number }[];

    beforeEach(() => {
      events = [];
    });

    const trackEvent = (name: string, properties: Record<string, any> = {}) => {
      events.push({
        name,
        properties,
        timestamp: Date.now()
      });
    };

    it('should track events with properties', () => {
      trackEvent('task_created', { priority: 'high', tags: ['work'] });

      expect(events).toHaveLength(1);
      expect(events[0].name).toBe('task_created');
      expect(events[0].properties.priority).toBe('high');
    });

    it('should track multiple events', () => {
      trackEvent('page_view', { page: '/tasks' });
      trackEvent('button_click', { button: 'create' });
      trackEvent('form_submit', { form: 'task' });

      expect(events).toHaveLength(3);
    });

    it('should include timestamp', () => {
      const before = Date.now();
      trackEvent('test_event');
      const after = Date.now();

      expect(events[0].timestamp).toBeGreaterThanOrEqual(before);
      expect(events[0].timestamp).toBeLessThanOrEqual(after);
    });
  });

  describe('User Metrics Calculation', () => {
    interface UserActivity {
      tasks_created: number;
      tasks_completed: number;
      voice_commands: number;
      session_duration: number;
      pages_visited: number;
    }

    const calculateMetrics = (activity: UserActivity) => {
      const completionRate = activity.tasks_created > 0
        ? (activity.tasks_completed / activity.tasks_created) * 100
        : 0;

      const voiceAdoption = activity.voice_commands > 10 ? 'high' :
                           activity.voice_commands > 5 ? 'medium' : 'low';

      const engagementScore = Math.min(100,
        (activity.session_duration / 60000) * 2 +
        activity.tasks_created * 5 +
        activity.pages_visited * 3
      );

      return {
        completionRate: Math.round(completionRate),
        voiceAdoption,
        engagementScore: Math.round(engagementScore)
      };
    };

    it('should calculate completion rate', () => {
      const activity: UserActivity = {
        tasks_created: 10,
        tasks_completed: 8,
        voice_commands: 0,
        session_duration: 0,
        pages_visited: 0
      };

      const metrics = calculateMetrics(activity);
      expect(metrics.completionRate).toBe(80);
    });

    it('should handle zero tasks', () => {
      const activity: UserActivity = {
        tasks_created: 0,
        tasks_completed: 0,
        voice_commands: 0,
        session_duration: 0,
        pages_visited: 0
      };

      const metrics = calculateMetrics(activity);
      expect(metrics.completionRate).toBe(0);
    });

    it('should classify voice adoption levels', () => {
      const lowUsage = calculateMetrics({
        tasks_created: 0, tasks_completed: 0,
        voice_commands: 3, session_duration: 0, pages_visited: 0
      });
      const mediumUsage = calculateMetrics({
        tasks_created: 0, tasks_completed: 0,
        voice_commands: 8, session_duration: 0, pages_visited: 0
      });
      const highUsage = calculateMetrics({
        tasks_created: 0, tasks_completed: 0,
        voice_commands: 15, session_duration: 0, pages_visited: 0
      });

      expect(lowUsage.voiceAdoption).toBe('low');
      expect(mediumUsage.voiceAdoption).toBe('medium');
      expect(highUsage.voiceAdoption).toBe('high');
    });

    it('should cap engagement score at 100', () => {
      const activity: UserActivity = {
        tasks_created: 100,
        tasks_completed: 100,
        voice_commands: 100,
        session_duration: 3600000,
        pages_visited: 100
      };

      const metrics = calculateMetrics(activity);
      expect(metrics.engagementScore).toBe(100);
    });
  });

  describe('Session Tracking', () => {
    interface Session {
      id: string;
      startTime: number;
      endTime?: number;
      events: string[];
    }

    let currentSession: Session | null = null;

    const startSession = () => {
      currentSession = {
        id: `session_${Date.now()}`,
        startTime: Date.now(),
        events: []
      };
      return currentSession;
    };

    const endSession = () => {
      if (currentSession) {
        currentSession.endTime = Date.now();
      }
      return currentSession;
    };

    const addSessionEvent = (event: string) => {
      if (currentSession) {
        currentSession.events.push(event);
      }
    };

    beforeEach(() => {
      currentSession = null;
    });

    it('should start a new session', () => {
      const session = startSession();

      expect(session.id).toBeDefined();
      expect(session.startTime).toBeDefined();
      expect(session.events).toHaveLength(0);
    });

    it('should track events within session', () => {
      startSession();
      addSessionEvent('page_view');
      addSessionEvent('button_click');

      expect(currentSession?.events).toHaveLength(2);
    });

    it('should end session with timestamp', () => {
      startSession();
      const session = endSession();

      expect(session?.endTime).toBeDefined();
      expect(session?.endTime).toBeGreaterThanOrEqual(session?.startTime || 0);
    });

    it('should calculate session duration', () => {
      const session = startSession();
      session.endTime = session.startTime + 60000; // 1 minute

      const duration = session.endTime - session.startTime;
      expect(duration).toBe(60000);
    });
  });

  describe('Funnel Analysis', () => {
    const analyzeFunnel = (steps: { name: string; count: number }[]) => {
      const results = steps.map((step, index) => {
        const previousCount = index > 0 ? steps[index - 1].count : step.count;
        const conversionRate = previousCount > 0
          ? (step.count / previousCount) * 100
          : 0;
        const dropoff = previousCount - step.count;

        return {
          ...step,
          conversionRate: Math.round(conversionRate),
          dropoff
        };
      });

      const overallConversion = steps.length > 0 && steps[0].count > 0
        ? (steps[steps.length - 1].count / steps[0].count) * 100
        : 0;

      return {
        steps: results,
        overallConversion: Math.round(overallConversion)
      };
    };

    it('should calculate step conversion rates', () => {
      const funnel = analyzeFunnel([
        { name: 'Visit', count: 1000 },
        { name: 'Sign Up', count: 200 },
        { name: 'First Task', count: 100 }
      ]);

      expect(funnel.steps[1].conversionRate).toBe(20);
      expect(funnel.steps[2].conversionRate).toBe(50);
    });

    it('should calculate dropoff at each step', () => {
      const funnel = analyzeFunnel([
        { name: 'Visit', count: 1000 },
        { name: 'Sign Up', count: 200 }
      ]);

      expect(funnel.steps[1].dropoff).toBe(800);
    });

    it('should calculate overall conversion', () => {
      const funnel = analyzeFunnel([
        { name: 'Visit', count: 1000 },
        { name: 'Sign Up', count: 200 },
        { name: 'Purchase', count: 50 }
      ]);

      expect(funnel.overallConversion).toBe(5);
    });
  });
});

import { describe, it, expect, vi } from 'vitest';
import { 
  wait, 
  withRetry, 
  createNetworkError, 
  createTimeoutError, 
  createAuthError 
} from './utils/test-helpers';

describe('Error Handling Integration', () => {
  describe('API Error Handling', () => {
    const handleApiError = async (apiCall: () => Promise<any>) => {
      try {
        return await apiCall();
      } catch (error) {
        const err = error as Error;
        return {
          error: err.message,
          fallback: true,
          retryable: !err.message.includes('Unauthorized')
        };
      }
    };

    it('should handle API errors gracefully', async () => {
      const failingApi = async () => {
        throw new Error('API Error: 500 Internal Server Error');
      };

      const result = await handleApiError(failingApi);

      expect(result.error).toBeDefined();
      expect(result.fallback).toBe(true);
    });

    it('should identify retryable errors', async () => {
      const networkError = async () => { throw createNetworkError(); };
      const authError = async () => { throw createAuthError(); };

      const networkResult = await handleApiError(networkError);
      const authResult = await handleApiError(authError);

      expect(networkResult.retryable).toBe(true);
      expect(authResult.retryable).toBe(false);
    });

    it('should return success for successful calls', async () => {
      const successApi = async () => ({ data: 'success' });

      const result = await handleApiError(successApi);

      expect(result.data).toBe('success');
      expect(result.error).toBeUndefined();
    });
  });

  describe('Retry Logic', () => {
    it('should retry failed operations', async () => {
      let attempts = 0;

      const unreliableApi = async () => {
        attempts++;
        if (attempts < 3) {
          throw new Error('Temporary failure');
        }
        return { success: true };
      };

      const result = await withRetry(unreliableApi, 5);

      expect(result.success).toBe(true);
      expect(attempts).toBe(3);
    });

    it('should throw after max retries', async () => {
      const alwaysFails = async () => {
        throw new Error('Permanent failure');
      };

      await expect(withRetry(alwaysFails, 3, 10)).rejects.toThrow('Permanent failure');
    });

    it('should succeed on first try if no error', async () => {
      let attempts = 0;

      const reliableApi = async () => {
        attempts++;
        return { success: true };
      };

      const result = await withRetry(reliableApi, 3);

      expect(result.success).toBe(true);
      expect(attempts).toBe(1);
    });

    it('should use exponential backoff', async () => {
      const delays: number[] = [];
      let lastCall = Date.now();

      const trackingApi = async () => {
        const now = Date.now();
        delays.push(now - lastCall);
        lastCall = now;
        if (delays.length < 3) throw new Error('Retry');
        return { success: true };
      };

      await withRetry(trackingApi, 5, 50);

      // Second delay should be longer than first (exponential backoff)
      expect(delays[2]).toBeGreaterThan(delays[1]);
    });
  });

  describe('Error Classification', () => {
    const classifyError = (error: Error): {
      type: string;
      severity: 'low' | 'medium' | 'high' | 'critical';
      retryable: boolean;
    } => {
      const message = error.message.toLowerCase();

      if (message.includes('network') || message.includes('timeout')) {
        return { type: 'network', severity: 'medium', retryable: true };
      }
      if (message.includes('unauthorized') || message.includes('forbidden')) {
        return { type: 'auth', severity: 'high', retryable: false };
      }
      if (message.includes('not found')) {
        return { type: 'not_found', severity: 'low', retryable: false };
      }
      if (message.includes('server') || message.includes('500')) {
        return { type: 'server', severity: 'critical', retryable: true };
      }

      return { type: 'unknown', severity: 'medium', retryable: true };
    };

    it('should classify network errors', () => {
      const result = classifyError(createNetworkError());
      expect(result.type).toBe('network');
      expect(result.retryable).toBe(true);
    });

    it('should classify auth errors', () => {
      const result = classifyError(createAuthError());
      expect(result.type).toBe('auth');
      expect(result.retryable).toBe(false);
    });

    it('should classify timeout errors', () => {
      const result = classifyError(createTimeoutError());
      expect(result.type).toBe('network');
      expect(result.severity).toBe('medium');
    });

    it('should classify server errors as critical', () => {
      const result = classifyError(new Error('500 Internal Server Error'));
      expect(result.type).toBe('server');
      expect(result.severity).toBe('critical');
    });
  });

  describe('Error Recovery', () => {
    it('should recover with fallback data', async () => {
      const fallbackData = { items: [], fromCache: true };

      const fetchWithFallback = async () => {
        try {
          throw new Error('API unavailable');
        } catch {
          return fallbackData;
        }
      };

      const result = await fetchWithFallback();

      expect(result.fromCache).toBe(true);
    });

    it('should log errors for monitoring', async () => {
      const errorLog: Error[] = [];

      const logError = (error: Error) => {
        errorLog.push(error);
      };

      const apiWithLogging = async () => {
        try {
          throw new Error('Test error');
        } catch (error) {
          logError(error as Error);
          throw error;
        }
      };

      await expect(apiWithLogging()).rejects.toThrow();
      expect(errorLog).toHaveLength(1);
    });
  });

  describe('Circuit Breaker Pattern', () => {
    class CircuitBreaker {
      private failures = 0;
      private lastFailure = 0;
      private state: 'closed' | 'open' | 'half-open' = 'closed';
      
      constructor(
        private threshold: number = 3,
        private resetTimeout: number = 1000
      ) {}

      async execute<T>(fn: () => Promise<T>): Promise<T> {
        if (this.state === 'open') {
          if (Date.now() - this.lastFailure > this.resetTimeout) {
            this.state = 'half-open';
          } else {
            throw new Error('Circuit breaker is open');
          }
        }

        try {
          const result = await fn();
          this.onSuccess();
          return result;
        } catch (error) {
          this.onFailure();
          throw error;
        }
      }

      private onSuccess() {
        this.failures = 0;
        this.state = 'closed';
      }

      private onFailure() {
        this.failures++;
        this.lastFailure = Date.now();
        if (this.failures >= this.threshold) {
          this.state = 'open';
        }
      }

      getState() {
        return this.state;
      }
    }

    it('should open circuit after threshold failures', async () => {
      const breaker = new CircuitBreaker(3, 100);
      const failingFn = async () => { throw new Error('Fail'); };

      // Trigger failures
      for (let i = 0; i < 3; i++) {
        try { await breaker.execute(failingFn); } catch {}
      }

      expect(breaker.getState()).toBe('open');
    });

    it('should reject calls when circuit is open', async () => {
      const breaker = new CircuitBreaker(1, 1000);
      const failingFn = async () => { throw new Error('Fail'); };

      try { await breaker.execute(failingFn); } catch {}

      await expect(breaker.execute(async () => 'success'))
        .rejects.toThrow('Circuit breaker is open');
    });

    it('should reset after timeout', async () => {
      const breaker = new CircuitBreaker(1, 50);
      const failingFn = async () => { throw new Error('Fail'); };

      try { await breaker.execute(failingFn); } catch {}
      
      await wait(60);

      // Should be half-open now, allowing one attempt
      const result = await breaker.execute(async () => 'success');
      expect(result).toBe('success');
      expect(breaker.getState()).toBe('closed');
    });
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { createMockTask, wait } from './utils/test-helpers';

describe('Offline Mode Integration', () => {
  describe('Operation Queuing', () => {
    let offlineQueue: { action: string; data: any; timestamp: number }[];

    beforeEach(() => {
      offlineQueue = [];
    });

    const queueOperation = (action: string, data: any) => {
      offlineQueue.push({
        action,
        data,
        timestamp: Date.now()
      });
    };

    it('should queue operations when offline', () => {
      queueOperation('create_task', { title: 'Offline task' });
      queueOperation('update_note', { id: '123', content: 'Updated' });

      expect(offlineQueue).toHaveLength(2);
      expect(offlineQueue[0].action).toBe('create_task');
    });

    it('should preserve operation order', () => {
      queueOperation('op1', {});
      queueOperation('op2', {});
      queueOperation('op3', {});

      expect(offlineQueue[0].action).toBe('op1');
      expect(offlineQueue[2].action).toBe('op3');
    });

    it('should include timestamp for each operation', () => {
      const before = Date.now();
      queueOperation('test', {});
      const after = Date.now();

      expect(offlineQueue[0].timestamp).toBeGreaterThanOrEqual(before);
      expect(offlineQueue[0].timestamp).toBeLessThanOrEqual(after);
    });
  });

  describe('Queue Synchronization', () => {
    it('should sync queued operations when online', async () => {
      const queue = [
        { action: 'create_task', data: { title: 'Task 1' }, timestamp: Date.now() - 1000 },
        { action: 'create_task', data: { title: 'Task 2' }, timestamp: Date.now() }
      ];

      const syncResults: { success: boolean; action: string }[] = [];

      for (const item of queue) {
        await wait(10);
        syncResults.push({ success: true, action: item.action });
      }

      expect(syncResults).toHaveLength(2);
      expect(syncResults.every(r => r.success)).toBe(true);
    });

    it('should handle sync failures gracefully', async () => {
      const queue = [
        { action: 'create_task', data: { title: 'Task 1' }, timestamp: Date.now() }
      ];

      const syncWithFailure = async () => {
        const results = [];
        for (const item of queue) {
          try {
            throw new Error('Sync failed');
          } catch (error) {
            results.push({ success: false, action: item.action, error: (error as Error).message });
          }
        }
        return results;
      };

      const results = await syncWithFailure();
      expect(results[0].success).toBe(false);
      expect(results[0].error).toBe('Sync failed');
    });

    it('should retry failed sync operations', async () => {
      let attempts = 0;
      const maxRetries = 3;

      const syncWithRetry = async (): Promise<boolean> => {
        for (let i = 0; i < maxRetries; i++) {
          attempts++;
          if (attempts >= 2) return true; // Succeed on second attempt
          await wait(10);
        }
        return false;
      };

      const result = await syncWithRetry();
      expect(result).toBe(true);
      expect(attempts).toBe(2);
    });
  });

  describe('Conflict Resolution', () => {
    interface VersionedData {
      id: string;
      title: string;
      updated_at: number;
    }

    const resolveConflict = (
      server: VersionedData,
      local: VersionedData,
      strategy: 'server-wins' | 'local-wins' | 'newest-wins' = 'newest-wins'
    ): { winner: string; data: VersionedData } => {
      switch (strategy) {
        case 'server-wins':
          return { winner: 'server', data: server };
        case 'local-wins':
          return { winner: 'local', data: local };
        case 'newest-wins':
        default:
          return server.updated_at > local.updated_at
            ? { winner: 'server', data: server }
            : { winner: 'local', data: local };
      }
    };

    it('should resolve conflict with server-wins strategy', () => {
      const server = { id: '1', title: 'Server', updated_at: Date.now() - 1000 };
      const local = { id: '1', title: 'Local', updated_at: Date.now() };

      const result = resolveConflict(server, local, 'server-wins');
      expect(result.winner).toBe('server');
      expect(result.data.title).toBe('Server');
    });

    it('should resolve conflict with local-wins strategy', () => {
      const server = { id: '1', title: 'Server', updated_at: Date.now() };
      const local = { id: '1', title: 'Local', updated_at: Date.now() - 1000 };

      const result = resolveConflict(server, local, 'local-wins');
      expect(result.winner).toBe('local');
      expect(result.data.title).toBe('Local');
    });

    it('should resolve conflict with newest-wins strategy', () => {
      const server = { id: '1', title: 'Server', updated_at: Date.now() };
      const local = { id: '1', title: 'Local', updated_at: Date.now() - 1000 };

      const result = resolveConflict(server, local, 'newest-wins');
      expect(result.winner).toBe('server');
    });

    it('should handle equal timestamps', () => {
      const timestamp = Date.now();
      const server = { id: '1', title: 'Server', updated_at: timestamp };
      const local = { id: '1', title: 'Local', updated_at: timestamp };

      const result = resolveConflict(server, local);
      // When equal, local wins (server.updated_at > local.updated_at is false)
      expect(result.winner).toBe('local');
    });
  });

  describe('Offline Detection', () => {
    it('should detect online status', () => {
      const isOnline = true; // Simulated
      expect(isOnline).toBe(true);
    });

    it('should detect offline status', () => {
      const isOnline = false; // Simulated
      expect(isOnline).toBe(false);
    });

    it('should determine if operation can proceed', () => {
      const canOperate = (isOnline: boolean, hasOfflineSupport: boolean) => {
        return isOnline || hasOfflineSupport;
      };

      expect(canOperate(true, false)).toBe(true);
      expect(canOperate(false, true)).toBe(true);
      expect(canOperate(false, false)).toBe(false);
    });
  });

  describe('Offline Storage', () => {
    it('should store data locally when offline', () => {
      const offlineStore: Record<string, any> = {};
      
      const storeOffline = (key: string, data: any) => {
        offlineStore[key] = { data, storedAt: Date.now() };
      };

      storeOffline('task_1', { title: 'Offline Task' });
      
      expect(offlineStore['task_1']).toBeDefined();
      expect(offlineStore['task_1'].data.title).toBe('Offline Task');
    });

    it('should retrieve offline data', () => {
      const offlineStore: Record<string, any> = {
        'task_1': { data: { title: 'Stored Task' }, storedAt: Date.now() }
      };

      const getOffline = (key: string) => offlineStore[key]?.data || null;

      expect(getOffline('task_1')?.title).toBe('Stored Task');
      expect(getOffline('nonexistent')).toBeNull();
    });
  });
});

import { describe, it, expect } from 'vitest';
import { wait, measureTime, TestCache } from './utils/test-helpers';

describe('Performance Integration', () => {
  describe('Operation Timing', () => {
    it('should measure operation duration accurately', async () => {
      const { duration } = await measureTime(async () => {
        await wait(50);
        return 'done';
      });

      expect(duration).toBeGreaterThanOrEqual(50);
      expect(duration).toBeLessThan(100);
    });

    it('should measure fast operations', async () => {
      const { duration } = await measureTime(async () => {
        return 1 + 1;
      });

      expect(duration).toBeLessThan(10);
    });

    it('should return operation result', async () => {
      const { result } = await measureTime(async () => {
        return { value: 42 };
      });

      expect(result.value).toBe(42);
    });
  });

  describe('Caching', () => {
    it('should cache and retrieve values', () => {
      const cache = new TestCache<string>();
      
      cache.set('key1', 'value1');
      
      expect(cache.get('key1')).toBe('value1');
    });

    it('should return null for missing keys', () => {
      const cache = new TestCache<string>();
      
      expect(cache.get('nonexistent')).toBeNull();
    });

    it('should expire cached values after TTL', async () => {
      const cache = new TestCache<string>(50); // 50ms TTL
      
      cache.set('key1', 'value1');
      expect(cache.get('key1')).toBe('value1');
      
      await wait(60);
      
      expect(cache.get('key1')).toBeNull();
    });

    it('should track cache size', () => {
      const cache = new TestCache<string>();
      
      cache.set('key1', 'value1');
      cache.set('key2', 'value2');
      
      expect(cache.size()).toBe(2);
    });

    it('should clear all cached values', () => {
      const cache = new TestCache<string>();
      
      cache.set('key1', 'value1');
      cache.set('key2', 'value2');
      cache.clear();
      
      expect(cache.size()).toBe(0);
      expect(cache.get('key1')).toBeNull();
    });
  });

  describe('Concurrent Operations', () => {
    it('should handle multiple concurrent operations', async () => {
      const operations = Array(100).fill(null).map((_, i) =>
        Promise.resolve({ id: i, success: true })
      );

      const results = await Promise.all(operations);

      expect(results).toHaveLength(100);
      expect(results.every(r => r.success)).toBe(true);
    });

    it('should complete concurrent operations within time limit', async () => {
      const { duration } = await measureTime(async () => {
        const operations = Array(10).fill(null).map(() => wait(10));
        await Promise.all(operations);
      });

      // All should complete in parallel, not sequentially
      expect(duration).toBeLessThan(50);
    });
  });

  describe('Memory Management', () => {
    it('should limit array size', () => {
      const MAX_SIZE = 100;
      const items: number[] = [];

      for (let i = 0; i < 150; i++) {
        items.push(i);
        if (items.length > MAX_SIZE) {
          items.shift();
        }
      }

      expect(items.length).toBe(MAX_SIZE);
      expect(items[0]).toBe(50); // First 50 items were removed
    });

    it('should implement LRU-like eviction', () => {
      const MAX_SIZE = 3;
      const cache = new Map<string, { value: any; lastAccess: number }>();

      const set = (key: string, value: any) => {
        if (cache.size >= MAX_SIZE) {
          // Remove least recently accessed
          let oldest: string | null = null;
          let oldestTime = Infinity;
          cache.forEach((v, k) => {
            if (v.lastAccess < oldestTime) {
              oldestTime = v.lastAccess;
              oldest = k;
            }
          });
          if (oldest) cache.delete(oldest);
        }
        cache.set(key, { value, lastAccess: Date.now() });
      };

      set('a', 1);
      set('b', 2);
      set('c', 3);
      set('d', 4); // Should evict 'a'

      expect(cache.has('a')).toBe(false);
      expect(cache.has('d')).toBe(true);
      expect(cache.size).toBe(3);
    });
  });

  describe('Debouncing', () => {
    it('should debounce rapid calls', async () => {
      let callCount = 0;
      const debounce = (fn: () => void, delay: number) => {
        let timeout: NodeJS.Timeout;
        return () => {
          clearTimeout(timeout);
          timeout = setTimeout(fn, delay);
        };
      };

      const increment = debounce(() => { callCount++; }, 50);

      // Rapid calls
      increment();
      increment();
      increment();
      increment();
      increment();

      await wait(100);

      expect(callCount).toBe(1);
    });
  });

  describe('Throttling', () => {
    it('should throttle frequent calls', async () => {
      let callCount = 0;
      let lastCall = 0;

      const throttle = (fn: () => void, limit: number) => {
        return () => {
          const now = Date.now();
          if (now - lastCall >= limit) {
            lastCall = now;
            fn();
          }
        };
      };

      const increment = throttle(() => { callCount++; }, 50);

      // Rapid calls over 100ms
      const start = Date.now();
      while (Date.now() - start < 100) {
        increment();
        await wait(10);
      }

      // Should have been called approximately 2-3 times
      expect(callCount).toBeGreaterThanOrEqual(2);
      expect(callCount).toBeLessThanOrEqual(3);
    });
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { createMockWidget, mockLocalStorage, wait } from './utils/test-helpers';

describe('Widget System Integration', () => {
  describe('Widget Layout Persistence', () => {
    let mockStorage: ReturnType<typeof mockLocalStorage>;

    beforeEach(() => {
      mockStorage = mockLocalStorage();
      Object.defineProperty(window, 'localStorage', { value: mockStorage });
    });

    it('should persist widget layout to storage', () => {
      const layout = [
        createMockWidget('clock', { position: { x: 0, y: 0 } }),
        createMockWidget('weather', { position: { x: 2, y: 0 } }),
        createMockWidget('tasks', { position: { x: 0, y: 2 } })
      ];

      mockStorage.setItem('widget_layout', JSON.stringify(layout));

      const stored = JSON.parse(mockStorage.getItem('widget_layout')!);
      expect(stored).toHaveLength(3);
    });

    it('should restore widget layout from storage', () => {
      const layout = [createMockWidget('clock')];
      mockStorage.setItem('widget_layout', JSON.stringify(layout));

      const restored = JSON.parse(mockStorage.getItem('widget_layout')!);
      expect(restored[0].type).toBe('clock');
    });

    it('should handle empty layout gracefully', () => {
      const stored = mockStorage.getItem('widget_layout');
      expect(stored).toBeNull();
    });
  });

  describe('Widget Resize Constraints', () => {
    const widgetConstraints: Record<string, { minW: number; minH: number; maxW: number; maxH: number }> = {
      clock: { minW: 1, minH: 1, maxW: 4, maxH: 4 },
      weather: { minW: 2, minH: 2, maxW: 4, maxH: 4 },
      tasks: { minW: 2, minH: 2, maxW: 6, maxH: 6 },
      calendar: { minW: 3, minH: 3, maxW: 6, maxH: 6 },
      notes: { minW: 2, minH: 2, maxW: 4, maxH: 4 }
    };

    const validateResize = (widgetType: string, newSize: { w: number; h: number }): boolean => {
      const constraints = widgetConstraints[widgetType];
      if (!constraints) return false;

      return newSize.w >= constraints.minW &&
             newSize.w <= constraints.maxW &&
             newSize.h >= constraints.minH &&
             newSize.h <= constraints.maxH;
    };

    it('should validate clock widget resize', () => {
      expect(validateResize('clock', { w: 2, h: 2 })).toBe(true);
      expect(validateResize('clock', { w: 1, h: 1 })).toBe(true);
      expect(validateResize('clock', { w: 5, h: 5 })).toBe(false);
    });

    it('should validate weather widget resize', () => {
      expect(validateResize('weather', { w: 2, h: 2 })).toBe(true);
      expect(validateResize('weather', { w: 1, h: 1 })).toBe(false);
      expect(validateResize('weather', { w: 4, h: 4 })).toBe(true);
    });

    it('should validate tasks widget resize', () => {
      expect(validateResize('tasks', { w: 3, h: 3 })).toBe(true);
      expect(validateResize('tasks', { w: 6, h: 6 })).toBe(true);
      expect(validateResize('tasks', { w: 7, h: 7 })).toBe(false);
    });

    it('should reject unknown widget types', () => {
      expect(validateResize('unknown', { w: 2, h: 2 })).toBe(false);
    });
  });

  describe('Widget Collision Detection', () => {
    const checkCollision = (
      widget1: { x: number; y: number; w: number; h: number },
      widget2: { x: number; y: number; w: number; h: number }
    ): boolean => {
      return !(
        widget1.x + widget1.w <= widget2.x ||
        widget2.x + widget2.w <= widget1.x ||
        widget1.y + widget1.h <= widget2.y ||
        widget2.y + widget2.h <= widget1.y
      );
    };

    it('should detect overlapping widgets', () => {
      const widget1 = { x: 0, y: 0, w: 2, h: 2 };
      const widget2 = { x: 1, y: 1, w: 2, h: 2 };

      expect(checkCollision(widget1, widget2)).toBe(true);
    });

    it('should allow adjacent widgets', () => {
      const widget1 = { x: 0, y: 0, w: 2, h: 2 };
      const widget2 = { x: 2, y: 0, w: 2, h: 2 };

      expect(checkCollision(widget1, widget2)).toBe(false);
    });

    it('should detect vertical overlap', () => {
      const widget1 = { x: 0, y: 0, w: 2, h: 2 };
      const widget2 = { x: 0, y: 1, w: 2, h: 2 };

      expect(checkCollision(widget1, widget2)).toBe(true);
    });

    it('should allow vertically stacked widgets', () => {
      const widget1 = { x: 0, y: 0, w: 2, h: 2 };
      const widget2 = { x: 0, y: 2, w: 2, h: 2 };

      expect(checkCollision(widget1, widget2)).toBe(false);
    });
  });

  describe('Widget Data Refresh', () => {
    const mockWidgetData: Record<string, any> = {
      weather: { temp: 72, condition: 'sunny', humidity: 45 },
      tasks: { pending: 5, completed: 10, overdue: 2 },
      calendar: { events: 3, nextEvent: 'Meeting at 2pm' },
      stocks: { portfolio: 15000, change: 2.5 }
    };

    const refreshWidget = async (widgetId: string): Promise<any> => {
      await wait(10); // Simulate API delay
      return mockWidgetData[widgetId] || null;
    };

    it('should refresh weather widget data', async () => {
      const data = await refreshWidget('weather');
      
      expect(data).toBeDefined();
      expect(data.temp).toBe(72);
      expect(data.condition).toBe('sunny');
    });

    it('should refresh tasks widget data', async () => {
      const data = await refreshWidget('tasks');
      
      expect(data.pending).toBe(5);
      expect(data.completed).toBe(10);
    });

    it('should handle unknown widget gracefully', async () => {
      const data = await refreshWidget('unknown');
      expect(data).toBeNull();
    });

    it('should refresh multiple widgets concurrently', async () => {
      const results = await Promise.all([
        refreshWidget('weather'),
        refreshWidget('tasks'),
        refreshWidget('calendar')
      ]);

      expect(results).toHaveLength(3);
      expect(results.every(r => r !== null)).toBe(true);
    });
  });

  describe('Widget Configuration', () => {
    it('should apply widget-specific config', () => {
      const weatherWidget = createMockWidget('weather', {
        config: { unit: 'fahrenheit', showHumidity: true }
      });

      expect(weatherWidget.config.unit).toBe('fahrenheit');
      expect(weatherWidget.config.showHumidity).toBe(true);
    });

    it('should merge default and custom config', () => {
      const defaultConfig = { refreshInterval: 60000, showTitle: true };
      const customConfig = { refreshInterval: 30000 };
      
      const mergedConfig = { ...defaultConfig, ...customConfig };

      expect(mergedConfig.refreshInterval).toBe(30000);
      expect(mergedConfig.showTitle).toBe(true);
    });
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { parseToolCalls, extractTextResponse, validateToolCall } from '@/services/orchestrator/parser';
import { 
  getToolByName, 
  getToolsByCategory, 
  getAllToolNames,
  toolExists,
  searchTools 
} from '@/services/orchestrator/tools';

describe('Orchestrator Parser', () => {
  describe('parseToolCalls', () => {
    it('should parse a single tool call from JSON block', () => {
      const response = `I'll create a task for you.
\`\`\`json
{"tool": "create_task", "parameters": {"title": "Buy groceries", "priority": "high"}}
\`\`\`
Done!`;
      
      const toolCalls = parseToolCalls(response);
      
      expect(toolCalls).toHaveLength(1);
      expect(toolCalls[0].tool).toBe('create_task');
      expect(toolCalls[0].parameters).toEqual({
        title: 'Buy groceries',
        priority: 'high'
      });
    });

    it('should parse multiple tool calls from response', () => {
      const response = `I'll help you with that.
\`\`\`json
{"tool": "create_task", "parameters": {"title": "Task 1"}}
\`\`\`
And also:
\`\`\`json
{"tool": "create_reminder", "parameters": {"text": "Reminder 1", "due_time": "2024-01-15T10:00:00Z"}}
\`\`\``;
      
      const toolCalls = parseToolCalls(response);
      
      expect(toolCalls).toHaveLength(2);
      expect(toolCalls[0].tool).toBe('create_task');
      expect(toolCalls[1].tool).toBe('create_reminder');
    });

    it('should return empty array for response without tool calls', () => {
      const response = 'Just a regular response without any tools.';
      
      const toolCalls = parseToolCalls(response);
      
      expect(toolCalls).toHaveLength(0);
    });

    it('should skip invalid JSON blocks', () => {
      const response = `Here's a task:
\`\`\`json
{"tool": "create_task", "parameters": {"title": "Valid"}}
\`\`\`
And invalid:
\`\`\`json
{invalid json here}
\`\`\``;
      
      const toolCalls = parseToolCalls(response);
      
      expect(toolCalls).toHaveLength(1);
      expect(toolCalls[0].tool).toBe('create_task');
    });

    it('should handle tool calls without parameters', () => {
      const response = `\`\`\`json
{"tool": "get_current_time"}
\`\`\``;
      
      const toolCalls = parseToolCalls(response);
      
      expect(toolCalls).toHaveLength(1);
      expect(toolCalls[0].tool).toBe('get_current_time');
      expect(toolCalls[0].parameters).toEqual({});
    });

    it('should handle nested parameters', () => {
      const response = `\`\`\`json
{"tool": "create_calendar_event", "parameters": {"title": "Meeting", "attendees": ["john@example.com", "jane@example.com"]}}
\`\`\``;
      
      const toolCalls = parseToolCalls(response);
      
      expect(toolCalls).toHaveLength(1);
      expect(toolCalls[0].parameters.attendees).toEqual(['john@example.com', 'jane@example.com']);
    });
  });

  describe('extractTextResponse', () => {
    it('should extract text without JSON blocks', () => {
      const response = `Here's what I found:
\`\`\`json
{"tool": "get_tasks"}
\`\`\`
Let me know if you need anything else.`;
      
      const text = extractTextResponse(response);
      
      expect(text).toBe("Here's what I found:\n\nLet me know if you need anything else.");
    });

    it('should return full text when no JSON blocks present', () => {
      const response = 'Just a simple response.';
      
      const text = extractTextResponse(response);
      
      expect(text).toBe('Just a simple response.');
    });

    it('should handle multiple JSON blocks', () => {
      const response = `First:
\`\`\`json
{"tool": "a"}
\`\`\`
Middle text
\`\`\`json
{"tool": "b"}
\`\`\`
End`;
      
      const text = extractTextResponse(response);
      
      expect(text).toContain('First:');
      expect(text).toContain('Middle text');
      expect(text).toContain('End');
      expect(text).not.toContain('{"tool"');
    });
  });

  describe('validateToolCall', () => {
    it('should validate a correct tool call', () => {
      const toolCall = {
        tool: 'create_task',
        parameters: { title: 'Test' }
      };
      
      const result = validateToolCall(toolCall);
      
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    it('should reject tool call without tool name', () => {
      const toolCall = {
        tool: '',
        parameters: {}
      };
      
      const result = validateToolCall(toolCall);
      
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    it('should reject tool call with non-string tool name', () => {
      const toolCall = {
        tool: 123 as any,
        parameters: {}
      };
      
      const result = validateToolCall(toolCall);
      
      expect(result.valid).toBe(false);
    });

    it('should reject tool call with non-object parameters', () => {
      const toolCall = {
        tool: 'test',
        parameters: 'invalid' as any
      };
      
      const result = validateToolCall(toolCall);
      
      expect(result.valid).toBe(false);
    });
  });
});

