/**
 * Production-safe logger utility
 * Logs only in development mode, always logs errors
 */

const isDev = import.meta.env.DEV;

export const logger = {
  /**
   * Log informational messages (dev only)
   */
  log: (component: string, ...args: any[]) => {
    if (isDev) {
      console.log(`[${component}]`, ...args);
    }
  },

  /**
   * Log warnings (dev only)
   */
  warn: (component: string, ...args: any[]) => {
    if (isDev) {
      console.warn(`[${component}]`, ...args);
    }
  },

  /**
   * Log errors (always)
   */
  error: (component: string, ...args: any[]) => {
    console.error(`[${component}]`, ...args);
  },

  /**
   * Log debug info (dev only)
   */
  debug: (component: string, ...args: any[]) => {
    if (isDev) {
      console.debug(`[${component}]`, ...args);
    }
  },

  /**
   * Group logs (dev only)
   */
  group: (label: string, fn: () => void) => {
    if (isDev) {
      console.group(label);
      fn();
      console.groupEnd();
    }
  },
};

"use client";

import { logger } from "./logger";

interface RetryOptions {
  maxRetries?: number;
  baseDelay?: number;
  maxDelay?: number;
  onRetry?: (attempt: number, error: Error) => void;
  shouldRetry?: (error: Error) => boolean;
}

/**
 * Retry a function with exponential backoff
 */
export async function retryWithBackoff<T>(
  fn: () => Promise<T>,
  options: RetryOptions = {}
): Promise<T> {
  const {
    maxRetries = 3,
    baseDelay = 1000,
    maxDelay = 10000,
    onRetry,
    shouldRetry = () => true,
  } = options;

  let lastError: Error | null = null;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;

      // Don't retry if we shouldn't
      if (!shouldRetry(error)) {
        throw error;
      }

      // Don't retry on last attempt
      if (attempt === maxRetries) {
        break;
      }

      // Calculate delay with exponential backoff
      const delay = Math.min(baseDelay * Math.pow(2, attempt), maxDelay);
      
      logger.warn('Retry', `Attempt ${attempt + 1}/${maxRetries} failed, retrying in ${delay}ms`, error.message);
      
      onRetry?.(attempt + 1, error);

      // Wait before retrying
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }

  throw lastError || new Error('Max retries exceeded');
}

/**
 * Retry specifically for API calls
 */
export async function retryAPICall<T>(
  fn: () => Promise<T>,
  operationName: string
): Promise<T> {
  return retryWithBackoff(fn, {
    maxRetries: 3,
    baseDelay: 1000,
    shouldRetry: (error) => {
      // Retry on network errors and 5xx errors
      const message = error.message.toLowerCase();
      return (
        message.includes('network') ||
        message.includes('timeout') ||
        message.includes('500') ||
        message.includes('502') ||
        message.includes('503') ||
        message.includes('504')
      );
    },
    onRetry: (attempt, error) => {
      logger.warn('API Retry', `${operationName} attempt ${attempt}:`, error.message);
    },
  });
}

/**
 * Retry with circuit breaker pattern
 */
class CircuitBreaker {
  private failures = 0;
  private lastFailureTime = 0;
  private state: 'closed' | 'open' | 'half-open' = 'closed';
  
  constructor(
    private threshold: number = 5,
    private timeout: number = 60000 // 1 minute
  ) {}

  async execute<T>(fn: () => Promise<T>): Promise<T> {
    if (this.state === 'open') {
      if (Date.now() - this.lastFailureTime > this.timeout) {
        this.state = 'half-open';
      } else {
        throw new Error('Circuit breaker is open');
      }
    }

    try {
      const result = await fn();
      
      if (this.state === 'half-open') {
        this.state = 'closed';
        this.failures = 0;
      }
      
      return result;
    } catch (error) {
      this.failures++;
      this.lastFailureTime = Date.now();
      
      if (this.failures >= this.threshold) {
        this.state = 'open';
        logger.error('CircuitBreaker', 'Circuit opened due to failures');
      }
      
      throw error;
    }
  }

  reset() {
    this.failures = 0;
    this.state = 'closed';
  }

  getState() {
    return {
      state: this.state,
      failures: this.failures,
      lastFailureTime: this.lastFailureTime,
    };
  }
}

export const openAICircuitBreaker = new CircuitBreaker(5, 60000);
export const supabaseCircuitBreaker = new CircuitBreaker(10, 30000);

/**
 * Validation Utilities
 * Provides consistent validation and sanitization across the app
 */

// Email validation
export function isValidEmail(email: string): boolean {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

// Phone number validation (basic)
export function isValidPhone(phone: string): boolean {
  const phoneRegex = /^[\d\s\-\+\(\)]{7,20}$/;
  return phoneRegex.test(phone);
}

// URL validation
export function isValidUrl(url: string): boolean {
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
}

// Date validation
export function isValidDate(date: string | Date): boolean {
  const d = date instanceof Date ? date : new Date(date);
  return !isNaN(d.getTime());
}

// Future date validation
export function isFutureDate(date: string | Date): boolean {
  const d = date instanceof Date ? date : new Date(date);
  return d.getTime() > Date.now();
}

// String length validation
export function isValidLength(
  str: string,
  min: number = 0,
  max: number = Infinity
): boolean {
  return str.length >= min && str.length <= max;
}

// Sanitize string input (remove dangerous characters)
export function sanitizeString(input: string): string {
  return input
    .replace(/[<>]/g, '') // Remove angle brackets
    .replace(/javascript:/gi, '') // Remove javascript: protocol
    .replace(/on\w+=/gi, '') // Remove event handlers
    .trim();
}

// Sanitize HTML (basic - for display purposes)
export function escapeHtml(str: string): string {
  const htmlEntities: Record<string, string> = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  };
  return str.replace(/[&<>"']/g, (char) => htmlEntities[char]);
}

// Validate and sanitize task input
export function validateTaskInput(input: {
  title: string;
  description?: string;
  priority?: string;
  due_date?: string;
}): { valid: boolean; errors: string[]; sanitized: typeof input } {
  const errors: string[] = [];
  const sanitized = { ...input };

  // Title validation
  if (!input.title?.trim()) {
    errors.push('Title is required');
  } else if (!isValidLength(input.title, 1, 200)) {
    errors.push('Title must be between 1 and 200 characters');
  } else {
    sanitized.title = sanitizeString(input.title);
  }

  // Description validation
  if (input.description) {
    if (!isValidLength(input.description, 0, 5000)) {
      errors.push('Description must be less than 5000 characters');
    } else {
      sanitized.description = sanitizeString(input.description);
    }
  }

  // Priority validation
  const validPriorities = ['low', 'medium', 'high', 'urgent'];
  if (input.priority && !validPriorities.includes(input.priority)) {
    errors.push('Invalid priority value');
  }

  // Due date validation
  if (input.due_date && !isValidDate(input.due_date)) {
    errors.push('Invalid due date');
  }

  return {
    valid: errors.length === 0,
    errors,
    sanitized,
  };
}

// Validate and sanitize reminder input
export function validateReminderInput(input: {
  text: string;
  due_time: string;
  channel?: string;
}): { valid: boolean; errors: string[]; sanitized: typeof input } {
  const errors: string[] = [];
  const sanitized = { ...input };

  // Text validation
  if (!input.text?.trim()) {
    errors.push('Reminder text is required');
  } else if (!isValidLength(input.text, 1, 500)) {
    errors.push('Reminder text must be between 1 and 500 characters');
  } else {
    sanitized.text = sanitizeString(input.text);
  }

  // Due time validation
  if (!input.due_time) {
    errors.push('Due time is required');
  } else if (!isValidDate(input.due_time)) {
    errors.push('Invalid due time');
  }

  // Channel validation
  const validChannels = ['push', 'sms', 'email'];
  if (input.channel && !validChannels.includes(input.channel)) {
    errors.push('Invalid channel');
  }

  return {
    valid: errors.length === 0,
    errors,
    sanitized,
  };
}

// Validate and sanitize contact input
export function validateContactInput(input: {
  name: string;
  phone: string;
  email?: string;
}): { valid: boolean; errors: string[]; sanitized: typeof input } {
  const errors: string[] = [];
  const sanitized = { ...input };

  // Name validation
  if (!input.name?.trim()) {
    errors.push('Name is required');
  } else if (!isValidLength(input.name, 1, 100)) {
    errors.push('Name must be between 1 and 100 characters');
  } else {
    sanitized.name = sanitizeString(input.name);
  }

  // Phone validation
  if (!input.phone?.trim()) {
    errors.push('Phone number is required');
  } else if (!isValidPhone(input.phone)) {
    errors.push('Invalid phone number');
  }

  // Email validation
  if (input.email && !isValidEmail(input.email)) {
    errors.push('Invalid email address');
  }

  return {
    valid: errors.length === 0,
    errors,
    sanitized,
  };
}

// Validate API key format
export function isValidApiKey(key: string, provider: string): boolean {
  switch (provider) {
    case 'openai':
      return key.startsWith('sk-') && key.length > 20;
    case 'anthropic':
      return key.startsWith('sk-ant-') && key.length > 20;
    default:
      return key.length > 10;
  }
}

// Rate limiting check
const rateLimitMap = new Map<string, { count: number; resetTime: number }>();

export function checkRateLimit(
  key: string,
  maxRequests: number,
  windowMs: number
): { allowed: boolean; remaining: number; resetIn: number } {
  const now = Date.now();
  const record = rateLimitMap.get(key);

  if (!record || now > record.resetTime) {
    rateLimitMap.set(key, { count: 1, resetTime: now + windowMs });
    return { allowed: true, remaining: maxRequests - 1, resetIn: windowMs };
  }

  if (record.count >= maxRequests) {
    return {
      allowed: false,
      remaining: 0,
      resetIn: record.resetTime - now,
    };
  }

  record.count++;
  return {
    allowed: true,
    remaining: maxRequests - record.count,
    resetIn: record.resetTime - now,
  };
}

